export const kannadaSongbook: Record<number, { title: string; lyrics: string }> = {
  1: { title: "ಯೇಸು ಕರ್ತಾ ನೀನೇ ಬಂದು", lyrics: "1. ಯೇಸು ಕರ್ತಾ ನೀನೇ ಬಂದು\nನಮ್ಮ ಮಧ್ಯದಲ್ಲಿದ್ದೀ\nನಿನ್ನ ಮೇಜಿನ್ ಹತ್ರ ಕೂತು\nಆತ್ಮ ತೃಪ್ತಿ ಕೊಡುತ್ತೀ.\nಹೀಗೆ ಕೂಡಿ ಬರುವಲ್ಲಿ\nಎಂಥಾ ಶ್ರೇಷ್ಠ ಕಾಲವೇ ;\nಬೇರೆ ಎಲ್ಲಾ ಆಶೆಬಿಟ್ಟು\nನಿನ್ನ ಭಜಿಸುವೆವು.\n2. ಪವಿತ್ರಾತ್ಮ ಪ್ರೇರ್ಣೆಯಿಂದ\nನಿನ್ ಸಮ್ಮುಖದಲ್ಲಿಯು\nರೊಟ್ಟಿತಿಂದು ಪಾತ್ರೆಯನ್ನು\nಪಾನ ಮಾಡಿಕೊಳ್ವೆವು.\nಮುರಿದಂಥಾ ನಿನ್ನ ದೇಹ\nನೀನು ಚೆಲ್ದ ರಕ್ತವ\nಜ್ಞಪ್ತಿ ಮಾಡಿ ಭಕ್ತಿಯಿಂದ\nನಿನ್ನಾರಾಧಿಸುವೆವು.\n3. ಇಂಥಾ ಗುರುತುಗಳಲ್ಲಿ\nನಿನ್ನ ಪ್ರೀತಿ ಕಾಣುತ್ತೆ ;\nಒಂದೇ ರೊಟ್ಟಿ ಒಂದೇ ಪಾತ್ರೆ\nಅನ್ಯೋನ್ಯ ಸೂಚಿಸುತ್ತೆ.\nಒಬ್ಬನೇ ನಮ್ ಶ್ರೇಷ್ಠ ತಲೆ ;\nನಾವು ಒಂದೇ ದೇಹವು ;\nಒಂದೇ ಮನದಿಂದ ಕೂಡಿ\nಇರ್ವದು ನಿನ್ ಚಿತ್ತವು.\n4. ಬೇಗ ಬರುತ್ತೇನೆ ನಾನು\nಸಿದ್ಧವಾದ ಮನೇಲಿ\nನಿಮ್ಮನ್ ಸೇರಿಸುವೆನೆಂದು\nವಾಗ್ದಾನ ಮಾಡಿರುತ್ತೀ.\nನಿನ್ನ ಬರವಂ ಹಾರೈಸಿ\nಕಾದಿದ್ದೇವಾನಂದದಿ\nನಮ್ಮಲ್ಲಿ ಪ್ರಾರಂಭಿಸಿದ\nಕಾರ್ಯ ಕೊನೆಗಾಣುವಿ." },
  2: { title: "ದೀನರಾಗಿ ಬಂದಿದ್ದೇವೆ", lyrics: "1. ದೀನರಾಗಿ ಬಂದಿದ್ದೇವೆ\nನಿನ್ನ ಮಾತಿನಿಂದಲೇ ;\nಜ್ಪ್ತಿ ಮಾಡಿಕೊಳ್ಳುತ್ತೇವೆ\nನಿನ್ನನ್ನೇ, ಓ ಕರ್ತನೇ !\n2. ಕ್ರೂರವಾದ ಕ್ರೂಜೆ ಮೇಲೆ\nಪಾಪ ಶಿಕ್ಷೆ ತಾಳಿದ್ದೀ ;\nಅಪರಾಧ ಬಲಿಯಾಗಿ\nಅಲ್ಲಿ ಪ್ರಾಣ ಬಿಟ್ಟಿದ್ದೀ.\n3. ನಿನ್ನ ದೇಹ ಎಲ್ಲರ್ಗಾಗಿ\nಕೊಟ್ಟು ಮುರಿಸಿದ್ದಾಯ್ತು ;\nಸ್ತೋತ್ರದಿಂದ ರೊಟ್ಟಿತಿಂದು\nನಿನ್ನ ಜ್ಞಪ್ತಿ ಮಾಡ್ವೆವು.\n4. ನೀನು ಕುಡಿದಂಥಾ ಪಾತ್ರೆ\nಕೋಪದಿಂದ ತುಂಬಿತು ;\nನಾವು ಮಂಗಳಾಶೀರ್ವಾದ\nಪಾತ್ರೆ ಪಾನ ಮಾಡ್ವೆವು.\n5. ನಮ್ಮ ಮೇಲೆ ನೀನಿಟ್ಟಂಥ\nಪ್ರೀತಿ ಕರುಣೆಯನ್ನು ;\nಈಗ ನಾವು ಜ್ಞಪ್ತಿಮಾಡಿ\nನಿನ್ನನ್ನೇ ಕೊಂಡಾಡ್ವೆವು." },
  3: { title: "ನಿನ್ನನ್ನು ಪ್ರಿಯಕರ್ತ,", lyrics: "1. ನಿನ್ನನ್ನು ಪ್ರಿಯಕರ್ತ,\nನಾ ಸ್ತೋತ್ರ ಮಾಡುವೆ ;\nನಿನ್ ಶಿಲುಬೆಯ ಹತ್ರ\nನಾ ಕೂತುಕೊಳ್ಳುವೆ ;\nವೈರಿಯು ಸೇರಲಾರ,\nದುರ್ಗುಣ ಸೋಲುತ್ತೆ,\nನಿನ್ನೊಂದೇ ಭದ್ರ ಸ್ಥಾನ\nನಿನ್ ಭಕ್ತರೆಲ್ಲರ್ಗೆ.\n2. ಆ ಶಿಲ್ಬೇ ತಾಪವನ್ನು\nನೆನಪು ಮಾಡುವೆ ;\nಎನ್ನಾತ್ಮ ರಕ್ಷಿಸಲು\nನೀನೆಲ್ಲಾ ತಾಳಿದೆ.\nನೀನೆಂಥಾ ಪ್ರಿಯ ಸ್ವಾಮಿ,\nಓ ಯೇಸು ಕ್ರಿಸ್ತನೇ!\nನಾ ಸದಾ ಕಾಲದಲ್ಲಿ\nನಿನ್ನಂಬಿ ಬಾಳುವೆ.\n3. ಪವಿತ್ರ ನಿನ್ನ ದೇಹ\nಜ್ಞಾಫಕ ಮಾಡಲು\nನೀ ಕೊಟ್ಟ ರೊಟ್ಟಿಯನ್ನು\nತೆಗೆದುಕೊಳ್ವೆನು\nಅಮೂಲ್ಯ ನಿನ್ನ ರಕ್ತ\nತೋರುವ ಪಾತ್ರೆಯೇ\nಕೃತಜ್ಞಸ್ತುತಿಯಿಂದ\nತೆಗೆದುಕೊಳ್ಳುವೆ.\n4. ಇನ್ನಲ್ಪ ಕಾಲದಲ್ಲಿ\nನಾನಿಲ್ಲಿ ನಿಲ್ಲದೆ,\nಆನಂದ ಲೋಕದಲ್ಲಿ\nನಾ ಸೇರಿಕೊಳ್ಳುವೆ ;\nನಿನ್ನ ಸನ್ನಿಧಿಯಲ್ಲಿ\nನಿರಂತ್ರ ಬಾಳುವೆ ;\nಅಮಿತ ನಿನ್ನ ಪ್ರೀತಿ\nಎನ್ ಪ್ರಾಣಾಧಾರವೇ." },
  4: { title: "ದೇವಾಸನದ ಮುಂದೆಯೇ", lyrics: "1. ದೇವಾಸನದ ಮುಂದೆಯೇ\nಪ್ರೇಮಾಬ್ಧಿ ಗುರು ಯೇಸುವೇ,\nನನ್ನಾತ್ಮವನ್ನು ಬಿಡದೆ\nಬಿನ್ನಹ ಮಾಡ್ವನಲ್ಲವೇ ?\n2. ಹೌದೆನ್ನ ಸ್ವಾಮಿ ಅಲ್ಲಿಯೇ\nಭಕ್ತನ ಶ್ರಮೆ ತಾನೇ\nಜ್ಞಾಫಕಮಾಡಿ ಒಡನೇ\nಸಹಾಯ ಕೊಡ್ವನಲ್ಲವೇ ?\n3. ಪಾಪಿಯ ಹೊಣೆಗಾರನೇ\nದೇವರು ಕಂಡ ಕೂಡಲೆ\nಪಾಪಿಗೆ ಶಿಕ್ಷೆ ಕೊಡೆನು\nಎಂತಂದು ಬಿಟ್ಟು ಬಿಟ್ಟನು.\n4. ಆತನಾಮೂಲ್ಯ ರಕ್ತವೇ\nನನ್ ಪಾಪ ನಿವಾರಿಸಿದೆ ;\nಮಹಾ ಪವಿತ್ರ ದೇವರ್ಗೆ\nಸಾಕು ಆ ಬಲಿ ರಕ್ತವೇ.\n5. ಆತನ ಕೈಗಳಲ್ಲಿಯೂ,\nಆತನ ಹೃದಯದಲ್ಲಿಯೂ,\nಎನ್ನಾಮ ಬರೆದಾಗಿದೆ ;\nಸಂತೋಷಪಡು ಮನವೇ !\n6. ಆ ಸ್ವಾಮೀ ಸ್ತೋತ್ರ ಮಾಡಲು,\nಓ ಪಾಪಿ, ನೀನಯೋಗ್ಯನು\nಎಂದಂಜಿಸುವ ವೈರಿಯು\nಏನಂದರೂ ನಾನಂಜೆನು.\n7. ದೇವಾಸನದ ಮುಂದೆಯೇ\nಎನ್ನೇಸು ನನಗಾಗಿಯೇ\nಕಾಣಿಸಿಕೊಳ್ಳುವಾಗಲೂ\nಹೋಗೆಂದೂ ಯಾರೂ ಹೇಳರು.\n8. ನಾನಾತನಲ್ಲಿ ಐಕ್ಯನೇ,\nಆತನ ರಕ್ತದಿಂದಲೇ\nನಾ ಕೊಳ್ಳಲ್ಪಟ್ಟ ದಾಸನು ;\nಸದಾ ಸಂತೋಷಿಸುವೆನು." },
  5: { title: "ನೋಡು, ಸಭೆ, ಕಣ್ಣನ್ನೆ್ತಿ!", lyrics: "1. ನೋಡು, ಸಭೆ, ಕಣ್ಣನ್ನೆ್ತಿ!\nದೇವಲೋಕದೊಳಗೂ\nಅಲ್ಲಿ ಕೂತುಕೊಂಡಿದ್ದಾನೆ\nನಮ್ಮ ಪ್ರಾಣಪ್ರಿಯನು.\n2. ಮಹಿಮೆಯ ಲೋಕದಿಂದ\nತನ್ನನ್ನೇ ಅರ್ಪಿಸಲು\nನಮಗಾಗಿ ದೇವಪುತ್ರ\nಇಹದಲ್ಲಿ ಬಂದನು.\n3. ಇಲ್ಲಿ ಹಿಂಸೆ ಹಾಸ್ಯ, ನಿಂದೆ\nಎಲ್ಲಾ ತಾಳಿಕೊಂಡನು ;\nಘೋರವಾದ ಶಿಲ್ಬೆ ಮೇಲೆ\nಬಾಧೆ ಪಟ್ಟು ಸತ್ತನು\n4. ಹೇಳಲಾರದಷ್ಟು ಕಷ್ಟ\nಎಷ್ಟೋ ವ್ಯಥೆಪಟ್ಟನು ;\nತಲೆ, ಕಾಲು, ಕೈಗಳಿಂದ\nರಕ್ತ ಸೋರುತ್ತಾ ಇತ್ತು.\n5. ಆತ ನಮ್ಮ ಪಾಪಕ್ಕಾಗಿ\nತಾನೇ ಯಜ್ಞವಾದರೂ,\nಆತ ವೀರನಾಗಿ ಎದ್ದು\nಮಹಿಮಾ ಲೋಕಕ್ಕೇರ್ದನು." },
  6: { title: "ಗೋರಿಯೊಳಿಳಿದ", lyrics: "1. ಗೋರಿಯೊಳಿಳಿದ\nಯೇಸು ರಕ್ಷಕ ;\nತಾನೇಳ್ವ ದಿನವ\nಕಾಯುತ್ತಿದ್ದ\nಪಲ್ಲವಿ\nಗೋರಿಯನ್ ಬಿಟ್ಟಿದ್ದನು !\nಯೇಸು ಮೃತ್ಯುಂಜಯಶಾಲಿಯು ;\nಮೃತ್ಯುವೆಂಬ ಶತ್ರು ಗೆದ್ದು ಬಂದನು,\nತನ್ನ ಭಕ್ತರೊಂದಿಗಿರ್ವನೆಂದಿಗೂ,\nಕ್ರಿಸ್ತನು ಎದ್ದನು,\nಹಲ್ಲೆಲೂಯ ಎದ್ದನು\n2. ಆತನ್ ಗೋರಿಗೆ\nಮುದ್ರೆಯ ಹಾಕಿ ;\nಪಹರೆ ಕಾದಿದ್ರೂ\nಸೋತ್ಥೋದರು.\n3. ವೈರಿ ತನ್ ಖೈದಿಯ\nಹಿಡಿಯದ್ಹೋದ ;\nಬೇಡಿಯ ಮುರಿದ.\nಎನ್ ರಕ್ಷಕ.\n4. ಮರಣ ಕೊಂಡಿಯೇ\nಮುರ್ಯಿತು ಕೂಡಲೇ ;\nಜಯ ವಿಜಯವೇ\nಎನ್ ಸ್ವಾಮಿಗೆ." },
  7: { title: "ಪ್ರಾಣಪ್ರಿಯ ನನ್ನ ಕರ್ತ", lyrics: "1. ಪ್ರಾಣಪ್ರಿಯ ನನ್ನ ಕರ್ತ\nನಿನ್ನ ಕ್ರೂಜೆ ಮುಂದೆಯೇ\nನಾನು ಕೂತು ನಿನ್ನ ಪ್ರೇಮ\nನೋಡಿ, ಹಾಡಿಕೊಳ್ಳುವೆ.\n2. ಇದು ಸುಪ್ರಸನ್ನ ಕಾಲ,\nಇಲ್ಲಿ ದಿವ್ಯಾನಂದವೇ,\nಪಾಪಿಗಳಾಮೂಲ್ಯ ಮಿತ್ರ\nಸದಾ ಸ್ತೋತ್ರ ಮಾಡುವೆ.\n3. ನಿನ್ನ ಮೇಲೆ ನನ್ನ ಪಾಪ\nಎಷ್ಟೋ ಭಾರವಾಗಿತ್ತು ;\nನನ್ನ ಭಾರ ನೀಗಿ ಹೋಯ್ತು ;\nನಿನಗೆಂದೂ ಸ್ತೋತ್ರವು.\n4. ನಿನ್ನಾಮೂಲ್ಯವಾದ ರಕ್ತ\nನನ್ನ ಶುದ್ಧಮಾಡಿದೆ ;\nಸಾಕೀ ಬಲಿ, ನನ್ನ ಪಾಪ\nಪರಿಹಾರವಾಗಿದೆ.\n5. ನಿನ್ನ ಮೇಲೆ ಈಗ ದೃಷ್ಟಿ\nಇಟ್ಟಿದ್ದೇನೆ ಯೇಸುವೇ!\nನೀನು ಸ್ವರ್ಗಾನಂದದಲ್ಲಿ\nಸೇರಿಸುವ ಪತಿಯೇ!\n6. ಇಲ್ಲಿ ನಿನ್ನ ಕ್ರೂಜೆ ಹತ್ರ\nಜಯಧ್ವನಿ ಗೈಯುವೆ ;\nಮೃತ್ಯುವಿನ ಬಂಧವನ್ನ\nಗೆದ್ದಿ ಸರ್ವಶಕ್ತನೇ !\n7. ಸ್ವಾಮಿ! ನನ್ನ ಬಲವಾಗು ;\nಎಲ್ಲಾ ಪಾಪ ಶೋಧನೆ\nನಾನು ಗೆದ್ದು ನಿನ್ನ ತೋಳು\nಆತುಕೊಂಡು ಹೋಗುವೆ." },
  8: { title: "ನೀನು ಬರ್ವವರೆಗೂ", lyrics: "1. ನೀನು ಬರ್ವವರೆಗೂ\nಪರೋಕ್ಷವಿದ್ದು ನನಗೂ\nಪ್ರತ್ಯಕ್ಷವಾಗ್ವ ಕಾಲವು\nಬೇಗ ಪ್ರಾಪ್ತವಾಗ್ವದು :\nಯೇಸು, ನನ್ನ ಆಪ್ತನೇ,\nಬೇಗ, ಬಾ ನಂಗಾಗಿಯೇ.\n2. ಪ್ರಿಯ ಜನ ಹೋದರೂ,\nಆಪ್ತ ಮಿತ್ರ ಬಿಟ್ಟರೂ,\nನೀನು ಹತ್ರ ನಿಲ್ಲುವಿ,\nಶಾಂತ ಮಾತನ್ನಾಡುವಿ ;\nಎಲ್ಲಾ ತಾಳಿಕೊಳ್ಳುವೆ\nನೀನು ಬರ್ವವರೆಗೆ.\n3. ನಿನ್ನ ಸಾವಿನ್ ನೆನಪು\nಈಗ ಮಾಡಿಕೊಳ್ಳಲು\nಬಂದೆ, ದಿವ್ಯ ಕರ್ತನೆ,\nಮಾತನ್ನಾಡು ನನಗೆ :\nನಿನ್ನ ಧ್ಯಾನ ಮಾಡುವೆ\nನೀನು ಬರ್ವವರೆಗೆ!\n4. ನಿನ್ನ ದಿವ್ಕ ದೇಹವ\nರೊಟ್ಟಿ ಗುರ್ತಿಸುತ್ತದೆ ;\nಪಾತ್ರೆಯಲ್ಲಿ ರಕ್ತವ\nಸೂಚಿಸುವ ರಸವ\nನೋಡಿ, ಸ್ತೋತ್ರ ಕೊಡುವೆ\nನೀನು ಬರ್ವ ವರೆಗೆ\n5. ದಾರಿ ಸೊಟ್ಟಗಿದ್ದರೂ,\nವೈರಿ ಹೊಂಚಿ ಕಾದರೂ,\nನೆರವಾಗು ಕರ್ತನೇ!\nಹಸ್ತ ನೀಡು, ನನಗೆ\nಬೇಗ ಬಾ, ಎನ್ನಾಪ್ತನೇ!\nನಿನ್ನನ್ನಾತುಕೊಳ್ಳುಮೆ" },
  9: { title: "|. ಕ್ರೂಜೆ ಧ್ಕಾನ ಮಾಡುತ್ತೇನೆ :", lyrics: "|. ಕ್ರೂಜೆ ಧ್ಕಾನ ಮಾಡುತ್ತೇನೆ :\nಎಂಥಾ ಪ್ರೀತಿ ತೋರುತ್ತೆ ;\nಪಂಚಗಾಯ ನೋಡುತ್ತೇನೆ\nಯೇಸು ಸ್ವಾಮಿಯಲ್ಲಿಯೇ\n2. ಸ್ವಲ್ಪ ಹೊತ್ತು ನಿಂತು ನೋಡ್ವೆ ;\nಹೆಚ್ಚು ನೋಡಲಾರೆನು ;\nಅಯ್ಕೋ, ನನ್ನ ಎಲ್ಲಾ ಶ್ರಮೆ\nಯೇಸು ತಾನೇ ತಾಳ್ಡನು.\n3. ಕ್ರೂಜೆ ಹತ್ರ ಹೋಗಲಾಗಿ\nದೊರೆತಾಶೀರ್ವಾದವು ;\nಯೇಸುವನ್ನು ನೋಡಲಾಗಿ\nನಿತ್ಯ ಶಾಂತಿ ಸಿಕ್ಕಿತು\n4. ಅಲ್ಲಿ ನಿಂತು ನೋಡುತ್ತೇನೆ\nದಿವ್ಯ ರಕ್ತಧಾರೆಯ ;\nಆತನಿಂದ ಹೊಂದುತ್ತೇನೆ\nಪವಿತ್ರಾತ್ಮ ಶಾಂತಿಯು.\n5. ಮಾಡಲೇನು ? ಕೊಡಲೇನು\nನಿನ್ನ ದಿಷ್ಯ ಸೇವೆಗೆ ?\nಹೇಳತೀರಲಾರದಷ್ಟು\nಪ್ರೀಷಿ ದಿವ್ಯ ಪ್ರೀತಿಯೇ!\n6. ಆತ್ಮ ಪ್ರಾಣ ದೇಹವನ್ನು\nನಿನ್ನ ದಿವ್ಯ ಸೇವೆಗೆ\nಸ್ಥಿರ ಮನದಿಂದ ತಂದು\nಬಲಿಯಾಗಿ ಕೊಡುಮೆ" },
  10: { title: "ಕೃತಜ್ಞ ಬಲಿ ತರುವೆ", lyrics: "1. ಕೃತಜ್ಞ ಬಲಿ ತರುವೆ\nಎನ್ನೇಸು ಸ್ವಾಮಿ ಬಳಿಗೆ,\n“ಎಲ್ಲವ ಸರಿಗೈದನು’”\nಎಂತಂದು ಸ್ತೋತ್ರ ಮಾಡ್ವೆನು\n2. “ಆತನು ಸರ್ವ ಶಕ್ತನೂ,\nಆತನು ಸರ್ವ ಬಲ್ಲನೂ,\nಸುಕಾರ್ಯ ಮಾಡ್ವ ಮಿತ್ರನೂ”\nಎಂತಂದು ಸ್ತೋತ್ರ ಮಾಡ್ವೆನು\n3. ಆತನ ಪ್ರೀತಿ ಇಷ್ಟೆಂದು\nನಾ ಹೇಳಿ ತೀರಲಾರೆನು ;\nಆತನು ಆತ್ಮದಾಪ್ತನು\nಸಂತೋಷದಿಂದ ಹಾಡ್ವೆನು.\n4. ನಾನೆಂಥ ಕಷ್ಟದೊಳಗೆ\nಬಿದ್ದಾಗ್ಯೂ ಇನ್ನೂ ಹಾಡುವೆ,\n“ಎಲ್ಲವ ಸರಿಮಾಡ್ವನು”\nಎಂತಂದು ಸ್ತೋತ್ರ ಮಾಡ್ವೆನು.\n5. ಆತನ ಸ್ವರ್ಗಾನಂದಕ್ಕೆ\nನಾನೇರಿ ಸದಾ ಇರುವೆ ;\nಆತನ ಕಾರ್ಯವೆಲ್ಲವೂ\nಸ್ತೋತ್ರಕ್ಕೆ ಯೋಗ್ಯವಾದವು." },
  11: { title: "ದುಱಖಿತ ಮನುಷ್ಯನು", lyrics: "1. ದುಱಖಿತ ಮನುಷ್ಯನು\nಎಂಬ ದೇವಮಗನು\nನನಗಾಗಿ ಸತ್ತನು :\nಹಲ್ಲೆಲೂಯ! ಎಂಥಾ ಕರ್ತ!\n2. ನಿಂದೆ, ಬಾಧೆ, ಶಿಕ್ಷೆಯ,\nನನಗಾಗಿ ತಾಳಿದ ;\nತನ್ನ ರಕ್ತ ಚೆಲ್ಲಿದ :\nಹಲ್ಲೆಲೂಯ! ಎಂಥಾ ಕರ್ತ !\n3. ದೋಷಪಾಪ ರಹಿತ\nಶಕ್ತಿಹೀನ ನನ್ನನ್ನ\nಪ್ರೀತಿಯಿಂದ ಎತ್ತಿದ.\nಹಲ್ಲೆಲೂಯ! ಎಂಥಾ ಕರ್ತ!\n4. ಶಿಲ್ಬೆಮೇಲೆ ದುಷ್ಟರು\nಆತನನ್ನು ಇಟ್ಟರು ;\nತೀರಿತೆಲ್ಲಾ ಅಂದನು :\nಹಲ್ಲೆಲೂಯ! ಎಂಥಾ ಕರ್ತ !\n5. ಸ್ವರ್ಗಲೋಕಕ್ಕೇರಿದ,\nತಂದೆ ಹತ್ರ ಸೇರಿದ,\nನನಗಾಗಿ ಬರುವ\nಹಲ್ಲೆಲೂಯ! ಎಂಥಾ ಕರ್ತ !\n6. ಆತ ಘನ ರಾಜನು ;\nಆತನೊಂದಿಗಿರ್ವೆನು.\nಸದಾಕಾಲ ಹಾಡ್ವೆನು :\nಹಲ್ಲೆಲೂಯ! ಎಂಥಾ ಕರ್ತ!" },
  12: { title: "ಕರ್ತಾ! ಯಾವ ರೀತಿಯಿಂದ", lyrics: "1. ಕರ್ತಾ! ಯಾವ ರೀತಿಯಿಂದ\nನಿನ್ನ ಸ್ತೋತ್ರ ಮಾಡೇನು?\nನಿನ್ನ ಕರುಣಾತಿಶಯ\nಬುದ್ಧಿ ಮಿಂಚಿಹೋದದ್ದು;\nನರರು ನಿನ್ ಕೃಪೆಯನ್ನು\nವಿವರಿಸಲಾರರು ;\nಹಲ್ಲೆಲೂಯ !\nನಿತ್ಯ ಸ್ತೋತ್ರ\nನಿನಗೆನ್ನ ತಂದೆಯೇ !\n2. ನಾನು ಕೆಟ್ಟ ಗುಣದಿಂದ\nಪಾಪಕ್ಕೊಳಗಾದೆನು ;\nನಿನ್ನಾಪಾರ ಕೃಪೆಯಿಂದ\nಪಶ್ಚಾತ್ತಾಪ ಪಟ್ಟೆನು ;\nಕರುಣಾ ಕಟಾಕ್ಷವುಳ್ಳ\nನಿನ್ನ ಹತ್ರ ಸೇರಿದೆ ;\nಹಲ್ಲೆಲೂಯ !\nನಿತ್ಯ ಸ್ತೋತ್ರ\nನಿನಗೆನ್ನ ತಂದೆಯೇ !\n3. ಪೂರ್ಣ ಅನುಗ್ರಹದಿಂದ\nನೀನು ನನ್ನ ನಡಿಸಿ,\nನಾನು ಹುಟ್ಟಿದಂದಿನಿಂದ\nಪ್ರೀತಿ ತೋರಿಸುತ್ತಿದ್ದೀ ;\nನಿನ್ನ ಪ್ರೀತಿಗಂತ್ಯವಿಲ್ಲ\nಓ ಮಹಾ ದಯಾಬ್ದಿಯೇ!\nಹಲ್ಲೆಲೂಯ !\nನಿತ್ಯ ಸ್ತೋತ್ರ\nನಿನಗೆನ್ನ ತಂದೆಯೇ !\n4. ನನ್ನ ಗುಣದ ಪರೀಕ್ಷೆ\nಮಾಡ ನೀನು ಯೋಚಿಸಿ,\nಆಗಿಂದಾಗ್ಯೂ ಕೃಪೆ ಶಿಕ್ಷೆ\nನನಗುಂಟು ಮಾಡುತ್ತೀ ;\nಅದೇನೀಗ ? ನಿನ್ನ ದಾಸ,\nನಿನ್ನ ಮಾತು ಕೇಳುವೆ ;\nಹಲ್ಲೆಲೂಯ !\nನಿತ್ಯ ಸ್ತೋತ್ರ\nನಿನಗೆನ್ನ ತಂದೆಯೇ !" },
  13: { title: "ಶಿಲ್ಬೆ ಮೃತಿ, ಯೇಸುವೇ,", lyrics: "1. ಶಿಲ್ಬೆ ಮೃತಿ, ಯೇಸುವೇ,\nನನ್ನ ಮೇಲಿಗಾಗಿಯೇ\nನೀನು ತಾಳ್ದರಿಂದಲೇ ;\nನಿನ್ನ ಭಜಿಸುವೆನು.\n2. ನಿನ್ನ ಘೋರ ಮೃತಿಯ,\nನಿನ್ನಾಪಾರ ದಯವ,\nತೋರಿಬಂದ ಪ್ರೀತಿಯ,\nನೋಡಿ ಭಜಿಸುವೆನು.\n3. ಅಂಧಕಾರ ಮುತ್ತಿತು.\nದಿವ್ಯ ರಕ್ತ ಚೆಲ್ಲಿತು.\nನನ್ನ ಪಾಪ ಮುಚ್ಚಿತು ;\nನಿನ್ನ ಭಜಿಸುವೆನು.\n4. ವೈರಿಯಿಂದ ಕಾಟವ,\nಜನರಿಂದ ಹಿಂಸೆಯ\nತಾಳಿ ಗೆದ್ದು ಬಂದಿದ್ದೀ ;\nನಿನ್ನ ಭಜಿಸುವೆನು.\n5. ಮೃತ್ಯುವಿನ ಕೊಂಡಿಯ\nಕಿತ್ತು ಗೋರಿ ಗೆಲ್ಲುವ\nನಿನ್ನ ಬಲ ನೋಡಿದ\nನಾನು ಭಜಿಸುವೆನು.\n6. ನಿನ್ನ ಮರಣವನ್ನು\nನಾ ಪ್ರಸಿದ್ಧಿ ಮಾಡ್ವೆನು\nನಿನ್ನ ಪ್ರೀತಿಸುವೆನು ;\nನಿನ್ನ ಭಜಿಸುವೆನು." },
  14: { title: "ರಾಜಾಧಿರಾಜನೇ!", lyrics: "1. ರಾಜಾಧಿರಾಜನೇ!\nಎನ್ನಾತ್ಮಾದರಣೆ !\nಸ್ತೋತ್ರಾರ್ಹನೇ !\nನಿನ್ ರಕ್ತದಿಂದಲೇ\nಪಾಪದ ಹೊರೆಯೇ\nಸಂಪೂರ್ಣ ಹೋಗಿದೆ,\nರಕ್ಷಕನೇ !\n2. ರಾಜಾಧಿರಾಜನೇ!\nಭಕ್ತರ ಮಿತ್ರನೇ!\nನೀ ಮಾತ್ರವೇ\nಹೃದಯ ಕಾಣಿಕೆ\nಹೊಂದಲು ಯೋಗ್ಯನೇ !\nಪ್ರೀತಿಗೆ ಪಾತ್ರನೇ!\nಎನ್ನೇಸುವೇ !\n3. ರಾಜಾಧಿರಾಜನೇ!\nನಿನ್ನಾಜ್ಞೆಯಂತೆಯೇ !\nನಾನೀಗಲೇ\nಸುಭಾವದಿಂದಲೂ\nದೀನತ್ವದಿಂದಲೂ\nನಿನ್ನ ಕೊಂಡಾಡ್ವೆನು,\nಅತ್ಯಾಪ್ತನೇ !\n4. ರಾಜಾಧಿರಾಜನೇ!\nಭಕ್ತರ ಗುರುವೇ!\nಕ್ರಿಸತ್ಯೇಸುವೇ !\nಸ್ತೋತ್ರದ ಬಲಿಯೇ\nನಿನ್ನವರಿಂದಲೇ\nದೇವಾಧಿದೇವನೇ,\nಹೊಂದೀಗಲೇ !" },
  15: { title: "ಯೇಸು ನಿನ್ನಾಮಸ್ಮರಣೆ", lyrics: "1. ಯೇಸು ನಿನ್ನಾಮಸ್ಮರಣೆ\nನನ್ನಾತ್ಮ ತುಂಬುತ್ತೆ ;\nನಿನ್ನ ಸಮ್ಮುಖ ಸೇರಲು\nನನ್ನಭಿಲಾಷೆಯೇ.\n2. ರಕ್ಷಕನೇ! ನಿನ್ನಾಮವು\nನಮ್ಮೆಲ್ಲರಲ್ಲಿಯೂ\nಅಮೂಲ್ಯವಾದ ರತ್ನವೇ,\nಶುದ್ಧಪರಂಜಿಯು.\n3. ಶುದ್ಧರಿಗೆ ನಿರೀಕ್ಷೆಯೇ,\nಭಕ್ತರಾನಂದವೇ ;\nಪಾಪಿಗೆ ದಿವ್ಯ ಶರಣ\nಶಾಂತಿದಾಯಕನೇ!\n4. ನಿನ್ನನ್ನರಸುವವರ್ಗೆ\nನೀನೆಂಥಾ ಮಿತ್ರನು ;\nಯಾರನ್ನೂ ತಳ್ಳದವನೇ\nಬಾ ಅನ್ನುವವನು\n5. ನಿನ್ನ ಹತ್ರ ಬಂದವರ್ಗೆ\nಹಿತವು ಏನಿದೆ ?\nಹೇಳಲಾಗದ ಭಾಗ್ಯವು\nಸಂಪ್ರಾಪ್ತಿಸುತ್ತದೆ.\n6. ಯೇಸು ನೀ ಮಾತ್ರ ಪಾಪಿಗೆ\nಸ್ವರ್ಗದ ಮಾರ್ಗವೇ ;\nನೀನೀಗ ನಮ್ಮ ಕೀರ್ತಿಯು\nನಿತ್ಯೆಮ್ಮಘನಮೆ" },
  16: { title: "ಕಾಲವು ಗತಿಸುತ್ತೆ,", lyrics: "1. ಕಾಲವು ಗತಿಸುತ್ತೆ,\nಎನ್ ಸ್ವಾಮಿ ಬರ್ವನು ;\nನಿರೀಕ್ಷೆಯಿಂದ ನಿತ್ಯ\nಎದುರು ನೋಡ್ವೆನು.\nಈ ಭೂಪ್ರಯಾಣದಲ್ಲಿ\nಕಣ್ಣೀರೆಷ್ಟಿದ್ದರೂ,\nಸ್ವರ್ಗ ಸಂತೋಷದಲ್ಲಿ\nಕಡೇಲಿ ಸೇರ್ವೆನು.\n2. ಕ್ರಿಸ್ತನು ನಿಜ ತೀರ್ಥ,\nಜೀವದ ಬುಗ್ಗೆಯು ;\nಹೌದಾತನಲ್ಲಿ ಮಾತ್ರ\nಸಂಪೂರ್ತಿ ಇರ್ವದು,\nನಾನಿಲ್ಲಿ ಆತನ್ ನಂಬಿ\nಆನಂದಗೊಳ್ಳುವೆ ;\nಆ ರಮ್ಯ ಲೋಕದಲ್ಲಿ\nಸಂತೃಪ್ತಿ ಹೊಂದುವೆ.\n3. ಸ್ವಾಮಿಯ ಲೋಕವೆಲ್ಲೂ\nಅಭಾವವಿಲ್ಲದ್ದು;\nಇಲ್ಲಿಂದ ಹೋಗಿಬಿಟ್ಟು\nನಿತ್ಯಲ್ಲಿ ಇರ್ವೆನು.\nನನ್ನನ್ನು ಪ್ರೀತಿಸುವ\nಎನ್ ಸ್ವಾಮಿ ಬರ್ವನು ;\nಆ ಲೋಕದಲ್ಲಿ ಆತ\nಸಂಪೂರ್ಣ ಕರ್ತನು.\n4. ಅಘೋರ ಶಿಲ್ಬೆಯಲ್ಲಿ\nದಯಾಳು ಕ್ರಿಸ್ತನು\nತನ್ನನ್ನು ಪಾಪ ಬಲಿ\nಅರ್ಪಿಸಿ ಕೊಟ್ಟನು ;\nಆತನು ಸ್ತೋತ್ರ ಹೊಂದ\nಅತ್ಯಂತ ಯೋಗ್ಯನೇ ;\nಎಂದೆಂದಿಗೂ ಕೊಂಡಾಡ\nಇಲ್ಲಿಂದ ಹೋಗುವೆ.\n5. ಘನ ಕಿರೀಟವಲ್ಲ\nಎನ್ ಸ್ವಾಮಿ ಮುಖವ\nನಾನೋಡಿ ಅಡ್ಡಬಿದ್ದು\nಕೊಂಡಾಡುವೆ ಸದಾ.\nಹಾ! ಗಾಯಪಟ್ಟ ಕರ್ತ\nಎನ್ನಾತ್ಮಾಧಾರವೇ ;\nಆ ದೇಶದ ಪ್ರಭಾವ\nಎನ್ ಕರ್ತ ಮಾತ್ರವೇ." },
  17: { title: "ಹಾ! ಜಜ್ಜಲ್ಪಟ್ಟ ಯೇಸು", lyrics: "1. ಹಾ! ಜಜ್ಜಲ್ಪಟ್ಟ ಯೇಸು\nಎಮ್ ಪ್ರಿಯ ಕರ್ತನೇ!\nನಿನ್ ಕಾಲು ಕೈಗಳನ್ನು\nಬಂದೀಗ ತೋರಿಸು,\nಯೆಹೋವ ನಿನ್ನ ಜಜ್ಜ\nಸಂತೋಷ ಪಟ್ಟನು ;\nನಾವಡ್ಡ ಬಿದ್ದು ನಿನ್ನ\nಆರಾಧಿಸುವೆವು.\n2. ಓ ಕರ್ತನಾದ ಯೇಸು\nನಿನ್ ಮೇಜಿನ ಮೇಲೆಯೇ\nಈ ರೊಟ್ಟಿ ಪಾತ್ರೆಯನ್ನು\nನೀ ಹರಸೆನ್ನಯ್ಯ ;\nನೀನೆಂಥಾ ದಿವ್ಯ ರೊಟ್ಟಿ\nನಿನ್ ಭಕ್ತರೆಲ್ಲರ್ಗೂ\nನಿನ್ನನ್ನು ಎಲ್ಲಾ ಕಾಲದಿ\nಸ್ತುತಿಸುವೆವು.\n3. ನಮ್ಮಾತ್ಮಗಳ ಮುಂದೆ\nಏನಾದ್ರೂ ಇದ್ದರೆ\nಅದನ್ನು ಹೋಗಮಾಡು\nನಿನ್ ಆತ್ಮನಿಂದಲೇ;\nನಿನ್ ಭೋಜನವನ್ನೀಗ\nಮಾಡಲು ಬಂದೆವು\nನಿನ್ ದಿವ್ಯ ಮುಖವನ್ನು\nಓ ಕರ್ತ ತೋರಿಸು.\n4. ಓ ಜೀವಾಧಾರನಾದ\nನಮ್ಮಾತ್ಮ ಪ್ರಿಯನೇ!\nನಿನ್ನ ನ್ನಿಧಿಯಲ್ಲಿ\nಸಂತೃಪ್ತಿ ಇರುತ್ತೆ ;\nಈಗ ನಿನ್ ಪ್ರೀತಿಯಿಂದ\nನಮ್ಮನ್ನು ತುಂಬಿಸು\nನಮ್ಮಲ್ಲಿ ನಿನ ವಾಕ್ಯವ\nನೆಲೆಗೊಳಿಸು." },
  18: { title: "ನೀ ಕೊಟ್ಟ ಭೋಜನದ", lyrics: "1. ನೀ ಕೊಟ್ಟ ಭೋಜನದ\nಈ ರೊಟ್ಟಿ ಪಾತ್ರೆಯೇ\nನಿನ್ನತಿಶಯ ಕೃಪೆಯ\nತೋರಿಸುತ್ತಿರುತ್ತೆ.\n2. ಪಾಪಿಗೆ ಬಂದ ಸಾವ\nತಾಳಿದ ರಾಜನೇ!\nಕ್ರೂಜೇಲಿಬಿಟ್ಟಿ ಪ್ರಾಣವ\nಓ ದಿವ್ಯ ಬಲಿಯೇ!\n3. ಈ ರೊಟ್ಟಿಯಲ್ಲಿ ನಾನು\nಪಾಲನ್ನು ಹೊಂದುವೆ ;\nನೀ ಜೀವ ರೊಟ್ಟಿ ನಂಗೂ\nನಾ ಹರ್ಷಗೊಳ್ಳುವೆ.\n4. ಈ ಪಾತ್ರೆ ನಿನ್ನ ರಕ್ತ\nಸೂಚಿಸುತ್ತಿರುತ್ತೆ ;\nಈ ರಕ್ತದಿಂದ ನನ್ ಪಾಪವ\nಸಂಪೂರ್ಣ ಮುಚ್ಚಿದೆ.\n5. ನಿನ್ನತಿ ಪ್ರೀತಿಯಲ್ಲಿ\nಸಂತೋಷಪಡುವೆ\nನಿನ್ ಮುಖವ (ನ್ನು) ನೋಡಲು\nಸಂತೃಪ್ತಿಯಾಗುತ್ತೆ.\n6. ನಾನಲ್ಲಿ ಸದಾಕಾಲ\nನಿನ್ನಂತೆ ಆಗುವೆ ;\nಅಮಿತ ನಿನ್ನ ಕೃಪೆ (ಯ)\nಕೊಂಡಾಡುತ್ತಿರುವೆ." },
  19: { title: "ಮುಳ್ಳು ಮುಡಿ ತಲೆಗೂ", lyrics: "1. ಮುಳ್ಳು ಮುಡಿ ತಲೆಗೂ\nಶಿಲ್ಬೆ ಬಾಧೆ ಮೈಯಲ್ಲೂ\nತಾಳಿಕೊಂಡೆ ಸ್ವಾಮಿಯೇ\nನನಗಾಗಿ ಅಲ್ಲವೇ ?\n2. ನನ್ನ ಭಾರ ಹೊತ್ತಿದ್ದೀ;\nನನ್ನ ಶಿಕ್ಷೆ ತಿಂದಿದ್ದೀ,\nಎಂಥಾ ಕಷ್ಟ ಬಾಧೆಯೇ\nಬಿತ್ತು ನಿನ್ನ ಮೇಲೆಯೇ.\n3. ನಿನ್ನ ಪರವಾಗಿಯೂ\nಯಾರೂ ನಿಲ್ಲಲಿಲ್ಲವು ;\nನೀನು ಅಲ್ಲಿ ಒಬ್ಬನೇ\nಹೊಣೆಯಾಗಿ ನಿಂತಿದ್ದೆ\n4. ತಂದೆಯಾದ ದೇವರು\nನಿನ್ನ ಬಿಟ್ಟು ಹೋದನು ;\nದ್ವೇಷ ಬಾಧೆ ಕತ್ತಲೂ\nಇವೇ ಮಾತ್ರ ಇದ್ದವು.\n5. ನನ್ನ ಪ್ರೀಯ ಕರ್ತನೇ\nನೀನೇ ನನ್ನ ಆಸರೆ ;\nನಿನ್ನ ಹಾಗೆ ಒಬ್ಬನೂ\nಎಲ್ಲೂ ಸಿಕ್ಕಲಾರನು.\n6. ಸ್ವಾಮಿಯೇ ಈ ಪ್ರೀತಿಗೆ\nಬದಲೇನು ಕೊಡಲಿ !\nರತ್ನ ಚಿನ್ನ ಕೊಟ್ಟರೂ\nಇದಕ್ಕೀಡು ಆಗದು." },
  20: { title: "ಲಕ್ಷಾಂತ್ರ ಧನವ", lyrics: "1. ಲಕ್ಷಾಂತ್ರ ಧನವ\nಅರ್ಪಿಸಿ ಕೊಟ್ಟರೂ\nಪಾಪಿಷ್ಠ ಮನಃಶುದ್ಧಿಯ\nಹೊಂದಲಿಕ್ಕಾಗದು.\n2. ಕ್ರಿಸ್ತ್ಯೇಸುವು ತಾನೇ\nಸಾಕಾದ ಯಜ್ಞವು ;\nಅಮೂಲ್ಯ ರಕ್ತದಿಂದಲೇ\nನಮ್ಮನ್ನು ಕೊಂಡನು.\n3. ನಿನ್ನನ್ನು ನಂಬುವೆ,\nಓ ದಿವ್ಯ ಹೊಣೆಯೇ!\nಅಘೋರವಾದ ಪಾಪಿಗೆ\nಆಶ್ರಯವು ನೀನೇ.\n4. ರಕ್ಷಣೆ ಮಾಡಿದ್ದೀ,\nಪ್ರಪಂಚಕ್ಕಾಗಿಯೇ ;\nನಮ್ಮಾತ್ಮ ದಾಪ್ತನಾಗಿದ್ದೀ,\nಓ ಪ್ರಾಣ ಪ್ರಿಯನೇ!" },
  21: { title: "ಓ ಪರಿಮಳ ನಾಮವೇ", lyrics: "1. ಓ ಪರಿಮಳ ನಾಮವೇ\nಕ್ರಿಸ್ಯೆಸು ಸ್ವಾಮಿಯು ;\nನಿರ್ಭಯ ಧೈರ್ಯಾದರಣೆ\nಈ ಒಳ್ಳೇ ಹೆಸರು.\n2. ಪಾಪಿಷ್ಠನಂತರ್ಗಾಯಕ್ಕೆ\nಮುಲಾಮು ಹಾಕುತ್ತೆ ;\nಆಯಾಸವುಳ್ಳ ಆತ್ಮಕ್ಕೆ\nವಿಶ್ರಾಂಿ ಕೊಡುತ್ತೆ.\n3. ಈ ನಾಮವೇ ವಿಶ್ವಾಸಿಗೆ\nಆಶ್ರಯ ಸ್ಥಾನವು ;\nನಾ ನಂಬಿಕೊಂಡೀ ದುರ್ಗವೇ\nಕೃಪಾಭಂಡಾರವು.\n4. ಎನ್ನರಸೇ, ಪ್ರವಾದಿಯೇ!\nಪ್ರಧಾನ ಯಾಜಕ !\nಎನ್ ದಿವ್ಯ ಕರ್ತ ! ನಿನಗೆ\nಅನಂತ ಶರಣ.\n5. ಎಂದೆಂದಿಗೂ ನಾ ಬಿಡೆನು\nನಿನ್ನಾಮಸ್ಮರಣೆ ;\nಎನ್ ರಾಗ ಸಾವಿನಲ್ಲಿಯೂ\nಈ ಶ್ರೇಷ್ಠ ಹೆಸರೇ." },
  22: { title: "ಆಶ್ಚರ್ಯವಾದ ಶಿಲುಬೆ", lyrics: "1. ಆಶ್ಚರ್ಯವಾದ ಶಿಲುಬೆ\nಕಣ್ಣಿಟ್ಟು ದೃಷ್ಟಿಸಿದರೆ,\nಈ ಲೋಕದ ಮಹತ್ವವು\nಬರೀ ಹುಚ್ಚಾಟವಾದದ್ದು\n2. ಎನ್ ಯೇಸು ಸ್ವಾಮಿ ಒಬ್ಬನೇ\nಅಮೂಲ್ಯ ರತ್ನ ನನಗೆ ;\nನಾನಾತನನ್ನು ಕಂಡರೆ\nಬೇರೆಲ್ಲಾ ಭಾಗ್ಯ ಶೂನ್ಯವೇ\n3. ದೇಹಾತ್ಮದಲ್ಲಿ ಆತನು\nಎಷ್ಟೋ ಸಂತಾಪ ಪಟ್ಟನು ;\nಇದೆಲ್ಲಾ ನನಗೋಸ್ಕರ\nಕಟಾಕ್ಷದಿಂದ ತಾಳಿದ.\n4. ಈ ದಿವ್ಯವಾದ ಪ್ರೀತಿಗೆ\nನಾ ಬದಲೇನು ಕೊಡುವೆ ?\nಸಂಪತ್ತು ಪ್ರಾಣ ಯಾವತ್ತು\nಕೊಟ್ಟಾಗ್ಯೂ ಇನ್ನು ಸಾಲದು." },
  23: { title: "ಎಲ್ಲರೂ ಅಡ್ಡ ಬೀಳಲಿ", lyrics: "1. ಎಲ್ಲರೂ ಅಡ್ಡ ಬೀಳಲಿ\nಗಂಭೀರ ನಾಮಕ್ಕೆ ;\nಕಿರೀಟವಿಟ್ಟು ಹಾಡಲಿ\n“ನೀ ಬಾಳು, ಯೇಸುವೇ!”\n2. ಇಮ್ಮಾನ್ವೇಲ್ ಪಟ್ಟ ಕಷ್ಟವು\nಎಷ್ಟೋ! ಓ ಸಭೆಯೇ!\nನಿರಂತ್ರವಾಗಾರ್ಭಟಿಸು\n“ನೀ ಬಾಳು, ಯೇಸುವೇ!”\n3. ಭೂಪರಸೈನ್ಯ ಕೊಡಲಿ\nಮಹತ್ತು ಕರ್ತಗೆ ;\nಸಾಷ್ಟಾಂಗ ಬಿದ್ದು ಕೂಗಲಿ\n“ನೀ ಬಾಳು, ಯೇಸುವೇ!”\n4. ನಾನಲ್ಲಿ ಕೂಡ, ಪ್ರಭುವೇ\nನಿನ್ನೊಂದಿಗಿರುವೆ ;\nಎಂದೆಂದಿಗೂ ನಾನ್ ಹಾಡುವೆ\n“ನೀ ಬಾಳು, ಯೇಸುವೇ!”" },
  24: { title: "ನನ್ನನ್ನು ಯೇಸುವೇ", lyrics: "1. ನನ್ನನ್ನು ಯೇಸುವೇ\nಸ್ನೇಹಿಸಿದ್ದೀ ;\nನಾನೇನು ನಿನಗೆ\nಸಲ್ಲಿಸಲಿ ?\nಪ್ರೀತಿಯ ಮಾಡುವೆ,\nದಾಸನಾಗಿರುವೆ,\nಹೃದಯ ಕಾಣಿಕೆ\nಅರ್ಪಿಸುವೆ.\n2. ಮೇಲಣ ಲೋಕದೊಳ್\nಆಳುತ್ತಿದ್ದೀ ;\nದೇವ ಸಮ್ಮುಖದೊಳ್\nಬೇಡುತ್ತಿದ್ದೀ ;\nನಿನ್ನ ವಿಜ್ಞಾಘನೆ\nಸಿದ್ದಿಯ ಕೊಡುತ್ತೆ\nಪಾಪಿಯ ಕೂಗಿಗೆ\nರಕ್ಷಕನೇ!\n3. ದಿನಾಲು ಕರ್ತನೇ\nಹತ್ರವಿದ್ದೀ ;\nಬೇಕಾದಾದರಣೆ\nಕೊಡುತ್ತಿದ್ದೀ ;\nನಿನ್ನನ್ನು ಬಿಡದೆ,\nಎಂದೆಂದೂ ನಂಬುವೆ,\nಸ್ಥಿರವಾಗಿರುವೆ,\nಜೀವಾಂತ್ಯಕ್ಕೆ.\n4. ದಿವ್ಯ ವಿಮೋಚಕ!\nಸದ್ಗುರುವೇ !\nಪಾಪಿಗೆ ಆಶ್ರಯ\nನೀ ಮಾತ್ರವೇ ;\nಸಾಷ್ಟಾಂಗವೆರಗಿ,\nನಿನ್ನನ್ನು ವಂದಿಸಿ\nನಿರಂತ್ರ ಸ್ತುತಿಸಿ,\nಸೇವಿಸುಮೆ" },
  25: { title: "ಪಲ್ಲವಿ", lyrics: "ಪಲ್ಲವಿ\nಜಯ, ಜಯ, ವಿಜಯ ಸ್ವಾಮಿಗೆ,\nಜಯ, ಜಯ, ವಿಜಯ ಕ್ರಿಸ್ತಗ,\nಜಯ, ಜಯ, ವಿಜಯ ಸ್ವಾಮಿಗೆ\nಜಯಶಾಲಿ ಯೇಸು ಸ್ವಾಮಿಯೇ" },
  26: { title: "ಪಾಪಾತ್ಮರು ಆತನ್ನ ಶಾತ್ಸಾರಗೈದರು,", lyrics: "1. ಪಾಪಾತ್ಮರು ಆತನ್ನ ಶಾತ್ಸಾರಗೈದರು,\nಈಗ ಸ್ವರ್ಗಪತಿಯಾದನು.\n2. ಕಿರೀಟ ಮುಳ್ಳಿನಿಂದ ಹೆಣೆದುಕೊಟ್ಟರು,\nಮಹಿಮಾ ಕಿರೀಟವಾಯಿತು.\n3. ಪಾಪಿಷ್ಠ ಮಿತ್ರನೆಂದು ಹೆಸರಿಟ್ಟು ನಕ್ಕರು,\nಆ ನಾಮ ಮಾನ ಹೊಂದಿತು.\n4. ವಿರೋಧಿಗಳಿಗಾಗಿ ಸ್ವಪ್ರಾಣ ಕೊಟ್ಟನು,\nಕರುಣಾ ಸಮುದ್ರನಾದನು.\n5. ಭೂಲೋಕದಲ್ಲಿ ಕಷ್ಟ ಸಹಿಸಿಕೊಂಡನು,\nಪರಲೋಕದರಾದನು.\n6. ಅಧೈರ್ಯಪಡದಿರು, ಓ ಕ್ರಿಸ್ತಭಕ್ತನೇ!\nರಾಜಾಧಿರಾಜ ಯೇಸುವೇ\n7. ಲೋಕಾಪವಾದವೇನು ? ತತ್ಕಾಲ\nಮಾತ್ರವೇ\nವಿಜಯದ ದಿನ ಬರುತ್ತೆ." },
  27: { title: "ಶುದ್ಧ ಶುದ್ಧ ಶುದ್ಧ", lyrics: "1. ಶುದ್ಧ ಶುದ್ಧ ಶುದ್ಧ\nಸರ್ವಶಕ್ತ ದೇವ!\nಹರ್ಷದಿಂದ ಹಾಡಿ\nಕೊಂಡಾಡಿಕೊಳ್ಳುವೆ ;\nಶುದ್ಧ ಶುದ್ಧ ಶುದ್ಧ\nಕೃಪಾಪೂರ್ಣ ಸಾಗ್ರ !\nಓ ತ್ರಯೈಕ ದೇವಾ\nಸ್ತುತಿ ನಿನಗೆ\n2. ಶುದ್ಧ ಶುದ್ಧ ಕರ್ತಾ !\nಪರಲೋಕ ಸೈನ್ಯ\nನಿನ್ನ ಮುಂದೆ ಬಿದ್ದು\nಆರಾಧಿಸುವದು ;\nನಾವು ಕೂಡ ಈಗ\nಏಕ ಚಿತ್ತದಿಂದ\nರಾಗವನ್ನು ಎತ್ತಿ\nಸ್ತುತಿಸುವವು.\n3. ನಿನ್ನ ಸುತ್ತು–ಮುತ್ತು\nಮೋಡ ಅಂಧಕಾರ\nವಸ್ತ್ರದಂತೆ ಬಂದು\nಅವರಿಸಿದರೂ,\nಶುದ್ಧ ನೀತಿ ಪ್ರೀತಿ\nನಿನ್ನಲ್ಲುಂಟು ನಿತ್ಯ\nನಿನ್ನ ಭಕ್ತರ್ಗೆಲ್ಲಾ\nಭೀತಿ ಇಲ್ಲವು.\n4. ಶುದ್ಧ ಶುದ್ಧ ಶುದ್ಧ\nಏಕ ಜಗನ್ನಾಥ!\nಸೇರಕೂಡದಂಥ\nಪ್ರಕಾಶದೊಳಿದ್ದೀ;\nನಿತ್ಯ ಘನ, ಮಾನ,\nಸರ್ವ ಸೃಷ್ಟಿಯಿಂದ\nನೀನು ಮಾತ್ರ ಹೊಂದ\nಯೋಗ್ಯನಾಗಿದ್ದೀ." },
  28: { title: "ಪಾಪಿಯಾದ ನನ್ನನ್ನು", lyrics: "1. ಪಾಪಿಯಾದ ನನ್ನನ್ನು\nಸ್ನೇಹಿಸಿದ ಯೇಸುವೇ !\nಘನ, ಮಾನ, ಸ್ತೋತ್ರವು\nನಿನ ಶ್ರೇಷ್ಠ ನಾಮಕ್ಕೆ\n2. ಪಾಪದ ಸಂಕೋಲೆಯ\nದಯದಿಂದ ಬಿಚ್ಚಿದ್ದೀ ;\nಘೋರವಾದ ಶಿಕ್ಷೆಯ\nಪರಿಹಾರ ಮಾಡಿದ್ದೀ.\n3. ಸಮಾಧಾನ, ನಂಬಿಕೆ,\nಪರಿಪೂರ್ಣಾನಂದವು\nನಿನ್ನ ರಕ್ತದಿಂದಲೇ\nನನಗೆ ಉಂಟಾದವು.\n4. ನಿಜವಾದ ಭಾಗ್ಯವ,\nಸ್ಥಿರವಾದ ಮಹಿಮೆ,\nನಿತ್ಯವಾದ ಜೀವವ,\nನಾ ನಿನ್ನಿಂದ ಹೊಂದುವೆ.\n5. ಪಾಪಿಯಾದ ನನ್ನನ್ನು\nಸ್ನೇಹಿಸಿದ ಯೇಸುವೇ!\nಘನ, ಮಾನ ಸ್ತೋತ್ರವು\nನಿನ ಶ್ರೇಷ್ಠ ನಾಮಕ್ಕೆ" },
  29: { title: "ನಿನ್ನ ಸ್ತೋಡ್ರ, ಯೇಸುವೇ,", lyrics: "1. ನಿನ್ನ ಸ್ತೋಡ್ರ, ಯೇಸುವೇ,\nಇಂದೂ ಎಂದೂ ಹಾಡುವೆ\nಸರ್ವಲೋಕದರಸಾ !\nನೀನು ನನ್ನ ರಕ್ಷಕ.\n2. ನಿನ್ನ ಆಜ್ಞೆಯಿಂದಲೇ\nಭೂಮಿಯಲ್ಲಿ ಹುಟ್ಟಿದೆ ;\nನಿನ್ನ ಆತ್ಮನಿಂದಲೇ\nಪುರ್ನಜನ್ಮ ಹೊಂದಿದೆ.\n3. ಶಾಪಗ್ರಸ್ತ ನನಗೆ\nನೀನು ಶಾಪ ತಾಳಿದೆ ;\nಸಾವ ಸಾವಿನಿಂದಲೇ\nಗೆದ್ದಿ ನನಗಾಗಿಯೇ\n4. ನಿನ್ನ ಘೋರ ಕಷ್ಟವು\nನನ್ನ ಸಮಾಧಾನವು\nನಿನ್ನ ಕ್ರೂರ ಮೃತ್ಯುವೇ\nನಿತ್ಯಜೀವ ನನಗೆ" },
  30: { title: "ಈವಾಗ ಭದ್ರ ಸ್ಮಾನಕ್ಕೆ", lyrics: "1. ಈವಾಗ ಭದ್ರ ಸ್ಮಾನಕ್ಕೆ\nತಂದಿಟ್ಟಿನನ್ನ ಲಂಗರ ;\nಆಧಾರ ಸ್ಥಿರ ನನಗೆ\nಕ್ರಿಸ್ತ್ಯೇಸುವಿನ ಮರಣ ;\nಭೂಪರಲೋಕ ಬಿದ್ದರೂ\nನಾನೆಂದೂ ಭಯಪಡೆನು ॥\n2 ಅಪಾರ ಪ್ರೀತಿ ಕಂಡೆನು,\nಸಂಪೂರ್ಣಾನಂದವಾಯಿತು ;\nಅನಂತ ದಯೆ ಸಿಕ್ಕಿತು\nವಿರಂತ್ರ ಹರ್ಷಿಸುವೆನು ;\nಅಘೋರ ಪಾಪವಿದ್ದರೂ\nದಿವ್ಯ ಕಟಸಾಕ್ಷ ಶಪ್ರದು ॥\n3. ಅಮೂಲ್ಯ ರಕ್ತ ಚೆಲ್ಲಿದ\nಪವಿಕ್ರನಾದ ಗುರುವೇ!\nಶಾಶ್ವತ ಶಾಂತಿ ಕೊಡುವ\nಸಾಮರ್ಥ್ಯವುಳ್ಳ ಕರ್ತನೇ!\nಅಮಿಕವಾದ ಕೃಪೆಯು\n4. ನಿನ್ನ ಮುಖಾಂತ್ರದಿಂದಲೇ\nನನ್ನಾಕ್ಮ ಕ್ಷೇಮ ಹೊಂದಿದೆ ;\nಓ ಪ್ರಾಣಪ್ರಿಯ ಯೇಸುವೇ!\nನಿನ್ನನ್ನು ಆಶುಕೊಳ್ಳುವೆ ;\nಭೂಪರಲೋಣ ಬಿದ್ದರೂ,\nನಾನೆಂದು ಭಯಪಡೆನು 1॥" },
  31: { title: "ಉಂಟೋ ನಿನಗೆ ಅಯಾಸ", lyrics: "1. ಉಂಟೋ ನಿನಗೆ ಅಯಾಸ\nಬೇಸರಿಕೆಯೂ ?\nಯೇಸುವಿನ ಹತ್ರ ಬಂದು\nತೀರಿಸು.\n2. ಅತನ್ನರಿಯುವ ಹಾಗೆ\nಏನು ಗುರುತು?\nಪಕ್ಕೆ ಕಾಲು ಕೈಗಳಲ್ಲಿ\nಗಾಯವು.\n3. ರಾಜನಂತೆ ಶಿರದಲ್ಲಿ\nಮುಕುಟವುಂಟೇ ?\nನಿಜವೇ, ಕಿರೀಟ ಉಂಟು\nಮುಳ್ಳಿಂದೇ\n4. ಅತ ಯಾವ ಬಹುಮಾನ\nಇಲ್ಲಿ ಕೊಟ್ಟನು ?\nಶಾನೆ ದುಱು, ಶಾನೆ ಕಷ್ಟ,\nಕಣ್ಣೀರು.\n5. ನನ್ನ ತಳ್ಳಿಬಿಟ್ಟಾನೇನೋ\nಹರಸೆನ್ನಲು ?\nಭೂಮ್ಯಾಕಾಶ ಬಿದ್ಹೋದಾಗ್ಯೂ\nತಳ್ಳಮ.\n6. ನಂಬಿ ಸೈರಿಸಿದವಂಗೆ\nಉಂಟೇ ಭಾಗ್ಯವು ?\nಉಂಟು ಎಂದು ದೇವ ವಾಕ್ಯ\nಅನ್ನತ್ತೆ." },
  32: { title: "ಓ ಕೃಪಾಸಂಪೂರ್ಣ ದಯಾಪರನೆ!", lyrics: "1. ಓ ಕೃಪಾಸಂಪೂರ್ಣ ದಯಾಪರನೆ!\nನಿನ್ನಾಮವು ಎಷ್ಟೋ ಅತ್ಯುತ್ತಮವೆ!\nಪ್ರಪಂಚವ ನೀನು ವಿಮೋಚಿಸಿದ್ದು\nಮಹಾ ಅತಿಶಯದ ಕರುಣೆಯು.\n2. ಸನ್ನ್ಯಾಯ ಪ್ರಮಾಣವ ನೋಡಿದರೆ,\nಪ್ರಣಾಜ್ಞೆ ನಿರ್ಣಯ ಸಂಪ್ರಾಪ್ತಿಸುತ್ತೆ;\nನಿನ್ನಾಶ್ಚರ್ಯವಾದ ಕಟಾಕ್ಷ ಒಂದೇ\nನನ್ನೊಳಗೆ ನಂಬಿಕೆ ಹುಟ್ಟಿಸುತ್ತೆ.\n3. ಹಾ! ಯೇಸು ಎಸ್ ದಿವ್ಯ\nವಿಮೋಚಕನು,\nಸ್ವರಕ್ತವ ಪಾಪಕ್ಕೆ ಚೆಲ್ಲಿದನು;\nಆ ರಕ್ತವು ನನಗೆ ಸಾಕಾದದ್ದು\nಎನ್ ಪಾಪದ ದೋಷವು ಹರಿಯಿಕು.\n4. ಓ ತಂದೆ ಕುಮಾರ ಪವಿತ್ರಾತ್ಮನೇ!\nಅತ್ಯಂತೋಪಕಾರಿ ಪಾಪಿಷ್ಠರಿಗೆ ;\nನಾ ಸಾಷ್ಟಾಂಗ ಬಿದ್ದು ಆರಾಧಿಸುವೆ\nಪ್ರೇಮಾಜ್ಧಿಯಾದಂಥ ದಯಾಳುವನ್ನೇ." },
  33: { title: "ನಾ ಪಾಪಿಯೇ ಹೌದು,", lyrics: "1. ನಾ ಪಾಪಿಯೇ ಹೌದು,\nಅಕ್ರಮಗಾರನೇ,\nಸ್ವನೀತಿ ಇಲ್ಲವು,\nನಾ ನರಕಪಾತ್ರನೇ\nಪಲ್ಲವಿ\nಯೇಸು ಸ್ವಾಮಿಯೇ !\nಹೊಣೆಯಾದನು ;\nಸಾಲವೆಲ್ಲಾ ಸಂದಿದೆ\nಕ್ರಿಸ್ಯೆು ೊಟ್ಟನು.\n2. ನಾ ಕೃಪೆಯಿಂದಲೇ\nರಕ್ಷಿಸಲ್ಪಟ್ಟೆನು,\nದೇವಕುಮಾರನೇ\nಉದ್ಧರಿಸಿದನು,\nಯೇಸು ಸ್ವಾಮಿಯೇ.\n3. ನಾ ಸಾಯುವಾಗಲು\nನಿರ್ಭಯವಾಗುತ್ತೆ ;\nಎನ್ಥತ್ರ ಶೂರನು\nಇದ್ದಾನೆ ಅಲ್ಲವೇ ?\nಯೇಸು ಸ್ವಾಮಿಯೇಒ\n4. ನಾ ಮೋಕ್ಷಕ್ರೇರಲು\nಎನ್ ರಾಗ ಯೇಸುವೇ;\nಕಿರೀಟ ಹೊಂದ್ವದು\nಅತನ ಕೃಪೆಯೇ\nಯೇಸು ಸ್ವಾಮಿಯೇ" },
  34: { title: "ಸ್ತೋತ್ರದಿಂದ ಹಾಡುವಾ", lyrics: "1. ಸ್ತೋತ್ರದಿಂದ ಹಾಡುವಾ\nತಂದೆ ಮಗ ಆತ್ಮನ,\nವೀಣೆಯಿಂದ ಆತನ್ನ\nಸ್ತುತಿ ಸ್ತೋತ್ರ ಮಾಡೋಣ\nಶಂತಿವಾದ್ಯದಿಂದಲೂ\nಪಿಳ್ಳಂಗೋವಿಯಿಂದಲೂ\nಪ್ರಭೆಯುಳ್ಳ ಸ್ವಾಮಿಗೆ\nಹಾಡಿ ಪಾಡಿ ಕೀರ್ತನೆ,\nಸ್ತೋತ್ರದಿಂದ ಹಾಡುವಾ\nತಂದೆ ಮಗ ಆತ್ಮನ\n2. ಭಕ್ತರೆಲ್ಲಾ ಹಾಡಿರಿ ;\nದೇವರಲ್ಲಿ ಹರ್ಷಿಸಿ\nನಾನಾ ವಾದ್ಯ ಬಾರಿಸಿ\nದೇವಸ್ತೋತ್ರ ಮಾಡಿರಿ\nಪೂರ್ಣ ಮನದಿಂದಲೂ\nತಾಳಮೇಳದಿಂದಲೂ\nಹೊಸರಾಗ ಎತ್ತಿರಿ ;\nಸರ್ವಕಾಲ ಪಾಡಿರಿ ;\nಸ್ತೋತ್ರದಿಂದ ಹಾಡುವಾ\nತಂದೆ ಮಗ ಆತ್ಮನು\nಸ್ವರ್ಗಲೋಕ ಸೈನ್ಯವೇ!\nಸರ್ವಲೋಕ ಪ್ರಜೆಯೇ !\nಚಿಕ್ಕ ಪ್ರಾಯದವರೇ!\nಪ್ರಾಯ ಹೋದ ಜನರೇ!\nಏಕ ಶಬ್ಧದಿಂದಲೇ\nಸ್ತೋತ್ರ ಹಾಡಿರೆಲ್ಲರೇ\nಸೂರ್ಯ ತಾರೆ ಚಂದ್ರರೇ!\nಹಾಡಿ, ಸರ್ವ ಸೃಷ್ಟಿಯೇ!\nಸ್ತೋತ್ರದಿಂದ ಹಾಡುವಾ\nತಂದೆ ಮಗ ಆತ್ಮನ." },
  35: { title: "ಶಾಂತ ಯೇಸುವೇ,", lyrics: "1. ಶಾಂತ ಯೇಸುವೇ,\nನಿನ್ನ ಹಾಗೆಯೇ\nಯಾರು ಸರ್ವಲೋಕದಲ್ಲಿ;\nಎಲ್ಲ ನರ ಪುತ್ರರಲ್ಲಿ\nಅತಿ ಶ್ರೇಷ್ಠನೇ\nಶಾಂತ ಯೇಸುವೇ!\n2. ನನ್ನ ಸಾಲವು\nಪೀಡೆ ಕೊಡಲು,\nನೀನು ದೊಡ್ಡ ಪ್ರೀತಿಯಿಂದ\nನನ್ನನ್ನೆಲ್ಲ ದೋಷದಿಂದ\nಶುದ್ಧಮಾಡಿದಿ\nಸಾಲ ಸಲ್ಲಿಸಿ.\n3. ಆದಿ ತೇಜನೇ,\nಪ್ರೀತಿಯಿಂದಲೇ\nನರರಲ್ಲಿ ನರನಾಗಿ\nನೀಚ ಶತ್ರು ಜನಕ್ಕಾಗಿ\nವಿನ್ನನ್ನರ್ಪಿಸಿ\nಯಜ್ಞಮಾಡಿದಿ!\n4. ದಿವ್ಯ ಶೂರನೇ,\nಮೃತಿಯೊಳಗೆ\nಸೇರಿ, ದುಷ್ಟ ಶತ್ರುವನ್ನು\nಜೈಸಿ ನಮ್ಮ ಶಿಕ್ಷೆಯನ್ನು\nಅನುಭವಿಸಿ,\nಮೇಲಕ್ಕೇರಿದಿ!\n5. ಸತ್ಪ್ರವಾದಿಯೇ,\nಸರ್ವರಾಜನೇ!\nನಿನ್ನ ಚಿತ್ತಕೊಪ್ಪುತ್ತೇನೆ :\nನಿನ್ನ ಶಿಷ್ಯನಾಗಿದ್ದೇನೆ,\nನಿನ್ನ ಪಾದವೇ\nಗತಿ ನನಗೆ.\nನಿನ್ನ ಸ್ತೋತ್ರ ಹಾಡುವೆ ;\nನಿನ್ನ ದಯ ನನಗೆ\nಎಷ್ಟಾಶ್ಚರ್ಯವಾಗಿದೆ !\nನಿನ್ನ ಚಿತ್ತದಿಂದಲೇ\nಇಹದಲ್ಲಿ ಹುಟ್ಟಿದೆ ;\nನಿನ್ನ ಕೃಪೆಯಿಂದಲೇ.\nಪರದಲ್ಲಿ ಸೇರುವೆ.\n2. ಪಾಪಿಗಳಿಗೋಸ್ಕರ\nತಾಳಿಕೊಂಡಿ ಶಾಪವ ;\nಜೀವ ಯಜ್ಞವರ್ಪಿಸಿ,\nಜೀವ ಉಂಟುಮಾಡಿದಿ ;\nಗೋರಿ ಗರ್ಭದೊಳಗೆ\nನೀನು ಸೇರಿದಾಗಲೇ\nಮರಣದ ಜಯವು\nಭಿನ್ನವಾಗಿ ಹೋಯಿತು.\n3. ನಿನ್ನ ದೇಹ, ಯೇಸುವೇ,\nಆತ್ಮಾಹಾರವಾಗಿದೆ,\nನಿನ್ನ ರಕ್ತ ಕರ್ತನೇ,\nಜೀವಪಾನ ನಮಗೆ ;\nಪ್ರಿಯ ಯೇಸು ಸ್ವಾಮಿಯೇ!\nನಿನ್ನ ಸ್ತೋತ್ರ ಮಾಡುವೆ ;\nನಿನ್ನ ದಯ ನನಗೆ\nಅತ್ಯವಶ್ಯವಾಗಿದೆ." },
  36: { title: "ಹ್ಯಾಗೆ ದಯವುಳ್ಳ ಯೇಸು", lyrics: "1. ಹ್ಯಾಗೆ ದಯವುಳ್ಳ ಯೇಸು\nನಿನ್ನ ಕೃಪೆ ಹಾಡಲಿ ?\nನಿನ್ನ ಪ್ರೀತಿಗೆ ತಕ್ಕಷ್ಟು\nಸ್ತೋತ್ರ ಹ್ಯಾಗೆ ಮಾಡಲಿ !\nನಾನು ಕುರುಡನ ಹಾಗೆ\nಮೋಸ ಮಾರ್ಗ ಹಿಡಿದೆ ;\nದಿನ ದಿನ ಜಾರಿಬಿದ್ದೆ\nನಾಶನದ ಹತ್ರಕ್ಕೆ\n2. ದೂರ ಹೋದೆ. ದೂರದಿಂದ\nನೀನು ನನ್ನ ಕರೆದಿ ;\nಕೃಪೆಯಿಂದ ನಿನ್ನ ಶಬ್ಧ\nಕೇಳ ಮನಸ್ಸು ಕೊಟ್ಟಿ;\nಇಂಥಾ ದಯವನ್ನು ಹೊಂದಿ,\nಪಶ್ಚಾತ್ತಾಪ ಪಟ್ಟಿನು :\nಅತಿ ತೀವ್ರವಾಗಿ ಓಡಿ,\nನಿನ್ನ ಹತ್ರ ಬಂದೆನು.\n3. ಈಗ ನನಗೆಷ್ಟು ಸುಖ.\nಎಷ್ಟಾನಂದವಾಯಿತು !\nದಿವ್ಯ ರಕ್ಷಕನ ಮುಖ\nನೋಡಿ ಎಷ್ಟೋ ತೃಪ್ತಿಯು !\nಸರ್ವ ಪಾಪ ಪರಿಹಾರ\nನನಗೆ ಉಂಟಾಯಿತು :\nಸ್ಥಿರವಾದ ಎಲ್ಲಾ ಭಾಗ್ಯ\nಅನುಭವಿಸಿದೆನು.\n4. ನಿನ್ನ ದಯವಿರುವಲ್ಲಿ\nನನಗೇನು ಭಯವು ?\nನೀನು ಕಾಯುತ್ತಿರುವಲ್ಲಿ\nನನಗೇನು ಚಿಂತೆಯು ?\nಜಯ ! ಜಯ ! ಹೆಚ್ಚೆಚ್ಚಾಗಿ\nನಿನ್ನ ರಾಜ್ಯ ಬರಲಿ ;\nಜಗದ್ರಕ್ಷಕಾ ! ಎಲ್ಲೆಲ್ಲಿ\nಸ್ತುತಿ ನಿನಗಾಗಲಿ." },
  37: { title: "ದಯವುಳ್ಳ ಯೇಸು ಕರ್ತಾ !", lyrics: "1. ದಯವುಳ್ಳ ಯೇಸು ಕರ್ತಾ !\nದಿವ್ಯವಾದ ಸ್ನೇಹಿತಾ !\nಅವಮಾನ,\nರಕ್ತಸ್ನಾನ,\nನನಗಾಗಿ ಹೊಂದಿದಿ.\n2. ಅತಿ ದುಖು, ಅತಿ ಭೀತಿ\nದುಷ್ಟರಿಂದ ತಾಳಿದಿ ;\nನಿನ್ನ ದುಚಖು\nನನ್ನ ಸುಖ,\nದೇವರ ಕುಮಾರನೇ !\n3. ನಿನ್ನ ಕಷ್ಟವಾದ ಸಾವು\nನನ್ನ ನಿತ್ಯಜೀವವು ;\nಘನ ಮಾನ,\nನಿತ್ಯ ರಾಜ್ಯ,\nನೀನು ಹೊಂದ ಯೋಗ್ಯನು." },
  38: { title: "ಜೀವಕಾಂತಿಯನ್ನು ಬಿಟ್ಟು", lyrics: "1. ಜೀವಕಾಂತಿಯನ್ನು ಬಿಟ್ಟು\nರಕ್ತಮಯ ಯೇಸುವೇ!\nಮುಳ್ಳಿನ ಕಿರೀಟ ತೊಟ್ಟು\nಗಾಯವಾದ ತಲೆಯೇ!\nದ್ವೇಷವೆಷ್ಟು॥ ನಿಂದ ಎಷ್ಟು ॥" },
  39: { title: "ನಿನ್ನ ಪ್ರೀತಿ ಕರ್ತನೇ", lyrics: "1. ನಿನ್ನ ಪ್ರೀತಿ ಕರ್ತನೇ\nಜ್ಲಞಪ್ತಿ ಮಾಡುವದಕ್ಕೆ\nಬಂದಿದ್ದೇವೆ, ಯೇಸುವೇ!\n2. ನಿನ್ನ ನಾಮ ಸ್ಮರಣೆ,\nನಮಗೆ ಆದರಣೆ,\nಜೀವವುಳ್ಳ ಕರ್ತನೇ !\nಕರ್ತನ ಭೋಜನ\n2. ನೀನು ಅತ್ತ ಕಾರಣವೇನು ?\nನನ್ನ ದುಷ್ಟ ಪಾಪವೇ ;\nನೀನು ಸತ್ತು ಹೋದದ್ದೇನು ?\nನನಗಿದ್ದ ಶಾಪವೇ ;\nದುಖದಲ್ಲಿ ॥ ರಕ್ತ ಚೆಲ್ಲಿ ॥\nಜೀವಕೊಟ್ಟಿ ನನಗೆ ॥\n3. ಏಕೆ ನಿನ್ನ ಮೇಲೆ ಕಷ್ಟ\nದುಖು ಶ್ರಮೆ ಬಿದ್ದವು ?\nನಿತ್ಯನನ್ನು ಜೀವನಷ್ಟ\nಏಕೆ ಹಿಡುಕೊಂಡಿತು?\n4. ನಿನ್ನ ಶುದ್ಧ ರಕ್ತದಿಂದ\nನನ್ನ ಪಾಪ ಹೋಯಿತು.\nನಿನ್ನ ಆತ್ಮ ಶಕ್ತಿಯಿಂದ\nಎಲ್ಲಾ ಕಾರ್ಯ ಸಾಧ್ಯವು !\nಕಡೆಯಲ್ಲಿ ॥ ನೀನಿದ್ದಲ್ಲಿ ॥\nನಾನು ಸೇರುವವನು 11\nಕರ್ತನ ಭೋಜನ\n3. ರೊಟ್ಟಿ ಉಣ್ಣುವಾಗಲು\nನಿನ್ನ ಸಾವು ನೆನಪು\nಮನದಲ್ಲಿ ಹುಟ್ಟಿಸು.\n4. ದ್ರಾಕ್ಷಾರಸ ಹೊಯ್ಯಲು\nನೀನು ರಕ್ತ ಚೆಲ್ಲಿದ್ದು\nಜ್ಲಪ್ತಿ ಮಾಡ ಬೋಧಿಸು.\nಕರ್ತನ ಭೋಜನ\n5. ಲೋಕದ ವಿಮೋಚಕ!\nನೀನು ನಮ್ಮ ರಕ್ಷಕ\nನಿತ್ಯವಾದ ಆಶ್ರಯ.\n6. ನೀನು ನಮ್ಮ ಭಾಗ್ಯವು\nಪಾಪದೋಷ ಹೋಯಿತು,\nಮೋಕ್ಷಾನಂದ ನಮ್ಮದು." },
  40: { title: "ತನ್ನನ್ನು ಪ್ರಿಯ ಯೇಸುವು", lyrics: "1. ತನ್ನನ್ನು ಪ್ರಿಯ ಯೇಸುವು\nಅರ್ಪಿಸಿಕೊಟ್ಟ ಇರುಳು\nಕೈಯಲ್ಲಿ ರೊಟ್ಟಿ ತೆಗೆದು,\nತನ್ನಾಶೀರ್ವಾದ ಕೊಟ್ಟನು.\n2. ಈ ರೊಟ್ಟಿ ನನ್ನ ದೇಹವು\nನಿಮ್ಮ ನಿಮಿತ್ತ ಮುರಿದ್ದು;\nನನ್ನನ್ನು ಜ್ಲಪ್ತಿ ಮಾಡಲು\nಭೋಜನ ಮಾಡಿರೆಂದನು.\n3. ಆ ಮೇಲೆ ಆತ ಹೇಳಿದ್ದು\nಈ ಪಾತ್ರೆ ನನ್ನ ರಕ್ತವು,\nಪಾಪಾರ್ಥಕ್ಕಾಗಿ ಚೆಲ್ಲಿದ್ದು\nಪಾನವ ಮಾಡಿ ಎಲ್ಲರೂ.\n4. ಓ ಯೇಸು ! ನಿನ್ನ ಆಜ್ಞೆಯ\nಕೈಕೊಳ್ಳ ಶಕ್ತಿ ಕೊಡೀಗ ;\nಸ್ವಮುಖವನ್ನು ತೋರಿಸು,\nನಮ್ಮನ್ನು ಆಶೀರ್ವದಿಸು.\nಕಾಣಿಕೆ" },
  41: { title: "ಕ್ರಿಸ್ತೇಸು ಸ್ವಾಮಿಯು", lyrics: "1. ಕ್ರಿಸ್ತೇಸು ಸ್ವಾಮಿಯು\nಪಾಪಿಷ್ಟರ್ಗಾಗಿಯೇ\nಸ್ವಪ್ರಾಣ ಕೊಟ್ಟು ಬಿಟ್ಟನು ;\nವಿಮೋಚಕಾತನೇ.\n2. ಹಾ ! ಗಾಯಪಟ್ಟನು\nಪ್ರೇಮಾಬ್ದಿ ಕರ್ತನು ;\nಈ ರೊಟ್ಟಿ ಉಣ್ಣುವಾಗಲು\nಆ ಗಾಯ ಧ್ಯಾನಿಸು.\n3. ದ್ರಾಕ್ಷೆಯ ರಸವ\nಪಾನವ ಮಾಡಲು,\nಕ್ರಿಸ್ೇಸು ರಕ್ತ ಚೆಲ್ಲಿದ\nಪ್ರೀತಿಯ ನೆನಸು.\n4. ಈ ಮೇಜ ಸೇರಲು\nಅಯೋಗ್ಯರಾದರೂ\nಕ್ರಿಸ್ತ್ಯೈಸು ಕೊಟ್ಟ ಯಜ್ಞವು\nಸಂಪೂರ್ಣವಾದದ್ದು\n5. ಕ್ರಿಸ್ತ್ಯೇಸು ನಾಮವ\nನಾವೀಗ ಸ್ತುತಿಸಿ,\nಕೊಂಡಾಡಿ ಗಾನ ಮಾಡುವ\nಇಂಪಾಗಿ ಹಾಡುತ.\nಕಾಣಿಕೆ" },
  42: { title: "ದೇವರಾಶೀರ್ವಾದದಿಂದ", lyrics: "1. ದೇವರಾಶೀರ್ವಾದದಿಂದ\nಬಾಳೂ ಸೊತ್ತೂ ಸಿಕ್ಕುತ್ತೆ;\nನನ್ನ ಸ್ವಂತ ಯತ್ನವೆಲ್ಲಾ\nಪೂರ್ಣವಾಗಿ ವ್ಯರ್ಥವೇ ;\nಬುದ್ಧಿ ಬಲ ಕಾಲ ಸೊತ್ತು\nಕರ್ತ ತಾನೇ ಕೊಟ್ಟನು ;\nಯಾವುದನ್ನೂ ಸ್ವಂತವೆಂದು\nಎಂದೂ ಹೇಳಲಾರೆನು.\n2. ಹತ್ತರಲ್ಲಿ ಒಂದು ಅಂಶ\nದೇವ ಭಾಗವಾಗಿದೆ.\nಹೀಗೆ ಕೊಡುವಂತೆ ಆತ\nಆಜ್ಞೆ ಮಾಡಲಿಲ್ಲವೇ ?\nಮನಃಪೂರ್ತಿಯಾಗಿ ನಾನು\nಅಷ್ಟು ಕೊಡತಕ್ಕದ್ದೇ ;\nದೇವ ಕಟ್ಲೆಯನ್ನು ಎಂದೂ\nಮೀರಬೇಡ, ಮನವೇ !\n3. ದೇವರಾಜ್ಯ ಬಲಗೊಳ್ಳ\nಚಿಂತೆಯುಂಟೋ ನಿನಗೆ ?\nಇದಕ್ಕಾಗಿ ಹಣ ತ್ರಾಣ\nಕೊಡಬೇಕು ತಪ್ಪದೆ ;\nಎಲ್ಲವನ್ನು ಕರ್ತಗಾಗಿ\nಕೊಡಬೇಕು ನ್ಯಾಯವೇ ?\nಸ್ವಲ್ಪ ಭಾಗ ಆತಗಾಗಿ\nಕೊಡುವದಕ್ಕಾಗದೆ ?\n4. ದೇವರೆಂದೂ ಲೋಭಿಯನ್ನ\nಮೆಚ್ಚಿಕೊಳ್ಳಲಾರನು ;\nನ್ಯಾಯವಾಗಿ ಕೊಟ್ಟವನ್ನ\nಆಶೀರ್ವದಿಸುವನು ;\nಹೇರ್ಳವಾಗಿ ಕೊಡುವವ\nನಷ್ಟ ಹೊಂದಲಾರನು ;\nಹೆಚ್ಚು ಮೇಲು ದೇವರಿಂದ ನಿಜವಾಗಿ\nಹೊಂದ್ವನು." },
  43: { title: "ಒಂದು ದಿನ ಕರ್ತ ಯೇಸು ನಿಂತು", lyrics: "1. ಒಂದು ದಿನ ಕರ್ತ ಯೇಸು ನಿಂತು\nನೋಡುತ್ತಿದ್ದನು ;\nಕಾಣಿಕೆ\nತಮ್ಮ ಕಾಣಿಕೆಗಳನ್ನು ಜನ ಹಾಕುತ್ತಿದ್ದರು\nಅವರಲ್ಲಿ ಮುಖ್ಯವಾಗಿ\nಬಡನಾಥೆಯಾದ ಸ್ತ್ರೀ\nತನಗಿದ್ದದ್ದೆಲ್ಲಾ ತಂದು ಕೊಟ್ಟಳು\nಸಂತೋಷದಿ.\n2. ಕರ್ತ ಈಕೆಯನ್ನು ನೋಡಿ ಮೆಚ್ಚಿ\nಬಡ ವಿಧವೆ\nಬೇರೆ ಎಲ್ಲರ್ಗಿಂತ ಹೆಚ್ಚು ಕೊಟ್ಟಿದ್ದಾಳೆ\nಕಾಣಿಕೆ ಎಂದ್ದೇಳಿದ. ಅವಳಂತೆ\nನಮಗಿರ್ವದೆಲ್ಲವ\nಕರ್ತ ಸೇವೆಗಾಗಿ ಕೊಟ್ಟು ಮೆಚ್ಚಿಕೆಯ\nಹೊಂದುವ.\n3. ಕರ್ತ ಬೇಗ ಬರುತ್ತೇನೆ ಎಂದು\nಹೇಳಿ ಹೋದನು.\nನಿಮ್ಮ ಕಾರ್ಯದ ಪ್ರಕಾರ ಪ್ರತಿಫಲ\nತರ್ವನು\nಆತನ್ ಬೊಕ್ಕಸಕ್ಕೆ ತನ್ನಿ ಕೊಡತಕ್ಕ\nಪಾಲನ್ನೇ ಆತನ್ ಶ್ರೇಷ್ಠ ಮುಖ\nನೋಡಿ ಪೂರ್ಣ ತೃಪ್ತಿಯಾಗುತ್ತೆ" },
  44: { title: "ಪಾಪಿಗಾಗಿ ಸತ್ತ ಯೇಸು", lyrics: "1. ಪಾಪಿಗಾಗಿ ಸತ್ತ ಯೇಸು\nಮೇಘದೊಳು ಬರುವ ;\nತನ್ನ ಕೂಡ ತರುವನು\nಸಾವಿರಾರು ದೂತರ,\nಹಲ್ಲೆಲೂಯ 11\nಕ್ರಿಸ್ತ ಪುನಃ ಬರುಮ\n2. ಪಂಚ ಗಾಯ ಕಾಣುವವು\nತೇಜಃಪುಂಜ ದೇಹದಿ\nಆಗ ಹರ್ಷ ಪಡುವರು,\nಮುಕ್ತರೆಲ್ಲ ನಿತ್ಯದಿ.\nಜಯಚಿನ್ಥೆ ॥\nನೋಡಿ ಹರ್ಷಿಸುವರು.\n3. ಕ್ರಿಸ್ತ! ಪೀಠವೇರಿಕೊಂಡು\nಶತ್ರುವನ್ನು ಜಯಿಸು ;\nಸರ್ವಬಲ ಮಾನಹೊಂದು\nಭಜಿಸಲು ಸರ್ವರು.\nಹಲ್ಲೆಲೂಯ 11\nರಾಜ್ಯವನ್ನು ನಡಿಸು." },
  45: { title: "ಯೇಸುವು ತಿರಿಗಿ ಬರುವನು!", lyrics: "1. ಯೇಸುವು ತಿರಿಗಿ ಬರುವನು!\nನಮಗೆ ಮಾತನ್ನು ಕೊಟ್ಹೋದನು\nಯಾರಾತನ್ನಂಬಿ ಸತ್ಹೋಗಿದ್ದರೂ\nಒಂದಿಗೆ ತರುವನು.\nಪಲ್ಲವಿ\nಯೇಸುವು ತಿರಿಗಿ ಬರುತ್ತಾನೆ\nತಿರಿಗಿ ಬರುತ್ತಾನೆ\nಸಮಸ್ತ ಜನಕ್ಕೆ ಸಾರೋಣವು\nತಿರಿಗಿ ಬರುತ್ತಾನೆ.\n2. ಯೇಸುವು ತಿರಿಗಿ ಬರುವನು,\nನಮ್ಮನ್ನು ಮೇಲಕ್ಕೆ ಎತ್ತುವನು,\nಕ್ರಿತನ ಪುನರಾಗಮನ\nಪ್ರಿಯರ ಕೂಡ ನಾವಿರುವೆವು.\nಕರ್ತನ ಜೊತೆಯಲ್ಲೂ\n3. ಯೇಸುವು ತಿರಿಗಿ ಬರುತ್ತಾನೆ ;\nಸಿದ್ಧರಾಗಿರ್ರಿ ಸಹೋದರರೇ ;\nನಂಬಿಕೆ ಶುದ್ಧತ್ವ ಕೇಳುತ್ತಾನೆ\nತನ್ನ ಸ್ವಜನರಲ್ಲೇ.\n4. ಆಗಲಿ ಕರ್ತನಾದೇಸುವೇ! ಬಾ\nಪೂರ್ಣ ವಿಮೋಚನೆ ಲೋಕಕ್ಕೆ ತಾ\nನಿನ್ನನ್ನು ಸಂಧಿಸಿ ಘನವೆಲ್ಲಾ\nನಿನಗೆ ಸಲ್ಲಿಸುವಾ." },
  46: { title: "ಸಮಾಧಿಯೊಳಗೆ", lyrics: "1. ಸಮಾಧಿಯೊಳಗೆ\nಈ ದೇಹ ಬೀಳುತ್ತೆ,\nಮಣ್ಣಾಗಿ ಹೋಗಿ ಹುಳಕ್ಕೆ\nಆಹಾರವಾಗುತ್ತೆ.\n2. ಆದಾಗ್ಯೂ, ಮೃತ್ಯುವು\nಎಂದೆಂದೂ ಜೈಸದು;\nಸದ್ಭಕ್ತನನ್ನು ಗೋರಿಯು\nನಶಿಸಲಾರದು.\n3. ಸಮಾಧಿ ಜೈಸಿದ\nಕ್ರಿಸ್ಯೈೆಸು ಬರಲು,\nಹೂಣಿಟ್ಟ ನಮ್ಮ ದೇಹವ\nರೂಪಾಂತ್ರ ಮಾಡ್ವನು." },
  47: { title: "ಯೇಸು ಕರ್ತನೆದ್ದನು,", lyrics: "1. ಯೇಸು ಕರ್ತನೆದ್ದನು,\nಹಲ್ಲೆಲೂಯ !\nಮೃತ್ಯು ಸೋತು ಹೋಯಿತು\nಹಲ್ಲೆಲೂಯ !\nಜೀವ ಸಾವಿಂದ್ಥುಟ್ಟಿದೆ\nಹಲ್ಲೆಲೂಯ !\nಜಯಪ್ರದ ಕ್ರಿಸ್ತಗೆ\nಹಲ್ಲೆಲೂಯ !\n2. ಲೋಕರಕ್ಷಕಾತನೇ,\nಹಲ್ಲೆಲೂಯ !\nನಂಬಿರೆಲ್ಲಾ ಜನರೇ\nಹಲ್ಲೆಲೂಯ !\nಪಾಪ ಹರಿಸಿದನು,\nಹಲ್ಲೆಲೂಯ !\nನಿತ್ಯ ಭಾಗ್ಯ ಕೊಡ್ವನು,\nಹಲ್ಲೆಲೂಯ !\n3. ನಮ್ಮ ದಿವ್ಯ ಅರಸು,\nಹಲ್ಲೆಲೂಯ !\nಸ್ತೋತ್ರ ಹೊಂದ ಯೋಗ್ಯನು,\nಹಲ್ಲೆಲೂಯ !\nನಮಸ್ಕಾರ ಮಾಡಿರಿ,\nಹಲ್ಲೆಲೂಯ!\nರಾಗ ಎತ್ತಿ ಹಾಡಿರಿ,\nಹಲ್ಲೆಲೂಯ !\nಪುನರುತ್ಥಾನ" },
  48: { title: "ಘಟ್ಯಾದ ಬಂಡೆಯಲ್ಲಿ", lyrics: "1. ಘಟ್ಯಾದ ಬಂಡೆಯಲ್ಲಿ\nಸಮಾಧಿ ಒಡೆದು,\nಅಮೂಲ್ಯ ಬೀಜವಲ್ಲಿ\nಯೋಸೇಫನಿಟ್ಟನು,\nಆ ಗೋರಿ ಲೋಕದಲ್ಲಿ\nವಿಶೇಷವಾದದ್ದು\nಆ ಬೀಜ ಭೂಮಿಯಲ್ಲಿ\nಉತೃಷ್ಟವಾದದ್ದು\n2. ತೃತೀಯ ದಿನದಲ್ಲಿ\nಉದಯವಾಗಲು,\nಆ ಬೀಜ ಭೂಮಿಯಿಂದ\nಉತ್ಪತ್ತಿಯಾಯಿತು ;\nಆ ದಿನದಲ್ಲಿ ಜೀವ\nಸಾವಿಂದ ಹುಟ್ಟಿತ್ತು\nಆ ದಿನದಲ್ಲಿ ಸಾವು\nಸತ್ಹೀನವಾಯಿತು.\n3. ಸಮಾಧಿಯಲ್ಲಿ ಸೇರಿ,\nಓ ಯೇಸು ಕ್ರಿಸ್ತನೇ\nನೀ ಜೀವಮಾರ್ಗವನ್ನು\nಪ್ರಸಿದ್ಧ ಮಾಡಿದೆ.\nನಿನ್ನಲ್ಲಿ ದೃಢವಾಗಿ ವಿಶ್ವಾಸಿಸಿದರೆ ;\nಸಮಾಧಿಯಲ್ಲಿ ಸೇರ\nನಾನಂಜದಿರುವೆ.\n4. ಈ ದೇಹಕ್ಕೆ ಸಮಾಧಿ\nವಿಶ್ರಾಂತಿ ಸ್ಥಳವು ;\nನನ್ನಾತ್ಮವಾಚೆ ದಾಟಿ,\nಉಜ್ಜೀವಿಸುವದು ;\nನೀ ಮೃತ್ಯುವಿನ ಶಕ್ತಿ\nಮೇಲ್ಗೊಂಡಿ, ಕರ್ತನೇ\nನಾನೂ ನಿನ್ನಲ್ಲಿ ನಂಬಿ,\nವಿಜಯ ಹೊಂದುವೆ.\nಪುನರುತ್ಮಾನ" },
  49: { title: "ಹೌದೌದು ನಿಜವೇ,", lyrics: "1. ಹೌದೌದು ನಿಜವೇ,\nಕ್ರಿಸತ್ಯೈಸು ಎದ್ದನು,\nಮಹತ್ತಿನಿಂದಲೇ\nಸಮಾಧಿ ಬಿಟ್ಟನು ;\nರಾಗೆತ್ತುವ !\nಪಿಶಾಚನು\nಸೋತ್ಹೋದನು,\nಜಯೋತ್ಸವ !\n2. ವಿಮುಕ್ತ ಗಣವು\nಇಂಪಾಗಿ ಬಾರಿಸಿ,\nಪ್ರಧಾನ ದೂತರು\nಸಾಷ್ಟಾಂಗವೆರಗಿ\n“ಬಾಳೆಂದಿಗೂ\nಓ ಪ್ರಭುವೇ!\nನೀ ಯೋಗ್ಯನೇ,\"\nಇಂತೆಂದರು." },
  50: { title: "ದಿವ್ಯಾಶೀರ್ವಾದದ ಮಳೆ", lyrics: "1. ದಿವ್ಯಾಶೀರ್ವಾದದ ಮಳೆ\nಇಳಿಯ ಮಾಡುವೆನು\nಎಂಬ ವಿಶೇಷದ ವಾರ್ತೆ\nಮನನ ಮಾಡಿಪ್ಪೆನು.\nಪಲ್ಲವಿ\nಆ ದಿವ್ಯ ಮಳೆ\nಇಳಿಯ ಮಾಡಲೀಗ\nಪ್ರಾರ್ಥನೆ\n3. ಮನುಷ್ಯ ಮಕ್ಕಳೇ!\nಸಂಗೀತ ಹಾಡಿರಿ,\nರಕ್ಷಣ ಬಾಧ್ಯರೇ\nಆನಂದ ಪಡಿರಿ,\nನೀವೆಲ್ಲರೂ\n“ಓ ಪ್ರಭುವೇ!\nನೀ ಯೋಗ್ಯನೇ,\nಬಾಳೆಂದಿಗೂ.”\n4. ಕರ್ತಾದಿ ಕರ್ತನೇ!\nನಮ್ಮನ್ನು ಎಬ್ಬಿಸಿ,\nಸ್ವಹಸ್ತದಿಂದಲೇ\nಕಿರೀಟ ಕೊಡುವಿ ;\nಎಂದೆಂದಿಗೂ\n““ಓ ಪ್ರಭುವೇ\nನೀ ಯೋಗ್ಯನೇ\"\nಹಾಡುವೆವು.\nಪ್ರಾರ್ಥನೆ\nನಿನ್ನನ್ನು ಕೇಳುವೆ, ತಂದೆ,\nನನ್ನನ್ನಾದರಿಸಯ್ಯಾ.\n2. ಮಳೆಯ ದೊಡ್ಡ ಸುಶಬ್ದ\nಅಲ್ಲಲ್ಲಿ ಕೇಳಿಸುತ್ತೆ ;\nನಮಗೆ ಹನಿಯು ಮಾತ್ರ\nಮೆಲ್ಲಗೆ ಬೀಳುತ್ತದೆ.\n3. ದಿವ್ಯ ವಾಗ್ದಾನಗಳನ್ನು\nಕೃಪೆಯಿಂ ಪಾಲಿಸಿದ್ದೀ\nಪ್ರಾರ್ಥನೆ ಕೇಳುವೆನೆಂದು\nಧೈರ್ಯವ ಹುಟ್ಟಸಿದ್ದೀ.\nಪ್ರಾರ್ಥಣ\nನನ್ನಿಂದ ಮಳೆಯ ಕೇಳು\nಮಳೆಯ ಕೊಡುವೆನು\nಎಂಬ ಸುವಾಗ್ತ್ತವನ್ನು\nತಂದೆಯೇ, ನಂಬುವೆನು.\n5. ನಿನ್ನ ಸುಕರುಣೆಯಿಂದ\nಅಲ್ಪನ ಪ್ರಾರ್ಥನೆಯ\nಲಾಲಿಸಿ ಉತ್ತರವನ್ನು\nಪಾಲಿಸಿ ನಡಿಸಯ್ಯಾ" },
  51: { title: "ದೇವ್ರ ಮುಂದೆ ಪ್ರಾರ್ಥನೆ", lyrics: "1. ದೇವ್ರ ಮುಂದೆ ಪ್ರಾರ್ಥನೆ\nಮಾಡ್ವ ಕಾಲವಿದು;\nದೀವರಾಗಿಲ್ಲಿ ಕೂಡಿ\nಬೀರಿಕೊಳ್ನೆವು\nದೃಢವಾದ ಮನಸ್ತು\nಇರಲಗತ್ಯವ್ು\nಪ್ರಾರ್ಥವಾಸಕ್ತಿಯಿಂದ\nಮಸ್ತ್ತಿ ಆಗ್ವದು." },
  52: { title: "ರೇವ್ರ ಮುಂದೆ ಪ್ರಾರ್ಥನೆ", lyrics: "1. ರೇವ್ರ ಮುಂದೆ ಪ್ರಾರ್ಥನೆ\nಮಾಡ್ಯ ಕಾಲನಿದು\nಪ್ರಾಣಸ್ರಿಯ ರಕ್ಕ್ಷ\nಸೋಶಸ್ಯು\nಸವಸ್ಯಗ ಕೇಳ್ಯನು,\nಉತ್ರ ಕೊಡುವನು;\nಜ್ರಾರ್ಥನಾಸ್ತಿಯೊಂದ\nಮನನ್ಕಾಂಸಿ ಆಗ್ನದು\n3. ದೇವ್ರ ಮುಂದೆ ಪ್ರಾರ್ಥನೆ\nಮಾಡ್ವ ಕಾಲವಿದು;\nಶೋಧಕನ ಬಲವ\nವ್ಯರ್ಥ ಮಾಡಲು\nಇದು ತಕ್ಕ ಸಮಯ,\nದಿವ್ಯ ಸಂದರ್ಭವು,\nಪ್ರಾರ್ಥನಾಸಕ್ತಿಯಿಂದ\nಮಹತ್ಕಾರ್ಯವಾಗ್ವದು.\n4. ದೇವ್ರ ಮುಂದೆ ಪ್ರಾರ್ಥನೆ\nಮಾಡ್ವ ಕಾಲವಿದು;\nನಾವು ಕೇಳ್ವ ಸಹಾಯ\nಆತನೀವನು,\nನಾವು ಧೈರ್ಯದಿಂದಲೂ\nಬೇಡಿ ಬರುವೆವು;\nಪ್ರಾರ್ಥನಾಸಕ್ತಿಯಿಂದ\nಎಲ್ಲಾಚಿಂಕೆ ಪೋಪುದು." },
  53: { title: "ಕರ್ಕಾ, ಎಚ್ಚರಿಸು !", lyrics: "1. ಕರ್ಕಾ, ಎಚ್ಚರಿಸು !\nನಿನ್ ಮಕ್ಕಳೆಲ್ಲರೂ\n2ನ್ ಮಾತುಗಳ ಕೇಳಲು\nಬಂದೀಗ ಮಾತಾಡು.\nಪಲ್ಲದಿ\nನಮ್ಮೆಲ್ಲರಲ್ಲಿಯೂ\nಸುಭಕ್ತಿ ಹೆಚ್ಚಿಗು,\nನೀ ಕಾರ್ಯವೆಲ್ಲ ನಮ್ಮಲ್ಲೂ\nಸಂಪೂರ್ಣ ದಾಡಿರು.\nಪ್ರಾರ್ಥನೆ\n2. ನಮ್ಮನ್ನೆಚ್ಚರಿಸು!\nನಿನ್ ಬಲ ತೋರಿಸು!\n೩ನ್ ಪ್ರೀತಿ ದಯೆಯಿಂದಲೂ\nನಮ್ಮನ್ನು ತುಂಬಿಸು,\n3. ನಮು್ಮುಪಯೋಗಿಸು,\nನಮ್ಮನ್ನು ನಡಿಸು,\nಅನೇಕರನ್ನೀ ಸಭೆಗೂ\nಬರಲು ಪ್ರೇರಿಸು.\n4. ನಿನ್ನ ಸುನಾಮವು\nಘನವ ಹೊಂದಲು\nನೀ ನಮ್ೃನ್ನೆಲ್ಲಾ ನಡಿಸು\nಪುನರುಜ್ಚೀವಿಸು.\n1, ಪನ್ನಾತ್ಮ ಸೂರ್ಯ ಕ್ರಿಸ್ತನೇ!\nಸಜ್ಚ್ರೋತಿ ನೀಮ ಪನಗೆ ;\nಹಿನ್ನ ಸಮ್ಮುಖ ಕಾಣಲು\nನನಗೆ ರಾತ್ರಿ ಇಲ್ಲವು.\n2, ಆ ಮುಖ ಮಂಚ್ಚುವದಕ್ಕೆ\nಭೂಮಂಜು ಏರದಿರಲಿ;\nಇರುಳು ಹಗಲಲ್ಲಿಯೂ\nನನ್ನ ಸಮೀಪವಾಗಿರು,\n3. ದಣಿದು ಮಲಗಿರಲು\nಪನ್ನ ಸಮೀಪ ಕಾದಿರು;\nಹೊತ್ತಾರೆ ಏಳುವಾಗಲೂ\nಪ್ರಕಾಶೋದಯ ಶೋರಿಸು.\n4. ಪ್ರಪಂಚ ಯುದ್ಧದೊಳಗೆ\n‘್ನಿಂದ ಜಯ ಹೊಂದುವೆ:\nಜೀವಾಂತ್ಯ ಕಾಲದಲ್ಲಿಯೂ\nನಸ್ನಿಂದುಜ್ಚೀವಿಸುವೆನು." },
  54: { title: "ಈ ಭೂಸಂಚಾರದಲ್ಲಿ", lyrics: "1. ಈ ಭೂಸಂಚಾರದಲ್ಲಿ\nನಾ ಬೇಡಿಕೊಳ್ಳೋದು\nಸಮಸ್ತ ಸ್ಥಿತಿಯಲ್ಲಿ\nದಾಸನ್ನ ರಕ್ಷಿಸು!\nಪಾ ರಾತ್ರಿ ನಿದ್ದೆಮಾಡಿ\nಮಂಂಹಾನೆ ೭ಳಲು,\nನೀವೆಂದಿಗೂ ಕಾಪಾಡಿ,\nದಾಸನ್ನ ರಕ್ಷಿಸು!\n2. ಉದ್ಯೋಗ ಮಾಡುದಲ್ಲಿ\nಪನ್ನನ್ನು ನಡಿಸು,\nಯಾವತ್ತೂ ಕಷ್ಟದಲ್ಲಿ\nದಾಸನ್ನ ರಕ್ಷಿಸು!\nದುರಿಚಸ್ಟಾಬಲದಿಂದ\nಗಂಡಾಂತ್ರ ಬಂದರೂ\nಓ ಕರ್ತಾ ! ದಯದಿಂದ\nದಾಸನ್ನ ರಕ್ಷಿಗು!\n3, ಹಾನಪಧ್ಯರ್ಯದಾಗಿ\nಅಶಕ್ತವಾಗಲೂ,\nವಿನ್ನಾಕ್ಮ ಮೂಲವಾಗಿ\nದಾಸನ್ನ ರಕ್ಷಿಸು!\nಸೈಶಾಣಿಂದ ಹಾನಿ\nಸಂಭಿಸಿದಲು\nನೀ ಕಾದು ಪ್ರೀಶಿಯಾಗಿ\nದಾಸನ್ನ ರಕ್ಷಿಸು!\n4. ಅಜ್ಞಾನ ಅವಿಶ್ವಾಸ\nಹೃದದಿ ಹುಟ್ಟಲು\nಕೊಡೆನಗೆ ಸುಜ್ಞಾನ,\nದಾಸನ್ನ ರಕ್ಷಿಸು!\nನಾ ಮೃತಿ ಹೊಂದುವಲ್ಲಿ\nನಿನ್ನನ್ನು ಬೇಡಲು\nನಿನ್ನೈದು ಗಾಯಕ್ಕಾಗಿ\nದಾಸನ್ನ ರಕ್ಷಿಸು!" },
  55: { title: "ದೇವಭಕ್ತರೆಲ್ಲರೂ", lyrics: "1. ದೇವಭಕ್ತರೆಲ್ಲರೂ\nಜಪಮಾಡತಕ್ಕದ್ದು;\nಭಕ್ತಿ ಹೆಚ್ಚುವದಕ್ಕೆ\n2. ದುಟಖಿಸುವ ಪಾಪಿಯೂ\nಶ್ರಮಪಡುವವನೂ\nಜಪಮಾಡಿಕೊಂಡರೆ\nಶಾಂತಿ ಹೊಂದಲಾಗುತ್ತೆ ॥\n3. ಶೋಧಕನು ಬಂದರೆ\nನಮ್ಮ ಬಲ ಪ್ರಾರ್ಥನೆ ;\nದೇವಶಕ್ತಿ ನಮಗೆ\nಹೀಗೆ ಮಾತ್ರ ಸಿಕ್ಕುತ್ತೆ ॥\n4. ದೇವರಾತ್ಮ ಇಳಿದು\nನಮ್ಮ ಭಕ್ತಿ ಹೆಚ್ಚಿಸು ;\nಜಪಮಾಡು ಮನಸ್ಸು\nಹೆಚ್ಚಿತ್ಚಾಗಿ ಹುಟ್ಟಸು 1\nಪ್ರಾರ್ಥನೆ" },
  56: { title: "ಯಥಾರ್ಥವಾದ ಪ್ರಾರ್ಥನೆ", lyrics: "1. ಯಥಾರ್ಥವಾದ ಪ್ರಾರ್ಥನೆ\nಆತ್ಮದಪೇಕ್ಷೆಯೇ ;\nಆಂತರ್ಯದಲ್ಲಿ ಇರುವ\nರಹಸ್ಯ ಆಶೆಯೇ.\n2. ಯಥಾರ್ಥವಾದ ಪ್ರಾರ್ಥನೆ\nವಿಶ್ವಾಸವುಳ್ಳದ್ದೇ ;\nಪರಾತ್ಪರನ ಒಡನೆ\nಸಂಭಾಷಿಸುವದು.\n3. ಯಥಾರ್ಥವಾದ ಪ್ರಾರ್ಥನೆ\nದೇವಾತ್ಮನಿಂದಲೇ ;\nಪಾಪಿಷ್ಠರ ಆದರಣೆ\nಭಕ್ತರ ಜೀವವೇ.\n4. ಓ ಪರಿಶುದ್ಧ ಆತ್ಮನೇ!\nನಮ್ಮಲ್ಲಿ ಈಗಲೂ ;\nಯಥಾರ್ಥವಾದ ಪ್ರಾರ್ಥನೆ\nಅರ್ಪಿಸ ಬೋಧಿಸು." },
  57: { title: "ಎಲ್ಲಾ ಒಳ್ಳೇ ದಾನಗಳ", lyrics: "1. ಎಲ್ಲಾ ಒಳ್ಳೇ ದಾನಗಳ\nಮೂಲಕರ್ತ ದೇವರೇ!\nನಿನ್ನ ದಿವಯ ಆಶೀರ್ವಾದ\nದಯಮಾಡು ನನಗೆ,\nನನಗೆ, ನನಗೆ,\nದಯಮಾಡು ನನಗೆ.\nಪ್ರಾರ್ಥನೆ\n2. ಪಾಪಿಯಾಗಿದ್ದೇನೆ ಹೌದು,\nಯೋಗ್ಯನಲ್ಲ ತಂದೆಯೇ !\nಕ್ರಿಸತಗಾಗಿ ಕ್ಷಮೆಯನ್ನು\nದಯಮಾಡು ನನಗೆ.\n3. ನಿನ್ನ ಮೇಲೆ ಭರವಸ\nಇಟ್ಟಿದ್ದೇನೆ ಯೇಸುವೇ!\nನಿನ್ನ ಸ್ಥಿರ ಸಮಾಧಾನ\nದಯಮಾಡು ನನಗೆ.\n4. ಜ್ಞಾನ ಭಕ್ತಿ ಸತ್ಯ ಶಾಂತಿ\nಕೊಡುವಂಥ ಆತ್ಮನೇ !\nನನ್ನ ಆತ್ಮದಲ್ಲಿ ಶಕ್ತಿ\nದಯಮಾಡು ಸ್ವಾಮಿಯೇ\n5. ಅತಿಶಯ ಕೃಪೆಯನ್ನು\nಪಾಲಿಸುವ ಪ್ರಭುವೇ!\nತಳ್ಳಬೇಡ ಪಾಪಿಯನ್ನು\nದಯಮಾಡು ನನಗೆ." },
  58: { title: "ಎನ್ ದಿವ್ಯ ಕರ್ತನೇ", lyrics: "1. ಎನ್ ದಿವ್ಯ ಕರ್ತನೇ\nಎನ್ ತಂದೆಯೇ\nಈ ಬಡ ಪ್ರಾರ್ಥನೆ\nಕೇಳೀಗಲೇ\nಪಲ್ಲವಿ\nಹೆಚ್ಚಾದ ಪ್ರೀತಿಯಿಂದ,\nದಿವ್ಯ ಶಕ್ತಿಯಿಂದ,\nಓ ಪವಿತ್ರಾತ್ಮನೇ,\nಎನ್ ತುಂಬಿಸು\n2. ನಾ ಬಲಹೀನನೇ,\nಕ್ರಿಸತ್ಯೆಸುವೇ!\nನಿನ್ ಶಕ್ತಿಯಿಲ್ಲದೆ\nನಾ ಬೀಳುವೆ!\n3. ನೀ ಕ್ಷಣಮಾತ್ರವೇ\nಕೈ ಬಿಟ್ಟರೆ\nನಾ ಕುಂದಿಹೋಗುವೆ,\nಎನ್ ಆಪ್ತನೇ." },
  59: { title: "ಯೇಸು ! ನಿನ್ನ ನಂಬುತ್ತೇನೆ,", lyrics: "1. ಯೇಸು ! ನಿನ್ನ ನಂಬುತ್ತೇನೆ,\nನಿನ್ನ ಮಾತ್ರವೆ ;\nಪೂರ್ಣವಾಗಿ ರಕ್ಷಿಸುವಿ\nನನ್ನನ್ನು\n2. ಪಾಪ ಪರಿಹಾರಕ್ಕಾಗಿ\nನಂಬಿಕೊಳ್ಳುವೆ ;\nಯೇಸು, ನನ್ನ ಶುದ್ಧ ಮಾಡು,\nಈಗಲೇ!\n3. ನಿನ್ನ ದಿವ್ಯ ಜ್ಞಾನದಿಂದ\nನನ್ನ ನಡಿಸು ;\nನಿನ್ನ ಸುಚಿತ್ತೆಲ್ಲವನ್ನು\nತೋರಿಸು.\n4. ನಿತ್ಯ ನಿನ್ನ ಶಕ್ತಿಯನ್ನು\nದಯಪಾಲಿಸು ;\nನಿನ್ನ ಮಾತು ಕೇಳುವಂತೆ\nಪ್ರೇರಿಸು.\n5. ಯೇಸು ನಿನ್ನ ನಂಬುತ್ತೇನೆ,\nನಿನ್ನ ಮಾತ್ರವು ;\nಎಲ್ಲಾ ಪಾಪದಿಂದ ಕಾಯಿ\nನನ್ನನ್ನು" },
  60: { title: "ಓ ಜಗತ್ಮಭುವೇ", lyrics: "1. ಓ ಜಗತ್ಮಭುವೇ\nಪ್ರೇಮಾಬ್ಧಿಯು ನೀನೇ,\nಪರಾತ್ಪರನು ;\nನಾವೆಲ್ಲಾ ನಿನಗೆ\nಮಾಡುವ ಪ್ರಾರ್ಥನೆ\nಅಸಡ್ಡೆ ಮಾಡದೆ\nಅಲೈಸಿರು.\n2. ಓ ಯೇಸು ಸ್ವಾಮಿಯೇ!\nದೇವಕುಮಾರನೇ!\nವಿಮೋಚಕ !\nಸ್ವರಕ್ತ ಫಲವ,\nಆಕ್ರಮಹರಣ,\nಮನೋವಿಶ್ರಮವ,\nಈವಾಗ ತಾ.\n3. ಓ ಶುದ್ಧ ಆತ್ಮನೇ!\nಎಲ್ಲಾ ಶುದ್ಧತ್ವಕ್ಕೆ\nಕಾರಣನೇ\nದುರ್ಗುಣ ತೆಗೆದು,\nಸುಜ್ಞಾನ ಬೆಳಕು\nನಮ್ಮಲ್ಲಿ ಹುಟ್ಟಿಸು\nದಯಾಪ್ರನೇ!\nಪ್ರಾರ್ಥನೆ\n4. ಪಿತಾಪುತ್ರಾತ್ಮನೇ!\nಏಕ ಯೆಹೋವನೇ!\nಕಟಾಕ್ಷಿಸು ;\nಯಾವತ್ತು ಭೂಮಿಯೊಳ್,\nಸಮಸ್ತ ಜನರೊಳ್,\nಗಾಡಾಂಧಕಾರದೊಳ್\nಪ್ರಕಾಶಿಸು." },
  61: { title: "ಸಜ್ಜ್ಯೋತಿಯಾದ ಯೇಸುವೇ!", lyrics: "1. ಸಜ್ಜ್ಯೋತಿಯಾದ ಯೇಸುವೇ!\nಪ್ರಕಾಶ ಕೊಡು ಲೋಕಕ್ಕೆ ;\nಪ್ರಪಂಚದ ಕಾರ್ಗತ್ತಲು\nಸಂಪೂರ್ಣವಾಗಿ ಹರಿಸು.\n2. ಪಿಶಾಚನಿಂದ ಜನರು\nಅಜ್ಞಾನರಾಗಿ ಹೋದರು ;\nಓ ಕರ್ತ ! ಕನಿಕರಿಸು,\nಸನ್ಮಾರ್ಗದಲ್ಲಿ ಸೇರಿಸು.\n3. ಪಾಪಧಿಕಾರ ತೆಗೆದು,\nಪರಿಶುದ್ಧತ್ವ ಹುಟ್ಟಿಸು ;\nಭೂಪ್ರಜೆ ನಿನಗೆರಗಿ,\nನಿನ್ನಲ್ಲಾನಂದಪಡಲಿ.\n4. ಎಲ್ಲೆಲ್ಲೂ ನಿನ್ನ ರಾಜ್ಯಕ್ಕೆ\nಜಯವ ಕೊಡು ದೇವರೇ!\nನಿನ್ನಾತ್ಮನನ್ನು ಹೊಯಿದು\nಪಾಪಿಷ್ಠರನ್ನು ರಕ್ಷಿಸು." },
  62: { title: "ಹಾ! ಎಂಥಾ ಅಮೂಲ್ಯ ಮಿತ್ರ", lyrics: "1. ಹಾ! ಎಂಥಾ ಅಮೂಲ್ಯ ಮಿತ್ರ\nನಮಗೀಗ ಸಿಕ್ಕಿದ!\nಪಾಪ ದುಖು ಭಯವೆಲ್ಲಾ\nಪರಿಹಾರ ಮಾಡಿದ ;\nಸ್ಥಿರಾನಂದ ಸಮಾಧಾನ\nಹೊಂದಲಾಶಿಸಿದರೆ,\nಯೇಸು ಸ್ವಾಮಿಯನ್ನು ನಿತ್ಯ\nಬೇಡುತ್ತಿರು, ಮನವೇ.\n2. ಶೋಧನೆ ಉಂಟಾಗುವಾಗ,\nತಾಪತ್ರಯದಲ್ಲಿಯೂ\nಮನದಲ್ಲಿ ಕುಗ್ಗಬೇಡ,\nಜಪ ಮಾಡುತ್ತಾ ಇರು ;\nನಂಬತಕ್ಕ ಇಂಥ ಮಿತ್ರ\nಬೇರೆ ಒಬ್ಬರಿಲ್ಲವು ;\nನಿನ್ನ ದುಖವೆಲ್ಲಾ ಬಲ್ಲ\nಆತುಕೊಳ್ಳುತ್ತಾ ಇರು.\n3. ತುಂಬ ವ್ಯಸನ ಉಪದ್ರ\nದುಸ್ಥಿತಿಯು ಬಂದರೂ,\nಯೇಸುನಾಥ ನಿತ್ಯಾಶ್ರಯ ;\nಬೇಡಿಕೊಳ್ಳುತ್ತಾ ಇರು ;\nನಿಂದೆ ಪೀಡೆ ಕಳವಳ\nಯಾವ ಕಷ್ಟ ಬಂದರೂ,\nಸರ್ವಶಕ್ತನ ಆಧಾರ\nಎಂದೂ ತಪ್ಪಿ ಹೋಗದು.\nಪ್ರಾರ್ಥನೆ" },
  63: { title: "ಈ ದಿನವೆಲ್ಲಾ ನನ್ನನ್ನು", lyrics: "1. ಈ ದಿನವೆಲ್ಲಾ ನನ್ನನ್ನು\nಕಾಪಾಡಿದಂಥ ದೇವರು\nಸರ್ವೋಪಕಾರಿ ; ಆತಗೆ\nಕೊಂಡಾಟ ಕೊಡು, ಮನವೇ.\n2. ಈ ಹೊತ್ತು ಕಂಡ ತಪ್ಪನ್ನು\nಓ ಕರ್ತಾ ಪರಿಹರಿಸು ;\nಈ ರಾತ್ರಿಯಲ್ಲಿ ನನ್ನನ್ನು\nಗಂಡಾಂತ್ರಕ್ಕೆಲ್ಲಾ ತಪ್ಪಿಸು,\n3. ನಾ ನಿದ್ದೆ ಗೈಯ್ಯುವಾಗಲು\nಅಶುಭ ಸ್ವಪ್ನ ತಪ್ಪಿಸು ;\nನಿನ್ ಕರುಣೆಯ ನೆನಪು\nನನ್ನಾತ್ಮದಲ್ಲಿ ಇರಿಸು.\n4. ಎನ್ ದೇಹ ಸುಖಪಡಿಸು\nಎನ್ನಾತ್ಮ ಸಮದಾಯಿಸು ;\nನಿನ್ನನ್ನು ಸೇವೆ ಮಾಡಲು\nಉದಯದಲ್ಲಿ ಎಬ್ಬಿಸು." },
  64: { title: "ಎನ್ನೊಂದಿಗಿರು, ಸಂಜೆಯಾಯಿತು,", lyrics: "1. ಎನ್ನೊಂದಿಗಿರು, ಸಂಜೆಯಾಯಿತು,\nಸಂದ್ಹೋಗುತ್ತೆ ಈ ಜೀವಕಾಲವು,\nಎನ್ನೊಂದಿಗಿರು, ದಿವ್ಯ ಮಿತ್ರನೇ !\nಅನಾಥನಾಥ ನೀನು ಅಲ್ಲವೇ!\n2. ಓ ಯೇಸು ! ನಿನ್ನ ಮುಖದರ್ಶನ\nಒಂದೊಂದು ಕ್ಷಣವೂ ಅವಸರ!\nಪ್ರಕಾಶ ಮೋಡ ಯಾವದಿದ್ದರೂ\nನೀನಿದ್ದರೆ ನನಗೆ ಹಿತವು.\n3. ನಿನ್ನ ಸಮ್ಮುಖವನ್ನು ಕಂಡರೆ,\nಸುಖ ದುಖ ಉಭಯ ಸಮವೇ\nಓ ಮೃತ್ಯು! ನಿನ್ನ ಕೊಂಡಿಹೋಯಿತು\nಸಮಾಧಿಯೇ! ನಿನ್ನನ್ನು ಗೆದ್ದೆನು.\n4. ಜೀವಾಂತ್ಯ ಕಾಲದಲ್ಲಿ ಕರ್ತನೇ!\nನಿನ್ನನ್ನು ಆತುಕೊಂಡು ಸಾಯುವೆ;\nಅನಂತ್ರ ಸ್ವರ್ಗೋದಯವಾಗಲು.\nಎಂದೆಂದೂ ನೀನು ನನ್ನ ಭಾಗವು." },
  65: { title: "ಕೃಪಾಸನದ ಬಳಿಗೆ", lyrics: "1. ಕೃಪಾಸನದ ಬಳಿಗೆ\nಬಾರದ ಹಾಗೆ ಅಡ್ಡಿಯೇ\nಕಂಡಿದ್ದರೂ ನಾ ಬರುವೆ\nದೇವ್ರ ಸಹಾಯ ಕೊಂದುಮೆ\nಕೃಪಾಸನದ ಬಳಿಗೆ\nವಿಶ್ವಾಸ ಪ್ರೀತಿಯೊಡನೆ\nನೀ ಬೇಡಿಕೋ ಎನ್ಸಾತ್ಮವೇ!\nವಿನ್ನಾಪ್ರನ್ಯೇಸು ಕೊಡನೇ ?\n3. ಪ್ರಾಣುಪ್ತನೆನು ಅಲ್ಲಿಯೇ\nಅರೂಢನಾದನಲ್ಲವೇ;\nಅದೈರ್ಯ ಬಿಟ್ಟು ಈಗಲೇ\nನೀ ಕೇಳಿಕೋ ಎನ್ನಾತ್ವೇ ;\nಯಾವಾಗಲಲ್ಲಿ ಬಂದರೆ\nಮಸೊನತಯಪ್ತಿಯಾಗುಕ್ತೆ;\nನೀನಲ್ಲದನ್ನೂ ಅಶಗೆ\nವಿವರ ಪೇಳಲಾಗುತ್ತೆ\nಪ್ರಾ್ಗ\n5. ನಾನೀಗ ಜಪದಲ್ಲಿಯೇ\nಕಾದಾಡಿ ಜಯ ಹೊಂದುವೆ ;\nಕೆಡುಕನೆಂಬ ವೈರಿಯು\nಸಂಪೂರ್ಣ ಸೋತು ಹೋಗ್ವನು\n6. ಪ್ರಾರ್ಥನೆಯಿಂದ ಕಷ್ಟವು\nವಾರಿಸುತ್ತೆ; ಸಂತೋಷವೂ\nಸಿಕ್ಕುವದೆಂದು ಬೇಡುವೆ\nನಿನ್ ಹತ್ರ ಬಂದೆ, ಯೇಸುವೇ!" },
  66: { title: "ಹೊತ್ತಾರೆ ಸೂರ್ಯನೊಂದಿಗೆ", lyrics: "1. ಹೊತ್ತಾರೆ ಸೂರ್ಯನೊಂದಿಗೆ\nಎಚ್ಚರವಾಗು ಮನವೇ!\nಉದಯದರ್ಪಣೆಯನ್ನು\nನೀ ಕರ್ತನಿಗೆ ಅರ್ಪಿಸು.\n2. ಇಂಪಾದ ನಿದ್ದೆ ನನಗೆ\nಪ್ರೇಮದಿ ಕೊಟ್ಟ ಕರ್ತಗೆ\nಹೃದಯ ಪೂರ್ತಿಯಿಂದಲೇ\nಸ್ತೋಶ್ರವ ಕೊಡು ಮನವೇ\n3. ಕಾಪಾಡಿದಂಥ ತಂದೆಯೇ!\nಅಲೈಸು ನನ್ನ ಪ್ರಾರ್ಥನೆ,\nನನ್ನನ್ನು ಅಶೀರ್ವದಿಸು.\nಸನ್ಮಾರ್ಗದಲ್ಲಿ ನಡಿಸು.\n4. ಓ ಸರ್ವ ಸೃಷ್ಟಿಪಾಲಕ!\nಕೃಪಾಕಟಾಕ್ಷ ಸಾಗರ!\nಯುಗ ಯುಗಾಂತ್ರ ನಿನ್ನನ್ನು\nನನ್ನಾಕ್ಮ ಸ್ತುತಿಸುವದು." },
  67: { title: "ಪಿತ ಪುತ್ರ ಆತ್ಮನೇ", lyrics: "1. ಪಿತ ಪುತ್ರ ಆತ್ಮನೇ\nಸರ್ವ ಜಗತ್ಪಭುವೇ!\nಕೇಳು ನಮ್ಮ ಪ್ರಾರ್ಥನೆ,\nದಯವುಳ್ಳ ಕರ್ತಾ 1॥\n2. ಲೋಕಕ್ಕತಿ ಕರುಣೆ\nತೋರಿಸಿದ ತಂದೆಯೇ\nಕೇಳು ನಮ್ಮ ಪ್ರಾರ್ಥನೆ,\n3. ನಮಗಾಗಿ ಶಿಲುಬೆ\nತಾಳಿದಂಥ ಯೇಸುವೇ!\nಕೇಳು ನಮ್ಮ ಪ್ರಾರ್ಥನೆ\nದಯವುಳ್ಳ ಕರ್ತಾ 1॥\n4. ಭಕ್ತರನ್ನು ಮೋಕ್ಷಕ್ಕೆ\nನಡಿಸುವ ಅತ್ಮನೇ!\nಕೇಳು ನಮ್ಮ ಪ್ರಾರ್ಥನೆ,\nದಯವುಳ್ಳ ಕರ್ತಾ 11\n5. ಈ ಪ್ರಪಂಚ ಶೋಧನೆ\nತಳ್ಳಿ ಬಿಡುವದಕ್ಕೆ\nಬಲಕೊಡು ನಮಗೆ,\nದಯವುಳ್ಳ ಕರ್ತಾ 19\n6. ನಮ್ಮ ಅತ್ಮ ಶತ್ರುವು\nಮೋಸಮಾಡ ಬರಲು\nದಾಸನನ್ನು ಶಪ್ಪಿಸು,\nದಯವುಳ್ಳ ಕರ್ತಾ 89\n7. ಯಾವ ಪಾಪ ನಮ್ಮನ್ನು\nಜೈಸದಿರು ನಿತ್ಯವು\nಪ್ರಾರ್ಥನೆ\nಹತ್ರವಿದ್ದು ರಕ್ಷಿಸು,\n8. ಸುಖ ದುಖ ಬಂದರೂ\nನೀನೇ ಸ್ಥಿರಾಶ್ರಯವು.\nಕಾಯುತ್ತಿರು ನಮ್ಮನ್ನು\n9. ಇಹಪರದಲ್ಲಿಯೂ\nಯುಗ ಯುಗವೆಂದಿಗೂ\nನಮ್ಮ ಭಾಗವಾಗಿರು," },
  68: { title: "ಸುಕಾಲವೇ! ಸುಕಾಲವೇ!", lyrics: "1. ಸುಕಾಲವೇ! ಸುಕಾಲವೇ!\nಆನಂದ ದೇವರಾಧನೆ ;\nಪ್ರಪಂಚ ಚಿಂತೆ ಬಿಡುವೆ,\nಕೃಪಾಸನ ನಾ ಸೇರುವೆ ;\nಇಷ್ಟಾರ್ಥ ಹೇಳಿ ತಂದೆಗೆ,\nದಿವ್ಯಾಶೀರ್ವಾದ ಬೇಡುವೆ ;\nಹಾ ! ಶುಭಕಾಲವಾಗಿದೆ,\nಒಳ್ಳೇದು ದೇವರಾಧನೆ 0\n2. ಸುಕಾಲವೇ! ಸುಕಾಲವೇ\nಅಮೃತ ದೇವರಾಧನೆ ;\nಹೃದಯ ಶಾಪಪಡಲು,\nವಿಶ್ರಮ ಕೊಡಲುಳ್ಳದ್ದು;\nಪರಾತ್ವರನ ಪಾದವೇ\nಆಶ್ರಯ ಸ್ಥಾನವಾಗಿದೆ;\nಹಾ ! ಶುಭಕಾಲವಾಗಿದೆ.\nಒಳ್ಳೇದು ದೇವರಾಧನೆ 69\n3. ಸುಕಾಲವೇ! ಸುಕಾಲವೇ!\nಆಧಾರ ದೇವರಾಧನೆ ;\nದುರ್ಗುಣವನ್ನು ಜಯಿಸ\nದೇವಾತ್ಮ ಶಕ್ತಿ ಕೊಡುವ.\nಸನ್ಮಾರ್ಗನಾಗ ಬಲವು\nಬೇಕಾದರೆ ವಿಜ್ಞಾಪಿಸು ;\nಹಾ ! ಶುಭಕಾಲವಾಗಿದೆ,\n4. ಸುಕಾಲವೇ! ಸುಕಾಲವೇ!\nವಿಶ್ರಾಂತಿ ದೇವರಾಧನೆ ;\nಮೇಲ್ಲೋಕಕೋರ ಮಾಡ್ವದು,\nಭೂಲೋಕದಾಶೆ ನೀಗ್ವದು,\nವ್ಯಾಕುಲ ತಪ್ಪಿಸುತ್ತದೆ,\nಮನೋವಿಶ್ರಾಂತಿ ಕೊಡುತ್ತೆ ;\nಹಾ ! ಶುಭಕಾಲವಾಗಿದೆ,\nಒಳ್ಳೇದು ದೇವರಾಧನೆ ॥" },
  69: { title: "ಯೂದ ಕುಲದ ಯೇಸು", lyrics: "1. ಯೂದ ಕುಲದ ಯೇಸು\nಎನ್ ಪ್ರಾರ್ಥನೆಯನ್ನು\nಕೇಳುತ್ತಾ, ಮೆಚ್ಚುತ್ತಾ,\nನಡಿಸುವನು ;\nಆತನ್ ಸನ್ನಿಧಿಯಲ್ಲಿ\nನಾ ಬಿದ್ದು ನಾ ಬೇಡಿ,\nನಾ ಭರವಸನಾಗಿ\nಕಾದಿರುವೆನು.\n2. ಯೂದ ಕುಲದ ಯೇಸು\nಎನ್ನಾಪತ್ತನ್ನೆಲ್ಲಾ\nಪ್ರಾರ್ಥನೆ\nಹಿಡಿದು, ಹರಿದು,\nಹಾರಿಸುವನು ;\nಆತನಲ್ಲಿ ನಾ ನಂಬಿ,\nನಾ ಹಾಡಿ, ಕೊಂಡಾಡಿ,\nನಾನರ್ಪಿಸುವೆನೆಂದು\nಸುಸೇವೆಯನ್ನು\n3. ಯೂದ ಕುಲದ ಯೇಸು\nಶತ್ರುಗಳನ್ನೆಲ್ಲಾ\nಬಗ್ಗಿಸಿ, ಭೇದಿಸಿ,\nಬಿಸಾಡುವನು ;\nದುಷ್ಟ ಬಲವನ್ನೆಲ್ಲಾ\nತಾನಣಗಿಸುವ,\nತಾ ಭಕ್ತನಾದ ನನ್ನನ್ನು\nಕಾಯುವನು.\n4. ಯೂದ ಕುಲದ ಯೇಸು\nಬೇಗ ಬರುವನು\nಸಂತೋಷ, ಸಂತೃಪ್ತಿ,\nಸಂಪೂರ್ಣತೆಯು\nನನಗಾಗುವುದೆಂದು\nಹಲ್ಲೆಲೂಯ ನಿತ್ಯವು\nನಿನ್ನಾಮ ಸ್ತೋತ್ರ ಮಾಡಿ\nಕೊಂಡಾಡುವೆನು." },
  70: { title: "ಕರ್ತಾ ಯೇಸು ಸ್ವಾಮಿಗೆಲ್ಲಾ", lyrics: "1. ಕರ್ತಾ ಯೇಸು ಸ್ವಾಮಿಗೆಲ್ಲಾ\nನಮ್ಮ ಎಲ್ಲಾ ಬಲವ,\nಮಾತಾಲೋಚನೆಗಳೆಲ್ಲಾ\nಆತನ್ ಮುಂದೆ ತರುವ.\nದೇವರಿಗೆ ಪ್ರತಿಷ್ಠೆ ಮಾಡಿಕೊಳ್ಳುವುದು\nಪಲ್ಲವಿ\nಕರ್ತ ಯೇಸು ಸ್ವಾಮಿಗೆಲ್ಲಾ\nನಮ್ಮ ದಿನ ತಾಸೆಲ್ಲಾ\nಕರ್ತ ಯೇಸು ಸ್ವಾಮಿಗೆಲ್ಲಾ\nಸ್ತುತಿ ಸ್ತೋತ್ರ ಕೊಡುವ.\n2. ಕೈಗಳಿಂದ ಆತನ್ ಸೇವಾ\nಕಾರ್ಯ ಮಾಡುತ್ತಿರುವ,\nಕಾಲ್ಗಳಿಂದ ಚುರುಕಾಗಿ\nಆತನ್ ಹಿಂದೆ ಹೋಗುವ.\n3. ನಮ್ಮ ದೃಷ್ಟಿ ಆತನ್ ಮೇಲೆ\nಸ್ಥಿರವಾಗಿಟ್ಟಿರುವ," },
  71: { title: "ಕರ್ತಾ ! ನಿನ್ನ ಸೇವೆಗೆ,", lyrics: "1. ಕರ್ತಾ ! ನಿನ್ನ ಸೇವೆಗೆ,\nನನ್ನ ಜೀವ ಕೊಟ್ಟೆನು ;\nನಿನ್ನ ಘನಕ್ಕಾಗಿಯೇ\nಹೊತ್ತು ಕಳೆಯುವೆನು.\n2. ನನ್ನ ಕೈಗಳ್ ನಿನಗೆ\nನಾ ಪ್ರತಿಷ್ಠೆ ಮಾಡಿದೆ;\nನನ್ನ ಕಾಲು ಕರ್ತನೇ,\nತಕ್ಕೋ ನಿನ್ನ ಸೇವೆಗೆ\n3. ನನ್ನ ಸ್ವರ ನಿನ್ನದೇ.\nನಿನ್ನ ಸ್ತೋತ್ರ ಮಾಡಲಿ ;\nನನ್ನ ಬಾಯಿ, ಕರ್ತನೇ,\nನಿನ್ನ ವಾಕ್ಯ ಸಾರಲಿ.\nಬೇರೆ ದೃಷ್ಟಿ ಎಲ್ಲಾ ಹೋಗಿ\nಶಿಲ್ಬೆ ಕಡೆ ನೋಡುವ.\n4. ಏನಾಶ್ಚರ್ಯ | ಏನಾಶ್ಚರ್ಯ !\nಮಹಿಮೆಯ ರಾಜನು\nಪ್ರೀತಿಯಿಂದ ಪ್ರಿಯರೆಂದು\nಕರ್ಯುತ್ತಾನೆ ನಮ್ಮನ್ನು\n5. ಸ್ತೋತ್ರ ಸ್ತೋತ್ರ, ಪ್ರಿಯ ಯೇಸು\nನಿನ್ನ ದಿವ್ಯ ಪ್ರೀತಿಗೆ\nನಿನ್ನ ರೆಕ್ಕೆ ನೆರಳೊಳು\nಇರುತ್ತೇವೆ ನಿತ್ಯವೇ.\nದೇವರಿಗೆ ಪ್ರತಿಷ್ಠೆ ಮಾಡಿಕೊಳ್ಳುವುದು\n4. ನನ್ನ ಬೆಳ್ಳಿ ಚಿನ್ನವ\nತಕ್ಕೋ, ದಿವ್ಯ ಮಿತ್ರನೇ ;\nನನ್ನ ಬುದ್ಧಿ ಎಲ್ಲವ\nತಕ್ಕೋ ನಿನ್ನ ಸೇವೆಗೆ\n5. ನನ್ನ ಚಿತ್ತ ನಿನ್ನದೇ,\nನಿನ್ನ ಇಷ್ಟ ಮಾಡುವೆ ;\nನನ್ನ ಮನದೊಳಗೆ\nನೀನೇ ಆಳು, ಕರ್ತನೇ.\n6. ನಿನ್ನ ಬಿಟ್ಟುಯಾರನ್ನೂ\nಪ್ರೀತಿ ಮಾಡಲಾರೆನು ;\nನನ್ನ ಪೂರ್ಣ ಮನಸ್ಸು\nನೀನೇ ತಕ್ಕೋ ಎಂದಿಗೂ." },
  72: { title: "ನಿನ್ನನ್ನು ಯೇಸುವೇ,", lyrics: "1. ನಿನ್ನನ್ನು ಯೇಸುವೇ,\nಪ್ರೀಶಿಸುವೆ;\nನಾನೆಲ್ಲಾ ನಿನಗೆ\nಸಲ್ಲಿಸುಮೆ\nಎನ್ನಾಕ್ಮ ಪ್ರಾರ್ಥನೆ\nಹೆಚ್ಚಲಿ ಪ್ರೀತಿಯೇ\nನನ್ನೊಳಗೆ,\nದಿವ್ಯಾಪ್ತನೇ\n2. ಲೋಕಾನಂದವ\nಹುಡುಕಿದೆ ;\nನಾನೀಗ ವಿನ್ನನ್ನು\nಹರಸುವೆ\nನಾನಿನ್ನು ಕೇಳುವೆ\nಹೆಚ್ಚಲಿ ಪ್ರೀಶಿಯೇ\nನನ್ನೊಳಗೆ,\nದಿವ್ಯಾಪ್ತನೇ\n3. ದುಱಿವೂ ಸುಖಿವೂ\nಏನ್ ಬಂದರೂ\nಅದೆಲ್ಲಾ ನನಗೆ\nಮೇಲ್ಮಾಡ್ವದು.\nಮತ್ತಿನ್ನು ಬೇಡುವೆ\nಹೆಚ್ಚಲಿ ಪ್ರೀತಿಯೇ\nನನ್ನೊಳಗೆ,\nದಿವ್ಯಾಪ್ತನೇ\n4. ಮೃತ್ಯು ಬಂದಿದ್ದರೂ\nಸಂತೋಷವೇ ;\nನಾನೆಲ್ಲೂ ಇದ್ದರೂ\nದೇವರಿಗೆ ಪ್ರತಿಷ್ಠ ಮಾಡಟಾಳ್ಳುವುದು\nಸ್ತೋತ್ರಿಸುವೆ.\nಹೌದಿನ್ನು ಕೇಳುವೆ\nಹೆಚ್ಚಲಿ ಪ್ರೀತಿಯೇ\nನನ್ನೊಳಗೆ,\nದಿವ್ಯಾಪ್ತನೇ" },
  73: { title: "ನನ್ನ ಪಾಪ ನೀಗಲು", lyrics: "1. ನನ್ನ ಪಾಪ ನೀಗಲು\nಕ್ರಿಸ್ತನು ಸತ್ತನು ;\nಸದಾ ನನ್ನ ಕಾಯಲು\nಎದ್ದು ಬಂದನು,\nಪಲ್ಲವಿ\nಜ್ಞಾನ ನೀತಿ ಬಲವು ;\nಆತ್ಮ ಶುದ್ಧಿ ಆಗ್ವವು ;\nಎನ್ನುದ್ಧಾರ ಕರ್ತನು\nಎನ್ನ ಕಾಯ್ವನು.\n2. ಯೇಸು ಕ್ರಿಸ್ತ ನನಗೆ\nಆಪ್ತನೇ, ಪ್ರಿಯನೇ ;\nನನಗಾಗಿ ಶಿಲುಬೆ\nತಾಳಿದಾತನೇ.\n3. ಯೇಸುವಿನ ರಕ್ತವೆ\nಭಕ್ತಗೆ ಪಾಯವೇ ;\nಅದು ದೇವ್ರ ಮನೆಗೆ\nಹಕ್ಕನ್ನೀಯುತ್ತೆ.\n4. ಸರ್ವ ಕಾಲ ಆತನು\nನೋಡ್ವನು, ಕಾಯ್ವನು ;\nಭಯವಿಲ್ಲವೆನಗೂ\nಆತನಿರ್ವನು.\n5. ಹಲ್ಲೆಲೂಯ! ಸ್ವಾಮಿಗೆ\nಜಯವೇ ಮಹಿಮೆ ;\nಆತನ್ ಶಕ್ತಿಯಿಂದಲೇ\nನಾನು ಗೆಲ್ಲುಮೆ." },
  74: { title: "ಧೈರ್ಯಶಾಲಿಯಾಗಿರು.", lyrics: "1. ಧೈರ್ಯಶಾಲಿಯಾಗಿರು.\nಅಂಜಿಕೊಳ್ಳದೆ,\nದೇವರಾಜ್ಞ ಕೈಕೊಂಡು\nಹೋರಾಡುವವನೇ !\nಪಲ್ಲವಿ\nದಾನಿಯೇಲನಂತೆ\nಸ್ಥಿರನಾಗಿರು,\nಮೇಲುದ್ದೇಶವಿಟ್ಟು ಮುಂದೆ\nಕಾರ್ಯ ಮಾಡಿರು.\n2. ತೋಮನಂತೆ ನೀನು\nಅಲ್ಪ ನಂಬಿಕೆ\nಬಿಟ್ಟು ಸ್ವಾಮಿಯಲ್ಲಿಯೂ\nಸ್ಮಿರನಾಗೀಗಲೇ.\n3. ಪೇತ್ರನಂತೆ ನೀನು\nಹೇಡಿಯಾಗದೆ\nದೇವಸಾಕ್ಷಿಯಾಗಿರು,\nಅಧಯರ್ಯಪಡದೆ.\n4. ಆತ್ಮ ಶತ್ರುಗಳನ್ನು\nಸೋಲಿಸೋದಕ್ಕೆ\nಕೂಡ್ಲೆ ನಿಂತು ಧೈರ್ಯದಿಂ\nಹೋರಾಡು ಭಟನೇ.\nದೇವರಿಗೆ ಪ್ರತಿಷ್ಠೆ ಮಾಡಿಕೊಳ್ಳುವುದು" },
  75: { title: "ಯೆಸುವಿನ ಪ್ರೀತಿಯಲ್ಲಿ", lyrics: "1. ಯೆಸುವಿನ ಪ್ರೀತಿಯಲ್ಲಿ\nನೆಲೆಗೊಂಡು ಸ್ತೋತ್ರಮಾಡಿ,\nಆತನೊಳ್ಳೆ ಸೇವೆಗಾಗಿ\nಎಲ್ಲಾ ಕೊಡುವೆ.\n2. ಯೇಸುವಿನ ವಾಕ್ಯದಲ್ಲಿ\nನಾನು ಭರವಸವಾಗಿ\nಅತುಕೊಂಡು ನೀತಿಯಲ್ಲಿ\nನಡಕೊಳ್ಳುಮೆ\n3. ಯೇಸುವಿನ ನಾಮದಲ್ಲಿ\nಹರ್ಷಗೊಂಡು ಸ್ಥಿರವಾಗಿ,\nವೈರಿಯೊಡನೆ ಹೋರಾಡಿ\nಜಯ ಹೊಂದುವೆ\n4. ಯೇಸುವಿನ ಪ್ರಭೆಯಲ್ಲಿ\nದೇವ್ರ ಹತ್ರ ನಿಲ್ಲುತ್ತೇನೆ\nಅಲ್ಲಿ ಸದಾಕಾಲ ಬಾಳಿ\nತೃಪ್ತಿ ಹೊಂದುಮೆ\n5. ಯೇಸು ಬೇಗ ಬರ್ವನೆಂದು\nಜ್ಲಪ್ತಿ ಮಾಡಿ ಹರ್ಷಗೊಂಡು,\nನನ್ನ ಸಿದ್ಧ ಮಾಡಿಕೊಂಡು,\nಕಾದುಕೊಳ್ಳುಮೆ" },
  76: { title: "ಯೇಸು ಸ್ವಾಮಿ, ನಿಂಗೆ ನಾನು", lyrics: "1. ಯೇಸು ಸ್ವಾಮಿ, ನಿಂಗೆ ನಾನು\nಎಲ್ಲವನ್ನೂ ಕೊಡ್ವೆನು,\nನಿನ್ನ ಮುಂದೆ ನಾನು ಬಿದ್ದು\nನಿನ್ನಾರಾಧಿಸುವೆನು.\nರೀವರಿಗೆ ಪ್ರತಿಷ್ಠೆ ಮಾಡಿಕೊಳ್ಳುವುದು\nಪಲ್ಲವಿ\nನಾ ಸಮಸ್ತವ,\nನಾ ಸಮಸ್ತವ\nನಿನಗೆ, ಎನ್ ದಿವ್ಯ ಕರ್ತ,\nಕೊಡುವೆನಯ್ಯಾ\n2. ನಿನ್ನ ಮುಂದೆ ಬಿದ್ದು ಸ್ವಾಮಿ,\nನಿನ್ನ ನಮಿಸುವೆನು ;\nಲೋಕದಾಶೆ ಎಲ್ಲಾ ನೀಗಿ\nನನ್ನ ಶುದ್ಧಪಡಿಸು.\n3. ಪೂರ್ಣವಾಗಿ ನಾನು ನಿನ್ನ\nದಾಸನ್ನಾಗಿ ಮಾಡಿಸು ;\nನೀನು ನನ್ನ ಕರ್ತನೆಂದು\nಎಲ್ಲರ್ ಮುಂದೆ ಹೇಳ್ವೆನು.\n4. ನನ್ನ ಕರ್ತ ನನ್ನ್ನೀಗ\nನಿನಗರ್ಪಿಸುವೆನು ;\nನಿನ್ನ ಪ್ರೀತಿ ಬಲದಿಂದ\nನನ್ನ್ನೀಗ ನಡಿಸು.\n5. ನಿನ್ನ ರಕ್ಷಣೆಯಾನಂದ\nಈಗ ತಿಳುಕೊಂಡೆನು ;\nಹಲ್ಲೆಲೂಯ ನಿನಗೆಂದು\nಸದಾ ಸ್ತೋತ್ರ ಮಾಡ್ವೆನು." },
  77: { title: "ಶಿಲ್ಬೆ ಹತ್ರ ಬರುವೆ,", lyrics: "1. ಶಿಲ್ಬೆ ಹತ್ರ ಬರುವೆ,\nನಾನು ಬಡ ಪಾಪಿಯು ;\nಪೂರ್ಣ ಶುದ್ಧನಾಗುವೆ,\nಯೇಸುವನ್ನು ನಂಬಲು.\nಪಲ್ಲವಿ\nನನಗಾಗಿ ಸತ್ತಿದ್ದೀ,\nದೇವರ ಕುಮಾರನೇ !\nಪಾಪಿಗಾಪ್ತನಾಗಿದ್ದೀ,\nರಕ್ಷಿಸನ್ನ್ನೀಗಲೇ.\n2. ಬಹುಕಾಲ ನನ್ನನ್ನು\nಸೈತಾನ್ ಆಳುತ್ತಿದ್ದನು ;\nಬಹುಕಾಲ ನಿನ್ನನ್ನು\nಆಭಿಲಾಷಿಸಿದೆನು.\n3. ನಿಜವಾಗಿ ನಿನ್ನನ್ನು\nಶುದ್ಧನಾಗ ಮಾಡುವೆ ;\nಹೌದು ಶುದ್ಧನಾದೆನು,\nಹರ್ಷ ! ಹರ್ಷ ! ಕರ್ತಗೆ\n4. ಆತೃ ದೇಹ, ಪ್ರಾಣವ,\nದಿವ್ಯ ಕರ್ತ! ನಿನಗೆ;\nನನ್ನದಾದ ಸರ್ವವ\nನಿನಗೀಗ ಕೊಡುವೆ." },
  78: { title: "ಕ್ರೈಸ್ತರಾದ ನಮ್ಮ ಮೇಲೆ", lyrics: "1. ಕ್ರೈಸ್ತರಾದ ನಮ್ಮ ಮೇಲೆ\nಬಿದ್ದ ಭಾರವು\nದೊಡ್ಡದೆಂದು ಧ್ಯಾನಮಾಡು\nರಾತ್ರಿ ಹಗಲು.\nಪಲ್ಲವಿ\nಅನ್ಯರಾದ ಬೇರೆ ಜನ್ರ\nನಾವು ಪ್ರೀತಿಸಿ\nರಕ್ಷಕನ ಹತ್ರ ತರ್ವ\nಹಂಗು ನಮ್ಮದು.\n2. ನೀನು ಇರುವಂಥ ಪ್ರತಿ\nಸ್ಥಳದಲ್ಲಿಯೂ\nಯೇಸುವಿನ ಮಾತಿನಂತೆ\nನಿತ್ಯ ವರ್ತಿಸು.\n3. ಸಾವಿರಾರು ಜನ ನಿತ್ಯ\nಸಾಯುತ್ತಿರಲು.\nಎಚ್ಚರಿಕೆ ವಾಕ್ಯ ಹೇಳಿ\nಪ್ರಾಣ ಕಾಪಾಡು.\n4. ಪಾಪಿಯನ್ನು ರಕ್ಷಿಸುವ\nಪ್ರತಿಯೊಬ್ಬನೂ\nಜ್ಯೋತಿಯಂತೆ ಶೋಭಿಸುತ\nಮಾನ ಹೊಂದ್ವನು." },
  79: { title: "ಕೆಲಸ ಮಾಡುತ್ತಿರು", lyrics: "1. ಕೆಲಸ ಮಾಡುತ್ತಿರು\nಹೊತ್ತಾರೆಯಲ್ಲಿಯೇ ;\nಮಧ್ಯಾಹ್ನದಲ್ಲೂ ಮಾಡು,\nಸಂಜೆ ಬರುತ್ತೆ ;\nಜಾಗ್ರತೆಯಾಗುತ್ತಿರು\nಹೊತ್ತಿರುವಾಗಲೇ,\nತಾತ್ಸಾರ ಮಾಡದಿರು,\nರಾತ್ರಿ ಬರುತ್ತೆ.\n2. ಕೆಲಸ ಮಾಡುತ್ತಿರು\nಸಂದರ್ಭದಲ್ಲಿಯೇ;\nಮನಸ್ಸು ಇಟ್ಟು ಮಾಡು,\nಹೊತ್ತು ತಪ್ುತ್ತೆ ;\nಜಾಗ್ರತೆ ಮಾಡುತ್ತಿರು\nದೇವರಿಗೆ ಪ್ರತಿಷ್ಠೆ ಮಾಡಿಕೊಳ್ಳುವುದು\nಜೀವವಿದ್ದಾಗಲೇ,\nಜೀವಾಂತ್ಯ ದಿನ ನೋಡು,\nಸಾವು ಬರುತ್ತೆ.\n3. ಕೆಲಸ ಮಾಡುತ್ತಿರು\nಸಮಯವೀಗಲೇ ;\nಕರ್ತನು ಬರುತ್ತಾನೆ,\nನ್ಯಾಯತೀರ್ಪಿಗೆ ;\nಜಾಗ್ರತೆಯುಳ್ಳ ದಾಸ\nಮೆಚ್ಚಿಗೆ ಹೊಂದುವ,\nಸೋಮಾರಿಯಾದ ಜಾಷ್ಯ\nಬಿದ್ದು ಹೋಗುವ." },
  80: { title: "ಸ್ವರ್ಗದಲ್ಲಿ ಸೇರುತ್ತೇನೆ,", lyrics: "1. ಸ್ವರ್ಗದಲ್ಲಿ ಸೇರುತ್ತೇನೆ,\nಹೌದೀ ಮಾತು ನಿಜವೇ ;\nಆದರೆನ್ನ ಸ್ವಾಮಿಗಾಗಿ\nನಾನು ಏನು ಮಾಡಿದ್ದೆ?\nಪಲ್ಲವಿ\nಯಾರು ಕ್ರಿಸ್ತನಲ್ಲಿ ನಂಬ\nಯಾವ ಯತ್ನ ಮಾಡದೆ\nಸ್ವಾಮಿ ಎದುರಾಗಿ ಹೋಗ\nಸರಿಯೋ, ಎನ್ನಾತ್ಮವೇ ?\n2. ಹೀಗೆ ಬಿಟ್ಟು ಹೋಗಲೇನು ?\nಸೇರಲಲ್ಲಿ ಹೀಗೆಯೇ ?\nರಕ್ಷಕನ ಮುಂದೆ ನಾನು\nನಾಚಿಕೊಳ್ಳಲಾಗುತ್ತೆ.\n3. ಶಾನೆ ದಿನ ಕ್ರಿಸ್ತನ್ನಂಬಿ\nಪಾಪಕ್ಷಮೆ ಹೊಂದಿದೆ ;\nಆದರೆ ಸ್ವಲಾಭಕ್ಕಾಗಿ\nನಾನು ಬಾಳಿ ಬಂದಿದ್ದೆ\n4. ಸುತ್ತಲಿನ ಜನರಲ್ಲಿ\nತಕ್ಕ ಸಾಕ್ಷಿ ಹೇಳದೆ,\nಚಿಂತೆ ಹೀನನಾಗಿ ಬಾಳಿ,\nಹೋಗ್ವದಲ್ಲಿ ಸರಿಯೇ.\n5. ಇತರರ ಹಿತಕ್ಕಾಗಿ\nಮಾಡು ನಿತ್ಯ ಪ್ರಾರ್ಥನೆ ;\nನಾಶವಾಗ್ವ ಜನಕ್ಕಾಗಿ\nಚಿಂತೆಪಡು, ಮನವೇ." },
  81: { title: "ಏಳೇಳು, ಚೀಯೋನ್ ಸಭೆ!", lyrics: "1. ಏಳೇಳು, ಚೀಯೋನ್ ಸಭೆ!\nಪ್ರಕಾಶವಾಗಿರು!\nಯೆಹೋವನಿಂದ ಪ್ರಭೆ\nನಿನ್ನಲ್ಲಿ ಹುಟ್ಟಿತು ;\nಸಮಸ್ತ ಜನರಲ್ಲಿ\nಆಗಾಧ ಕತ್ತಲು,\nಸಮಸ್ತ ಭೂಮಿಯಲ್ಲಿ\nಅಜ್ಞಾನವಾಯಿತು.\n2. ನಿನ್ನನ್ನು ಸೇರಬೇಕು\nಸಮಸ್ತ ಜನರು ;\nಸನ್ಮಾನ ಮಾಡಬೇಕು\nಪ್ರಖ್ಯಾತ ರಾಜರು ;\nಕಣ್ಣೆತ್ತಿ ಗುಂಪು ನೋಡಿ\nದೇವರಿಗೆ ಪ್ರತಿಷ್ಠೆ ಮಾಡಿಕೊಳ್ಳುವುದು\nಸಂತೋಷವಾಗಿರು ;\nಮಹಾಸಮೂಹ ಓಡಿ\nನಿನ್ನನ್ನು ಹೊಂದಿತು.\n3. ದ್ವೀಪಾಂತರಗಳೆಲ್ಲಾ\nನಿನ್ನಾಸ್ತಿಯಾಗಿವೆ ;\nಜನಾಂಗದವರೆಲ್ಲಾ\nಸ್ವತಂತ್ರ ನಿನಗೆ ;\nಏಳೇಳು, ಚೀಯೋನ್ ಸಭೆ !\nಪ್ರಕಾಶವಾಗಿರು ;\nಯೆಹೋವನಿಂದ ಪ್ರಭೆ\nನಿನ್ನಲ್ಲಿ ಹುಟ್ಟಿತು." },
  82: { title: "ಯುದ್ಧ ಸನ್ನದ್ಧರಾಗಿ,", lyrics: "1. ಯುದ್ಧ ಸನ್ನದ್ಧರಾಗಿ,\nಕ್ರಿಸ್ತನ ಭಟರೇ !\nಆತನ ಧ್ವಜವೆತ್ತಿ\nಹೋರಾಡಿ ವೀರರೇ !\nಕರ್ತನು ತನ್ನ ಸೈನ್ಯ\nಮುಂದರಿಸುವನು\nವಿರೋಧಿಗಳ ಬಲ\nಸಂಹರಿಸುವನು.\n2. ಯುದ್ಧ ಸನ್ನದ್ಧರಾಗಿ,\nತುತ್ತೂರಿ ಕೂಗುತ್ತೆ ;\nಸ್ವಾಮಿಯ ಸೈನ್ಯದಲ್ಲಿ\nಸೇರಿರಿ ಈಗಲೇ,\nಅಪಾಯ ಹೆಚ್ಚುವಾಗ\nಹೆಚ್ಚಾದ ಧೈರ್ಯದಿ\nಕ್ೈಸ್ತರ ದಿವ್ಯ ಯುದ್ಧ\nಸೋಲದೆ ಮಾಡಿರಿ.\n3. ಯುದ್ಧ ಸನ್ನದ್ಧರಾಗಿ,\nಕರ್ತನ ತ್ರಾಣವ\nಯಾವಾಗ್ಯೂ ನಂಬುತ್ತಿರ್ರಿ\nಬಿಡಿರಿ ಸ್ವಾಸ್ಟ್ರವ,\nಸುವಾರ್ತಾ ಸರ್ವಾಯುಧ\nತೆಗೆದುಕೊಳ್ಳಿರಿ ;\nಮಾಡುತ್ತಲಿರ್ರಿ ಜಪ\nಕಠಿಣ ಯುದ್ಧದಿ.\n4. ಯುದ್ಧ ಸನ್ನದ್ಧರಾಗಿ,\nವಿಜಯವಪ್ುದು ;\nಹೋರಾಟ ಘೋಷ ತೀರಿ\nಜಯದಾರ್ಭಟವು\nಉಂಟಾಗೆ ಜಯಶಾಲಿ\nಜೀವದ ಮಾಲೆಯ\nಸಂಭ್ರಮದಿಂದ ಹೊಂದಿ\nನಿರಂತ್ರ ಆಳುವ." },
  83: { title: "ದೇವಸೇವೆ ಮಾಡು,", lyrics: "1. ದೇವಸೇವೆ ಮಾಡು,\nಕಾಲ ನೀಗುತ್ತೆ ;\nಜಾಗರೂಕನಾಗು,\nಜನ ಸಾಯುತ್ತೆ :\nವಾಕ್ಯ ಸಾರಿ ಹೇಳು\nಹೋಗು ಈಗಲೇ,\nಪ್ರೀತಿಯಿಂದ ಸಾರು\nರಾತ್ರಿ ಬರುತ್ತೆ.\n2. ಘನವುಳ್ಳದ್ದೆಂದು\nದೇವ ಕೆಲಸ,\nಕ್ರಿತ್ತನಿಗೆ ಸೇವೆ ಮಾಡುವುದು\nಮನಸ್ಸಿಟ್ಟು ಮಾಡು\nಪ್ರಾಣ ರಕ್ಷಿಸು ;\nದೈವ ಬಹುಮಾನ\nನಿಜ ದಾಸಗೆ\nಸಿಕ್ಕಿ ಕರ್ತನಿಂದ\nಭಾಗ್ಯವಾಗುತ್ತೆ.\n3. ಶುದ್ಧರೆಲ್ಲಾ ಕೂಡಿ\nಸರ್ವಕಾಲವೂ\nದೇವ ಸ್ತೋತ್ರ ಮಾಡಿ\nಅಡ್ಡಬೀಳಲು,\nತನ್ನಾಸನದಿಂದ\nಕರ್ತ ಹೇಳ್ವನು\n“ನೀನು ನಂಬಿಗಸ್ತ ಒಳ್ಳೇ ದಾಸನು.\"" },
  84: { title: "ಕರ್ತಾ ! ಸಿದ್ಧವಾಗಿದ್ದೇನೆ,", lyrics: "1. ಕರ್ತಾ ! ಸಿದ್ಧವಾಗಿದ್ದೇನೆ,\nನನ್ನ ಕೂಡ ಮಾತಾಡು ;\nನಿನ್ನ ಧ್ವನಿ ಕೇಳದೇನೆ\nಇರಲಿಷ್ಟವಿಲ್ಲವು ;\nನಾನು ಕೇಳುತ್ತಿರುವೆ\nನನಗೇನು ಹೇಳುವೆ ?\n2. ನಾ ಸಂದೇಹ ಪಡಲಾಗಿ\nಕರೆ ನನ್ನ ಹೆಸರು ;\nನಿನ್ನ ಹಿಂದೆ ತ್ವರೆಯಾಗಿ\nಹೋಗ ಬಲಪಡಿಸು ;\nಕುರ್ಬನಂತೆ ಮಂದೆಯ\nನೆರಳ್ಗೊಯ್ಯು, ಓ ಕರ್ತಾ !\n3. ಸ್ವಾಮೀ ನಿನ್ನ ಭಕ್ತರಲ್ಲಿ\nಅಲ್ಪವಾದವ ನಾನೇ ;\nಆದರೂ ಇದೆ ನಿನ್ನಲ್ಲಿ\nಪ್ರೀತಿ; ನನ್ನ ತಳ್ಳದೆ,\nನನ್ನಾಕಾಂಕ್ಷೆ ತೀರಿಸು,\nಭಾಗ್ಯಕ್ಕೆನ್ನ ನಡಿಸು.\n4. ನಿನ್ನ ದಿವ್ಯ ಚಿತ್ತವನ್ನು\nತಿಳುಕೊಂಡು ಕೂಡಲೇ\nಪೂರ್ಣ ವಿಧೇಯತ್ವವನ್ನು\nತೋರಿಸುತ್ತಲಿರುವೆ ;\nನಾನು ಕೇಳುತ್ತಾ ಇರೆ\nಮಾತನ್ನಾಡು, ಕರ್ತನೇ !" },
  85: { title: "ಎಷ್ಟು ತಪ್ಪಿಹೋದ ಕುರಿ", lyrics: "1. ಎಷ್ಟು ತಪ್ಪಿಹೋದ ಕುರಿ\nಪಾಪ ಮಾರ್ಗದಲ್ಲಿಯೇ\nಸಂಚಾರ ಮಾಡುತ್ತಾರೆ,\nಒಳ್ಳೇ ಕುರ್ಬನಿಲ್ಲದೆ,\nಅವರ್ಗೆ ನಿರೀಕ್ಷೆಯಿಲ್ಲ;\nಆಶ್ರಯವೇವಿದೆ ?\nಗಂಡಾಂತ್ರ ದಿನದಲ್ಲಿ\nಶಪ್ಲಿಕೊಳ್ವದು ಹ್ಯಾಗೆ ?\nಪಲ್ಲವಿ\nಓ, ಬ್ನಿ ಹುಡುಕುವಾ\nತಪ್ಪಿ ಹೋದವರನ್ನು!\nಪರಲೋಕ ಸೇರಿ ಕೂಗ್ವೆವು\n“ಕರಕೊಂಡು ಬಂದೆವು”\nಕ್ರಿತನಿಗೆ ಸೇವೆ ಮಾಡುವುದು\n2. ಎಷ್ಟು ಮಂದಿ ಕತ್ತಲಲ್ಲಿ\nದೇವ ಬೆಳಕಿಲ್ಲದೆ\nವ್ಯರ್ಥ ಬೊಂಬೆ ಪೂಜಿೆಮಾಡಿ\nಕೆಟ್ಟು ಹೋಗುತ್ತಿದ್ದಾರೆ ;\nನಮ್ಮ ಹತ್ರ ಬೆಳಕುಂಟು,\nಬನ್ನಿ ಸಹೋದ್ರರೇ!\nಇದೇ ರಕ್ಷಣೆ ದಿನ;\nರಾತ್ರಿ ಬೇಗ ಬರುತ್ತೆ.\n3. ನಮ್ಮ ಜೀವ ಸಂಜೆಯಲ್ಲಿ\nಪಯಣ ಮಾಡುವಾಗಲು\nಅನೇಕ ಕುರಿಗಳ\nಕರಕೊಂಡು ಬಂದೆವು\nಎಂದು ಹೇಳಿ ಅವರನ್ನು\nಕರ್ತನ ಪಾದಕ್ಕೆ\nಕರಕೊಂಡು ಸ್ತೋತ್ರ ಮಾಡಿ\nಸಂಕೀರ್ತಿಸುತ್ತೇವೆ." },
  86: { title: "ಒಂದೇ ಬೇಕು, ಒಂದೇ ಮಾತ್ರ.", lyrics: "1. ಒಂದೇ ಬೇಕು, ಒಂದೇ ಮಾತ್ರ.\nನನಗೆ ಅವಶ್ಯವು ;\nಬೇರೆ ಎಲ್ಲಾಪೇಕ್ಷೆ ವ್ಯರ್ಥ,\nಬೇರೆ ಸುಖ ಶೂನ್ಯವು ;\nಯೇಸು ಸ್ವಾಮಿ – (3)\nಜೀವ ಬುಗ್ಗೆ ನನಗೆ\n2. ಏಕಾಪೇಕ್ಷೆ ಇದ್ದು ಮನ\nಲೋಕದಾಶೆ ಬಿಡಲಿ,\nಕ್ಿಸ್ತನಲ್ಲಿ ಸಿಮರ ಧ್ಯಾನ\nನನ್ನ ಆತ್ಮವಿಡಲಿ ;\nಯೆಳು ಸ್ವಾಮಿ – (3)\nಜೀವ ಬುಗ್ಗೆ ನನಗೆ.\n3. ನಿನ್ನ ಮೇಲೆ ನನ್ನಾಪೇಕ್ಷೆ\nಉಂಟು, ಪ್ರಿಯ ಕರ್ತನೇ!\nನಿತ್ಯವೂ ನನ್ನಭಿಲಾಷೆ\nನೀನೇ, ದಿವ್ಯ ಮಿತ್ರನೇ !\nಯೆಸು ಸ್ವಾಮಿ – (3)\nಜೀವ ಬುಗ್ಗೆ ನನಗೆ\n4. ನನ್ನ ದಿವ್ಯ ಯಜಮಾನ\nನಾನು ಕಂಡುಕೊಂಡೆನು,\nಆತ ಬೋಧಿಸುವ ಜ್ಞಾನ\nಹೊಂದಿ ತೃಪ್ತಿಯಾಯಿತು.\nಯೇಸು ಸ್ವಾಮಿ – (3)\nಜೀವ ಬುಗ್ಗೆ ನನಗೆ" },
  87: { title: "ಹರ್ಷದಿಂ, ಹರ್ಷದಿಂ,", lyrics: "1. ಹರ್ಷದಿಂ, ಹರ್ಷದಿಂ,\nಮುಂದೋಡುವ !\nಮೋಕ್ಷದ ಸೈನ್ಯವ ಸಂಧಿಸುವ!\nಯೇಸುವು ಬಾ ಎಂದು ಕರೆಯಲು\nಹರ್ಷದಿಂ ಮೇಲಕ್ಕೆ ಓಡುವೆವು ;\nಲೋಕ ಪ್ರಯಾಣವು ಮುಗಿಯಲು\nಸ್ವರ್ಗಾನಂದಕ್ಕೆ ಸೇರುವೆವು ;\nಸೇರಿದ ಬಳಿಕ ಎಂದೆಂದಿಗೂ\nಹರ್ಷದಿಂ, ಹರ್ಷದಿಂ, ಹಾಡುವೆವು.\n2. ಸಾವಿನ ಬಾಣವು ತಾಕಿದರೂ\nದಿಗಿಲು ನಮ್ಮನ್ನು ಹಿಡಿಯದು :\nಯೇಸು ಸಮಾಧಿಯ ಜಯಿಸಿದ,\nಹರ್ಷದಿಂ, ಹರ್ಷದಿಂ,\nಮುಂದೋಡುವ,\nವಿವಿಧ ಸಂಗೀತಗಳು\nಮರಣ ನಮ್ಮನ್ನು ಜಯಿಸದು,\nಯೇಸುವಿನವರ ಮಿತ್ರ ಅದು ;\nಪರಮ ಭಾಗ್ಯವ ಆಶಿಸಿದ್ಯಾ ?\nಹರ್ಷದಿಂ, ಹರ್ಷದಿಂ,\nಮುಂದೋಡುವ.\n3. ನಮ್ಮನ್ನು ಬಿಟ್ಟಾಪ್ತ ಸ್ನೇಹಿತರು\nಮೇಲಣ ಸೈನ್ಯದ ಸಂಗಡಲು\nನಮ್ಮನ್ನು ಮೇಲಕ್ಕೆ ಕರೆದರು,\nಹರ್ಷದಿಂ, ಹರ್ಷದಿಂ, ಹೋಗುವೆವು\nಬಂಗಾರ ವೀಣೆಯಂ ಸ್ವರಗಳ\nಇಂಪಾದ ರಾಗದ ಧ್ವನಿಗಳ\nಕಿವಿಗಳೊಳಗೆ ಕೇಳಿದೆವು,\nಹರ್ಷದಿಂ, ಹರ್ಷದಿಂ, ಓಡುವೆವು." },
  88: { title: "ಭಯವೇನಿಲ್ಲ ಸಂತೋಷವೇ,", lyrics: "1. ಭಯವೇನಿಲ್ಲ ಸಂತೋಷವೇ,\nಯೇಸು ನನ್ನಾತ್ಮ ಗೆಳೆಯನೇ ;\nಸ್ವರ್ಗದ ಭಾಗ್ಯ ಬಾಧ್ಯತೆಯೇ\nನನಗೆ ಉಂಟು ಅಭಯವೇ.\nಪಲ್ಲವಿ\nಇದು ಎನ್ ರಾಗ ವಿತ್ಯ ಭಾಗ್ಯ\nನನ್ನಲ್ಲಿ ಉಂಟು ಹಲ್ಲೆಲೂಯ ;\nಯೇಸು ಎನ್ನಾತ್ಮ ಉದ್ಧಾರಕ ;\nಸ್ವಾಮಿಗೆ ಸ್ತೋತ್ರ, ನಿತ್ಯ ಘನು\n2. ಪರಿಶುದ್ಧಾತ್ಮ ನನ್ನಲ್ಲಿಯೇ\nಪವಿತ್ರ ಶಾಂತಿದಾಯಕನೇ ;\nಯೇಸುವು ಅಂದ ಸತ್ಯವನ್ನೇ\nಶೋರಿಸಿ ಕೊಡ್ವನೆನ್ನಾತ್ಕ್ಕೆ\n3. ಆನಂದವೆಷ್ಟು ನಿರೀಕ್ಷೆಯೂ\nನನ್ನಲ್ಲಿ ತುಂಬಿ ಇರುವುದು ;\nಯೇಸುವು ಬರ್ವ ಕಾಲವನ್ನು\nಎದುರು ನೋಡಿ ಕಾಯುವೆನು.\n4. ಎನ್ನಾತ್ಮದಾಪ್ತ ಬರುವನು ;\nಆತನ ಕೂಡ ಹೋಗುವೆನು,\nಆತನೂ ನಾನೂ ಸ್ವರ್ಗದಲ್ಲೂ\nವೈಭವದಲ್ಲಿ ಇರುವೆವು." },
  89: { title: "ಬಹುಕಾಲ ಗರ್ವದಿಂದಲೂ", lyrics: "1. ಬಹುಕಾಲ ಗರ್ವದಿಂದಲೂ\nಸ್ವಾಮಿ ವಾಕ್ಯ ತಳ್ಳಿಬಿಟ್ಟರೂ ;\nಯೇಸು ನನ್ನ ಪ್ರೀತಿಸಿದನು,\nಕಲ್ವೇರಲ್ಲಿ.\nಪಲ್ಲವಿ\nಕೃಪೆ ಅಲ್ಲಿ ನನ್ನ ಕಡೆಗೆ\nಸ್ವಾಮಿ ತೋರಿಸಿದನಲ್ಲವೇ !\nಅಲ್ಲಿ ಪಾಪ ಸಾಲ ಸಂದಿದೆ,\nಕಲ್ವೇರಲ್ಲಿ\n2. ದೇವ ಸತ್ಯ ವಾಕ್ಯ ನನ್ನಲ್ಲೂ\nಬಹು ಭಯ ಉಂಟು ಮಾಡಿತು.\nಆತ್ಮ ಸಮಾಧಾನ ಕೊಟ್ಟನು,\nಕಲ್ವೇರಲ್ಲಿ\n3. ಈಗ ನಾನು ಯೇಸು ಸ್ವಾಮಿಗೆ\nನಿತ್ಯ ಸೇವೆ ಮಾಡಿ ಹಾಡುವೆ ;\nಪರಿಪೂರ್ಣ ಪ್ರೀತಿ ನೋಡುವೆ ;\nಕಲ್ವೇರಲ್ಲಿ.\nವಿವಿಧ ಸಂಗೀತಗಳು\n4. ಎಂಥಾ ಪ್ರೀತಿ ನನ್ನ ಸುತ್ತಿದೆ,\nಎಂಥಾ ಕೃಪೆ ನನ್ನ ಮೇಲೆಯೇ,\nಎಂಥಾ ಕರುಣಾತಿಶಯವೇ,\nಕಲ್ವೇರಲ್ಲಿ\n5. ಯೇಸು ನನ್ನ ನಿತ್ಯ ನಾಥನು,\nನಾನು ಯೇಸುವಿನ ಸಾಕ್ಷಿಯು,\nನಿತ್ಯ ವಾಸಸ್ಥಳ ನನಗೂ,\nಕಲ್ವೇರಲ್ಲಿ." },
  90: { title: "ಆಶ್ಚರ್ಯವಾದವ,", lyrics: "1. ಆಶ್ಚರ್ಯವಾದವ,\nಆಶ್ಚರ್ಯವಾದವ,\nದೇವಪುತ್ರ ಯೇಸು ಸ್ವಾಮಿ,\nಹೌದೌದು,\nಆಶ್ಚರ್ಯವಾದವ.\n2. ಆಲೋಚನಾ ಕರ್ತ,\nಆಲೋಚನಾ ಕರ್ತ,\nದೇವ ಪುತ್ರ ಯೇಸು ಸ್ವಾಮಿ,\nಹೌದೌದು,\nಆಲೋಚನಾ ಕರ್ತ.\n3. ಬಲಿಷ್ಠನಾ ದೇವ,\nಬಲಿಷ್ಠನಾ ದೇವ,\nದೇವಪುತ್ರ ಯೇಸು ಸ್ವಾಮಿ,\nಹೌದೌದು,\nಬಲಿಷ್ಠನಾದೇವ.\n4. ನಿತ್ಯನಾದ ತಂದೆಯು\nನಿತ್ಯನಾದ ತಂದೆಯು,\nದೇವಪುತ್ರ ಯೇಸು ಸ್ವಾಮಿ,\nಹೌದೌದು,\nನಿತ್ಯನಾದ ತಂದೆಯು\n5. ಸಮಾಧಾನ ಪ್ರಭುವು,\nಸಮಾಧಾನ ಪ್ರಭುವು,\nದೇವಪುತ್ರ ಯೇಸು ಸ್ವಾಮಿ,\nಹೌದೌದು,\nಸಮಾಧಾನ ಪ್ರಭುವು." },
  91: { title: "ಯೇಸು ಸ್ವರ್ಗಲೋಕ ಬಿಟ್ಟು", lyrics: "1. ಯೇಸು ಸ್ವರ್ಗಲೋಕ ಬಿಟ್ಟು\nನನಗಾಗಿ ಸತ್ತನು,\nಶಿಲ್ಬೆ ಘೋರ ಮೃತಿಪಟ್ಟ\nಎಂಥಾ ಪ್ರಾಣಪ್ರಿಯನು!\nಪಲ್ಲವಿ\nಹೌದಾ ಪ್ರೇಮದತಿಶಯ\nಇಂದೂ ಎಂದೂ ಹಾಡುವೆ\nಕ್ಿ್ತ ಭಕ್ತ ಗಣಗಳ\nಜೊತೆ ಸೇರಿ ಹಾಡುವೆ.\n2. ನಾನು ತಪ್ಪಿ ಹೋದ ಕುರಿ,\nಯೇಸು ನನ್ನ ಕುರ್ಬನು,\nತಗ್ಗು ಬೆಟ್ಟಗಳ ದಾಟಿ\nನನ್ನನ್ನೆತ್ತಿ ತಂದನು.\n3. ನಾನು ಕಷ್ಟದಲ್ಲಿ ಬಿದ್ದು\nದಿಕ್ಕು ಕಾಣದಿರಲು\nಯೇಸು ಸ್ವಾಮಿ ಹತ್ರ ಬಂದು\nನನ್ನನ್ನಪ್ಪಿಕೊಂಡನು.\n4. ಕಣ್ಣು ಕಾಣದಿರುವಾಗ\nದಿವ್ಯ ದೃಷ್ಟಿ ಕೊಟ್ಟನು ;\nಧೈರ್ಯ ಕುಂದಿ ಹೋಗುವಾಗ\nನನ್ನ ಬಳಿ ನಿಂತನು.\nವಿವಿಧ ಸಂಗೀತಗಳು\n5. ಬಾಧೆ ದುಖು ಸಾಗ್ರದಲ್ಲಿ\nಯೇಸು ಹತ್ರವಿರುವ,\nತನ್ನ ದಿವ್ಯ ಹಸ್ತ ನೀಡಿ\nನನ್ನ ಮೇಲಕ್ಕೆತ್ತುವ.\n6. ಕಡೆಯಲ್ಲಿ ಇಹಲೋಕ\nಬಿಟ್ಟು ಮುಂದೆ ಹೋಗುವೆ ;\nನನಗೇನೂ ಭಯವಿಲ್ಲ\nಸ್ವಾಮಿಯೊಂದಿಗಿರುವೆ." },
  92: { title: "ಎಂದಾದರೂ ನಾ ಹೋಗುವೆ,", lyrics: "1. ಎಂದಾದರೂ ನಾ ಹೋಗುವೆ,\nನಾನಿಲ್ಲಿ ನಿಲ್ಲದಿರುವೆ,\nಕ್ರಿಸ್ತನ ಅರಮನೆಗೆ\nನಾ ಸೇರಿ ಹರ್ಷಗೊಳ್ಳುವೆ.\nಪಲ್ಲವಿ\nಸ್ವರ್ಗದ ಗಾನ ಕೃಪೆಯ\nಅಲ್ಲೇನೂ ದುಚಖವಾಗದು ;\nದೇವರ ಮುಖ ನೋಡುವೆ,\nನಿರಂತ್ರ ಸ್ತುತಿಸುವೆನು.\n2. ಅಂದೇ ಈ ದೇಹ ಬಿಡ್ವೆನು ;\nಎಂದ್ಹೋಗುವೆ ನಾನರಿಯೆ\nಅಂತೂ ಆತನ ಮನೆಯು\nಎನ್ನಿತ್ಯ ಸ್ಥಳವಾಗುತ್ತೆ.\n3. ಆ ದಿನ ಸ್ವಾಮಿ ನನಗೆ\nನೀ ಒಳ್ಳೆ ದಾಸನಾಗಿದ್ದೀ\nಅನ್ನುವುದನ್ನು ಕೇಳಿಯೇ\nಎಷ್ಟೋ ಸಂತೋಷವಿರುತ್ತೆ.\n4. ಆ ದಿನಕ್ಕಾಗಿ ಕಾಯುವೆ,\nಹೋಗಲು ಸಿದ್ಧನಾಗುವೆ ;\nಅಪ್ಟಣೆಯಾದ ಕೂಡಲೆ\nಇಲ್ಲಿಂದ ಎದ್ದು ಹೋಗುಮೆ\n5. ಆತನ ಲೊಣ ನನಗೂ\nನಿರಂತ್ರ ಮನೆಯಾಗ್ವದು.\nಅಲ್ಲಿಂದ ಹೋಗೆನೆಂದಿಗೂ\nಸದಾ ಸಂತೋಷಿಸುವೆನು." },
  93: { title: "ಎನ್ನೇಸುವೇ ನಿನ್ನಲ್ಲಿಯೇ", lyrics: "1. ಎನ್ನೇಸುವೇ ನಿನ್ನಲ್ಲಿಯೇ\nಸಂತೃಪ್ತಿಗೊಳ್ವೆಮ ;\nವಿಶ್ರಾಂತಿ ದಿವ್ಯಾನಂದವೇ\nಏ್ನಿಂದಲಾಗ್ವವು.\nಪಲ್ಲವಿ\nಇವ್ಯಾರ ಬಳಿ ಹೋಗೆನು,\nವಾನೆಲ್ಲಿ ನೋಡೆನು,\nಸುಪ್ರೇಮ ಶಾಂಶಿಯೆಲ್ಲವೂ\nವಿನ್ನಲ್ಲಿ ರ್ವವು\n2. ಎನ್ ಸ್ವಾಮ್ಯ ಪ್ರೀಶಿ ಕರುಣೆ\nಧಿಕ್ಕರಿದ್ದೆನು;\nಪನ್ನನ್ನು ಆತ ಶಳ್ಳದೆ\nಸ್ವಿಶರಿಸಿದನು.\n3. ಜೀವದ ಬುಗ್ಗೆ ಕಾಣದೆ\nನಾ ಗುರಿಗೆಟ್ಟಿನು ;\nನಿನ್ ಹತ್ರ ಬಂದು ಕುಡಿದೆ\nಎನ್ ದಾಹ ಶೀರಿತು.\nವಿವಿಧ ಸಂಗೀತಗಳು\n4. ಲೊಕ ವಿನೋದ ಚಿಂತೆಯೂ\nಆವರಿಸಿದವು ;\nನಿನ್ನಿಂದಲೀಗ ತೃಪ್ತಿಯು\nಎನ್ನಾತ್ಮ ತುಂಬ್ವದು.\n5. ಸಂತೋಷವಲ್ಲ ದುಚವೇ,\nನನ್ನಲ್ಲಿ ಶುಂಬಿತ್ತು ;\nನಾ ನಿನ್ನ ನೋಡಿ ಕೂಡಲೇ\nಸಂತೋಷಪಟ್ಟಿನು." },
  94: { title: "ದೇವರು ನಿಮ್ಮನ್ನು ಕಾಯಲಿ ;", lyrics: "1. ದೇವರು ನಿಮ್ಮನ್ನು ಕಾಯಲಿ ;\nದಿನೇ ದಿನೇ ದಾರಿ ತೋರ್ಸಿ,\nತನ್ನ ಹಟ್ಟಿಯಲ್ಲಿ ಸೇರ್ಸಿ,\nದೇವರು ನಿಮ್ಮನ್ನು ಕಾಯಲಿ.\nಪಲ್ಲವಿ\nಕ್ರಿಸ್ತ ಪಾದಕ್ಕೆ ಸೇರ್ವವರೆಗೆ\nನಿಮ್ಮನ್ನೆಲ್ಲಾ ದೇವರು ಕಾಪಾಡಲಿ\nಕ್ರಿಸ್ತ ಪಾದಕ್ಕೆ ಕೂಡ್ವವರೆಗೆ\nದೇವರು ನಿಮ್ಮನ್ನು ಕಾಯಲಿ.\n2. ದೇವರು ನಿಮ್ಮನ್ನು ಕಾಯಲಿ ;\nಬಾಧೆ ಕಷ್ಟ ಬರುವಲ್ಲಿ\nಶೋಧನೆಯುಂಟಾಗುವಲ್ಲಿ\nದೇವರು ನಿಮ್ಮನ್ನು ಕಾಯಲಿ.\n3. ದೇವರು ನಿಮ್ಮನ್ನು ಕಾಯಲಿ,\nಶನ್ನ ರೆಕ್ಕೆಯಲ್ಲಾಶ್ರಯಿಸಿ,\nತನ್ನ ವಾಕ್ಯದಿಂ ಸಂತೈೆಸಿ,\nದೇವರು ನಿಮ್ಮನ್ನು ಕಾಯಲಿ.\nವಿವಿಧ ಸಂಗೀತಗಳು\n4. ದೇವರು ನಿಮ್ಮನ್ನು ಕಾಯಲಿ ;\nಆತ್ಮಾನ್ಯೋನ್ಯವ ನಿಮ್ಮಲ್ಲಿ\nಹೆಚ್ಚುತ್ತಿರುವಂತೆ ಮಾಡಿ,\nದೇವರು ನಿಮ್ಮನ್ನು ಕಾಯಲಿ." },
  95: { title: "ಲೋಕಕ್ಕೆಲ್ಲಾ ದುಖ", lyrics: "1. ಲೋಕಕ್ಕೆಲ್ಲಾ ದುಖ\nಪ್ರಾಪ್ತವಾಗಿದೆ\nಆದರೆ ಸಂತೋಷ\nಉಂಟು ನಮಗೆ ;\nಯೇಸು ಸ್ವಾಮಿಯನ್ನು ನಂಬಿಕೊಳ್ಳಲು\nಆತನ್ ದಿವ್ಯಾನಂದ\nಪೂರ್ತಿಯಾಯಿತು.\nಪಲ್ಲವಿ\nದುಖುವು ಬಾಧೆ ಭಯವನ್ನೆಲ್ಲಾ\nಕರ್ತನ ಸಂತೋಷದಿಂ\nನಿತ್ಯ ಜೈಸುವ ॥\n2. ನಿತ್ಯ ಪ್ರಾತಣಾಲ\nಸೂರ್ಯನಿಂದಲೇ\nರಾತ್ರಿ ಕತ್ತಲೆಲ್ಲಾ\nಹಾರಿ ಹೋಗುತ್ತೆ ;\nನಮ್ಮ ಪ್ರಿಯ ಕರ್ಶ\nನೀತಿ ಸೂರ್ಯನು\nನಮ್ಮ ಪಾಪವೆಲ್ಲಾ ಹಾರಿಸುವನು.\n3. ಸ್ವರ್ಗಕ್ಕೆ ಪ್ರಯಾಣ\nಮಾಡುತ್ತಿರಲು\nನಿತ್ಯ ಉಪಕಾರ\nತೋರಿಸುಶ್ತಿರು ;\nಎಲ್ಲಕ್ಕಿಂಶ ಪ್ರೀಶಿ\nಶ್ರೇಷ್ಯವಾಗಿದೆ.\nಎಂದು ಯೇಸು ಸ್ವಾಮಿ\nದಿವ್ಯ ಮಾಶಿದೆ." },
  96: { title: "ನಮ್ಮನ್ನು ಸ್ನೇಹಿಸಿದವನ್ಯಾರು ?", lyrics: "1. ನಮ್ಮನ್ನು ಸ್ನೇಹಿಸಿದವನ್ಯಾರು ?\nಯೇಸುವೇ, ಯೇಸುವೇ,\nಸದಾ ಸಮೀಪದಿ ಇರುವನು ;\nಯೇಸುವೇ, ಯೇಸುವೇ.\nಪಲ್ಲವಿ\nನಮ್ಮ ಕಷ್ಟಗಳೆಲ್ಲಾ ಬಲ್ಲ:\nನಿತ್ಯ ಕಾಯುವವನಲ್ಲವೇ !\nಆತನ ಹಾಗೆ ಮತ್ತೊಬ್ಬರಿಲ್ಲ:\nಯೇಸುವೇ, ಯಸುವೇ\n2. ನಮ್ಮನ್ನು ರಕ್ಷಿಸಿದವನ್ಯಾರು ?\nಯೇಸುವೇ, ಯೇಸುವೇ,\nಪಾಪವ ಜಿಡಿಸಿದವನ್ಯಾರು ?\nಯೇಸುವೇ, ಯೇಸುವೇ.\n3. ಆತ್ಮದ ರೋಗಕ್ಕೆ ವೈದ್ಯನಾತ ;\nಯೇಸುವೇ, ಯೇಸುವೇ.\nಇವನ ಹೊರ್ತು ರಕ್ಷಕನಿಲ್ಲ;\nಯೇಸುವೇ, ಯೇಸುವೇ.\n4. ಆತನ ಪ್ರೀತಿಯ ಮರೆಯಬೇಡ್ರಿ ;\nಕ್ರೆಸ್ತರೇ, ಕರೆಸ್ತರೇ !\nನಿತ್ಯದಿ ಸ್ತೋತ್ರವನ್ನರ್ಪಿಸಿರಿ ;\nಸ್ವಾಮಿಗೆ, ಸ್ವಾಮಿಗೆ" },
  97: { title: "ಓ ಯೆಹೋವಾ! ನಮ್ಮ ದೇವಾ!", lyrics: "1. ಓ ಯೆಹೋವಾ! ನಮ್ಮ ದೇವಾ!\nನಿನ್ನನ್ನು ಕೊಂಡಾಡುವೆ,\nನಿನ್ನ ನಾಮ ಸ್ತುತಿಸುವೆ,\nಅದ್ಭುತದ ದೇವರೇ!\nಪಲ್ಲವಿ\nಸಮಾಧಾನ ಸಿಕ್ಕುತ್ತೆ –\nಪೂರ್ಣ ಸಮಾಧಾನವೆ –\nನಾನಿನ್ನಲ್ಲಿ ಇಟ್ಟರೆ\nಸ್ಥಿರವಾದ ನಂಬಿಕೆ.\n2. ಬಡವರಿಗೆ ಆಶ್ರಯ ;\nದೀನರಿಗೆ ಶರಣಾ,\nಬಿಸಿಲಲ್ಲಿ ನನಗಾಗಿ,\nನೆರಳಾಗಿದ್ದೀ, ದೇವಾ!\n3. ನಿರೀಕ್ಷಿಸಿದ್ದೇನೆ ನಿನ್ನ;\nರಕ್ಷಿಸಿದ್ದೀ ನನ್ನನ್ನು;\nಹರ್ಷಿಸುವೆನು ನಿನ್ನಲ್ಲಿ\nನೀನೇ ನನ್ನ ಭಾಗ್ಮವು.\n4. ನಿತ್ಯವಾದ ಬಲವುಂಟು\nವಿನ್ನಲ್ಲಿ ಯೆಹೋವನೇ!\nಸ್ಮಿರ ಭರವಸವಿಟ್ಟೆ\nದೃಢ ಮನಸ್ಲಿಂದಲೇ" },
  98: { title: "ನಿರಿಕ್ಷಿಸಿದ್ದೆಮು, ಕರ್ಶನೇ!", lyrics: "1. ನಿರಿಕ್ಷಿಸಿದ್ದೆಮು, ಕರ್ಶನೇ!\nಕೇಳದ್ದೀ ಪನ್ನ ಮೊರೆಯೇ;\nವಿವಿಧ ಸಂಗೀತಗಳು\nಸಾಯುವ ನನ್ನನ್ನು ಪಾಪದ\nಕುಣಿಯಿಂದ ಎತ್ತಿದ್ದೀ.\nಪಲ್ಲವಿ\nನೀ ಯೋಚಿಸುತ್ತಿದ್ದೀ,\nಕರ್ತಾ, ನನಗಾಗಿ!\nನೀ ದುಖ ತಪ್ಪಿಸ ಬರುತ್ತೀ,\nನೀ ಯೋಚಿಸುತ್ತಿದ್ದೀ.\n2. ಎನ್ ಪಾದವಿಟ್ಟಿದ್ದೀ ಬಂಡೆಗೆ,\nಸ್ಥಿರಮಾಡಿ ನನ್ನ ನಡೆಯೇ,\nಸುರಾಗ ಕೊಟ್ಟಿದ್ದೀ ಬಾಯಲ್ಲೇ -\nಸ್ತೋತ್ರದ ರಾಗವೇ.\n3. ಜನ ಕೇಳಿ ಭಯದಿಂದಲೂ\nನಿನ್ನ ತಾನೇ ಹರಸುವರು ;\nನಿನ್ನನ್ನು ನಂಬುವ ಮನುಜ\nಸೌಭಾಗ್ಯವಂತನು.\n4. ನಿನ್ನನ್ನು ಹರಸುವವರು\nನಿನ್ ಕಾರ್ಯವ ಪ್ರೀತಿಸುವರು.\nನಿನ್ನಲ್ಲಿ ಹರ್ಷಿಸಿ ಅವರು\nಜಯವ ಹೊಂದ್ವರು.\n5. ಓ ದೇವರೇ! ತಡಮಾಡದೆ\nನೀ ಬೇಗ ಬಂದು ಭಕ್ತಗೆ\nಸಹಾಯಿಸು; ನಿನ್ನಾಮಕ್ಕೆ\nಬರಲಿ ಮಹಿಮೆ." },
  99: { title: "ಭ್ರಮೆಯು ಬೇಡ ಕಷ್ಟದೊಳ್ –", lyrics: "ಭ್ರಮೆಯು ಬೇಡ ಕಷ್ಟದೊಳ್ –\nದೇವರು ಕಾಯ್ಡನು,\nಪ್ರೀತಿಯ ರೆಕ್ಕೆ ನೆರಳೊಳ್\nದೇವರು ಕಾಯ್ವನು.\nಪಲ್ಲವಿ\nದೇವರು ಕಾಯ್ವನು\nಅನುದಿನ ಹಾದಿಗಳೊಳ್\nಕಾಯುವ ನಿಶ್ಚಯ ;\nದೇವರು ಕಾಯ್ವನು.\n2. ಹೃದಯ ಕುಂದಿಹೋದರೂ\nದೇವರು ಕಾಯ್ವನು\nಮಾರ್ಗದೊಳ್ ಭಯವಿದ್ದರೂ\nದೇವರು ಕಾಯ್ವನು.\n3. ಬೇಕಾದದ್ದನ್ನು ಕೊಡ್ವನು ;\nದೇವರು ಕಾಯ್ವನು.\nಕೊಡುವನೆಂದು ನಂಬಿರು ;\nದೇವರು ಕಾಯ್ವನು.\n4. ಒಂಟಿಗನಾಗಿ ಹೋದರೂ\nದೇವರು ಕಾಯ್ವನು ;\nಆತನು ಶಾಂತಿ ಕೊಡ್ವನು ;\nದೇವರು ಕಾಯ್ವನು.\n5. ಎಂಥಾ ಪರೀಕ್ಷೆಯಾದರೂ\nದೇವರು ಕಾಯ್ವನು ;\nಆತನನ್ನಾತುಕೊಂಡಿರು ;\nದೇವರು ಕಾಯ್ವನು." },
  100: { title: "ಭಕ್ತಿ ಭಯದಲ್ಲಿ ವಾಕ್ಯ ಬೆಳಕಲ್ಲಿ", lyrics: "1. ಭಕ್ತಿ ಭಯದಲ್ಲಿ ವಾಕ್ಯ ಬೆಳಕಲ್ಲಿ\nನಾವು ನಡೆಯುತ್ತಾ ಬಂದರೆ\nನಮ್ಮ ಸಂಗಡಲೂ ಕರ್ತ ಬರುವನು;\nಸಂಶೋಷವ ಕೊಡುತ್ತನೆ\nವಿವಿಧ ಸಂಗೀತಗಳು\nಪಲ್ಲವಿ\nಕೇಳುವದೇ ಹಾಗೆ ಮಾಡುವದೇ\nಸಂತೋಷದ ಮಾರ್ಗ ಇದೇ\nಅಲ್ಲವೇ?\n2. ವ್ಯಥೆ ವ್ಯಸನವೆಲ್ಲಾ ಭೀತಿ ಬ್ರಾಂತಿ ಸಹ,\nಆತನ್ ಮುಂದೆ ಹಾರಿ ಹೋಗ್ವವು ;\nಕರ್ತ ಶಾಂತಿಯನ್ನೂ ಸಮಾಧಾನವನ್ನೂ\nತನ್ನನ್ ಕೇಳ್ವರಿಗೆ ಕೊಡ್ವನು.\n3. ಕರ್ತ ಪ್ರೀತಿಯನ್ನು ಅನುಭವಿಸಲು\nನಮ್ಮ ಹೃದಯವನ್ನು ತಂದು\nಆತನ್ ಸುವಶಕ್ಕೆ ಒಪ್ಪಿಸಿಕೊಟ್ಟರೆ\nಅತಿ ದಯವ ಹೊಂದುವೆವು.\n4. ಆತನೈಕ್ಯದಲ್ಲೇ ಕರ್ಶನ ಪಾದಕ್ಕೆ\nಕೂತುಕೊಳ್ಳುವ ನಿತ್ಯದಲ್ಲೇ,\nಆತನ್ ಸುಚಿತ್ತವಾಶಕ್ತಿಯಿಂ ಮಾಡುವ\nಆಶೀರ್ವಾದವು ಸಿಕ್ಕುತ್ತದೆ." },
  101: { title: "ಎಂಥಾಮೂಲ್ಯವಾದ ರಕ್ತ", lyrics: "1. ಎಂಥಾಮೂಲ್ಯವಾದ ರಕ್ತ\nಶಿಲ್ಬೆ ಮೇಲಿಯೇ\nಪಾಪಿಗಳಿಗಾಗಿ ಯೇಶು\nಚೆಲ್ಯಲ್ಲವೇ ?\nಪಲ್ಲವಿ\nಎಂಥಾಮೂಲ್ಯವಾದ ರಕ್ತ\nಚೆಲ್ಲಿತಲ್ಲವೇ ;\nಕರ್ತ ಯೇಸುವಿನ ಡ್ತ\nನನಗಾಗಿಯೇ\n2. ಯೇಸುವಿನಾಮೂಲ್ಯ ರಕ್ತ\nಶುದ್ಧ ಮಾಡುತ್ತೆ,\nಹರಿಯುತ್ತೆ ನಿನಗಾಗಿ\nನನ್ನ ಆತ್ಮವೇ!\n3. ಪಾಪ ಅತಿ ಕೆಂಪಾಗಿದ್ದು\nಹೆಚ್ಚಾಗಿದ್ದರೂ\nಯೇಸುವಿನಾಮೂಲ್ಯ ರಕ್ತ\nಶುದ್ಧ ಮಾಡ್ವದು.\n4. ನನ್ನ ಕೊಂಡುಕೊಂಡ ರಕ್ತ\nಶಾಂತಿ ಮಾಡ್ವದು ;\nಅದರಿಂದ ಪಾಪ ಕ್ಷಮೆ\nದೊರೆಯುವದು.\n5. ದೇವ ಪರಿಶುದ್ಧವಾದ\nಸನ್ನಿಧಾನಕ್ಕೆ\nನನಗೆ ಪ್ರವೇಶವುಂಟು\nಧೈರ್ಯವಿರುತ್ತೆ.\n6. ಆತ್ಮ ಯುದ್ಧದಲ್ಲಿ ನಾನು\nಸೋತು ಹೋಗೆನು,\nಯೇಸುವಿನ ರಕ್ತದಿಂದ\nಜಯ ಹೊಂದ್ವೆನು.\n7. ಸ್ತೋತ್ರ ಬಲಿಗಳ ತಂದು\nಅರ್ಪಿಸುವೆನು\nಕರ್ತನಾದ ಯೇಸು ಸ್ವಾಮಿ\nಹೊಂದ ಯೋಗ್ಯನು." },
  102: { title: "ಸುತ್ತ ದೊಡ್ಡದಂಡು ನೋಡಿ,", lyrics: "1. ಸುತ್ತ ದೊಡ್ಡದಂಡು ನೋಡಿ,\nಜತೆಗಾರರೇ !\nಎದುರಾಳಿ ಸೈತಾನ್ ಬಂದು\nನಿಂತನಲ್ಲವೇ ?\nವಿವಿಧ ಸಂಗೀತಗಳು\nಪಲ್ಲವಿ\nಕೋಟೆ ಭದ್ರ ! ಅಂದನೇಸು\nವೀರರಾಗಿರಿ ;\nಸ್ಥಿರವಾಗಿದ್ದೇವೆ ಎಂದು\nಉತ್ರಕೊಡಿರಿ.\n2. ಶಿಲ್ಬೇ ಧ್ವಜವನ್ನು ಕಂಡು\nಧೈರ್ಯಪಡಿರಿ ;\nಕರ್ತನ ವಾಗ್ದತ್ತ ನಂಬಿ,\nಯುದ್ಧ ಮಾಡಿರಿ.\n3. ಯುದ್ಧ ಘೋರವಾಗಿದ್ದಾಗ್ಯೂ\nಭಯವಿಲ್ಲವು ;\nಜೊತೆಯಲ್ಲಿ ರಾಜನಿರುವ\nಸೋತು ಹೋಗೆವು.\n4. ಹೌದು ನಮ್ಮ ಕೂಡಿದ್ದಾನೆ,\nಜಗತ್ಪಭುವೇ ;\nರಾಜ್ಯವನ್ನು ಆಳುತ್ತಾನೆ,\nಜಯವಾಗುತ್ತೆ." },
  103: { title: "ಹೌದೌದು, ಭದ್ರವಾದೆ", lyrics: "1. ಹೌದೌದು, ಭದ್ರವಾದೆ\nಯೇಸುವಿನಲ್ಲಿಯೇ,\nಆ ಪ್ರೀತಿಯುಳ್ಳ ಎದೆ\nಆಶ್ರಯ ಮಾಡಿದೆ;\nದೂತರ ಶಬ್ದ ಕೇಳು,\nಆನಂದ ಸ್ವರವೇ,\nಮೇಲಾದ ಲೋಕದಿಂದ\nಇಂಪಾಗಿ ಬರುತ್ತೆ.\nವಿವಿಧ ಸಂಗೀತಗಳು\nಪಲ್ಲವಿ\nಹೌದೌದು, ಭದ್ರವಾದೆ\nಯೇಸುವಿನಲ್ಲಿಯೇ ;\nಆ ಪ್ರೀತಿಯುಳ್ಳ ಎದೆ\nಆಶ್ರಯ ಮಾಡಿದೆ.\n2. ಯೇಸು ನನ್ನಾತ್ಮದಾಪ್ತ,\nವ್ಯಾಕುಲ ಹೋಯಿತು ;\nಶೋಧಕ ಜೈಸಲಾರ,\nಪಾಪಾಶೆ ಇಲ್ಲವು.\nಕಣ್ಣೀರು ಈಗ ಇಲ್ಲ\nದಿಗಿಲು ಹೋಯಿತು,\nಉಪದ್ರ ಬಂದರೇನು ?\nತತ್ಕಾಲ ಮಾತ್ರದ್ದು\n3. ಯೇಸು ನನ್ನಾತ್ಮಾಶ್ರಯ,\nಪಾಪಿಯ ಮಿತ್ರನು ;\nಈ ತ್ರಾಣ ಸ್ಥಾನ ನಾನು\nಎಂದೆಂದೂ ಬಿಡೆನು.\nಈಗಿನ ಮೋಡ ಹೋಗ\nಕಾದು ಕೊಂಡಿರುವೆ.\nಸುವರ್ಣ ದೇಶ ನೋಡ\nನಿರೀಕ್ಷಿಸಿರುವೆ." },
  104: { title: "ಕಾಪಾಡುವವ ದೇವರೇ,", lyrics: "1. ಕಾಪಾಡುವವ ದೇವರೇ,\nಸಂತೋಷವುಳ್ಳ ಯೋಚನೇ\nನಾನೆಲ್ಲಿ ಹೇಗೆ ಇದ್ದರೂ\nಕಾಪಾಡುವವ ದೇವರೇ.\nಪಲ್ಲವಿ\nಕಾಪಾಡುವವ ದೇವರೇ,\nತನ್ನ ಸ್ವಹಸ್ತದಿಂದಲೇ,\nಅಧೈರ್ಯ ಬಿಟ್ಟು ನಂಬುವೆ,\nಕಾಪಾಡುವವ ದೇವರೇ.\n2. ಒಂದೊಂದು ವೇಳೆ ದುಬುವು,\nಒಂದೊಂದು ವೇಳೆ ಸುಖವು,\nಹೇಗಿದ್ದರೂ ನಿಶ್ಚಿಂತೆಯೇ,\nಕಾಪಾಡುವವನಾತನೇ.\n3. ಏನೇನು ಪ್ರಾಪ್ತಿಸಿದರೂ\nನಾ ಗುಣಗುಟ್ಟಲಾರೆನು ;\nಯಾವಾಗಲೂ ಸಂತೃಪ್ತನೇ,\nಕಾಪಾಡುವವನಾತನೇ.\n4. ಈ ಜೀವದಂತ್ಯ ಬಂದರೂ,\nನಾ ಯೋರ್ದನ್ ಹತ್ರ ನಿಂತರೂ,\nನಿರ್ಭಯವಾಗಿ ದಾಟುವೆ,\nಕಾಪಾಡುವವನಾತನೇ." },
  105: { title: "ಎಂದೂ ಧೈರ್ಯಗೊಳ್ಳು ಭ್ರಾತ!", lyrics: "1. ಎಂದೂ ಧೈರ್ಯಗೊಳ್ಳು ಭ್ರಾತ!\nಮಾರ್ಗ ಕತ್ತಲಾದರೂ ;\nಕರ್ತ ನಿನ್ನ ನಡಿಸುವ\nನಂಬಿ ಮಾಡು ಒಳ್ಳೇದು.\nಎಂದೂ ಧೈರ್ಯಗೊಳ್ಳು ಭ್ರಾತ!\nದಾರಿ ಸೊಟ್ಟಗಿದ್ದರೂ ;\nಹೆಜ್ಚೆ ಇಡು ಸ್ಥಿರದಿಂದ\nನಂಬಿ ಮಾಡು ಒಳ್ಳೇದು.\n2. ಎಂದೂ ಧೈರ್ಯಗೊಳ್ಳು ಭ್ರಾತ!\nಯಾರ ದಯ ಬೇಡವು;\nದೇವರಲ್ಲಿ ಭರವಸ\nಇಟ್ಟು ಮಾಡು ಒಳ್ಳೇದು.\nಎಂದೂ ಧೈರ್ಯಗೊಳ್ಳು ಭ್ರಾತ!\nಕ್ರೋಧ ತಡೆ ಬಂದರೂ ;\nಬಿಟ್ಟು ಚಿಂತೆ ಭ್ರಾಂತಿ ಎಲ್ಲಾ\nನಂಬಿ ಮಾಡು ಒಳ್ಳೇದು.\n3. ಎಂದೂ ಧೈರ್ಯಗೊಳ್ಳು ಭ್ರಾತ!\nಭಕ್ತರಿಗೆ ಜಯವು ;\nಅಂತ್ಯದಲ್ಲಿ ಉಂಟು ಸತ್ಯ,\nನಂಬಿ ಮಾಡು ಒಳ್ಳೇದು.\nಎಂದೂ ಧೈರ್ಯಗೊಳ್ಳು ಭ್ರಾತ!\nಮಾರ್ಗ ಕತ್ತಲಾದರೂ ;\nಕರ್ತ ನಿನ್ನ ನಡಿಸುವ\nನಂಬಿ ಮಾಡು ಒಳ್ಳೇದು." },
  106: { title: "ಸರ್ವ ಕಷ್ಟ ಪರಿಹಾರ", lyrics: "1. ಸರ್ವ ಕಷ್ಟ ಪರಿಹಾರ\nಗೈಯುವಂಥ ಕ್ರಿಸ್ತನು\nಇದ್ದರೆನಗೆಂಥಾ ಭಾಗ್ಯ\nಆತ್ಮಕೆಂಥಾ ಸೌಖ್ಯವು\nಮರ್ತ್ಯರಾದ ಮಿತ್ರೆಲ್ಲ\nನನ್ನ ಬಿಟ್ಟು ಬಿಟ್ಟರೂ\nದಿವಯ ಮಿತ್ರನಾದ ಕ್ರಿಸ್ತ\nಎಂದೂ ಬಿಡದಾತನು.\n2. ಆತ ಹತ್ರವಿರುವಲ್ಲಿ\nತಾಪತ್ರಯ ಬಂದರೂ\nವಿವಿಧ ಸಂಗೀತಗಳು\nದೃಷ್ಟಿಯಿಟ್ಟು ಆತನಲ್ಲಿ\nಶಾಂತಿ ಹೊಂದುತಿರ್ವೆನು ;\nಆತನ್ನೊಳ್ಳೆ ಮಿತ್ರನಾಗಿ\nತಾಪಿಯಾದ ನನಗೆ\n“ನಾನು ಸಹ ತಾಪಿ’” ಎಂದು\nಧೈರ್ಯವನ್ನು ಹೇಳನೆ ?\n3. ಹೊತ್ತುಕೊಳ್ಳಲಾರದಂಥ\nಭಾರ ನನಗಿರಲು\nಆಪ್ತಮಿತ್ರ, ನೆರವಾಗು,\nನೀನೇ ನನ್ನ ಶರಣು,\nನಾನು ಬಲಹೀನನೆಂದು\nನೀನು ತಿಳಿದಾತನು,\n“ನಿನಗೆನ್ನ ಕೃಪೆ ಸಾಕು”\nಎಂದು ಬಲಪಡಿಸು." },
  107: { title: "ಹಾ! ಸಹೋದ್ರ ಪ್ರೀತಿಯು", lyrics: "1. ಹಾ! ಸಹೋದ್ರ ಪ್ರೀತಿಯು\nಎಷ್ಟು ರಮ್ಯವಾದದ್ದು!\nಪರಸ್ಪರ ಪ್ರೇಮವು\nಭಕ್ತರಲಂಕಾರವು.\n2. ಪರಿಮಳದಂತೆಯೇ\nಎಲ್ಲಾ ಕಾಲದಲ್ಲಿಯೂ\nಪ್ರೇಮದಿಂ ಸುವಾಸನೆ\nಬೀಸುತ್ತದೆ ಸುತ್ತಲು.\n3. ಮನಃ ಪೂರ್ತಿಯಿಂದಲೇ\nಪ್ರೀತಿ ಕ್ಷಮೆ ಕೊಡುತ್ತೆ\nಯಾವ ಕೇಡು ಮಾಡದೆ,\nಹಗೆಯನ್ನು ತಾಳುತ್ತೆ.\n4. ಯಾವ ಗುಣವಿದ್ದರೂ\nಪ್ರೀತಿಯಿಲ್ಲದಿದ್ದರೆ,\nನಾನು ಏನು ಇಲ್ಲವು,\nನಿನ್ನ ಮುಂದೆ ದೇವರೇ!\n5. ಪ್ರೀತಿಯುಳ್ಳ ಹೃದಯ\nದೇವರಿಂದ ಹುಟ್ಟುತ್ತೇ\nಇಂಥಾ ದಿವ್ಯ ಗುಣವ\nನನ್ನಲ್ಲಿಡು, ಕರ್ತನೇ !\n6. ಕ್ರಿಸ್ತ ಸಭಾ ಶಿರಸ್ಸೇ,\nನಿನ್ನ ಜನರೆಲ್ಲರೂ\nಪೂರ್ಣ ಪ್ರೀತಿಯಿಂದಲೇ\nನಡಕೊಳ್ಳ ಬೋಧಿಸು." },
  108: { title: "ದೇವಾಸನದ ಸುತ್ತಲೂ", lyrics: "1. ದೇವಾಸನದ ಸುತ್ತಲೂ\nಕರ್ತನ ಮುಂದೆಯೇ\nದೊಡ್ಡ ಸಮೂಹ ಮಕ್ಕಳು\nಇರುತ್ತಾರಲ್ಲವೆ ?\nಸ್ತುತಿ, ಸ್ತೋತ್ರ, ಹಾಡಿ, ಪಾಡಿ ॥\n2. ಆ ಬೆಳಕುಳ್ಳ ಲೋಕಕ್ಕೆ\nಹೇಗೆ ಪ್ರವೇಶವು ?\nಆ ಸೌಖ್ಯವಾದ ಸ್ಥಾನಕ್ಕೆ\nಹೇಗೆ ಸೇರಿದರು ?\nಸ್ತುತಿ, ಸ್ತೋತ್ರ, ಹಾಡಿ, ಪಾಡಿ ॥\n3. ಜಗತ್ತಿಗಾಗಿ ಯೇಸುವು\nಸತ್ತದ್ದರಿಂದಲೇ,\nಶುದ್ಧತ್ವ ಹೊಂದಿ ಅವರು\nವಿವಿಧ ಸಂಗೀತಗಳು\nಬಂದರು ಭಾಗ್ಯಕ್ಕೆ\n4. ಭೂಲೋಕದ ರಕ್ಷಕನ್ನ\nಪ್ರೀತಿಸಿದವರು,\nಸುಲೋಕದಲ್ಲಿ ಘನವ\nಸಂಪಾದಿಸಿದರು." },
  109: { title: "ಹೌದು, ರಮ್ಯ ನಿವಾಸವಿದೆ", lyrics: "1. ಹೌದು, ರಮ್ಯ ನಿವಾಸವಿದೆ\nದೇವ ಜನರಿಗೋಸ್ಕರವು\nನಮ್ಮ ಪರಮ ತಂದೆ ತಾನೇ\nಅಲ್ಲಿ ಸ್ಥಳವ ಕೊಡುವನು.\nಪಲ್ಲವಿ\nಅಲ್ಲಿ ಕೂಡುವೆವೆಂದಂದಿಗೂ ॥\n2. ಆ ಮಹಾಸುಖ ದೇಶಸ್ಥರೊಳ್\nತುಂಬಾನಂದವು ಆಗುವದು ;\nಮತ್ತು ಕಣ್ಣೀರು ಮುಖಗಳೊಳ್\nಎಂದೂ ಕಾಣದೆ ಇರುವದು,\nಇನ್ನು ಮೇಲ್ ಹೌದೌದು.\n3. ಇಂಥಾ ಕೋರಿಕೆ ಕೊಡಿಸುವ\nಪರಮೋತ್ತಮ ಕರ್ತನಿಗೆ\nನಿತ್ಯ ಸ್ತೋತ್ರವ ಅರ್ಪಿಸುವ,\nಎಲ್ಲಾ ಭಕ್ತರ ಸಂಗಡಲೇ,\nಇನ್ನು ಮೇಲ್ ಹೌದೌದು." },
  110: { title: "ಸಂತೋಷವೇ! ಸಂತೋಷವೇ ;", lyrics: "1. ಸಂತೋಷವೇ! ಸಂತೋಷವೇ ;\nನಾ ಕ್ರಿಸ್ತನ್ಥತ್ರ ಸೇರುವೆ ;\nಭೂವಾಸಕ್ಕಿಂತ ಅಲ್ಲಿಯೇ\nಮಹಾ ಸಂಭ್ರಮ ಸಿಕ್ಕುತ್ತೆ!\nಪಲ್ಲವಿ\nಹರ್ಷವೇ! ಹರ್ಷವೇ!\nಮಹಾ ಸಂಭ್ರಮವಾಗುತ್ತೆ !\nಕ್ರಿಸ್ತೆಸು ಆಗ ನನಗೆ\nಪ್ರತ್ಯಕ್ಷನಾಗ್ವನಲ್ಲವೇ!\nಹರ್ಷವೇ! ಹರ್ಷವೇ!\nಮಹಾ ಸಂಭ್ರಮವಾಗುತ್ತೆ.\n2. ಪರಾತ್ಪರನಾದ ದೇವರ\nಕಣ್ಣಾರೆ ನಾನು ನೋಡುವೆ ;\nರಕ್ಷಕನಿಂದಲೇ ಆಗ\nಕಿರೀಟವನ್ನು ಹೊಂದುವೆ.\n3. ಶುದ್ಧಾತ್ಮರೆಲ್ಲರೊಡನೆ\nನಿನ್ನಾಮ, ಕರ್ತಾ ! ಹಾಡುವೆ ;\nಚಿಯೋನ ಪಟ್ಣದೊಳಗೆ\nನಿನ್ನಯ ಸೇವೆ ಮಾಡುವೆ.\n4. ಸಂತೋಷಗಳ ತೃಪ್ತಿಯು\nನಿರಂತ್ರ ಸ್ವರ್ಗದೊಳುಂಟು ;\nಬಂಗಾರ ವೀಣೆ ಎಂದಿಗೂ\nಎನ್ ಹಸ್ತ ಬಿಟ್ಟು ಹೋಗದು.\n5. ಈ ಲೋಕ ಬಿಟ್ಟು ಹೋಗ್ವದು\nಎನ್ನಾತ್ಮಕ್ಕೆ ಸಂತೋಷವು ;\nಎವಿಧ ಸಂಗೀತಗಳು\nವಿಮೋಚಕನ್ನ ನೋಡ್ವದು\nಸಂಪೂರ್ಣವಾದ ಭಾಗ್ಯವು." },
  111: { title: "ಕರ್ತನ ಹತ್ರವೇ", lyrics: "1. ಕರ್ತನ ಹತ್ರವೇ\nಸದಾ ಇರುವೆನು ;\nಇಂಥಾ ಗಂಭೀರ ಯೋಚನೆ\nಮಹಾ ಸಂತೋಷವು.\nಪಲ್ಲವಿ\nಸುವರ್ಣ ದೇಶಕ್ಕೆ\nನಾನೀಗ ದೂರವೇ ;\nಆದಾಗ್ಯೂ ದಿನ ದಿನಕ್ಕೆ\nಸಮೀಪ ಹೋಗುವೆ ;\nಹೋಗುವೆ, ಹೋಗುವೆ,\nಸಮೀಪ ಹೋಗುವೆ.\n2. ನಿನ್ನ ನಿವಾಸವ\nಎನ್ನಾತ್ಮ ನೋಡುತ್ತೆ ;\nಆ ರಮ್ಯ ಪಟ್ಣದ್ವಾರವ\nಓ ತೆರೆ, ಕರ್ತನೇ.\n3. ಚೀಯೋನ ಪಟ್ಣವು\nಸಮೀಪವಾಗಿದೆ,\nಅದನ್ನು ನನ್ನ ಮನವು\nಅತ್ಯಾಶಿಸುತ್ತದೆ.\n4. ಈ ಪ್ರಾಣ ಹೋಗಲು,\nಎನ್ ತಂದೇ! ನಿನ್ನನ್ನು\nನಾ ಕಂಡು, ನಿನ್ನ ಹತ್ರವೇ\nಎಂದೆಂದೂ ಬಾಳುವೆ." },
  112: { title: "ಯೇಸುವೇ! ನೀನು", lyrics: "1. ಯೇಸುವೇ! ನೀನು\nಎಂದೂ ನಡಿಸು :\nಮಾರ್ಗಯಾಸವಾಗಿದ್ದಾಗ್ಯೂ,\nಶತ್ರು ಎದುರಿಸಿದ್ದಾಗ್ಯೂ\nಭಯವಿಲ್ಲದೆ\nಮುಂದೆ ಹೋಗುವೆ.\n2. ಕತ್ತಲಾದರೂ,\nಶತ್ರು ಬಂದರೂ,\nಧೈರ್ಯ ಕೊಡು ಕೃಪೆಯಿಂದ ;\nಹಿಡಿ ನಿನ್ನ ಹಸ್ತದಿಂದ ;\nನನ್ನ ತಪ್ಪಿಸು,\nಮೋಕ್ಷ ತೋರಿಸು.\n3. ದುಃಖ ಬರಲು,\nಶಾಂತಿ ನೀ ಕೊಡು ;\nಎಲ್ಲಾ ಶೋಧನೆಗಳನ್ನು\nಸಹಿಸುವ ತಾಳ್ಮೆಯನ್ನು\nದಯಪಾಲಿಸು,\nಬಲಪಡಿಸು.\n4. ಯೇಸುವೇ! ನೀನು\nಎಂದೂ ನಡಿಸು;\nಮುಂದೆ ಕಾಣುವಂಥ ಶಾಂತಿ\nಪರಲೋಕದ ವಿಶ್ರಾಂತಿ\nಸೇರ್ವ ಮಟ್ಟಿಗೂ\nನನ್ನ ನಡಿಸು\nವಿವಿಧ ಸಂಗೀತಗಳು" },
  113: { title: "ಓ ಯೇಸು! ನಿನ್ನ ನಾಮವು", lyrics: "1. ಓ ಯೇಸು! ನಿನ್ನ ನಾಮವು\nಎಷ್ಟೋ ಆಶ್ಚರ್ಯವೇ !\nನೀ ಪಾಪಿಗೆ ಆಶ್ರಯವು\nಓ ದಿವ್ಯನಾದ ಕರ್ತನೇ !\nಪಲ್ಲವಿ\nಓ ದಿವ್ಯನಾದ ಯೇಸು !\nಓ ದಿವ್ಯನಾದ ಯೇಸು !\nಓ ದಿವ್ಯನಾದ ಯೇಸು !\nನನ್ನನ್ನ ರಕ್ಷಸು.\n2. ನಾ ಬಡ ಪಾಪಿ ನಿಜವೇ,\nಓ ಪ್ರಿಯನಾದ ಯೇಸು!\nನಿನ್ ಹತ್ರ ಬಂದೆ, ಈಗಲೇ,\nಓ ಪ್ರಿಯನಾದ ಯೇಸು!\n3. ನನ್ ಪಾಪ ಎಷ್ಟು ಇದ್ದರೂ,\nನೀ ಎಂದೂ ತಳ್ಳಲಾರಿ ;\nನಿನ್ ಮುಂದೆ ಕ್ಷಮೆ ಬೇಡಲು\nನನ್ ಪಾಪ ಹರಿಸುವಿ." },
  114: { title: "ಬನ್ನಿ ಪಶ್ಚಾತ್ತಾಪದಿಂದ", lyrics: "1. ಬನ್ನಿ ಪಶ್ಚಾತ್ತಾಪದಿಂದ\nಸ್ವಾಮಿ ಹತ್ರ ಬರುವಾ ;\nಆತನಲ್ಲಿ ಕೃಪೆಯುಂಟು\nಆತ ಶಾಂತಿ ಕೊಡುವ.\n2. ಶಿಕ್ಷಿಸಿದ ನೀತಿಯಿಂದ,\nಪ್ರೀತಿ ತೋರಿಸುವನು ;\nಪೆಟ್ಟು ಕೊಟ್ಟ ಹಸ್ತದಿಂದ\nಪೂರ್ಣ ವಾಸಿಮಾಡ್ವನು.\n3. ದೇವರನ್ನು ಆಶೆಯಿಂದ\nಹುಡುಕುವ ಎಲ್ಲರೇ\nಕೊಡುವನು ಕೃಪೆಯಿಂದ\nಹರ್ಷ ಬೇಡುವಲ್ಲಿಯೇ.\n4. ಹ್ಯಾಗೆ ಮೊಳಕೆಯ ಮೇಲೆ\nತಿಳಿ ಮಂಜು ಬೀಳುತ್ತೋ,\nಹಾಗೆ ನಮ್ಮ ಮೇಲೆ ಕೃಪೆ\nಸುರಿಸುವನಲ್ಲವೇ ?\n5. ಮಳೆಯಿಂದ ಅಂದ ಪುಷ್ಟ\nವಿಕಸಿಸ್ವ ಮೇರೆಗೆ,\nನಮ್ಮ ಮನದೊಳಾನಂದ\nಹುಟ್ಟಿ ತೃಪ್ತಿಯಾಗುತ್ತೆ.\n6. ಬನ್ನಿ ಪಶ್ಚಾತ್ತಾಪದಿಂದ\nಸ್ವಾಮಿ ಹತ್ರ ಬರುವಾ ;\nಆತನಲ್ಲಿ ಕೃಪೆಯುಂಟು,\nಆತ ಶಾಂತಿ ಕೊಡುವ." },
  115: { title: "ಅಘೋರ ಮನಕ್ಲೇಶವು", lyrics: "1. ಅಘೋರ ಮನಕ್ಲೇಶವು\nಸಂಪ್ರಾಪ್ತವಾದರೇನು ?\nಗೋಳಾಟ ಚಿಂತೆಯಾದರೂ\nಉಪದ್ರ ಕೊಟ್ಟರೇನು ?\nಪಲ್ಲವಿ\n“ನಿನ್ನ ಭಾರ, ಭಕ್ತನೇ!\nಎಲ್ಲಾಲೇಸು ಮಾಡುವೆ,”\nವಿವಿಧ ಸಂಗೀತಗಳು\nಎಂಬ ದಿವ್ಯ ಮಾತನ್ನೇ\nನಂಬು, ನಂಬು, ನಂಬು.\n2. ಸ್ವಮಿತ್ರ ಶತ್ರುವಾದರೂ,\nಅನ್ಯಾಯ ಹೊಂದಿದಾಗ್ಯೂ\nಕಂಗೆಟ್ಟು ತಾಪಪಟ್ಟರೂ,\nನೀ ಧೈರ್ಯವಾಗಿ ನಂಬು.\n3. ನೀ ಮೇಲು ಮಾಡುತ್ತಿರಲು\nವಿರೋಧ ಬಂದರೇನು ?\nಯಥಾರ್ಥನಾಗಿ ಬಾಳಲು\nದುರ್ನಾಮ ಪಟ್ಟರೇನು ?\n4. ಭೂಲೋಕ ಬಂಧು ಮಿತ್ರರು\nಹೋದಾಗ್ಯೂ ದುಖ ಬೇಡ;\nಮೇಲ್ಲೋಕ ತಂದೆ ಎಂದಿಗೂ\nನಿನ್ನನ್ನು ಬಿಡಲಾರ.\n5. ಅನಾಥನಾಗಿ ಇದ್ದರೂ,\nಆಯಾಸ ಚಿಂತೆ ಯಾಕೆ ?\nಸುಲೋಕ ದೂತರೆಲ್ಲರೂ\nನಿನ್ನನ್ನು ಕಾಯುತ್ತಾರೆ.\n6. ಭೂಮ್ಯಾಶೆಯೆಲ್ಲಾ ಹೋದರೂ,\nಸಮಾಧಿ ಮಾತ್ರ ಈಗ\nನಿನ್ ಮುಂದೆ ಕಾಣ ಬಂದರೂ,\nಅಪಾಯವೇನೂ ಇಲ್ಲ" },
  116: { title: "ದೇವರ ಪ್ರೀತಿ ಶ್ರೇಷ್ಠವು ಇಂಪಾದ", lyrics: "1. ದೇವರ ಪ್ರೀತಿ ಶ್ರೇಷ್ಠವು ಇಂಪಾದ\nಭಾಷೆಗಿಂತಲೂ,\nಪ್ರೀತಿಯಿಲ್ಲದ ಜೀವವು ಘಂಟೆಯ\nಶಬ್ದವು.\nಪಲ್ಲವಿ\nಪ್ರೀತಿಯ ಕೈ ನನ್ನೆ್ತಿತು ಕೆಸರಿನ್\nಕುಣಿಯಿಂದಲೂ ;\nಅಮೂಲ್ಯವಾದ ಪ್ರೀತಿಯೇ !\nನಿತ್ಯವು ಸ್ತೋತ್ರ ನಿನಗೆ\n2. ಎಲ್ಲಾ ವರಗಳಿದ್ದರೂ, ವಿಶ್ವಾಸ\nಹೆಚ್ಚಾಗಿದ್ದರೂ ;\nಪ್ರೀತಿಯಿಲ್ಲದ ಮನಸ್ಸು ಫಲವ\nಕೊಡದು.\n3. ನನ್ನಾಸ್ತಿ ಬಡವರಿಗೆ ಕೊಟ್ಟಾಗ್ಯೂ\nದೇಹ ಬೆಂಕಿಗೆ\nಈ ಪ್ರೀತಿಯಿಲ್ಲದಿದ್ದರೆ\nಎಲ್ಲವು ವ್ಯರ್ಥವೆ.\n4. ಪ್ರೀತಿಯು ತಾಳ್ಮೆಯುಳ್ಳದ್ದು;\nಪ್ರೀತಿಯು ಹಗೆಮಾಡದು ;\nಪ್ರೀತಿಯು ಉಜ್ಬಿಕೊಳ್ಳದು ;\nಇಲ್ಲ ಹೊಟ್ಟೆಕಿಚ್ಚು\n5. ಪ್ರೀತಿಯು ಸಿಟ್ಟುಮಾಡದು ; ನೆನಸದು\nಯಾವ ಕೇಡು ;\nಅನ್ಯಾಯಕ್ಕೆ ಈ ಪ್ರೀತಿಯು\nಸಂತೋಷ ಪಡದು.\n6. ಎಲ್ಲಾ ವಿಶ್ವಾಸಿಸುವದು ; ಎಲ್ಲಾ\nನಿರೀಕ್ಷಿಸುವದು ;\nಎಲ್ಲವ ಸಹಿಸುವದು ; ಎಂದಿಗೂ\nಹೋಗದು.\n7. ಪ್ರವಾದನೆಗಳಾದರೂ, ಭಾಷೆ ಜ್ಞಾನ\nವರಗಳೂ ;\nನಿಜ ನಾಶವಾಗುವವು ; ಪ್ರೀತಿ\nಶಾಶ್ವತವು.\n8. ಪ್ರೀತಿಯ ಸಂಪೂರ್ಣತೆಯು ನನ್ನಲ್ಲಿ\nಬರುವಾಗಲು ;\nಅಪೂರ್ಣವಾದದೆಲ್ಲವು\nಇಲ್ಲದಂತಾಗ್ವವು.\nವಿವಿಧ ಸಂಗೀತಗಳು" },
  117: { title: "ಎಷ್ಟು ಭಾಗ್ಯವಂತರು;", lyrics: "ಎಷ್ಟು ಭಾಗ್ಯವಂತರು;\nಪಾಪ ದುಖು ಭಯವು\nಪರಿಹಾರವಾಯಿತು;\nಪಾಲುಗಾರನಾಗುವೆ 11\n2. ಕ್ರಿಸ್ತನಿಂದ ಅವರು\nನೀತಿವಂಶರಾದರು\nಮನಶ್ಶಾಂತಿ ಎಲ್ಲರು\nಹೊಂದಿ ಹರ್ಷಿಸುವರು ;\nಪಾಲುಗಾರನಾಗುವೆ 11\n3. ತಂದೆ ಹತ್ರ ಮಕ್ಕಳು\nಹೋಗ ಭಯಪಡರು ;\nದೇವರನ್ನು ಭಕ್ತರು\nನೋಡಲಂಜಲಾರರು ;\n11 ನಾನು ಅವರೊಂದಿಗೆ\nಪಾಲುಗಾರನಾಗುವೆ ॥\n4. ಬಾಧೆ ಕಷ್ಟ ಬಂದರೂ\nನಷ್ಟ ಹೊಂದಲಾರರು ;\nಶ್ರಮೆ ದೇವಜನಕ್ಕೆ\nಮೇಲು ಉಂಟುಮಾಡುತ್ತೆ ;\nಪಾಲುಗಾರನಾಗುವೆ\n5. ಇಹದಲ್ಲಿ ಕೃಪೆಯೂ\nಸಾಯುವಲ್ಲಿ ಜಯವೂ\nಪರದಲ್ಲಿ ಜೀವವೂ\nಹೊಂದಿ ಹರ್ಷಿಸುವರು,\n11 ನಾನು ಅವರೊಂದಿಗೆ" },
  118: { title: "ನಿನ್ ಹತ್ರ ದೇವರೇ,", lyrics: "1. ನಿನ್ ಹತ್ರ ದೇವರೇ,\nನಿನ್ ಹತ್ರಕ್ಕೆ\nನನ್ನಾತ್ಮ ಏರುತ್ತೆ.\nಓ ತಂದೆಯೇ!\nಇಷ್ಟಾರ್ಥ ತೀರಿಸ\nನಿನ್ನಲ್ಲಿಯೇ.\n2. ಈ ಭೂಪ್ರಯಾಣವು\nಪ್ರಯಾಸವೇ.\nಎಲ್ಲೆಲ್ಲೂ ಕತ್ತಲು\nಉಂಟಾಗಿದೆ.\nನೀನ್ ಹತ್ರವಿದ್ದರೆ,\nನಿರ್ಭಯವಾಗುತ್ತೆ !॥\nಎನ್ ದೇವರೇ!\n3. ಉಪದ್ರ ಬಂದರೂ\nನಿರ್ಭಯವೇ ;\nಇದು ಮೇಲ್ಲೋಕಕ್ಕೆ\nನಿಚ್ಚಣಿಯೇ ;\nಪ್ರಪಂಚ ತಪ್ಪಿಸ\nಸದ್ಗತಿ ಯೋಚಿಸ ॥\nಸಹಾಯವೇ.\n4. ಮಾರ್ಗದ ಲಕ್ಷಣ\nಕೇಡಾದರೂ,\nಅಘೋರ ಸಂಕಟ\nಬಂದಿದ್ದರೂ\nನೀನ್ ಹತ್ರವಿದ್ದರೆ\nಸಂತೋಷವಾಗುತ್ತೆ ॥\nಎನ್ ದೇವರೇ!\nವಿವಿಧ ಸಂಗೀತಗಳು" },
  119: { title: "ಮೋಡವಿಲ್ಲದಿರ್ಪ ದಿನ", lyrics: "1. ಮೋಡವಿಲ್ಲದಿರ್ಪ ದಿನ\nಸ್ವಾಮಿ ಸ್ವರ್ಗದಲ್ಲಿಯೇ\nನನ್ನ ನಾಮವೆತ್ತಿ ಕೂಗುವಾಗಲೇ,\nಹಾಜರಾಗಿದ್ದೇನೆ ಸ್ವಾಮೀ\nಎಂದು ಉತ್ರಕೊಡುವೆ ;\nಆಗ ಸದಾನಂದ ಭಾಗ್ಯವಿರುತ್ತೆ.\nಪಲ್ಲವಿ\nಹಾಜರಾಗಿದ್ದೇನೆ ಸ್ವಾಮೀ ;\nಹಾಜರಾಗಿದ್ದೇನೆ ಸ್ವಾಮೀ ;\nಹಾಜರಾಗಿದ್ದೇನೆ ಸ್ವಾಮೀ ;\nಎಂದು ಹರ್ಷದಿಂದ ಉತ್ರ ಕೊಡುವೆ.\n2. ಲೋಕದೆಲ್ಲಾ ಕಡೆಯಿಂದ\nಕ್ರಿಸತ ಭಕ್ತರೆಲ್ಲರೂ\nಸ್ವರ್ಗಲೋಕದಲ್ಲಿ ಹಾಜರಾಗ್ವರು ;\nನಂಬಿ ಗುಣಪಡುವಂಥ\nಯಾವ ನಿಜ ಭಕ್ತನೂ\nಸ್ವಾಮಿಯಿಂದ ತಳ್ಳಲ್ಪಡಲಾರನು.\n3. ಯೇಸು ಬೇಗ ಬರುತ್ತಾನೆ\nಎಂದು ಜ್ಸ್ಪ್ತಿ ಮಾಡುವಾ ;\nಆ ಸುಲೋಕಕ್ಕೇರ ಸಿದ್ಧರಾಗುವ ;\nಆಗ ಕಣ್ಣುರೆಪ್ಪೆ ಮುಚ್ಚು\nವಷ್ಟರೊಳು ಸೇರುವ;\nಆ ಸಂತೋಷದಲ್ಲಿ ಎಂದಿಗಿರುವೆ.\n4. ಲೋಕದಲ್ಲಿ ಐಕ್ಯರಾಗಿ\nಆತನ್ ಸೇವೆ ಮಾಡುವಾ ;\nಜಾಗರೂಕರಾಗಿ ಸಾಕ್ಷಿ ಕೊಡುವಾ ;\nಕರ್ಮ ಮಾರ್ಗವೆಲ್ಲಾ ಬಿಟ್ಟು\nಆತನಲ್ಲಿ ಮೆಚ್ಚುವಾ ;\nಸ್ವಾಮಿ ಕಾರ್ಯದಲ್ಲಿ ಹರ್ಷಗೊಳ್ಳುವೆ.\n5. ಯೇಸುವಿನ ಮುಕ್ತಿ ಮಾರ್ಗ\nನಂಬದಿರುವವರ\nಯೇಸುವಿನ ಮುಂದೆ ಜ್ಞಪ್ತಿಮಾಡುವಾ ;\nಆತ ಶೀಘ್ರ ಬರುತ್ತಾನೆ ಎಂದು\nಸಾರಿ ಹೇಳುವೆ ;\nಶುಭ ದಿನ ನಾನು ಎದುರ್ಗೊಳ್ಳುಮೆ." },
  120: { title: "ಆನಂದವೇ! ಆನಂದವೇ!", lyrics: "1. ಆನಂದವೇ! ಆನಂದವೇ!\nನಾ ಕ್ರಿಸ್ತ ಭಕ್ತನಾದೆನು;\nಸಂಭ್ರಮ ಪಡು, ಮನವೇ\nನಾ ಭಾಗ್ಯವಂತನಾದೆನು.\nಪಲ್ಲವಿ\nಹರ್ಷವೇ! ಹರ್ಷವೇ!\nನಾ ಭಾಗ್ಯವಂತನಾದೆನು,\nಕ್ರಿಸ್ತೇಸುವಿನ ರಕ್ತವು\nನನ್ನನ್ನು ಶುದ್ಧ ಮಾಡಿತು.\nಹರ್ಷವೇ ! ಹರ್ಷವೇ!\nನಾ ಭಾಗ್ಯವಂತನಾದೆನು.\n2. ಸಂತೃಪ್ತನಾದೆ, ಕರ್ತನು\nನನ್ನನ್ನು ದೃಷ್ಟಿಸಿದನು ;\nವಿರೋಧಿಯನ್ನು ಕೊಂದನು.\nನನ್ನನ್ನು ಬಿಡಿಸಿದನು.\n3. ಈವಾಗ ಮನಶ್ಶಾಂತಿಯು\nಉಂಟಾಗಿ ತೃಪ್ತಿ ಪಟ್ಟೆನು,\nಇನ್ನಿಲ್ಲ ಬೇರೆ ಆಶೆಯು,\nಅಮೃತ ಪಾನವಾಯಿತು.\nವಿವಿಧ ಸಂಗೀತಗಳು\n4. ನನ್ನನ್ನು ದೈವ ಸೇವೆಗೆ\nಪ್ರತಿಷ್ಠೆ ಮಾಡಿಕೊಂಡೆನು ;\nಎಂದೆಂದೀ ಒಡಂಬಡಿಕೆ\nಕಾಪಾಡಿ ಸೇವಿಸುವೆನು." },
  121: { title: "ನಾ ಕರ್ತನಾದ ಯೇಸುಸ್ವಾಮಿ", lyrics: "1. ನಾ ಕರ್ತನಾದ ಯೇಸುಸ್ವಾಮಿ\nಹತ್ರ ಬಂದೆನು ;\nನನ್ ಪಾಪ ಕಷ್ಟವೆಲ್ಲಾ ಪರಿಹರಿಸಿದನು.\nಮುಖಕ್ಕೆ ಪ್ರಕಾಶ, ಆತ್ಮಕ್ಕೆ ವಿಶ್ವಾಸ,\nಕೊಡುತ್ತಾನೀಗ–ದೇವರಿಗೆ ಸ್ತೋತ್ರವು.\n2. ಓ ಕ್ರೈಸ್ತನೇ! ನೀ ಯಾಕೆ ದುಚಖು\nಕಷ್ಟ ಪಡುತ್ತೀ !\nನೀ ಯಾಕೆ ಮನಗುಂದಿ ಸದಾ\nಸೋತು ಹೋಗುತ್ತೀ ?\nಕರ್ತನಿಗೆ ಜಯ, ಸೈತಾನನಿಗೆ ಲಯ,\nನೀ ನಂಜಿಕೊಳ್ಳುವಲ್ಲಿ ಧೈರ್ಯ\nಗೊಳ್ಳುಮಿ\n3. ಸನ್ಮಾರ್ಗ ತಪ್ಪಿ ಚಿಂತಾ ಕ್ರಾಂತನಾದ\nಕ್ನೈಸ್ತನೇ ;\nನಿನ್ ಆಪ್ತ ಜನರೆಲ್ಲಾ ಬಿಟ್ಟು\nಹೋದ್ರೇನಂಜಿಕೆ ?\nದಿವ್ಯ ಯಜಮಾನ, ಬೇಕಾದಷ್ಟು ಜ್ಞಾನ\nಸ್ವಕೃಪೆಯಿಂದ ದಯಪಾಲಿಸುವನೇ.\n4. ಮೊದಲಿದ್ದಾಸಕ್ತಿ ಪ್ರೀತಿ ತಂಪಾಗಿದೆಯೋ?\nನೀ ಮುಂಚೆ ಕೊಟ್ಟಸಾಕ್ಷಿ\nನುಡಿ ನಿಂತು ಹೋಯಿತೋ ?\nಕರ್ತ ಯೇಸು ಕ್ಷಮೆ, ಅತ ಪಟ್ಟ ಶ್ರಮೆ,\nನೀ ಜ್ಲಪ್ತಿ ಮಾಡಿ ಆತನ್ ಪ್ರೀತಿ\nಮಾಡಿಕೋ.\n5. ಕರ್ತನು ಬೇಗ ಬರುತ್ತಾನೆ ಪ್ರಿಯ\nಮಿತ್ರರೇ ;\nಆತನ್ ಸೇವೆಗಾಗಿ ಇನ್ನು ಸ್ವಲ್ಪ\nಕಾಲವೇ ;\nಹೊಂದುವಾ ಶುದ್ಧತ್ವ, ಇರಲಿ ಸಿದ್ಧತ್ವ,\nಬಾ ಕರ್ತನಾದ ಯೇಸುಸ್ವಾಮಿ\nಬೇಗನೇ" },
  122: { title: "ಚಿಂತೆಯಿಂದ ಭಕ್ತಿ ಕುಂದಿ ಹೋಗಲೂ,", lyrics: "1. ಚಿಂತೆಯಿಂದ ಭಕ್ತಿ ಕುಂದಿ ಹೋಗಲೂ,\nನಷ್ಟ ತಾಪತ್ರಯ ಕಷ್ಟ ಮುತ್ತಲೂ\nಕರ್ತನಲ್ಲಿ ತೋರಿಬಂದ ಪ್ರೀತಿಯ\nಜ್ಲಪ್ತಿ ಮಾಡಿಕೊಳ್ಳುತ್ತಿರು ಸ್ತೋಕ್ರವ\nಪಲ್ಲವಿ\nಕ್ರಿಸ್ತನ್ಲಿ ಬಂದ ಭಾಗ್ಯವು\nಭಕ್ತನಾದ ನಿನ್ನ ಪಾಲಿಗೂ\nಅಷ್ಪಿಷ್ಪೆಂದು ಲೆಕ್ಕ ಮಾಡಲು\nನಿನ್ನ ಕೈಗಳಲ್ಲಿಯೂ ಅಸಾಧ್ಯವು.\n2. ರತ್ನ ಚಿನ್ನ ಬೆಳ್ಳಿ ಲೋಕದವರು\nಕೂಡಿಸಿಟ್ಟು ತುಂಬಾನಂದಪಡ್ವರು ;\nಅವು ಸ್ವಲ್ಪಕಾಲ ಮಾತ್ರ ಬರ್ವವು ;\nಯೇಸು ಕೊಟ್ಟ ಭಾಗ್ಯವೆಂದೂ\nಹೋಗದು.\n3. ಯಾವ ಕಷ್ಟದಲ್ಲಿ ನೀನು ಬಿದ್ದರೂ,\nಲೋಕ ದ್ವೇಷ ಮಾಡಿ ಪೀಡಿಸಿದರೂ,\nನಿನ್ನ ಭಾಗ್ಯವೆಂದೂ ಹೋಗಲಾರದು,\nಅದು ಕ್ರಿಸ್ತನಲ್ಲಿ ಭದ್ರವಾಗ್ವದು.\nವಿವಿಧ ಸಂಗೀತಗಳು\nಚಿಂತೆ ಭಯ ಬಂದರೇನು ? - ನಿನಗೆ\nನನ್ನ ಕೃಪೆ ಸಾಕು, ಎಂದು ಯೇಸುವೇ\nರಾತ್ರಿ ಹಗಲಲ್ಲಿ ದೂರ ಹೋಗದೆ,\nಹತ್ರ ನಿಂತು ಹೇಳುತ್ತಾನೆ ನಿನಗೆ\n5. ಅಲ್ಪ ದೃಢನಾಗಿ ನೀನು ಇದ್ದರೆ\nದೇವರಾಶೀರ್ವಾದ ಹೇಗೆ ಸಿಕ್ಕುತ್ತೆ?\nಅಪನಂಬಿಕೆಲ್ಲ ಬಿಡು ಈಗಲೇ\nದೃಢನಾಗಿ ಬಾಳುತ್ತಿರು, ಭಕ್ತನೇ!" },
  123: { title: "ಯೇಸು ರಕ್ಷಕನ ಮಹಾ ಪ್ರೀತಿಯು", lyrics: "1. ಯೇಸು ರಕ್ಷಕನ ಮಹಾ ಪ್ರೀತಿಯು\nದಿನೆ ದಿನೆ ಸಿಹಿಯಾಗಿರ್ವದು ;\nನಮ್ಮ ಮುಂದೆ ಶಾಂತಿಯ ನಿರೀಕ್ಷೆಯು\nದಿನೆ ದಿನೆ ಸಿಹಿಯಾಗಿರ್ವದು.\nಪಲ್ಲವಿ\nಓ ಸ್ತೋತ್ರ ಬಲಿ ಅರ್ಪಿಸಿ\nಎಷ್ಟೋ ಹರ್ಷದಿಂದ ಹಾಡ್ವೆವು.\nಕರ್ತನಿಗೆ ಆ ರಾಗವು\nದಿನೇ ದಿನೇ ಸಿಹಿಯಾಗಿರ್ವದು.\n2. ನಿತ್ಯಜೀವ, ಬೆಳಕು, ಪ್ರಕಾಶವು\nದಿನೇ ದಿನೇ ಹೆಚ್ಚಾಗಿರ್ವವು;\nನಮ್ಮ ಕರ್ತ ಬರುವಿಕೆ ವಾಗ್ದಾನ\nದಿನೇ ದಿನೇ ಶ್ರೇಷ್ಠವಾಗ್ವದು.\n3. ಕರ್ತ ಯೇಸು ಕೊಡ್ವ ಸಮಾಧಾನವು\nದಿನೇ ದಿನೇ ಪ್ರಿಯವಾಗ್ವದು\nಪರಲೋಕಾಮೂಲ್ಯವಾದ ಸುಖವು.\nದಿನೇ ಮಹಾಶ್ಚರ್ಯವಾಗ್ವದು.\nವಿವಿಧ ಸಂಗೀತಗಳು" },
  124: { title: "ಪರಲೋಕದಲ್ಲಿಂಪಾದ ರಮ್ಯ", lyrics: "1. ಪರಲೋಕದಲ್ಲಿಂಪಾದ ರಮ್ಯ\nರೀತಿಯಿಂದಲೇ\nದೂತರ್ ಸೈನ್ಯವೆಲ್ಲಾ ದೇವರನ್ನು\nಸ್ತುತಿಸುತ್ತಾರೆ\nಅಲ್ಲಿ ಸದಾನಂದದಿಂದ ಭೀತಿ\nಭಯವಿಲ್ಲದೆ\nದೇವ ಸಿಂಹಾಸನದ ಮುಂದೆ\nನಿಂತಾರಾಧಿಸುತ್ತಾರೆ.\nಪಲ್ಲವಿ\nಶುದ್ಧ ಶುದ್ಧನೆಂತ್ಥಾಡುವರು\nದೂತರ ಕೂಡ ನಾನು ಸಹಾ\nಸ್ತೋತ್ರ ಹಾಡ್ವೆನು\nಅಂತೂ ವಿಮೋಚಕನ ಪ್ರೀತಿ\nಹಾಡುತ್ತಿರಲು\nಆ ದೂತರು ಎನ್ ಜೊತೆಯಲ್ಲಿ\nಹಾಡಲಾರರು\n2. ಪರಲೋಕದಲ್ಲಿನ್ನೊಂದು ಗುಂಪು\nಗೀತ ಹಾಡ್ವದು.\nತನ್ನ ರಕ್ತ ಸುರಿಸಿ ನಮ್ಮನ್ನು\nಕೊಂಡುಕೊಂಡನು\nನಮ್ಮನ್ ಪಾಪದಿಂದ ಬಿಡಿಸಿ\nಸಂರಕ್ಷಿಸಿದನು\nಎಂದು ಕುರಿಮರಿಗಾಗಿ ಸ್ತುತಿ\nಸ್ತೋತ್ರ ಹಾಡ್ವದು.\n3. ನಾವು ಮಹಾ ಹಿಂಸೆಪಟ್ಟು ಮಹಾ\nಕಷ್ಟದಿಂದಲು\nನಮ್ಮ ರಕ್ಷಕನ್ ಸಹಾಯದಿಂದ\nಇಲ್ಲಿ ಬಂದೆವು.\nಎಂದಾ ಸಭೆ ರಾಗ ಕೇಳುವಾಗ\nದೂತರೆಲ್ಲರು\nಅಂಥಾ ರಾಗದಲ್ಲಿ ಸೇರಿ ಸ್ತೋತ್ರ\nಹಾಡಲಾರರು.\n4. ಈಗ ನಾನು ದೂತನಲ್ಲ ಅಂತೂ\nಕಷ್ಟ ಲೊಕದೊಳ್\nನಾನು ಇದ್ದರೂ ಎನ್ ಕರ್ತನಿಗೆ\nಸ್ತೋತ್ರ ಹಾಡ್ವೆನು ;\nಆತ ಕಲ್ವ್ಿ ಬೆಟ್ಟದಲ್ಲಿ ತನ್ನ\nಪ್ರಾಣ ಕೊಟ್ಟನು,\nಇಂಥಾ ಪಾಪಿಯಾದ ನನ್ನನ್ನು\nರಕ್ಷಿಸ ಸತ್ತನು." },
  125: { title: "ಏನ್ ಏನ್ ಪಾಪ ನೀಗ್ವದು ?", lyrics: "1. ಏನ್ ಏನ್ ಪಾಪ ನೀಗ್ವದು ?\nಯೇಸುವಿನ ರಕ್ತ ಮಾತ್ರ;\nಏನು ಸ್ವಸ್ಥ ಕೊಡ್ವದು ?\nಯೇಸುವಿನ ರಕ್ತ ಮಾತ್ರ.\nಪಲ್ಲವಿ\nಹಾ! ದಿ್ಯ ರಕ್ತವೇ!\nಈ ಬುಗ್ಗೆ ಅಲ್ಲದೆ\nಬೇರೊಂದು ಅರಿಯೆ.\nಯೇಸುವಿನ ರಕ್ತ ಮಾತ್ರ.\n2. ಶುದ್ಧ ಮಾಡತಕ್ಕದ್ದೇ\nಯೇಸುವಿನ ರಕ್ತ ಮಾತ್ರ ;\nಸಾಕೀ ಬಲಿ ನನಗೆ,\nಯೇಸುವಿನ ರಕ್ತ ಮಾತ್ರ.\n3. ನಾಶ ಮೋಸ ಹರಣ,\nಯೇಸುವಿನ ರಕ್ತ ಮಾತ್ರ ;\nಆತ್ಮ ಶುದ್ಧೀಕರಣ,\nಯೇಸುವಿನ ರಕ್ತ ಮಾತ್ರ.\n4. ಭದ್ರಾಶ್ರಯ ಸಿಕ್ಕಿತು;\nಯೇಸುವಿನ ರಕ್ತ ಮಾತ್ರ ;\nನಂಬಿಕೊಂಡೆ ಎಂದಿಗೂ,\nಯೇಸುವಿನ ರಕ್ತ ಮಾತ್ರ.\nಸುವಾರ್ತಾ ಸೇವೆಗಾಗಿ" },
  126: { title: "ಯೇಸು ಆತ್ಮ ಕದವನ್ನು", lyrics: "1. ಯೇಸು ಆತ್ಮ ಕದವನ್ನು\nತಟ್ಟುತ್ತಿರುವಾಗಲೇ\nತೆರೆ ನಿನ್ನ ಮನವನ್ನು\nಆತನಂಬು, ನರನೇ.\nಪಲ್ಲವಿ\nಆತ ಘನ ಲೋಕ ರಾಜ\nಕದ ತಟ್ಟುವವನು ;\nಆತನಾಜ್ಞೆಯಂತೆ ಈಗ\nಮನದಲ್ಲಿ ಸೇರಿಸು.\n2. ಆತ ನಿನಗಾಗಿ ಸತ್ಯ,\nರಕ್ತ ಚೆಲ್ಲಿ ಬಿಟ್ಟನು ;\nಜಯಶಾಲಿಯಾಗಿ ಎದ್ದ\nನಿನ್ನ ಪ್ರೀತಿಸುವನು.\n3. ಇದು ಸುಪ್ರಸನ್ನ ಕಾಲ,\nರಕ್ಷಣೆಯ ದಿನವು\nಎಂಬ ವಾಕ್ಯ ಕೇಳುವಾಗ\nತಡಮಾಡದೆ ಇರು.\nಸುವಾರ್ತಾ ಸೇವೆಗಾಗಿ\n4. ಆತ ನಿಂತು ನಿನ್ನ ಬಳಿ\nಸದಾ ಕೇಳಲಾರನು ;\nಕಡೆಯಲ್ಲಿ ನಿನ್ನ ತಳ್ಳಿ\nನಾಶ ಮಾಡಿಬಿಡ್ವನು." },
  127: { title: "ದೊಡ್ಡ ದಿನ ಬರುತ್ತೆ – ದೊಡ್ಡ ದಿನ ಬರುಕ್ಕ", lyrics: "1. ದೊಡ್ಡ ದಿನ ಬರುತ್ತೆ – ದೊಡ್ಡ ದಿನ ಬರುಕ್ಕ\nದೊಡ್ಡ ದಿನ ಬರುತ್ತೆ – ಇನ್ನೂ ಮೇಲ್ ;\nಭಕ್ತರೂ ಪಾಪಿಷ್ಠರೂ\nಭಾಗಿಸಲ್ಪಡುವರು ;\nಸಿದ್ಧವಾಗಿ ಇದ್ದೀಯೋ ನೀನು ?\nಪಲ್ಲವಿ\nಸಿದ್ಧವಾಗಿ ಕಡುಪಾಪಿ ಸಿದ್ಧವಾಗಿ\nದ್ದೀಯೋ ನ್ಯಾಯತೀರ್ಪಿಗೆ ?\nಬಲಗಡೆ ಎಡಗಡೆ ಯಾವದು\nಹೋಗ್ವದೇ ?\n2. ಕಾಂತಿ ದಿನ ಬರುತ್ತೆ – ಕಾಂತಿ ದಿನ\nಬರುತ್ತೆ\nಕಾಂತಿ ದಿನ ಬರುತ್ತೆ – ಇನ್ನೂ\nಮೇಲ್ ;\nಕರ್ತನ ಪ್ರೀತಿ ಮಾಡುವವರಿಗೆ\nಸುಖವು ;\nಪ್ರೀತಿ ನಿನ್ನಲ್ಲಿದೆಯೋ ನೋಡು.\n3. ದುಚಖ ದಿನ ಬರುತ್ತೆ – ದುಚ ದಿನ\nಬರುತ್ತೆ\nದುಖ ದಿನ ಬರುತ್ತೆ - ಇನ್ನೂ\nಮೇಲ್ ;\nಪಾಪಿಯೇ ನಿನ್ನರಿಯೆ ಕರ್ತನು\nಹೇಳ್ವನೋ ?\nಇಂಥಾ ತೀರ್ಪಿಗೆ ತಪ್ಪಿಸಿಕೋ." },
  128: { title: "ಪಾಪವು ಹೋಗಲು ಆಶೆಯುಂಟೋ?", lyrics: "1. ಪಾಪವು ಹೋಗಲು ಆಶೆಯುಂಟೋ?\nಉಂಟು ಶಕ್ತಿ ಶಕ್ತಿ ರಕ್ತದಲ್ಲಿಯೇ,\nಪಾಪದ ಹೊರೆಯು ಬಿದ್ದು ಹೋಗಲೋ?\nಉಂಟು ಶಕ್ತಿ ರಕ್ತದಲ್ಲಿಯೇ.\nಪಲ್ಲವಿ\nಉಂಟು ಶಕ್ತಿ ಶಕ್ತಿ ದಿವ್ಯವಾದ ಶಕ್ತಿ\nನಮ್ಮ ಕರ್ತನಾದ ಯೇಸುವಿನ\nರಕ್ತದಲ್ಲಿಯೇ,\nಉಂಟು ಶಕ್ತಿ ಶಕ್ತಿ ದಿವ್ಯವಾದ ಶಕ್ತಿ\nನಮ್ಮ ಯೇಸುವಿನ ರಕ್ತದಲ್ಲಿಯೇ.\n2. ಗರ್ವದ ಬಿಡುಗಡೆ ಆಗಬೇಕೋ ?\nಉಂಟು ಶಕ್ತಿ ಶಕ್ತಿ ರಕ್ತದಲ್ಲಿಯೇ ;\nಪಾಪದ ಸೆರೆಯಿಂದ ತಪ್ಪಿಸಿಕೋ !\nಉಂಟು ಶಕ್ತಿ ರಕ್ತದಲ್ಲಿಯೇ.\n3. ಸೈತಾನ್ನ ಜಯಿಸಲು ಆಶೆಯುಂಟೋ ?\nಉಂಟು ಶಕ್ತಿ ಶಕ್ತಿ ರಕ್ತದಲ್ಲಿಯೇ ;\nಪಾಪದ ಗುಣವ ಕಳೆಯಬೇಕೋ ?\nಉಂಟು ಶಕ್ತಿ ರಕ್ತದಲ್ಲಿಯೇ.\n4. ಹಿಮಕ್ಕಿಂತ ಬಿಳುಪಾಗಬೇಕೋ ?\nಉಂಟು ಶಕ್ತಿ ಶಕ್ತಿ ರಕ್ತದಲ್ಲಿಯೇ ;\nನೀತಿಯ ವಸ್ತ್ರವ ಬೇಗುಟ್ಟುಕೋ !\nಉಂಟು ಶಕ್ತಿ ರಕ್ತದಲ್ಲಿಯೇ.\n5. ಯೇಸು ರಾಜನ ಸೇವೆ ಬೇಕೋ ?\nಉಂಟು ಶಕ್ತಿ ಶಕ್ತಿ ರಕ್ತದಲ್ಲಿಯೇ ;\nನಾನು ಅವನವನೆಂದೊಪ್ಪಿಕೋ !\nಉಂಟು ಶಕ್ತಿ ರಕ್ತದಲ್ಲಿಯೇ.\nಸುವಾರ್ತಾ ಸೇವೆಗಾಗಿ" },
  129: { title: "ಯಾರೋ ನಿಂತಿದ್ದಾರೀಗ ಹೊರಗೂ ?", lyrics: "1. ಯಾರೋ ನಿಂತಿದ್ದಾರೀಗ ಹೊರಗೂ ?\nಕರೆ ಈ ಹೊತ್ತಾತನ ಒಳಗೂ\nಎಷ್ಟೋ ಸಾರಿ ನಿಂತಿದ್ದ\nಬಿಟ್ಟು ಹೋಗದಂತಾತ\nಪರಿಶುದ್ಧ ಯೇಸುವ ಸೇರಿಸು.\n2. ನಿನ್ನ ಹೃದಯ ತೆರೆ ಸ್ವಾಮಿಗೂ ;\nಹೋಗುತ್ತಿದ್ದಾನೆ ಕರೆ ಒಳಗೂ,\nಆತ ನಿನ್ನ ಸ್ನೇಹಿತ\nನಿನ್ನ ಆತ್ಮಕ್ಕಾಧಾರ\nನಿತ್ಯವಾಗಿ ಕಾಯುವ ಸೇರಿಸು.\n3. ಪ್ರೀತಿಯ ಶಬ್ದ ಕೇಳು ಈಗಲೂ ;\nಆತನನ್ನಂಗೀಕರಿಸು ಆತ್ಮಕ್ಕೂ,\nಆತ ಬಾಗಿಲಲ್ಲಿಯೇ,\nನಿಂತು ತಟ್ಟುತ್ತಿದ್ದಾನೆ\nತೆರೆದಾಶೆಯಿಂದಲೇ ಸೇರಿಸು." },
  130: { title: "ಯೇಸು ಕ್ರಿಸ್ತನ ಪ್ರೀತಿಯನ್ನು", lyrics: "1. ಯೇಸು ಕ್ರಿಸ್ತನ ಪ್ರೀತಿಯನ್ನು\nಎಂದಾದರೂ ಕೇಳಿದಿಯಾ ?\nಹ್ಯಾಗೆ ದೇವರ ಲೋಕ ಬಿಟ್ಟು\nನಿನ್ನ ರಕ್ಷಿಸ ಇಲ್ಲಿ ಬಂದ ?\nಪಲ್ಲವಿ\nಹೌದೌದು! ನಿನ್ನ ರಕ್ಷಕ\nಯೇಸು ತಾನೇ,\nಹೌದೌದು! ನಿನ್ನನ್ನು ಪ್ರೀತಿ\nಮಾಡುತ್ತಾನೆ.\n2. ಆತನ್ ಪಟ್ಟಕಷ್ಟ ಶ್ರಮೆಯಾ\nನಾನ್ ಹೆಚ್ಚಾಗಿ ಕೇಳಿದೆನು,\nಮತ್ತು ನಿಜವೇ ಇದನ್ನೆಲ್ಲಾ\nನನಗೋಸ್ಕರ ತಾಳಿದನು.\n3. ಯೇಸು! ಈ ನನ್ನ ಮನವಿಯ\nದಯಮಾಡಿ ಅಂಗೀಕರಿಸು,\nದಿವ್ಯ ಪರಿಶುದ್ಧಾತ್ಮನಿಂದ\nನಿನ್ ಹತ್ರ ನನ್ನ ಸೇರಿಸು." },
  131: { title: "ಯೇಸುಸ್ವಾಮಿ", lyrics: "1. ಯೇಸುಸ್ವಾಮಿ\nನಿನಗಾಗಿ\nಸತ್ತಿದ್ದಾನೆ,\nಬಾರೈೆ, ಬಾರೈ\nಈವಾಗಲೇ,\nಬಾರೈ ಈವಾಗಲೇ,\n2. ನಿನ್ನ ಪಾಪ\nಪರಿಹಾರ\nಮಾಡಬಲ್ಲ\nಬಾರೈ, ಬಾರೈೆ.\nಈವಾಗಲೇ,\nಬಾರೈ ಈವಾಗಲೇ.\n3. ತಳ್ಳಲಾರ,\nನಂಬು ಮಾತ್ರ,\nಓ ಪಾಪಾತ್ಮಾ!\nಬಾರೈ, ಬಾರೈ,\nಈವಾಗಲೇ,\nಬಾರೈ ಈವಾಗಲೇ,\nಸುವಾರ್ತಾ ಸೇವೆಗಾಗಿ\n4. ತಡ ಮಾಡೆ,\nಬಂದೆ, ಬಂದೆ,\nನಂಬುತ್ತೇನೆ,\nಈಗ, ಈಗ,\nಈವಾಗಲೇ,\nನಂಬುತ್ತೇನೀಗಲೇ." },
  132: { title: "ಕ್ರಿಸ್ತೇಸು ಕರೆದ,", lyrics: "1. ಕ್ರಿಸ್ತೇಸು ಕರೆದ,\nಪಾಪಾತ್ಮನೇ !\nಈಗಲೇ ಕರೆದ,\nಕೇಳ್ ಪಾಪಿಯೇ !\n2. ಈ ಹೊತ್ತು ಕರೆದ,\nಓಡೋಡಿ ಬಾ!\nಬಿಟ್ಹೋಗು ಮನುಜಾ\nದುರ್ಮಾರ್ಗವ\n3. ಈ ಹೊತ್ತು ಕರೆದ\nಕೇಳಾತನ\nನಿನ್ನೊಡೆಯ ನಿನ್ನ\nಕಾಪಾಡುವ.\n4. ಈ ಹೊತ್ತು ಕರೆದ,\nಸುಪ್ರೇಮದಿ ;\nನೀ ಕೇಳದಿದ್ದರೆ\nಹಾಳಾಗುತ್ತೀ.\n5. ಈ ಹೊತ್ತು ಕರೆದ,\nಕೇಳಿದಿಯಾ 11\nಕ್ರಿಸ್ತೇಸು ಕಾಯುವ\nನಿನ್ನಾತ್ಮವ" },
  133: { title: "ನಿನ್ನಿಂದೇನು ಬೇಡುವು,", lyrics: "1. ನಿನ್ನಿಂದೇನು ಬೇಡುವು,\nಬೇಡ ಪಾಪಿಯೇ!\nಯೇಸು ಎಲ್ಲ ಮಾಡ್ವನು\nಮುಂಚೆ ನಿಜವೇ.\nಪಲ್ಲವಿ\nಯೇಸು ತೀರಿತೆಂದನು,\nತೀರಿತೆಲ್ಲವು\nಇಷ್ಟೇ ಸಾಕು ಅಲ್ಲವೇ!\nಬಾಕಿ ಏನಿದೆ ?\n2. ಸ್ವರ್ಗಲೋಕ ಬಿಟ್ಟನು\nನಿನಗಾಗಿಯೇ,\nಸ್ವಂತ ಜೀವ ಕೊಟ್ಟನು ;\nನಂಬು ಪಾಪಿಯೇ!\n3. ಯಾಕೆ ಕಷ್ಟ ಪಡುತ್ತೀ\nಪಾಪದಿಂದಲೇ ?\nಯಾಕೆ ಭಾರ ಹೊರುತ್ತೀ ?\nಎಲ್ಲಾ ವ್ಯರ್ಥವೇ.\n4. ಸ್ವಂತ ನೀತಿ ಅರ್ಪಿಸಿ\nಆತನ್ ಪಾದಕ್ಕೆ ;\nಕ್ರಿಸ್ತನ್ಲಿ ನಂಬಲು\nಕ್ಷಮೆಯಾಗುತ್ತೆ." },
  134: { title: "ಓ ಒಳ್ಳೇ ಸುದ್ದಿ! ರಕ್ಷಣೆ", lyrics: "1. ಓ ಒಳ್ಳೇ ಸುದ್ದಿ! ರಕ್ಷಣೆ\nಸಂಪೂರ್ಣ ವಾಯಿತು ॥\nಪಾಪಿಷ್ಟರೆಲ್ಲಾ ಕರುಣೆ\nಈಗ್ಥೊಂದಬಹುದು ॥\nನಾ ನಂಬುವೇ ನಾ ಹಾಡುವೆ.\nಸುವಾರ್ತಾ ಸೇವೆಗಾಗಿ\n2. ಕ್ರಿಸ್ತೇಸು ನಮ್ಮ ರಕ್ಷಕ\nಸಮಾಧಿ ಬಿಟ್ಟನು ; |\nಸಿಂಹಾಸನದ ಹತ್ತಿರ\nಮಧ್ಯಸ್ಥನಾದನು 1\nನಾ ನಂಬುವೇ ನಾ ಹಾಡುವೆ.\n3. ಈ ಶುಭ ಸಮಾಚಾರವ\nಭೂಮ್ಯಂತ್ಯಗಳ ತನಕ\nಪ್ರಸಿದ್ಧಿ ಮಾಡಿರಿ ॥\nನಾ ನಂಬುವೇ ನಾ ಹಾಡುವೆ.\n4. ಪ್ರಪಂಚದವರೆಲ್ಲರೇ\nವಿಮೋಚಕನ ನಾಮಕ್ಕೆ\nನಾ ನಂಬುವೇ ನಾ ಹಾಡುವೆ.\nಘನ, ಮಾನ, ಸ್ತುತಿ, ಸ್ತೋತ್ರ\nಯೇಸುಸ್ವಾಮಿಗಾಗಲೆಂದೂ ;\nಯೇಸು ನಮ್ಮ ರಕ್ಷಕಾದ\nಹಲ್ಲೆಲೂಯ ! ಸ್ತುತಿಸಿರಿ." },
  135: { title: "ಓ ಯೇಸುಸ್ವಾಮಿ! ನಿನ್ನಲ್ಲ", lyrics: "1. ಓ ಯೇಸುಸ್ವಾಮಿ! ನಿನ್ನಲ್ಲ\nಸನ್ಮಾರ್ಗ ಕಂಡೆನು,\nನಿನ್ನಲ್ಲಿ ಹೊರ್ತು ಪರಕ್ಕೆ\nಸೇರಲಿಕ್ಕಾಗದು.\n2. ನೀ ಸತ್ಯ : ನಿನ್ನ ವಾಕ್ಯವು\nಜ್ಲಾನೋಪದೇಶವೇ ;\nಸುಬುದ್ಧಿ ಶುದ್ಧ ಮನಸ್ಸು\nನಿನ್ನಿಂದಲಾಗುತ್ತೆ.\n3. ನೀ ಜೀವ ಗೋರಿ ತೆಗೆದು\nಸಾವನ್ನು ಜೈಸಿದಿ ;\nನಿನ್ನನ್ನು ನಂಬಿದವನು\nಇನ್ನೇತಕ್ಕಂಜಲಿ ?\n4. ನೀ ಮಾರ್ಗ, ಸತ್ಯ, ಜೀವವು.\nನಿನ್ನನ್ನು ಸಂಬುವೆ ;\nನೀನೊಬ್ಬನೇ ಸದ್ಗುರುವು ;\nನಿನ್ನ್ನು ಸೇರುವೆ." },
  136: { title: "ಅಮಿತವಾದದ್ದು", lyrics: "ಅಮಿತವಾದದ್ದು\nಸಂಪೂರ್ಣವಾದ ನೀತಿ\nಸಿಸ್ನ್ಿಂದಲಾಯತು;\nನ್ನಲಿ ಎನ್ನ ಹ್ಞಾರ\nಉತ್ತ್ತಿಯಾದರೆ,\nಮಪಾ ಅನಂದದಿಂದ\nನಿಸ್ನನ್ನು ಸೇರುಮೆ.\n2. ಎಸ್ ಪಾಪ ಬಂಧದಿಂದ\nನೀ ಪನ್ನ ದಯಿ,\nಅಫೋರ ಕೇಡಿದಿಂದ\nರಕ್ಷಣೆ ಮೂಡಿದ್ದೀ;\nಸಂಪೂರ್ಣ ನೀತಿಯಸ್ನು\nಸುವಾರ್ತಾ ಸೇವೆಗಾಗಿ\nನಿನ್ನಿಂದ ಹೊಂದಿದೆ,\nಅನಂತ ಭಾಗ್ಯವನ್ನು\nಸಂಪಾದ್ಯ ಮಾಡಿದೆ.\n3. ಓ ಪಾಪಿ! ನಿನ್ನ ದ್ರೋಹ\nಅಪಾರವಾದರೂ\nನಿನ್ನಲ್ಲಿ ಮನಸ್ತಾಪ\nಎಷ್ಟಾಗಿ ಇದ್ದರೂ\nದಯಾಳು ಕರ್ತನನ್ನು\nನೀ ಬೇಡಿಕೊಂಡಿರು,\nನಿನೆಲಾ ಕಷ್ಟವನ್ನು\nನಿವಾರಿಸುವನು." },
  137: { title: "ಕೃಪೆಯುಳ್ಳ ಯೇಸು ಕರ್ತಾ!", lyrics: "1. ಕೃಪೆಯುಳ್ಳ ಯೇಸು ಕರ್ತಾ!\nನನ್ನ್ನೀಗ ದೃಷ್ಟಿಸು;\nವಿನ್ನ ಪೂರ್ಣ ಕನಿಕರ\nದಯವಾಗಿ ತೋರಿಸು ;\nನಾನು ಪಾಪಿ –3\nಶಳ್ಳಿ ಬಿಡದೆ ಇರು.\n2. ಕಷ್ಪಟ್ಟು ಭಾರವನ್ನು\nಹೊರುವಂಥ ಜನರೇ\nವನ ಹತ್ರ ಓಡಿಬಂದು\nಶಾಂಶಿ ಹೊಂದಿರೆಲ್ಲರೇ\nಎಂಬ ಮಾತು -3\nನೀನು ಆಡಲಿಲ್ಲವೇ ?\n3. ಬಂದಿದ್ದೇನೆ, ರಿವ್ಯ ಮಿತ್ರಾ\nನೀಮು ಪಪ್ನಾಶ್ರಯವು.\nವಿನ್ನ ಮೇಲೆ ನನ್ನ ಭಾರ\nಈಗ ಹೊರಿಸಿದೆನು ;\nಪನ ಭಾರ - 3\nನೀನು ಹೊತ್ತುಕೊಂಡಿರು.\nಸುವಾರ್ತಾ ಸೇವೆಗಾಗಿ\n4. ನನ್ನ ಅಪವಿತ್ರ ಗುಣ\nಪೂರ್ಣವಾಗಿ ನೀಗಿಸು ;\nನಿನ್ನ ಹಿಂದೆ ಅಂಟಿಹೋಗ\nಶಕ್ತಿ ದಯಪಾಲಿಸು ;\nಮೋಕ್ಷದಲ್ಲಿ –3\nತರುವಾಯ ಸೇರಿಸು." },
  138: { title: "ಯೋರ್ದನ್ ನದೀ ತೀರದೊಳ್", lyrics: "1. ಯೋರ್ದನ್ ನದೀ ತೀರದೊಳ್\nಸಾವಿನ್ ತೆರೇ ಘೋಷದೊಳ್\nಏನಾಸ್ಪದ ? ॥\nಮಾರ್ಗ ಜಿಟ್ಟ ಪಾಪಿಯೇ\nಆಗ ಏನು ನಂಬಿಕೆ ?\nದೈವ ಕೃಪೆ ಇಲ್ಲದೆ\nಏನಾಸ್ಪದ ? ಏನಾಸ್ಟದ ?\n2. ದೇಹಾಚಾರ ಮಾಡಲು\nಏನಾಸ್ಟದ ? 18\nಭಕ್ತಿ ವೇಷವಿದ್ದರೂ\nಏನಾಸ್ಟದ ? 18\nನಿತ್ಯ ಜಪಸ್ಥಾನಕ್ಕೂ\nಬಂದು ಬಂದು ಕೂತರೂ\nಗುಣವಿಲ್ಲದಿದ್ದರೆ,\n3. ಜಾರಿಬಿದ್ದ ಕ್ರೆಸ್ತರೇ\nಏನಾಸ್ದದ ? 10\nಕಡೇ ದಿನ ಬಂದರೇ,\nಏನಾಸ್ಥದ? 6\nಮನಸ್ತಾಕ್ಷಿ ಪೀಡಿಸಿ,\nಗಡಗಡ ವಡುಗಿ\nಮುಂದೆ ಏನು ಮಾಡುವಿ ?\nವಿನಾಸ್ಥದ ? 58 ಏಿಣಾಸ್ಬದ ? 66\n4. ನಿನಗೆ ನನ್ನಾತ್ಮವೇ\nಏನಾಸ್ಪದ? |॥\nಪ್ರಾಣ ಹೋಗುವಲ್ಲಿಯೇ\nರಕ್ಷಕನ ಎದೆಯೇ\nಆತುಕೊಂಡು ಸಾಯುವೆ,\nಯೇಸುವಿನ ಶಿಲುಬೆ\nನನ್ನಾಸ್ಪದು ನನ್ನಾಸ್ಟದ" },
  139: { title: "ಎನ್ ಧ್ಯಾನ ಮೇಲಣ ಲೋಕವೇ,", lyrics: "1. ಎನ್ ಧ್ಯಾನ ಮೇಲಣ ಲೋಕವೇ,\nಪವಿತ್ರ ದೇಶವೇ,\nಇದ್ದಾರೆ ಮಿತ್ರರಲ್ಲಿಯೇ\nಸುಕ್ಷೇಮವಂತರೇ\nಅಲ್ಲಿಗೆ ಹೋಗ್ವೆ,\nಅಲ್ಲಿಗೆ ಹೋಗ್ವೆ,\nಅಲ್ಲಿಗೆ ಹೋಗ್ವೆ,\nಅಲ್ಲಿಗೆ ಹೋಗ್ಡೆನ್ಯೈ\n2. ಎನ್ ಧ್ಯಾನ ಮೇಲಣ ಲೋಕವೇ,\nಎನ್ ಸ್ವಾಮಿ ಅಲ್ಲಿಯೇ,\nಗಂಭೀರವಾಗಿ ಆಳುವ,\nಸಂಪೂರ್ಣ ಹರ್ಷವೇ,\nಅಲ್ಲಿಗೆ ಹೋಗ್ನೆ- (4)\n3. ಎನ್ ಧ್ಯಾನ ಮೇಲಣ ಲೋಕವೇ,\nಅಮೂಲ್ಯ ಸ್ಥಾನವು ;\nಕಿರೀಟ ಸಿಕ್ವದಲ್ಲಿಯೇ,\nಉತ್ಸಾಹ ಶೀರದು.\nಅಲ್ಲಿಗೆ ಹೋಗ್ನೆ (4)\n4. ಎನ್ ಧ್ಯಾನ ಮೇಲಣ ಲೋಣವೇ,\nಸುವರ್ಣ ದೇಶವು ;\nಸುರಾಗ ಹಾಡಿ ಎಂದಿಗೂ\nಸಂಭ್ರೆಮ ಶೀರದು.\nಅಲ್ಲಿಗೆ ಹೋಗ್ವೆ- (4)\n5. ಎನ್ ಧ್ಯಾನ ಮೇಲಣ ಲೊಕವೇ,\nವಾಗ್ಥಾತ್ತ ದೇಶವೇ\nಎನ್ನಾಕ್ಮ ಶುಂಬ ಕೋರುತ್ತೆ\nಆ ಲೊಣ ಸೇರ್ಲಿಕ್ಕೆ\nಅಲ್ಲಿಂದ ಹೋಗೆ\nಅಲ್ಲಿಂದ ಹೋಗೆ,\nಅಲ್ಲಿಂದ ಹೋಗೆ,\nಅಲ್ಲಿಂದ ಹೋಗೆವೈ." },
  140: { title: "ಪಾಪಿ ಏಕೆ ನಶಿಸಿ", lyrics: "1. ಪಾಪಿ ಏಕೆ ನಶಿಸಿ\nಏಕೆ ಸತ್ತು ಹೋಗುತ್ತೀ ?\nಸ್ವಂತ ಪ್ರಾಣ ಶೆಗೆದು\nಕೆಡಲೇನ್ನಿಮಿತ್ತವು ?\n2. ತಂದೆಯಾದ ದೇವರೂ\nರಕ್ತ ಕೊಟ್ಟ ಯೇಸುವೂ\nಸ್ನೇಹಿಸುವ ಆಶ್ಮನೂ\nಏತಕ್ಕೆಂದು ಅಂದರು.\n3. ನೀತಿ ಮಾರ್ಗ ಶ್ಯಜಿಸಿ\nಪಾಪದಲ್ಲಿ ಸತ್ತಿದ್ದೀ\nಎರಡನೇ ಮರಣ\nತಾಳಲಾಶೆಪಟ್ಟಿಯಾ ?\nಸುವಾರ್ತಾ ಸೇವೆಗಾಗಿ\n4. ಮೊ ಸ್ಮಾನದಲ್ಲಿ ನೀ\nಏಕೆ ನಿಂಕು ಕೊಂಡಿದ್ದೀ ?\nನರಕದ ಬಾಧೆಗೆ\nಭಯವೇನು ಇಲ್ಲವೇ ?\n5. ಕೇಳು ಕೇಳು ದ್ರೋಹಿಯೇ!\nಕೃಪಾ ಶಬ್ದ ಕೂಗುತ್ತೆ\nಕಿವಿಗೊಟ್ಟು ತಿರುಗು\nಕ್ಷಮೆ ಹೊಂದಿ ಬದುಕು." },
  141: { title: "ದೇವರಾಜ್ಯದಲ್ಲಿ ಉಂಟು,", lyrics: "1. ದೇವರಾಜ್ಯದಲ್ಲಿ ಉಂಟು,\nಇನ್ನು ಸ್ಥಳ ಪಾಪಿಯೇ !\nಹೌದು ಯೇಸುಸ್ವಾಮಿಯಲ್ಲಿ\nದಿವ್ಯ ಪುಣ್ಯ ಸಿಕ್ಕುತ್ತೆ.\nಬ್ನೂ ಬನ್ನಾ\nಬನ್ನಿ ಬನ್ನಿ\nಯೇಸುಸ್ವಾಮಿ ಪ್ರಿಯನೇ\n2. ಯೇಸು ಪಾಪಿಯನ್ನು ಹೌದು\nಅಂಗೀಕರಿಸುವನು ?\nನಿತ್ಯಜೀವ, ನಿತ್ಯ ಸುಖ\nಕೊಡುತ್ತಾನೆ ನಿಜವೇ.\nಬನ್ನಿ ಬನ್ನಿ\nಬ್ನಾ ಒನ್ನಿ\nಯೇಸುಸ್ವಾಮಿ ಮಿತ್ರನೇ\n3. ನಿಮ್ಮ ಮೇಲೆ ಯೇಸು ಕ್ರಿಸ್ತ\nಪ್ರೀತಿ ಇಟ್ಟು ಸತ್ತನು\nಈಗ ನಿಮ್ಮ ಪಾಪವೆಲ್ಲ\nಪರಿಹರಿಸುವನು.\nಒನ್ನಿ ಬನ್ನಿ\nಬನ್ನಿ ಬನ್ನಿ\nಯೇಸು ಸ್ವಾಮಿ ಆಪ್ತನು\n4. ಬೇಗ ಬನ್ನಿ ಎಲ್ಲಾ ಸಿದ್ಯ\nಈಗ ಶಾನೆ ಸ್ಥಳವು\nಯೇಸುವನ್ನು ನಂಬಿಕೊಂಡು,\nಪಾಪ ಕಳಕೊಳ್ಳಿರಿ.\nಬ್ನಿ ಬ್ನಿ\nಬ್ನಾ ಬ್ನಾ\nಯೇಸು ರಕ್ಷಿಸುವನು" },
  142: { title: "ಯೆಸು ಸ್ವಾಮಿ ನಿಮಗಾಗಿ", lyrics: "1. ಯೆಸು ಸ್ವಾಮಿ ನಿಮಗಾಗಿ\nಶನ್ನ ಪ್ರಾಣ ಕೊಟ್ಟನು,\nನಿಮ್ಮ ಪಾಪ ಕ್ಷಮೆಗಾಗಿ\nಕೂಗುತ್ತಾನೆ ನಿಮ್ಮನ್ನು\nಪಲ್ಲವಿ\nನಂಬಿರಿ ಈಗಲೇ,\nನಂಬಿ ಬನ್ನಿ ಈ ಹೊತ್ತೇ,\nಈಗಲೇ ಬಂದರೆ\nನಿಜ ಮುಕ್ತಿ ಸಿಕ್ಕುತ್ತೆ\n2. ದೊಡ್ಡ ಪಾಪಿಯಾಗಿದ್ದೇನೆ,\nಹೌದೀ ಮಾತು ನಿಜವೇ\nಪಾಪವೆಲ್ಲಾ ಬಿಟ್ಟು ನಂಬಿ\nಸಮಾಧಾನ ಹೊಂದುವೆ.\n3. ಶಾನೆ ದಿನ ಪಾಪದಲ್ಲಿ\nಬಿದ್ದಿದ್ದೇನೆ ನಿಶ್ಚಯ.\nನನ್ನ ಮೇಲೆ ದೇವ ಪ್ರೀಶಿ\nಉಂಟು ಎಷ್ಟೋ ಆಶ್ಚರ್ಯ.\nಪಾಪಕ್ಕಾಗಿ ದುಖಪಟ್ಟು\nಬೇಡುವಂಥ ನಿನ್ನನ್ನು\nಯೇಸುಸ್ವಾಮಿ ಸೇರ್ಸಿಕೊಂಡು\nಶಾಂತಿ ಪಾಲಿಸುವನು.\nಸುವಾರ್ತಾ ಸೇವೆಗಾಗಿ\n5. ಸ್ವಾಮಿ ಹತ್ರ ಹೋಗುತ್ತೀರಿ\nಅ ಸುವರ್ಣ ದೇಶದಿ\nನಿತ್ಯಜೀವ ಸುಖ ಅಲ್ಲಿ\nಹೊಂದುತ್ತೀರಾನಂದದಿ." },
  143: { title: "ಹೌದುಂಟು ಸುಭಾಗ್ಯವು ಶುದ್ಧರಿಗೆ,", lyrics: "1. ಹೌದುಂಟು ಸುಭಾಗ್ಯವು ಶುದ್ಧರಿಗೆ,\nದೇವೋಗ್ರದ ಭಯವು ತಪ್ಪಿ ಇದೆ ;\nಪಾಪಾತ್ಮರಿಗೋಸ್ಕರ ರಕ್ಷಣೆಯು\nಉಂಟೇಸುವಿನೊಳಗೆ ಎಂದೆಂದಿಗೂ.\nಪಲ್ಲವಿ\nಓ ಕರ್ತನ ಪ್ರೀತಿಯ\nಹಾಡಿರಿ ಭಕ್ತರೇ,\nಯೇಸುವು ರಕ್ಷಿಸ\nಬಲಿಷ್ಯನೇ.\n2. ಹೌದುಂಟು ಸುಭಾಗ್ಯವು ಶುದ್ಧರಿಗೆ\nಪವಿ್ರ ಸ್ವಭಾವವ ಹೊಂದಿದ್ದಾರೆ :\nಹೃದಯದೊಳೀಗಲು ದೇವಾತ್ಮನು\nನಿವಾಸವ ಮಾಡುತ್ತಾ ಇರುವನು.\n3. ಹೌದುಂಟು ಸುಭಾಗ್ಯವು ಶುದ್ಧರಿಗೆ\nಮಹಾ ಸಮಾಧಾನವು ಅವರದೇ ;\nಕ್ರಿಸ್ತೇಸುವು ತಾಳಿದ ಶಿಲುಬೆಯು\nಸಂಪೂರ್ಣ ವಿಮೋಚನೆ ಕೊಡುವದು.\n4. ಹೌದುಂಟು ಸುಭಾಗ್ಯವು ಶುದ್ಧರಿಗೆ,\nಪಿಶಾಚನ ತಂತ್ರವು ಸೋತ್ಥೋಗಿದೆ ;\nದುರ್ಮರಣವಾಗದು ಕ್ರೈಸ್ತರಿಗೆ\nಸಮಾಧಿಯ ಮೇಲೆಯೂ ಜಯವಿದೆ." },
  144: { title: "ಅದಿ ಕರ್ಶ ಕ್ರಿಸ್ತನೇ!", lyrics: "1. ಅದಿ ಕರ್ಶ ಕ್ರಿಸ್ತನೇ!\nಸೀಳಲ್ಪ್ಟಿ ಬಂಡೆಯೇ!\nನಿೀನು ಪ್ಟುಗಾಯವು\nಹೊಯ್ದ ನೀರೂ ರಕ್ತವೂ\nಪನ್ನಪಾಪ ನೀಗಿ,\nಪೂರ್ಣ ಶುದ್ಧಮಾಡಲಿ.\n2, ದೈವಕಟ್ಲಿ ಕೈಕೊಂಡು\nಬಾಳ ಶಕ್ತಿಯಲ್ಲವು ;\nಎಷ್ಟು ಶಾಸಪಟ್ಟರೂ\nಕಣ್ಣೀರೆಷ್ಟು ಬಿಟ್ಟರೂ\nಪನ್ನ ದ್ರೋಹ ಹೋಗದು ;\nಕರ್ಪ ! ವೀನೇ ರಕ್ಷಿು.\nಯೇಸು! ನಿನ್ನ ಶಿಲುಬೆ\nಪತ್ನಾಧಾರವಾಗಿದೆ ;\nನಾನು ಘೋರ ಪಾಪಿಯು\nನೀತಿ ವಸ್ತ್ರ ಹೊದ್ಧಿು ;\nನೀನು ತಳ್ಳಿದಟ್ಟರೆ\nಬೇರೆ ಗತಿ ಎಲ್ಲಿದೆ?\nಭೂಸಿವಾಸದಲ್ಲಿಯೂ,\nಸಾಯುತ್ತಿರುವಾಗಲೂ,\nನ್ಯಾಯಶೀರ್ಪಿನಲ್ಲಿಯೂ,\nಯಗೆ ಯುಗವೆಂದಿಗೂ,\nಸೀಳಲ್ಪಟ್ಟ ಬಂಡೆಯೇ!\nನೀನೇ ದಿಕ್ಕು ಪನಗೆ\nಸುವಾರ್ತಾ ಸೇದೆಗಾಗಿ" },
  145: { title: "ಓ ಒನ್ನಿ ಹಿರೀಕಿರ್ಯರೇ!", lyrics: "1. ಓ ಒನ್ನಿ ಹಿರೀಕಿರ್ಯರೇ!\nಸುರಾಗ ಎಸ್ತಿರಿ,\nಹೊನ್ನ ಎಂದು ಕ್ರಿಸ್ತಗ\nಇಂಪಾಗಿ ಹಾಡಿರಿ;\nದೇವಾವಶಾರ ಅಶನೇ,\nಸಂಕೋಜಪಡಿರಿ ;\nರಾಜಾಧಿರಾಜ ಪ್ರಭುವೇ\nಸಾಷ್ಟಾಂಗ ಬೀಳಿರಿ.\n2. ಕ್ರಿಸ್ತೆಸುವಿನ ಪಾಮವು\nಮಹತ್ವವುಳ್ಳದ್ದು\nಸಮಸ್ತ ಜನ ಅದನ್ನು\nಕೊಂಡಾಡಶಕ್ಕದ್ದು;\nಹೌದಾತನೇ ವಿಮೋಚಕ,\nಲೋಕೋಪಕಾರಿಯು,\nಎಲ್ಲರಿಗಾತ ರಕ್ಷಕ,\nಶಾಶ್ವಹಾಶ್ರಯವು\n3. ಅನಂದವುಳ್ಳ ಲೋಕವ\nಕಣ್ಣೆ್ತಿ ೃಪ್ಟಿ,\nಅಲ್ಲಾಗುವಂಥ ವೈಭವ\nಇಲ್ಲಿಂದ ನೋಡಿರಿ\nಆಹಾ! ಆ ಸುಖ ಪೂರ್ತಿಯು\nಸಂಪಾದ್ಯವಾದರೆ,\nನಿರಂತ್ರಾರ್ಧಟಿಸುವೆವು\nಬಾಳೇಸು ಸ್ವಾಮಿಯೇ!\nಸುವಾರ್ತಾ ಸೇವೆಗಾಗಿ\nಪಾಪಿಯಾದ ನನಗೆ ?\nದೋಷ ಕ್ಷಮೆ ಅದೀತೇ\nಬುರ್ಧಿಗೆಟ್ಟ ದ್ರೋಹಿಗೆ?\n2. ಬಹು ಕಾಲದಿಂದಲೂ\nಕರ್ತನನ್ನು ಬಿಟ್ಟಿು ;\nಅತಗೆಷ್ಟೋ ದುಬುವ\nನಾನು ಹುಟ್ಟಿದೆನು!\n3. ದೀರ್ಘಶಾಂಶಿ ಕರ್ಕಮ\nಇಮ್ನೂ ಕೋರಿಸಿದನು;\nಪ್ರೀಶಿಯಿಂದ ಅತನು\nಯೇಶುವನ್ನು ಕೊಟ್ಟನು.\n4. ನನಗಾಗಿ ಕ್ರಿಸ್ತಮ\nಗಾಯಪಟ್ಟು ಸತ್ತನು ;\nವೈರಿಗಾಗಿ ಆತನು\nಕಾರ್ಯಕರ್ತನಾದನು." },
  147: { title: "ಶಿಲ್ಬೆ ಪಟ್ಟವನನ್ನು ನೋಡಿದರೆ", lyrics: "ಶಿಲ್ಬೆ ಪಟ್ಟವನನ್ನು ನೋಡಿದರೆ\nಜೀವದುತ್ತ್ತಿಯಾಗುವದು,\nಓ ಪಾಪಾತ್ಮರೇ! ನೋಡಿರೀವಾಗಲೇ\nಶಾಪ ಶಾಳಿದ ಕ್ರಿಸ್ತನನ್ನು\nಪಲ್ಲವಿ\nನೋಡೋ ನೋಡಿರಿ ;\nಶಿಲ್ಬೆ ಪಟ್ಟವನನ್ನು ನೋಡಿದರೆ\nಜೀವದುತ್ತ್ತಿಯಾಗುವದು.\n2. ಯೆಗು ಕನ್ನನ್ನು ಒಬ್ರಿಕೊಟ್ಟಾಗಲೇ\nನಿಮ್ಮ ದೋಷವು ಹರಿಯತು,\nಅತ ರಕ್ತವ ಚೆಲ್ಲಿ ಸಪ್ತಾಗಲೇ\nನಿಮ್ಮ ಸಾಲವು ಸಂಧ್ಹ್ೋಯತು\n3. ಜಪಶಪ ಗೋಳಾಟದಿಂದೇನು ಇದೆ ?\nಅತ್ಮ ರಕ್ಷಣೆ ಹೊಂದಿಸವು ;\nದೇವಪುತ್ರನ ರಕ್ತದ ಬುಗ್ಗೆ ಒಂದೇ\nಶುದ್ಧ ಹೃದಯ ಕೊಡುವದು.\n4. ಸಂದೇಹವು ಯಾಕೆ? ಯೆಹೋವ ಶಾನೇ\nಸ್ಥಿರ ವಾಗ್ತ್ತ ಮಾಡಿದನು,\nಶ್ರೇಷ್ಠ ಯಾಜಕನಾದ ಕ್ರಿಸ್ತೇಲುವೇ\nಪರಲೋಕದೋಳ್ ಮಧ್ಯಸ್ಮ\n5. ಸಂಶೋಷದಿಂದೀಗಲೂ ತಕ್ಕೊಳ್ಳಿರಿ.\nವಿತ್ಯಜೀವದ ದಾನವನ್ನು\nಮತ್ತು ನಿಶ್ಚಯವಾಗಿ ಗ್ರಹಿುಿನಿ\nಸಾವು ನಿಮ್ಮನ್ನು ಕೆಿಸದು,\nನಂದೋ ನಂಜಿರಿ ;\nಶಿಲ್ಚೆಪಟ್ಟವನನ್ನು ನಂಬಿದರೆ\nಜೀವದುಶತ್ತಿಯಾಗುವದು." },
  148: { title: "ಮಹಾ ಸಮೂಹ ಏಶಕ್ಕೆ", lyrics: "1. ಮಹಾ ಸಮೂಹ ಏಶಕ್ಕೆ\nದಿನಾಲು ಕೂಡಿ ಬರುತ್ತೆ?\nಇದೇನಾಶ್ಚರ್ಯ ಜನರು\nಇಷ್ಟಾಗಿ ಗುಂಪು ಕೂಡಿದ್ದೆ?\nಪ್ರಶ್ಯುತ್ರವಾಗಿ ಅಂದರು\nನಜರೇತ್ ಯೇಸು ಬಂದನು 8\n2. ಈ ಯೇಸು ಯಾರು ? ಏತಕ್ಕ\nಊರೆಲ್ಲ ಬಂತು ಇಲ್ಲಿಗೆ ?\nಕಾರಣವೇನೀ ಭ್ರಮೆಗೆ\nಸಮಸ್ತ ಜನರೊಳಗೆ ?\nಆದೇ ಪ್ರಕಾರ ಅಂದರು\nವಜರೇತ್ ಯೇಸು ಬಂದನು 11\n3. ಹೌದೇಸುವನ್ನು ಬಲ್ಲೆವು\nಭೂಲೋಕ ರಕ್ಷಕಾತನು\nಯಾವಾಗ್ಯೂ ಎಲ್ಲಾ ಜನಕ್ಕೂ\nಸರ್ವಪಕಾರಿ ಆತನು ;\nಸಂತೋಷ ಪಡತಕ್ಕದ್ದು\nನಜರೇತ್ ಯೇಸು ಬಂದನು 1॥\n4. ಪಾಪಾತ್ಮರೆಲ್ಲಾ ಬನ್ನಿರಿ\nಶ್ರಮವನ್ನು ಹೊಂದಿರಿ\nಎಂತಂದು ಯೇಸು ಕರೆದು,\nನಮ್ತ್ರ ನಿಂತುಕೊಂಡನು.\nಆನಂದ ಪಡಿ ಈಗಲು\nನಜರೇತ್ ಯೇಸು ಬಂದನು ॥\n5. ಓ ಬನ್ನಿರೆಲ್ಲಾ ಜನರೇ\nಈ ಸ್ನೇಹಿತನ, ಬಳಿಗೆ;\nನಾವೊಲ್ಲೆವೆಂದು ಹೇಳಲು,\nನಿಮ್ಮನ್ನು ಬಿಟ್ಟು ಬಿಟ್ಟಾನು ;\nಗೋಳಾಟ ಆಗ ಶಪ್ಪದು,\nನಜರೇತ್ ಯೆಸು ಹೋದನು 9" },
  149: { title: "ಕ್ರಿಸ್ತೇಸು ನಿಜ ತೀರ್ಥವು", lyrics: "1. ಕ್ರಿಸ್ತೇಸು ನಿಜ ತೀರ್ಥವು\nಈ ತೀರ್ಥದೊಳಗೆ\nಪಾಪಾತ್ಮ ತೊಳಕೊಳ್ಳಲು\nಶುದ್ಧಿಯ ಹೊಂದ್ವನು.\nಸುವಾರ್ತಾ ಸೇವೆಗಾಗಿ\n2. ಇಲ್ಲಿ ಪ್ರಸಿದ್ಧ ದುಷ್ಟನು\nಶುದ್ಧತ್ವ ಹೊಂದಿದ ;\nಪಾಪಾತ್ಮನಾದ ನನ್ನನ್ನು\nನಿರ್ಮಲ ಮಾಡುವ,\n3. ಈ ಬುಗ್ಗೆ ಕಂಡ ನನಗೆ\nಸಂಭ್ರಮ ಹುಟ್ಟಿತು;\nಸ್ವರ್ಗದೊಳು ಕೊಂಡಾಡುವೆ\nಈ ಶ್ರೇಷ್ಠ ತೀರ್ಥವ.\n4. ಈ ತೀರ್ಥದಲ್ಲಿ ಶುದ್ಧಿಯ\nಹೊಂದಿದ ಪಾಪಿಯು;\nಅತ್ಯಂತ ಶುದ್ಧ ದೇವರ\nಸಮ್ಮುಖ ಸೇರ್ವನು.\n5. ನಾ ನಂಬುವೆ, ನಾನ್ ಹಾಡುವೆ,\nರಕ್ಷಣೆ ನನ್ನದು,\nನನ್ನಪರಾಧ ಹರಿಸ\nಕ್ರಿಸ್ಯೈಸು ಸತ್ತನು." },
  150: { title: "ಕಣ್ಣೆತ್ತಿ ಕ್ರೂಜೆಯನ್ನು", lyrics: "1. ಕಣ್ಣೆತ್ತಿ ಕ್ರೂಜೆಯನ್ನು\nಪಾಪಾತ್ಮ ದೃಷ್ಟಿಸು ;\nಸ್ವಾಮಿಯ ಪ್ರೀತಿಯನ್ನು\nಎಷ್ಟೆಂದು ಧ್ಯಾನಿಸು;\nಆ ಶ್ರಮ ನಿನಗಾಗಿ\nಕ್ರಿಸ್ೇಸು ತಾಳಿದ ;\nನಿನ್ನ ಅಕ್ರಮಕ್ಕಾಗಿ\nಸ್ವರಕ್ತ ಚೆಲ್ಲಿದ.\nಸುವಾರ್ತಾ ಸೇವೆಗಾಗಿ\nಪಾಪಾತ್ಮನೇ, ಆಲೈಸು!\nಸಂದೇಹ ಬೇಡವು ;\nಏಶ್ವಾಸಿಗೆಷ್ಟು ಮಾತ್ರ\nರಕ್ಷಣೆ ಶಪ್ಪದು ;\nರೋಗಿಷ್ಠ ನನ್ನ ಹತ್ರ\nಕ್ಷೇಮಕ್ಕೆ ಬರಲು,\nಆರೋಗ್ಯ ಕೊಡುತ್ತೇನೆ\nಎಂದ್ಯೇಸು ಅಂದನು.\n3. ಸ್ವನೀತಿ ನಂಬಬೇಡ,\nಅದೆಲ್ಲಾ ವ್ಯರ್ಥವು ;\nಪ್ರಪಂಚದ ಪ್ರಭಾವ\nನೀ ನೋಡಬಾರದು ;\nಕ್ರಿಸ್ತೆಸು ಸ್ವಾಮಿ ತಾನೇ\nನಿನ್ನೊಂದೇ ಮಾರ್ಗವು,\nಪಾಪಾತ್ಮ ಬಂದ ಕೂಡ್ಲೆ\nವಿಮೋಚಿಸುವನು.\n4. ಇನ್ನೆಲ್ಲಿ ಮನಶ್ಶಾಂತಿ\nಯಾರಿಗೂ ಸಿಕ್ಕದು,\nಹೃದಯದ ವಿಶ್ರಾಂತಿ\nಇನ್ನೆಲ್ಲಿ ಇಲ್ಲವು ;\nಓ ಪಾಪಿ! ಬಂದು ನೋಡು\nವಿಮೋಚಕನನ್ನು ;\nಭಯವೆಲ್ಲಾ ತೊರೆದು\nಆತನ್ನ ನಂಬಿರು." },
  151: { title: "ಕೈಯಲ್ಲಿ ಒಂದೂ ಇಲ್ಲದೆ.", lyrics: "1. ಕೈಯಲ್ಲಿ ಒಂದೂ ಇಲ್ಲದೆ.\nನಿನ್ನತ್ರ ಬಂದೆ, ಕರ್ತನೇ !\nನೀ ಸತ್ತಿ ನನಗಾಗಿಯೇ ;\nಪಾಪಾತ್ಮ ರೃಷ್ಟಿಸ್ಯೇಸುವೇ !\n2. ಕೈಯಲ್ಲಿ ಒಂದೂ ಇಲ್ಲದೆ.\nನಾ ಕೆಟ್ಟುಹೋದ ದ್ರೋಹಿಯೇ,\nನೀ ಮಾತ್ರ ಗತಿ ನನಗೆ ;\nಪಾಪಾತ್ಮ ಕ್ಷಮಿಸ್ಯೇಸುವೇ!\n3. ಕೈಯಲ್ಲಿ ಒಂದೂ ಇಲ್ಲದೆ,\nನಾ ಕೇವಲ ಅಯೋಗ್ಯವೇ ;\nದೌರ್ಭಾಗ್ಯ ನೋಡಿ ತಳ್ಳದೆ.\nಪಾಪಾತ್ಮ ಸೇರಿಸ್ಯೆಳುವೇ !\n4. ಕೈಯಲ್ಲಿ ಒಂದೂ ಇಲ್ಲದೆ.\nಇನ್ನಾವ ದಿಕ್ಕು ಕಾಣದೆ\nನಿನ್ನನ್ನು ಮಾತ್ರ ನಂಬಿದೆ,\nಪಾಪಾತ್ಮ ರಕ್ಷಿಸ್ಯೇ ಳುವೇ." },
  152: { title: "ದೇವರ ದಯವೇ", lyrics: "1. ದೇವರ ದಯವೇ\nಪಾಪಿಯ ಕಡೆಗೆ\nಪ್ರತ್ಯಕ್ಷವಾಗಿದೆ ;\nನೋಡೀಗ ಪಾಪಿಯೇ.\nಪಲ್ಲವಿ\nಯಾರ್ಯಾರು ನೋಡಿ ನಂಬ್ವರೋ\nನಿರಂತ್ರ ಜೀವ ಹೊಂದ್ವರು ;\nನಿರಂತ್ರ ಜೀವ ಹೊಂದ್ವರು.\n2. ಗಣೆಯ ಸರ್ಪವ\nನೋಡಿದ ಹಾಗೆಯೇ\nಕ್ರೂಜಿತ ಯೇಸುವ\nನೀ ನೋಡು ಪಾಪಿಯೇ.\n3. ನಾಶನ ಮಾಡಲು\nಕ್ರಿಸ್ರೈೇು ಒಲ್ಲನು ;\nರಕ್ಷಣೆ ಎಲ್ಲರ್ಗೂ\nಪೂರೈಸ ಬಂದನು.\n4. ಪಾಪಿಗೆ ಶಾಪವು\nನೇಮಿಸಲ್ಪಟ್ಟಿತು ;\nಕ್ರಿಸ್ತೇಸು ಸ್ವಾಮಿಯು\nಎನ್ ತಪ್ಪಿಸಿದನು.\n5. ಪಾಪಿಯ ಮಿತ್ರನೇ\nನನ್ನ ಸಹಾಯಿಸು !\nಶಾಂತಿದಾಯಕನೇ\nನನ್ನಂಗೀಕರಿಸು !" },
  153: { title: "ಯೇಸುವನ್ನೇ ಪ್ರೀತಿ ಮಾಡುವೆನು ;", lyrics: "1. ಯೇಸುವನ್ನೇ ಪ್ರೀತಿ ಮಾಡುವೆನು ;\nವಿಧೇಯನಾಗಿ ನಾನಿರುವೆನು ;\nನನ್ನನ್ನು ಎಷ್ಟಾಗಿ ಸ್ನೇಹಿಸಿದ,\nಹಗಲು ರಾತ್ರಿ ಕಾಪಾಡುತ್ತಿದ್ದ\nಪಲ್ಲವಿ\nಅವನ ಸೇವೆ ಮಾಡುವೆನು,\nನೀನು ಮಾಡುವದಿಲ್ಲವೋ ?\nಅವನ ಸೇವೆ ಮಾಡುವೆನು ;\nನನ್ನು ಸ್ನೇಹಿಸಿದು\n2. ಯೆಸುವನ್ನೇ ಪ್ರೀತಿ ಮಾಡುವೆನು\nಅವಸನ್ನೆಂದಿಗೂ ನಂಬುವೆನು ;\nಅವನು ನನಗೆ ಚಿಂತಿಸುತ್ತಾ,\nಜೀವದ ಅಂತ್ಯಕ್ಕೂ ಪೋಷಿಸುಮ\n3. ಯೆಸುವನ್ನೇ ಪ್ರೀಶಿ ಮಾಡುವೆನು\nಪಾಪದ ಅಶೆಯ ಬಿಡುವೆನು ;\nಅವನು ಮೇಲಕ್ಕೆ ಕರೆಯಲು\nಸ್ತೋಶ್ರದ ಕೊಂಡಾಟ ಕೊಡುವೆನು.\nಸುವಾರ್ತಾ ಸೇವೆಗಾಗಿ" },
  154: { title: "ರಕ್ಷಕನನ್ನು ಸೇರೀಗಲೇ ;", lyrics: "1. ರಕ್ಷಕನನ್ನು ಸೇರೀಗಲೇ ;\nಮಾರ್ಗವ ವೇದ ತೋರಿಸುತ್ತೆ :\nಕರುಣಾ ಶಬ್ದ ಉಂಟಲ್ಲವೇ ?\nಓ ಪಾಪಿ! ಇತ್ತ ಬಾ.\nಪಲ್ಲವಿ\nಹರ್ಷ ! ಹರ್ಷ ! ನಿತ್ಯ ಮಹಿಮೆ ;\nಯೇಸು ಸ್ವಾಮಿ ಕೊಟ್ಟನನಗೆ\nತಿಳ್ನೀರು ಪಾನವಾಗುತ್ತದೆ.\nತಂದೆಯ ಮನೆಯೊಳ್.\n2. ಮಕ್ಕಳೇ ಬನ್ನಿ ಎಂದು ಹೀಗೆ\nಯೇಸು ಕರೆಯುತ್ತಾನಲ್ಲವೇ ?\nತಡ ಮಾಡದೆ ಬೇಗನೆ ಬಾ\nಆನಂದದಿಂದ ಬಾ.\n3. ಯೋಚನೆ ಮಾಡು, ಕರ್ತ ತಾನೇ,\nದಯದ ಮಾತು ಹೇಳುತ್ತಲೇ,\nವಿಧೇಯನಾಗಿ ಕೇಳ್ ಪಾಪಿಯೇ!\nರಕ್ಷಣೆ ಹೊಂದ ಬಾ." },
  155: { title: "ಇದ್ದಾನೆ ಘನವೈದ್ಯನು", lyrics: "1. ಇದ್ದಾನೆ ಘನವೈದ್ಯನು\nಕಟಾಕ್ಷವುಳ್ಳ ಯೇಸು ;\nಆರೋಗ್ಯ ಮಾಡಬಲ್ಲನು,\nಆ ಸುಕ್ಷೇಮ ಇಲ್ಲಿ ಕೇಳು.\nಪಲ್ಲವಿ\nಹಾ! ಇಂಪಾದ ಸ್ವರವೇ,\nಅತಿ ರಮ್ಯ ರಾಗವೇ,\nಮುದ್ದು ಮುದ್ದು ಹೆಸರೇ,\nಯೇಸು ಪ್ರಿಯ ಯೇಸು.\n2. ನಿರ್ಭಯ ಶಾಂತಿ ಕೊಡುತ್ತೆ\nಕ್ರಿಸ್ಯಸುವಿನ ಧ್ಯಾನ ;\nಅನಂತ ಪರಿಮಳವೇ\nಈ ಶ್ರೇಷ್ಠವಾದ ನಾಮ.\n3. ಕೊಂಡಾಡಿರಿ ಸಮಸ್ತರೇ,\nಈ ದಿವ್ಯ ಮಿತ್ರನನ್ನು;\nಆನಂದ ಪಟ್ಟು ಮನವೆ.\nಆರಾಧಿಸ್ಯೇಸುವನ್ನು\nಆಲೈಸಿ, ಹಿರಿಕಿರ್ಯರೇ!\nಕ್ರಿಸ್ೇಸು ನಿಮ್ಮ ಜೀವ ;\nನಮ್ಮಾತ್ಮದಾಪ್ತನಾತನೇ\nಸಮಾಧಿ ಜೈಸಿದಾತ.\n5. ನಾ ಪರಲೋಕಕ್ಕೇರಲು,\nಎನ್ ಹಾಡು ಯೇಸುಸ್ವಾಮಿ ;\nಬೇರೊಂದು ನಾಮವೆಂದಿಗೂ\nನಾ ಸ್ತೋತ್ರ ಮಾಡಲೊಲ್ಲೆ" },
  157: { title: "ದೇವರಿಂದುಂಟಾದ ವಾಕ್ಯ", lyrics: "1. ದೇವರಿಂದುಂಟಾದ ವಾಕ್ಯ\nನನ್ನ ಬೊಕ್ಕಸಾಗಿದೆ ;\nನಾನದನ್ನು ದಿನ ದಿನ\nಧ್ಯಾನ ಮಾಡಿಕೊಳ್ಳುವೆ,\nಸಮಾಧಾನ,\nಸುವಾರ್ತಾ ಸೇವೆಗಾಗಿ" },
  158: { title: "ರಕ್ಷಕ ಯೇಸುವು ಕರೆಯುತ್ತಾನೆ,", lyrics: "1. ರಕ್ಷಕ ಯೇಸುವು ಕರೆಯುತ್ತಾನೆ,\nಮನುಜನೇ ! ಮನುಜನೇ !\nನಿನಗೆ ಶುದ್ಧತ್ವ ಕೊಡುತ್ತಾನೆ ;\nಈ ಹೊತ್ತು ಕೇಳ್ ಪಾಪಿಯೇ\n2. ಈಗಲೇ ನಿನಗೆ ಹೇಳುತ್ತಾನೆ,\nನನ್ ಹತ್ರ ಬಾ! ನನ್ ಹತ್ರ ಬಾ\nಪಾಪವನ್ನೆಲ್ಲಾ ನಾನ್ ಮನ್ನಿಸುವೆ.\nವಿಶ್ರಾಂತಿ ಕೊಡುವೆ ನಾ.\n3. ಪಾಪದ ಬೆಟ್ಟದ ಮೇಲೆ ಯಾಕೆ\nಅಲೆಯುತ್ತೀ, ಓ ಮನುಜಾ ;\nದೇವರು ಹತ್ರ ಇದ್ದಾನಲ್ಲವೇ ?\nನಿನ್ನ್ನು ಸೇರಿಸುಮ.\n4. ನಂಬಿದರೆ ನಿತ್ಯಜೀವವನ್ನು\nಕೊಡುವನು, ಕೊಡುವನು,\nನಂಬದೆ ಹೋದರೆ ನರಕವು\nನಿನಗೆ ಆಗುವದು.\nದೇವರ ವಾಕ್ಯ\nನಿತ್ಯಭಾಗ್ಯ,\n2. ದುಷ್ಟನಾದವನ ಮೋಸ,\nಎಂದೂ ಪ್ರಾಪ್ತಿಸಿದರೆ,\nದೇವವಾಕ್ಯ ಖಡ್ಗದಿಂದ\nಎದುರಿಸಿ ನಿಲ್ಲುವೆ ;\nಧೈರ್ಯವಾಗಿ\nಯುದ್ಧಮಾಡಿ\n3. ಲೊಣದಲ್ಲಿ ಬಾಧೆ ಭೀಷಿ\nದುಚು ಕಷ್ಟ ಬಂದರೂ\nದೇವವಾಕ್ಕವು ವಿಶ್ರಾಂತಿ\nಕೂಡ ಬಲವುಳ್ಳದ್ದು;\nಗ್ರಂಥ ರತ್ನ!\nದೈವ ದಾನ!\nನೀನು ನನಗಾಸ್ತಿಯು" },
  159: { title: "ಪರಾತ್ತರನ ವಾಕ್ಕವು", lyrics: "1. ಪರಾತ್ತರನ ವಾಕ್ಕವು\nಎಷ್ಟೋ ನಿರ್ಮಲವು!\nಎಲ್ಲಾ ರುರ್ಮಾರ್ಗಗಳಿಗೂ\nವಿರೋಧವಾದದ್ದು\n2. ರರ್ಪಣ ಮುಖ ಭಾವವ\nತೋರಿಸುವಂತೆಯೇ\nಸದ್ವೇದವು ಅಂತರ್ಯವ\nಪ್ರತ್ಯಕ್ಷ ಮಾಡುತ್ತೆ\n3. ಈ ವೇದವನ್ನು ಧ್ಯಾನಿಸಿ\nಕೈಕೊಳ್ಳುವಮರು\nಕಳಂಕವನ್ನು ತ್ಯಜಿಸಿ\nಶುರ್ಧತ್ವ ಕೊಂದ್ದರು.\n4. ದೇವಾತ್ಮನೇ! ಅ ವಾಕ್ಯವ\nನಮಗೆ ದೋಧಿಸು;\nತದನುಸಾರ ನಡೆಯ\nಸಹಾಯವಾಗಿರು.\nದೇವರ ವಾಕ್ಕ" },
  160: { title: "ಶುದ್ಧ ದಿವ್ಯ ಗ್ರಂಥವೇ", lyrics: "1. ಶುದ್ಧ ದಿವ್ಯ ಗ್ರಂಥವೇ\nನನ್ನ ಶ್ರೇಷ್ಠ ದ್ರವ್ಯವೇ,\nತೋರಿಸೆನ್ನ ಸ್ಥಿತಿಯ,\nಹೇಳು ದೈವ ಶ್ರುತಿಯ,\nಶುದ್ಧ ದಿವ್ಯ ಗ್ರಂಥವೇ\nಶ್ರೇಷ್ಠ ದ್ರವ್ಯವೆನಗೆ\n2. ನೀವೆ ನಡಿಸೆನ್ನನ್ನು\nತೋರಿಸೆನ್ನ ಪಾಪವ !\nನೀನೆ ನನ್ನ ರಕ್ಷಣೆ\nನನ್ನ ಜೀವ ಮಾರ್ಗವೇ ;\nಶುದ್ಧ ದಿವ್ಯ ಗ್ರಂಥವೇ ;\nಶ್ರೇಷ್ಠ ದ್ರವ್ಯವನಗೆ\n3. ಮೋಕ್ಷದ ಆನಂದವ\nಮಾಡೆನ್ನಲ್ಲಿ ಖಚಿತ!\nಮರಣಾಂಧಕಾರದಿ\nನಿಲ್ಲಿಕ್ಕೆ ಧೈರ್ಯದಿ,\nಶುದ್ಧ ದಿವ್ಯ ಗ್ರಂಥವೇ\nನೀನೆ ಬೋಧಿಸೆನಗೆ!\n4. ನಾನು ಸತ್ತು ಏಳಲು,\nಮಹಿಮಾ ಕಿರೀಟವ\nದೇವರಿಂದ ಹೊಂದುವ\nಮಾರ್ಗ ಬುದ್ಧಿಶಕ್ತಿಯ\nನೀನು ಬೋಧಿಸೆನಗೆ,\nಶುದ್ಧ ದಿವ್ಯ ಗ್ರಂಥವೇ!\nಸುವಾರ್ತಾ ಸೇವೆಗಾಗಿ" },
  161: { title: "ಸಮುದ್ರ ಹತ್ರದಿ", lyrics: "1. ಸಮುದ್ರ ಹತ್ರದಿ\nಕ್ರಿಸ್ತ್ರೈಸುವೇ!\nಆಶ್ಚರ್ಯ ರೀತೀಲಿ\nಕೊಟ್ಟಂತೆಯೇ,\nಜೀವದ ರೊಟ್ಟೆಯ\nಓ ಪಾಲಿಸು ;\nನನ್ನಾತ್ಮದಾಶೆಯ\nನೀ ತೀರಿಸು.\n2. ನಿನ್ನನ್ನು ಬಿಟ್ಟರೆ\nಬದುಕೆನು ;\nಇನ್ಯಾರ ಬಳಿಗೆ\nಹೋಗೋಣವು ?\nಪ್ರೇಮ ಸಂಪೂರ್ಣನೆ\nವೇದೋಕ್ತಿಯ\nಪ್ರೀತಿಸುವಂತೆಯೇ\nಪ್ರೇರಿಸೆನ್ನ\n3. ದೇವಾತ್ಮ ಪ್ರೇರಿತ\nಶಾಸ್ತ್ರದಲ್ಲಿ\nಜೀವದ ನಾಯಕಾ!\nಅಡಗಿದ್ದೀ ;\nಅಲ್ಲೇನೂ ಕಾಣದ\nಕುರುಡನು\nನಿನ್ನನ್ನು ಈಕ್ಷಿಸ\nದೃಷ್ಟಿಕೊಡು\nನಿನ್ನನ್ನೆಲ್ಲೆಲ್ಲಿಯೂ\nಹುಡುಕುವೆ ;\nನನ್ನಾತ್ಮಹಾರವು\nನೀ ಮಾತ್ರವೇ ;\nಮೇಲಣ ಲೋಕದೊಳ್\nನಿನ್ನೊಂದಿಗೆ\nಶಾಶ್ವತಾನಂದದೊಳ್\nನಾನಿರುಮೆ\nವಿವಾಹ\nವಿವಾಹ" },
  162: { title: "ಆದಿಯಲ್ಲಿ ದೇವರು", lyrics: "1. ಆದಿಯಲ್ಲಿ ದೇವರು\nಸ್ತ್ರೀ ಪುರುಷರಿಬ್ಬರ\nಉಂಟು ಮಾಡಿ ಅವರ\nತಾನೇ ಒಂದು ಮಾಡಿದ.\n2. ದೈವ ಕಟ್ಲೇ ಮೇರೆಗೆ\nಈಗ ಆದ ಮದುವೆ\nಸೃಷಿಕ್ಕರ್ತನಿಂದಲೇ\nಆಶೀರ್ವಾದ ಹೊಂದುತ್ತೆ.\n3. ಪರಸ್ಪರ ಪ್ರೀತಿಯು\nಇಬ್ಬರಲ್ಲೂ ಹುಟ್ಟಿಸು !\nಜೀವದಂತ್ಯ ಮಟ್ಟಿಗೂ\nಐಕ್ಯದಲ್ಲಿ ಇರಿಸು.\n4. ಎಲ್ಲಾ ಕಾಲದಲ್ಲಿಯೂ\nಒಬ್ಬರನ್ನು ಒಬ್ಬರು\nಪ್ರೀತಿಯಿಂದ ಸೈರಿಸಿ,\nಜೀವನವ ಮಾಡಲಿ.\n5. ಶತ್ರುಗಳ ಬಾಣಕ್ಕೂ\nಪಾಪ ಕರ್ಮ ದೋಷಶ್ಕೂ\nಇವರನ್ನು ತಪ್ಪಿಸು,\nಪ್ರೀಶಿಯಿಂದ ಕಾಪಾಡು." },
  163: { title: "ಕಾನಾ ಊರಲ್ಲಿ ಇಬ್ಬರು", lyrics: "1. ಕಾನಾ ಊರಲ್ಲಿ ಇಬ್ಬರು\nವಿವಾಹವಾಗುತ್ತಿರಲು.\nಕ್ರಿಸತೆಸು ಅಲ್ಲಿ ಹೋದನು,\nತನ್ನಾಶೀರ್ವಾದ ಕೊಟ್ಟನು\n2. ಆದೇ ಪ್ರಕಾರ ನಮ್ಮನ್ನು\nಈ ಹೊತ್ತು ಅಶೀರ್ವದಿಸು ;\nಈಗಾಗುವಂಥ ಮದುವೆ\nಮಂಗಳ ಮಾಡು, ಕರ್ತನೇ ;\n3. ಸಭೆಯ ಮದಲಿಂಗನೇ!\nಅಲೈಸು ನಮ್ಮ ಪ್ರಾರ್ಥನೆ ;\nಇಲ್ಲಿ ಪ್ರಸನ್ನನಾಗಿರು\nನಿನ್ನ ಕಟಾಕ್ಷ ತೋರಿಸು\n4. ಒಂದೇ ಕಟ್ಟಾಗಿ ಇವರು\nಸದ್ರಾಗಿ ನಡೆದು,\nಒದ್ಟೊಬ್ಬರನ್ನು ಸ್ನೇಹಿಸಿ\nಸಂಕೋಷದಿಂದ ಬಾಳಲಿ.\n5. ಪ್ರಪಂಚೆ ಯುದ್ಧ ಮಾಡಲು\nಇವರ ಬಲಪಡಿಸು ;\nಜೀವಾಂತ್ಯಕಾಲ ಬರಲು\nವಿನ್ನ ಬಳೀಲಿ ಸೇರಿಸು\nಹೊಸ ವರುಷ" },
  164: { title: "ಬನ್ನಿಕೂಡ ಹಾಡುವ", lyrics: "1. ಬನ್ನಿಕೂಡ ಹಾಡುವ\nಪರ್ಷದಿಂದ ಗೀಶವ;\nಮೋಸ ನಷ್ಟ ಕಷ್ಟವು\nಎಷ್ಟು ಬಂದು ಇದ್ದರೂ,\nಜೀವದಿಂದ ಈಗಲು\nಕೊಸ ವರ್ಷ ಕಂಡೆವು ;\nಹಕ್ರವಿದ್ದು ಶಂದೆಯು\nಶಮನ್ನೆಲ್ಲ ಕಾಡನು,\nಒನ್ನಿ ಕೊಡ ಪಾಡುವ\nಕರ್ಷರಿಂದ ಗೀತಮ\nಹೊಸ ವರುಷ\n2. ಎಷ್ಟೋ ದ್ರೋಹ ತಾಳಿದ,\nಎಷ್ಟೋ ಪಾಪ ಮುಚ್ಚಿದ,\nನಮ್ಮ ಕಡೆಗಾತನು\nದೀರ್ಘ ಶಾಂತನಾದನು ;\nರಮ್ಯ ಸ್ಥಳದಲ್ಲಿಯೇ\nನಮ್ಮ ಭಾಗ ಬಿದ್ದದೆ,\nಹೌದು ನಮ್ಮ ಪಾತ್ರೆಯು\nತುಂಬಿ ಚೆಲ್ಲಿ ಹೋಯಿತು.\nಬನ್ನಿ ಕೂಡ ಹಾಡುವ\nಹರ್ಷದಿಂದ ಗೀತಮ\n3. ಹೊಸ ವರ್ಷ ಕೊಟ್ಟಂಥ\nಕೃಪೆಯುಳ್ಳ ದೇವರ,\nಹೊಸ ಆಶೀರ್ವಾದಮ,\nಈಗ ಬೇಡಿಕೊಳ್ಳುವಾ ;\nಆತಗುಂಟು ಎಂದಿಗೂ\nಅತ್ಯಧಿಕ ದಯವು ;\nಘನ ಮಾನ, ಕರ್ತನೇ,\nಹೊಂದ ಯೋಗ್ಯನು ನೀನೇ\nಬನ್ನಿ ಕೂಡ ಹಾಡುವ\nಹರ್ಷದಿಂದ ಗೀತಮ" },
  165: { title: "ಇನ್ಮೊಂದು ವರ್ಷವು", lyrics: "1. ಇನ್ಮೊಂದು ವರ್ಷವು\nಸಮಾಪ್ತವಾಯಿತು ;\nಈ ಮೇರೆ ನಮ್ಮ ಅಯಸ್ಸು\nಮುಗಿದು ಹೋಗ್ವದು.\n2. ಒಂದೊಂದು ವರ್ಷವು\nನಮ್ಮನ್ನು ದಾಟಲು,\nಪ್ರಾಣಾಂತ್ಯವಾಗ್ವ ಕಾಲವು\nಸಮೀಪವಾಗ್ವದು\nಮಕ್ಕಳ ಸಂಗೀತ\n3. ಶತ್ಕಾಲ ಮಾತ್ರವೇ\nಎನ್ ಸ್ವಂತವಾದದ್ದು\nಈ ಕಾಲ ನಷ್ಟವಾದರೆ\nನಾ ಹುಚ್ಚನಾದೆನು\n4. ಲಕ್ಷಾಂತ್ರ ಸಂಪತ್ತು\nಈಡಾಗಿ ಕೊಟ್ಟರೂ,\nಸಂಧ್ಹೋದ ಕಾಲ ಯಾರಿಗೂ\nಎಂದೆಂದೂ ಸಿಕ್ಕದು\n5. ತತ್ಕಾಲ ನನಗೆ\nಅಮೂಲ್ಯವಾದದ್ದು\nಸುಜೀವ ಹೊಂದ ಈಗಲೇ\nತಕ್ಕಂಥ ವೇಳೆಯು\n6. ಓ ದೇವರಾತ್ಮನೇ!\nಈ ದೊಡ್ಡ ನೆನಪು\nಎಲ್ಲರ ಆತ್ಮದೊಳಗೆ\nಬೇರೂರ ಮಾಡಿಸು.\nಮಕ್ಕಳ ಸಂಗೀತ" },
  166: { title: "ಹೌದು, ಹೌದು, ಮಿತ್ರನುಂಟು", lyrics: "1. ಹೌದು, ಹೌದು, ಮಿತ್ರನುಂಟು\nಆಕಾಶದಲ್ಲಿಯೇ ;\nಅತ್ಯಂತ ಪ್ರಿಯ ಮಿತ್ರ\nಸದ್ಬಾಲಕರಿಗೆ\n2. ಹೌದು, ಹೌದು, ಸುಖವುಂಟು\nಆಕಾಶದಲ್ಲಿಯೇ ;\nನಿರಂತ್ರವಾದಾನಂದ\nಸದ್ಬಾೀಕರಿಗೆ\n3. ಹೌದು, ಹೌದು, ಮನೆಯುಂಟು\nಆಕಾಶದಲ್ಲಿಯೇ ;\nಉತ್ತಮ ವಾಸಸ್ಥಳ\nಸದ್ಬಾಲಕರಿಗೆ\n4. ಹೌದು, ಹೌದು, ಘನ ಉಂಟು\nಆಕಾಶದಲ್ಲಿಯೇ ;\nಮಹತ್ವದ ಕಿರೀಟ\nಸದ್ಬಾಲಕರಿಗೆ\n5. ನಾ ಯೇಸು ಸ್ವಾಮಿಯನ್ನು\nವಶ್ವಾಸಿದರೆ!\nಆ ಶ್ರೇಷ್ಠ ಲೊಣದಲ್ಲಿ\nಕಡೇಲಿ ಸೇರುಮೆ" },
  167: { title: "ನಿನ್ನ ಮಾರ್ಗ, ಕರ್ತನೆ,", lyrics: "1. ನಿನ್ನ ಮಾರ್ಗ, ಕರ್ತನೆ,\nತೋರಿಸೆನ್ನ ಆ್ಕ್ಕೆ:\nಭಕ್ತಿ ಶಾಂತಿ ತಾಳಿಮೆ\nನನ್ನಲ್ಲಿರಿಸ್ಯ ಸುವೆ\n2. ನಾನು ಕೂಸು, ಆದರೂ\nನಿನ್ನ ಸ್ನೇಹಿಸುವೆನು ;\nಜೀವ ವಾಕ್ಯದಿಂದಲೇ\nನನ್ನ ಪೋಷಿಸ್ಯೇಕುವೇ\n3. ನನ್ನಶಕ್ತಿ ಸ್ವಲ್ದೇ,\nತ್ರಾಣ ಕೊಡು, ಕರ್ಶನೇ!\nನಾನು ಜಾರದಂತೆಯೇ\nನನ್ನ ಕಾಯಿ, ಯಸುವೇ!\n4. ನಾನು ಬುದ್ಧಿಹೀವನು\nನೀಮ ಪೂರ್ಣ ಜ್ಞಾನಿಯು!\nಸತ್ಯ ಮಾತು ಯೋಚನೆ\nನಿಷೇ ಹುಟ್ಟ್ಯೇಸುವೇ!\n5. ನನ್ನ ಆತ್ಮ ಶತ್ರುವು\nತನ್ನ ಬಲೆ ಒಡ್ಡಲು\nಹತ್ರವಿದ್ದು ಬೇಗನೇ\nತಪ್ಪಿೆನ್ನ ಯೇಸುವೇ!\n6. ಧಕ್ತಿ ಮಾರ್ಗ ಬಿಡದೆ,\nವಿನ್ನ್ನಾತಕೊಳ್ಳುವೆ\nಮೊಕ್ಷ ರಾಜ್ಕದೊಳಗೆ\nನನ್ನ ಸೇರಿಸ್ಕೇಉುವೇ!\nದಿಮ್ಯವಾದ ಕರ್ತನೇ\nನನ್ನ ದೀವ ಪ್ರಾರ್ಥನೆ\nದಯಮಾಡಿ ತೆಳ್ಳದೆ\nಕೇಳು ಪ್ರಿಯ ಯೇಸುವೇ!" },
  168: { title: "ಕುರ್ಬನಂತೆ ಮುಂದೆ ಹೋಗು,", lyrics: "1. ಕುರ್ಬನಂತೆ ಮುಂದೆ ಹೋಗು,\nನಮ್ಮ ಿವ್ಯ ಕರ್ತನೇ\nನಿನ್ನ ಮಂದೆಯನ್ನು ಮೇಯ್ಸು\nರಮ್ಯ ಹೊಲದಲ್ಲಿಯೇ\nಪ್ರಿಯ ಯೆಸು,\nಪ್ರಿಯ ಯೆಸು,\nನಾವು ನಿನ್ನ ಮಂದೆಯೇ\nಮಕ್ಕಳ ಸಂಗೀತ\n2. ಮಂದೆಯನ್ನು ಪ್ರೀತಿಯಿಂದ\nಮಾರ್ಗದಲ್ಲಿ ನಡಿಸು:\nತಪ್ಪಿಷೋದ ಕುರಿಯನ್ನ\nಕರುಣಿಸಿ, ಹುಡುಕು\nಪ್ರಿಯ ಯೇಸು,\nಪ್ರಿಯ ಯಸು,\nಕೇಳು, ಕೇಳು, ನಮ್ಮನ್ನು\n3. ನಾವು ಪಾಪ ಮಾಡಿದ್ದಾಗ್ಯೂ\n“ಬನ್ನಿ ನಾನು ತಥ್ಳೆಮ ;\nನಿರ್ಮಲತ್ವ ಕೊಡುತ್ತೇನೆ”\nಎಂದು ನೀನು ಹೇಳಿದೆ;\nಪ್ರಿಯ ಯೇಸು,\nಪ್ರಿಯ ಯೇಸು,\nಬರುತ್ತೇವೆ ಈಗಲೇ.\n4. ಬಾಲ್ಯದಲ್ಲಿ ನಿನ್ನ ದಯ\nನಮ್ಮ ಮೇಲೆ ಇರಲಿ ;\nನಿನ್ನ ದಿವ್ಯವಾದ ಪ್ರೀತಿ\nಎದೆಯನ್ನು ತುಂಬಲಿ\nಪ್ರಿಯ ಯೇಸು,\nಪ್ರೀತಿ ಮಾಡು,\nಹಿಂದೆ ಪ್ರೀತಿ ಮಾಡಿದ್ದೀ" },
  169: { title: "ಯೇಸು ಲೊಕದಲ್ಲಿ", lyrics: "1. ಯೇಸು ಲೊಕದಲ್ಲಿ\nಇರುವಾಗಲು,\nಎಳೇ ಮಕ್ಕಳನ್ನು\nಹರಿಸಿದನು ;\nಪರದಲ್ಲಿ ಕೂಡ\nಪ್ರೀತಿಯಿಂದಲು\nಮಕ್ಕಳನ್ನು ಆತ\nಸ್ನೇಹಿಸುವನು\nಸುವಾರ್ತಾ ಸೇವೆಗಾಗಿ\nಮಕ್ಕಳು ಅತನ್ನ\nಬೇಡಿಕೊಳ್ಳಲು\nಅತ ಪ್ರೀತಿಯಿಂದ\nರಕ್ಷಿಸುವನು ;\nತನ ಕೈಗಳಲ್ಲಿ\nಎತ್ತಿಕೊಳ್ವನು\nತನ್ನ ಎದೆಯಲ್ಲಿ\nಅಪ್ಟಿಕೊಳ್ವನು\n3. ಭೂಪ್ರಯಾಣದಲ್ಲಿ\nನಡಿಸುವನು,\nಸ್ವರ್ಗಾನಂದದಲ್ಲಿ\nಸೇರಿಸುವನು ;\nಜೀವಜಲವನ್ನು\nಕುಡಿಸುವನು\nಎಲ್ಲಾ ದುಚಿವನ್ನು\nಹಾರಿಸುವನು.\n4. ನನಗಾಗಿ ಸತ್ತು\nಎದ್ದ ಕರ್ತನೇ!\nನಿನ್ನ ನಾಮಕ್ಕೆಂದೂ\nಸ್ತೋತ್ರ ಮಾಡುವೆ,\nಜೀವಕಾಲದಲ್ಲಿ\nಆಶೀರ್ವದಿಸು ;\nಸಾವು ಬರುವಲ್ಲಿ\nಸ್ವರ್ಗಕ್ಕೇರಿಸು." },
  170: { title: "ಯೇಸುವಿನ ಪ್ರೀತಿಯು", lyrics: "1. ಯೇಸುವಿನ ಪ್ರೀತಿಯು\nಉಂಟು ನನ್ನ ಮೇಲೆಯೂ ;\nಮಕ್ಕಳನ್ನು ಆತನು ಅಂಗೀಕರಿಸುವನು,\nಹೌದೌದು ನಿಜ,\nಸದ್ವೇದ ಮಾತಿದು.\n2. ಪ್ರೀತಿಯಿಂದ ಶಿಲುಬೆ\nಯೇಸು ತಾಳ್ಡನಲ್ಲವೆ ?\nನನ್ನ ಪಾಪ ಅತನು\nಪರಿಹರಿಸುವನು,\nಸದ್ವೇದ ಮಾತಿದು\n3. ಆತನನ್ನು ನಾ ಸಹ\nಸ್ನೇಹಿಸುವೆನು ಸದಾ ;\nಯೇಸು ಆಗ ನನ್ನನ್ನು\nಸ್ವರ್ಗಕ್ಕೇರಸುವನು\nಸದ್ವೇದ ಮಾತಿದು." },
  171: { title: "ಹೌದೌದು ಸಿಕ್ಕಿತು", lyrics: "1. ಹೌದೌದು ಸಿಕ್ಕಿತು\nಸುದೇಶವು ;\nಸೌಭಾಗ್ಯ ಜನರು\nಅಲ್ಲವರು ;\n“ರಕ್ಷಕ ಯೇಸುವು\nಸ್ತೋತ್ರಹೊಂದ ಯೋಗ್ಯನು”\nಎಂತಂದು ಹಾಡ್ವರು\nಎಂದೆಂದಿಗೂ\n2. ಆ ಒಳ್ಳೇದೇಶಕ್ಕೆ\nಬರುತ್ತೀಯಾ ?\nತಡವು ಏತಕ್ಕೆ?\nಈ ಹೊತ್ತೇ ಬಾ!\nಓ ಎಷ್ಟೋ ಭಾಗ್ಕವು\nಅನುಭವಿಸುವೆವು ;\nಕಣ್ಣೀರು ಇಲ್ಲವು\nಎಂದೆಂದಿಗೂ.\nಸುವಾರ್ತಾ ಸೇವೆಗಾಗಿ\n3. ಆ ಭಾಗ್ಯ ದೇಶದೊಳ್\nಅನಂದವೇ,\nತಂದೆಯ ಹತ್ರದೊಳ್\nಸೌಭಾಗ್ಯವೇ ;\nವೈಭವ ಲೋಕಕ್ಕೆ\nರಾಜ ಮುಡಿಗಾಗಿಯೇ\nಮುಂದೋಡು ಬೇಗನೇ\nಬಾಳೆಂದಿಗೂ." },
  172: { title: "ಹೌದುಂಟು ಒಳ್ಳೇ ದೇಶವು", lyrics: "1. ಹೌದುಂಟು ಒಳ್ಳೇ ದೇಶವು\nಮೇಲೆಯೇ ಮೇಲೆಯೇ ;\nಉಪದ್ರ ಎಂದೂ ಇಲ್ಲದ್ದು;\nಸುಖವೇ! ಸುಖವೇ!\nಅಲ್ಲೆಲ್ಲಾ ಜನ ಯೋಗ್ಯರು,\nಅಲ್ಲೆಲ್ಲಾ ಮಾತು ಪ್ರೀತಿಯು,\nಅಲ್ಲೆಲ್ಲಾ ಕ್ರಿಯೆ ಶುದ್ಧವು ;\nಸುಖವೇ! ಸುಖವೇ!\n2. ಕಣ್ಣೀರು ಅಲ್ಲಿ ಇಲ್ಲವು ;\nಸುಖವೇ! ಸುಖವೇ!\nಓಿಶಾಚ ಹತ್ರ ಸೇರನು\nಸುಖವೇ! ಸುಖವೇ!\nಆ ದೇಶದ ನಿವಾಸಿಯು\nಎಂದೆಂದೂ ಭಾಗ್ಯವಂತನು,\nಅಮೃಶ ಪಾನವಾಯಿತು,\nನಿತ್ಯವೇ! ನಿತ್ಯವೇ !\n3. ನಾವೆಲ್ಲಾ ಶಾಪಗ್ರಸ್ತರು,\nನಿಜವೇ, ನಿಜವೇ ;\nಟ್ತಸು ರಕ್ಿದನು,\nಮಕ್ಕಳ ಸಂಗೀತ\nಪ್ರೀತಿಯೇ ಪ್ರೀತಿಯೇ;\nಈ ದಿವ್ಯ ಯಜ್ಞಪಶುವು\nಸಮಸ್ತ ಪಾಪ ತೊಳೆದು,\nಮೇಲ್ಲೋಕಕ್ಕೇರಿಸುವನು ;\nಭಾಗ್ಯವೆ! ಭಾಗ್ಯವೇ!" },
  173: { title: "ಪ್ರಿಯರಾದ ಮಕ್ಕಳೇ!", lyrics: "1. ಪ್ರಿಯರಾದ ಮಕ್ಕಳೇ!\nನಮ್ಮ ಕೂಡ ಬನ್ನಿರಿ,\nಕಾಂತಿಯುಳ್ಳ ಲೋಕಕ್ಕೆ\nಬ್ನಾ! ಬ್ನ!\nಹರ್ಷ ! ಹಲ್ಲೆಲೂಯ ॥\nಸ್ತುತಸಿರಿ.\n2. ತಂದೆಯಾದ ದೇವರ\nಅಲ್ಲಿ ದೃಷ್ಟಿಸುವೆವು;\nಕಾಂತಿಯುಳ್ಳ ಲೋಕಕ್ಕೆ\nಬನ್ನಿ! ಬನ್ನಿ!\nಹರ್ಷ ! ಹಲ್ಲೆಲೂಯ ॥\nಸ್ತುತಿಸಿರಿ.\n3. ಯೇಸು ನಮ್ಮ ರಕ್ಷಕ\nಅಲ್ಲಿ ತೋರಿ ಬರುವ;\nಕಾಂತಿಯುಳ್ಳ ಲೋಕಕ್ಕೆ\nಬನ್ನಿ! ಬನ್ನಿ!\nಸ್ತುತಿಸಿರಿ.\n4. ಜೀವದ ಕಿರೀಟವು\nಸಿಕ್ಕುತ್ತದೆ ಆಗಲೂ ;\nಕಾಂತಿಯುಳ್ಳ ಲೋಕಕ್ಕೆ\nಬನ್ನಿ! ಬ್ನಿ!\nಹರ್ಷ ! ಹಲ್ಲೆಲೂಯ ॥\nಸ್ತುತಿಸಿರಿ.\nವಿವಿಧ ಸಂಗೀತಗಳು\n5. ಅತ್ಯಾನಂದ ಎಂದಿಗೂ\nಅನುಭವಿಸುವೆವು ;\nಕಾಂತಿಯುಳ್ಳ ಲೋಣಕ್ಕೆ\nಬ್ನೂ! ಬ್ನಿ!\nಹರ್ಷ ! ಹಲ್ಲೆಲೂಯ ॥\nಸ್ತುಶಗಿ\n6. ನಾವು ನಿಮ್ಮ ಸಂಗಡ\nಬರುತ್ತೇವೆ ಈಗಲೇ ;\nಕಾಂತಿಯುಳ್ಳ ಲೋಕಕ್ಕೆ\nಬರುವೆವು.\nಹರ್ಷ ! ಹಲ್ಲೆಲೂಯ ॥\nಸ್ತುತಿಸಿರಿ." },
  174: { title: "ಇಹದಲ್ಲಿ ನಮಗೆ", lyrics: "1. ಇಹದಲ್ಲಿ ನಮಗೆ\nಬಾಧೆ ದುಖು ಕಷ್ಟವೇ,\nವಿಶ್ರಾಂತಿ ಎಲ್ಲಿದೆ ?\nಪಲ್ಲವಿ\nಎಷ್ಟೋ ಸಂತೋಷ\nಎಷ್ಟೋ ಸಂತೋಷ\nಎಷ್ಟೋ ಸಂತೋಷ\nಸ್ವರ್ಗದಲ್ಲಿ ಆಗುತ್ತೆ !\n2. ಸದ್ಭಕ್ತರು ಮಾತ್ರವೇ\nಭಾಗ್ಯವುಳ್ಳ ಲೋಕಕ್ಕೆ\nಸೇರೋಣವಾಗುತ್ತೆ.\n3. ಬಾಲ್ಯನಾದ ನನಗೆ\nದೇವಭಕ್ತಿ ಇದ್ದರೆ\nಆ ಸ್ಥಳ ಸೇರುಮೆ\n4. ಪನ್ನ ಪ್ರಿಯ ಯೇಸುವು\nನನ್ನ ಕಣ್ಣಿಗೆಂದಿಗೂ\nಪ್ರ್ಯಕ್ಷಿಾಗ್ನನು\n5. ಅಲ್ಲಿ ದೇವ ಮಹಿಮೆ\nದೃಶ್ಯವಾಗಿ, ನನಗೆ\nಯಾವಾಗ್ಯೂ ಭಾಗ್ಯವೇಲ" },
  175: { title: "ಧೂಪರಲೋಕ ದೇವರೇ!", lyrics: "1. ಧೂಪರಲೋಕ ದೇವರೇ!\nಸಮಸ್ತ ಕೊಡುವಾತನೇ !\nಅನಂತ ಸ್ತೋತ್ರ ನಿನಗೆ\nದಯಾಪ್ರನೇ!\n2. ನಿನ್ನಿಂದ ಸೂರ್ಯ ಶಪ್ಪದೆ\nಸದಾ ಉದಯವಾಗುತ್ತೆ ;\nಅನಂತ ಸ್ತೋತ್ರ ನಿನಗೆ\nದಯಾಪ್ರನೇ!\n3. ಭೂಫಲವನ್ನು ಹುಟ್ಟಿಸಿ\nಎಲ್ಲರ ಜೀವ ಕಾಯುತ್ತೀ ;\nಅನಂತ ಸ್ತೋತ್ರ ನಿನಗೆ\nದಯಾಪ್ರನೇ !\n4. ಸಂಸಾರ ಕ್ಷೇಮ, ಬಾಳಿಗೆ,\nನಿನ್ನಾಶೀರ್ಮಾದದಿಂದಲೇ ;\nಅನಂತ ಸ್ತೋತ್ರ ವಿನಗೆ\nದಯಾಪ್ರನೇ !\n5. ಈ ಲೋಕದ ರಕ್ಷಣೆಗೆ\nಸ್ವಪುತ್ರನನ್ನು ಕೊಟ್ಟಿದ್ದೀ ;\nಅನಂತ ಸ್ತೋತ್ರ ನಿನಗೆ,\nದಯಾಪ್ರನೇ!\n6. ನೀ ಕೊಟ್ಟ ಶುದ್ಧ ವೇದವೇ\nನನ್ನಾತ್ಮಕ್ಕೆ ಆದರಣೆ !\nಅನಂತ ಸ್ತೋತ್ರ ನಿನಗೆ,\nದಯಾಪ್ರನೇ!\n7. ಮೇಲಣ ಲೋಕ ಬಾಧ್ಯತೆ\nಕೊಡುತ್ತೇನೆಂದು ಹೇಳಿದ್ದೀ ;\nಅನಂತ ಸ್ತೋತ್ರ ನಿನಗೆ\nದಯಾಪ್ರನೇ !\n8. ನನ್ನನ್ನು ನಿನ್ನ ಸೇವೆಗೆ\nಸಂತೋಷದಿಂದ ಒಪ್ಪಿಸಿ,\nನಿನ್ನನ್ನು ಮಾತ್ರ ನಂಬುವೆ,\nದಯಾಪ್ರನೇ!" },
  176: { title: "ಕತ್ತಲ್ಲಿ ದೀಪ ಉರಿಯುತ್ತದೆ", lyrics: "1. ಕತ್ತಲ್ಲಿ ದೀಪ ಉರಿಯುತ್ತದೆ\nಹಾಗೆ ಸುಗುಣದಿ, ಪ್ರಿಯ ಮಗುವೇ\nಬೆಳಕಿನ ಹಾಗೆ ಗುಣ ತೋರಿಸು ;\nಇದೇ ಯಸು ಸ್ವಾಮಿ ಕೊಟ್ಟ\nಅಜ್ಞೆಯು.\nನಮ್ಮ ಸುತ್ತು ಮುತ್ತು ಎಷ್ಟು ಪಾಪವು\nಎಲ್ಲಾ ಜನರಲ್ಲಿ ನಡಿಯುವದು ;\nನಾವು ಶುದ್ಧರಾಗಿ ಕಾಂತಿ ಕೊಡುವ,\nಕರ್ತನಾದ ಯೇಸು ಮೆಚ್ಚಿಕೊಳ್ಳುಮ\nಮಕ್ಕಳ ಸಂಗೀತ\n3. ಆತ್ಮದಲ್ಲಿ ದೀನ ಗುಣವಿದ್ದರೆ\nಒಳ್ಳೇ ಮಾತು, ಕ್ರಿಯೆ ಸದಾ ಬರಸ್ತ\nಹೀಗೆ ನಮ್ಮ ದೀಪ ಕತ್ತಲಲ್ಲಿಯು\nಒಳ್ಳೇ ಬೆಳಕನ್ನು ಸದಾ ಕೊಡ್ವನು" },
  177: { title: "ಹೃದಯವನ್ನು ಮಗನೇಕ್ಕೆ", lyrics: "1. ಹೃದಯವನ್ನು ಮಗನೇಕ್ಕೆ\nನನಗೆ ಒಪ್ಪಿಸು;\nಪರಮ ತಂದೆ ಹೀಗೆಯೇ\nಆಜ್ಞಾಿಸಿದನು.\nಪಲ್ಲವಿ\nಓ ಬನ್ನಿ! ಬನ್ನಿ! ಮಕ್ಕಳೇ\nಯೆಷು ಸ್ವಾಮಿ ಹತ್ರ ಬನ್ನಿ\nನೀವು ಬಂದರೆ ನಿಮ್ಮ ಹೃದಯ\nಪೂರ್ಣ ಶುದ್ಧವಾಗುತ್ತೆ.\nಅಕ್ರಮದಲ್ಲಿ ಹುಟ್ಟಿದ್ದೀ\nಅಶುದ್ಧ ಪಾಪಿಯೇ!\nನಾ ಸರ್ವಶಕ್ತನಾಗಿಯೂ\nಶುದ್ಧತ್ವ ಕೊಡುವೆ.\nನೀ ದೂರದಲ್ಲಿ ಹೋದರೂ\nನಾ ಎಂದೂ ಬಿಡೆನು ;\nನಿನ್ ಶಂದೆಗಿಂತ ಪ್ರೇಮದಿ\nಸಂರಕ್ಷಿಸುವೆನು.\nವಿವಿಧ ಸಂಗೀತಗಳು" },
  178: { title: "ನಾ ಚೀಯೋನ್ ಬೆಟ್ಟವನ್ನೇರುತ್ತೇನೆ", lyrics: "1. ನಾ ಚೀಯೋನ್ ಬೆಟ್ಟವನ್ನೇರುತ್ತೇನೆ\nಒಂದಿಗೆ ಯೇಸು ಇದ್ದಾನೆ ;\nಆನಂದ ಮನೆಗೆ ಸೇರುತ್ತೇನೆ ;\nಒಂದಿಗೆ ಯೇಸು ಇದ್ದಾನ.\nಪಲ್ಲವಿ\nಯೇಸು, ಯಸು,\nಎನ್ನೊಂದಿಗೆ ಯಸು ಇದ್ದಾನೆ ;\nಯೇಸು, ಯಸು, ಎನ್ನೊಂದಿಗೆ\nಯೇಸು ಇದ್ದಾನೆ ;\n2. ಈ ಪಯಣದಲ್ಲಿ ಎಷ್ಟೋ ಸಂತೋಷ\nಒಂದಿಗೆ ಯೇಸು ಇದ್ದಾನೆ ;\nನನ್ನಾತ್ಮ ಧ್ವನಿಯ ಕೇಳುವವ ;\nಒಂದಿಗೆ ಯೇಸು ಇದ್ದಾನೆ.\n3. ಈ ಪಯಣ ತೊಂದರೆ ಬಂದರೇನು.\nಒಂದಿಗೆ ಯೇಸು ಇದ್ದಾನೆ ;\nನಾನೆಲ್ಲಾ ಹಿಂಸೆಯ ತಾಳುವೆನು ;\nಒಂದಿಗೆ ಯೇಸು ಇದ್ದಾನೆ\n4. ಆ ಚೀಯೋನ್ ಜನರು ಹಾಡುತ್ತಾರೆ.\nಒಂದಿಗೆ ಯೇಸು ಇದ್ದಾನೆ ;\nಸಂಪೂರ್ಣ ಜಯವ ಹೊಂದುತ್ತಾರೆ ;\nಒಂದಿಗೆ ಯೇಸು ಇದ್ದಾನೆ.\n5. ಈ ಪಯಣ ಅಂತ್ಯವ ಬಯ್ಸುತ್ತೇನೆ,\nಒಂದಿಗೆ ಯೇಸು ಇದ್ದಾನೆ.\nನಿರಂತ್ರ ಮನೆಯಲ್ಲಿರುತ್ತೇನೆ ;\nಒಂದಿಗೆ ಯೇಸು ಇದ್ದಾನೆ." },
  179: { title: "ಆ ಮಗುವನ್ನು ನೋಡಿರಿ", lyrics: "1. ಆ ಮಗುವನ್ನು ನೋಡಿರಿ\nಗೋದಲಿಯಲ್ಲಿ ಮಲಗಿ\nಸಮಸ್ತ ಲೋಕದೊಡೆಯ\nಅಲ್ಲವತಾರ ಮಾಡಿದ.\n2. ಓ ಘನರಾಜಾ! ವಂದನೆ,\nನೀ ಬಂದೀ ಪಾಪಿಗೋಸ್ಕರವೇ\nಇಷ್ಟಾಗಿ ತಗ್ಗಿಸಿಕೊಂಡದ್ದು\nಎಷ್ಟೋ ಹೆಚ್ಚಾದ ದಯವು.\n3. ಓ ಸರ್ವ ಲೋಕದೊಡೆಯಾ !\nಏನಾದಿ ನನಗೋಸ್ಕರ ?\nಆಕಾಶ ಸ್ಥಾನವಗಲಿ,\nದೀನತ್ವದಲ್ಲಿ ಸೇರಿದಿ.\n4. ಈ ಲೊಕವೆಲ್ಲಾ ರತ್ನದ್ದು\nಬಂಗಾರದಿಂ ತುಂಬಿದ್ದರೂ,\nಓ ಯೆಸು ನಿನಗೆಂದಿಗೂ\nತಕ್ಕಂಥ ದಾನವಾಗದು.\n5. ನನ್ನಾಪ್ತ ಪ್ರಿಯ ಕರ್ತನೇ;\nನಿವಾಸ ಮಾಡೆನ್ನೊಳಗೆ,\nನಿನ್ನನ್ನು ಯುಗಯುಗಕ್ಕೂ\nಕೊಂಡಾಡಿ ಹರ್ಷಿಸುವೆನು." },
  180: { title: "ಸಹೋದ್ರರೇ! ಎಲ್ಲರೂ ಹರ್ಷಿಸಿ,", lyrics: "1. ಸಹೋದ್ರರೇ! ಎಲ್ಲರೂ ಹರ್ಷಿಸಿ,\nಮಹಾ ಸಂಶೋಷದಿಂದ ಹಾಡಿರಿ!\nಆ ದಿನದಲ್ಲಿ ಜೀವ ಪ್ರಧುವು\nಪ್ರಪಂಚೋದ್ಧಾರಕ್ಕಾಗಿ ಬಂದನು;\nಈ ಮರ್ಮವನ್ನು ಸ್ವರ್ಗದವರು\nಅನಂದಪಟ್ಟು ಸಾರುಕ್ತಿದ್ದರು.\n2 “ಮಹೋನ್ಾಳಲ್ಲಿ ಸ್ತೋಕ್ರವು\nದೋಲಂಕದಲ್ಲಿ ಸಮಾಧಾವು\nದಾವೀದ ಪ್ದೊಳು ಆಕ್ಕ\nರೈವಾನು್ರಹರಿಂದ ಶುಟ್ಟರ್\nಹಿಗೆಯ ಪಲಿಕ ಸೈಷ್ವ\nಗಂಧೀರ ರಾಗೆ ಎತ್ತಿಕೊಂಡದ\nಈ ಅತಿಸಯವಾದ ಜೀನ\nಷ\nಮಾವಾಗ್ಕೂ ಜ್ತಶ್ತಿಮಾಡಿಕೊಳ್ಳುವ\nಆಂಭದಿಯದ ಕಡೇ ತಸ\nಕ್ರಿ್ತಸುವಿನ ಶ್ರಮ ನೋಡಾವ\nಎಷ್ನೋ ಪ್ರಯಾಸ ಪ್ರಣ ಸೇಶೆಟ\nನಮ್ಮ ನಿಮಿತ್ತೆಮಗಿ ಹಳಿದ\nಅಸ್ತರ್ಮವದ ಪ್ರೀತಿ ಧ್ಯಾನಿಸಿ\nವಿಮೋಚನ ಪೆಜ್ಜೆ ಪತ್ತಿರಿ;\nಕಡೇಲಿ ಮೊಕ್ಷ ರಜ್ಯದೊಳಗೆ\nಸಮಸ್ತ ರೂತ ಸೈನ್ಯದೊಳಗೆ\nನಷ್ಟಗ ಬಿದ್ದು ಹಡಿ ಅನ್ಮ\n“ನರತ್ರ ದಾಳು ದಿದ್ೈ ರಕ್ಷೆ!\"\n1 ಚಿಕ್ಕವರಾದ ನಮಗೆ\nದಯವ ಮೂಡು ಯೆಗುವೇ,\nನಂತಸವಾದ ಮನ್ನು\nಉಂಪಗೆ ಮೂಡಿ ರಕ್ಷಿನು\n2 ಚಕ್ಕವರೆಲ್ಲಾ ಬರಲಿ,\nನನ್ನಾನೀರ್ವಾದ ಕೊಂದರಿ ;\nನೀನು ಪೇಳಿದ ಹಾಗೆಯೇ\nಬಂದು ಇದ್ದೇವೆ, ಕರ್ತನೇ!\nನಮ್ಮೊಳು ಬುದ್ಧಿ ಸ್ವಲವೇ,\nಮಮೊಳು ಗುಣ ಕ್ಪದ್ದೇ;\nಆದಾಗ್ಯೂ ನಿನ್ನ ಪ್ರೀತಿಯ\nಎಷ್ಟೋ ವಿಸ್ತಾಂವಾದದ್ದು\nಪಾಪವನ್ನೆಲ್ಲಾ ಮಸ್ನಿಸನು,\nಮಮ್ಮನ್ನ ಅಶಿರ್ವರಿಸು;\nಪಿಶಾಚಜನಿಂದ ತಪ್ಪಿನ್ು,\nವಿಸ್ನ ರಾಜ್ಯಕ್ಕೆ ನೇಲಸು" },
  181: { title: "ಕೇಳು ದೂತರ್ಗಾನಮ,", lyrics: "1. ಕೇಳು ದೂತರ್ಗಾನಮ,\nಫನರಾಜ ಹುಟ್ಟಿದ\n“ಸ್ನರ್ಗದಲ್ಲಿ ಮಹಿಮೆ,”\n“ಭೂಮಿಯಲ್ಲಿ ಕರುಣ್ಷೆ”\nಎಲ್ಲಾಜನ ನಂಬಲ,\nದೂರಕಡ ಹಾಡಲಿ,\nಬೇಶ್ತಿಪೇಮಿಸೊಳಗೆ\nಪರಂಜ್ಯೋತಿ ಕೋರಿದೆ,\nಕೇಳು ದೂತರ್ಣಗಾನಮ\nಘನ ರಾಜ ಹುಟ್ಟಿದ\n2. ಆಗ ಹುಟ್ಟಿದಾತನು\nಪರಲೋಣದರಸು;\nಮೇಲೆಿನಿಂದ ಇಳಿದು\nಪರನಾಗಿ ಬಂದನು ;\nಪ್ರೀತಿಯಿಂದ ಶನ್ನಮ್ಮ\nದೀಪ ಮಾಡಿಕೊಂಡನು ;\nದೇವರ ಕುಮಾರನು\nಇಲ್ಲಿ ವಾಸಸಿದಮ,\nಕೇಳು ದೂಶರ್ಗಾಸಮ,\nಘನ ರಾಜ ಹುಟ್ಟಿದು\nವಿವಿಧ ಸಂೀತಾಗಳು\nಓ ಮಹತ್ಯರರಾ!\nರರ್ವಲೊಣ ರಕ್ಷಕಾ!\nಸಮಾಧಾನ ಗುರುವೇ\nನೀತಿ ಸೂರ್ಯ ಕ್ರಿಸ್ತನೇ!\nಮನಪ್ಕಾಂಕಿ ಹುಟ್ಟಸ\nಮೊಣ್ನಾನಂದ ತಂದಿದ್ದೀ\nನಮಸ್ಕಾರ ಯೇಸುವೆ!\nನಿಶ್ಕ ಮಾನ ವಿಷಣೆ\nಕೇಳು ದೂತರ್ನಾಸಮ\nಫನ ರಾಜ ಹೆಟ್ಟಿದ" },
  182: { title: "ಯೇನು ಪಾಪಿಗಳನ್ನು", lyrics: "1. ಯೇನು ಪಾಪಿಗಳನ್ನು\nಪಾಪರೊಳಗಿಂದಲು\nಈಗ ಜಿಡಿಯುವನು,\nನಿಜವಾಗಿ ಹೇಳಿದ್ದು\nಹಾಡಿ ಪಾಡಿ ಮನವೇ\nಹಾಡಿ ಪಾಡಿ, ಎಲ್ಲರೇ\nಯೇಸು ಪಾಪಿಗಳನ್ನು\nಈಗ ಕ್ಷಮಿಸುವನು\n2. ಪಾಪ ಕಂಡು, ಅರಿಕೆ\nಮಾಡುವಂಥ ಪಾಪಿಗೆ\nಯೇಸುವನ್ನಂಜಿದರೆ\nಪರಿಹಾರವಾಗುತ್ತೆ.\n3. ಪಾಪಕ್ಕಾಗಿ ದುಱುವೇ\nಸಾಲದು ಓ ಪಾಪಿಯೇ\nರಕ್ಷಕನ ಮೇಲಿಯೇ\nಇಡಬೇಕು ನಂಜಿಕೆ" },
  183: { title: "ಒಕ್ಟೇ ಸುದ್ದಿ ಕೇಳಿದೆ", lyrics: "1. ಒಕ್ಟೇ ಸುದ್ದಿ ಕೇಳಿದೆ\nತ್ಷಣೆ ಸದ್ಧಿಯೇ\nಸರ್ವತ್ರ ಈ ಸುದ್ಧಿಯೇ\nಕಬ್ೆ ುಟಸ್ತೆ\nಜನೆಲ್ಲಾ ಕೇಳಲಿ,\nಯೇಸುವನ್ನು ನಂಬಲಿ,\nಯೇಸುವಿಸ ನಮಕ್ಕೆ\nಭನವು ಆಗಲಿ.\n2 ಎಲ್ಲಾದೇಶಗಳಿಗೂ\nಕೋಿ, ಕೋ್ರ\nಸರ್ವ ಪಾಷಿಗಳಿಗೂ\nಹೇಳಿರಿ, ಹೇಳಿರಿ,\nಯೆದು ರ್ಞಷಿಸುವನು\nಪಾಪ ಕ್ಷಮಿಸುವನು\nಯೇಸುವಿನ ಅಪ್ಪಣೆ\nಬೇಗಪ ಸಾರಿರಿ.\n3. ದಿವ್ಯ ಸಮಾಜಾರವ\nಹಾಡಿರಿ, ಪಾಡಿರಿ\nಯೆದು ಪಾ೭ಗಳಿಗೆ\nಸ್ತನು, ಎದ್ಧಮ,\nಜೀವಮಾನದಲ್ಲಿಯೂ\nಎಲ್ಲಾ ಸ್ಮಳದಲ್ಲಿಯೂ\nಸರ್ವ ಜಶರಲ್ಲಿಯೂ\nಪ್ರೇಮರಿಂ ಹಾಡಿರಿ.\n2. “ಮಹೋನ್ನತಗಳಲ್ಲಿ ಸ್ತೋತ್ರವು\nಭೂಲೋಕದಲ್ಲಿ ಸಮಾಧಾನವು.\nದಾವೀದ ಪಟ್ಣದೊಳು ರಕ್ಷಕ\nದೈವಾನುಗ್ರಹದಿಂದ ಹುಟ್ಟಿದ’\nಹೀಗೆಂದು ಪರಲೋ ಸೈನ್ಕವು\nಗಂಭೀರ ರಾಗ ಎತ್ತಿಕೊಂಡರು.\n3. ಈ ಅತಿಶಯವಾದ ಜನನ\nಯಾವಾಗ್ಕೂ ಜ್ಲಪ್ತಿಮಾಡಿಕೊಳ್ಳುವ\nಆರಂಭದಿಂದ ಕಡೇ ತನಕ\nಕ್ರಿಸ್ತೇಸುವಿನ ಶ್ರಮ ನೋಡುವ\nಎಷ್ಟೋ ಪ್ರಯಾಸ ಪ್ರಾಣ ಸಂಕಟ\nನಮ್ಮ ನಿಮಿತ್ತವಾಗಿ ತಾಳಿದು\n4. ಅಶ್ಚರ್ಯವಾದ ಪ್ರೀತಿ ಧ್ಯಾನಿಸಿ\nವಿಮೋಚಕನ ಹೆಜ್ಜೆ ಹತ್ತಿರಿ ;\nಕಡೇಲಿ ಮೊಣ್ಷ ರಾಜ್ಯದೊಳಗೆ\nಸಮಸ್ತ ದೂತ ಸೈನ್ಯದೊಳಗೆ\nಸಾಷ್ಟಾಂಗ ಬಿದ್ದು ಹಾಡಿ ಅನ್ನುವ,\n“ನಿರಂತ್ರ ಬಾಳು, ದಿವ್ಯ ರಕ್ಷಕ!\"" },
  184: { title: "ಚಿಕ್ಕಮರಾದ ನಮಗೆ", lyrics: "1. ಚಿಕ್ಕಮರಾದ ನಮಗೆ\nದಯವ ಮಾಡು ಯೆಸುವೇ,\nನೂತನವಾದ ಮನಸ್ಸು\nಉಂಟಾಗ ಮಾಡಿ ರಕ್ಷಿಸು.\n2. ಚಿಕ್ಕವರೆಲ್ಲಾ ಬರಲಿ,\nನನ್ನಾಶೀರ್ವಾದ ಹೊಂದಲಿ ;\nನೀನು ಹೇಳಿದ ಹಾಗೆಯೇ\nಬಂದು ಇದ್ದೇವೆ, ಕರ್ತನೇ!\nವವಧ ಸರಗಶಗಗಕು\n3. ನಮ್ಮೊಳು ಬುದ್ಧಿ ಸ್ವಲ್ಪವೇ,\nನಮ್ಮೊಳು ಗುಣ ಕೆಟ್ಟದ್ದೇ ;\nಆದಾಗ್ಯೂ ನಿನ್ನ ಪ್ರೀತಿಯು\nಎಷ್ಟೋ ವಿಸ್ತಾರವಾದದ್ದು\n4. ಪಾಪವನ್ನೆಲ್ಲಾ ಮನ್ನಿಸು,\nನಮ್ಮನ್ನು ಆಶೀರ್ವದಿಸು ;\nಪಿಶಾಚನಿಂದ ತಪ್ಪಿಸು,\nನಿನ್ನ ರಾಜ್ಯಕ್ಕೆ ಸೇರಿಸು" },
  185: { title: "ಕೇಳು ದೂತರ್ಗಾನಮ,", lyrics: "1. ಕೇಳು ದೂತರ್ಗಾನಮ,\nಘನರಾಜ ಹುಟ್ಟಿದ\n“ಸ್ವರ್ಗದಲ್ಲಿ ಮಹಿಮೆ,\"\n“ಭೂಮಿಯಲ್ಲಿ ಕರುಣೆ,”\nಎಲ್ಲಾ ಜನ ನಂಬಲಿ,\nದೂತರ್ಕೂಡ ಹಾಡಲಿ,\nಬೇತ್ಲೆಹೇಮಿನೊಳಗೆ\nಪರಂಜ್ಯೋತಿ ತೋರಿದೆ,\nಕೇಳು ದೂತರ್ಗಾನಮ\nಘನ ರಾಜ ಹುಟ್ಟಿದ\n2. ಆಗ ಹುಟ್ಟಿದಾತನು\nಪರಲೋಕದರಸು ;\nಮೇಲಿನಿಂದ ಇಳಿದು\nನರನಾಗಿ ಬಂದನು ;\nಪ್ರೀತಿಯಿಂದ ಶನ್ನನ್ನು\nದೀನ ಮಾಡಿಕೊಂಡನು ;\nದೇವರ ಕುಮಾರನು\nಇಲ್ಲಿ ವಾಸಿಸಿದನು,\nಕೇಳು ದೂತರ್ಗಾನಮ,\nಘನ ರಾಜ ಹುಟ್ಟಿದ\nವಿವಿಧ ಸಂಗೀತಗಳು\n3. ಓ ಮಹತ್ವದರಸಾ!\nಸರ್ವಲೋಕ ರಕ್ಷಕಾ!\nಸಮಾಧಾನ ಗುರುವೇ!\nನೀತಿ ಸೂರ್ಯ ಕ್ರಿಸ್ತನೇ!\nಮನಶ್ಶಾಂತಿ ಹುಟ್ಟಿಸಿ\nಮೋಕ್ಷಾನಂದ ತಂದಿದ್ದೀ\nನಮಸ್ಕಾರ, ಯೇಸುವೆ !\nನಿತ್ಯ ಮಾನ ನಿನಗೆ\nಕೇಳು ದೂತರ್ಗಾನಮ,\nಘನ ರಾಜ ಹುಟ್ಟಿದು" },
  186: { title: "ಯೇಸು ಪಾಪಿಗಳನ್ನು", lyrics: "1. ಯೇಸು ಪಾಪಿಗಳನ್ನು\nಪಾಪದೊಳಗಿಂದಲು\nಈಗ ಬಿಡಿಸುವನು,\nನಿಜವಾಗಿ ಹೇಳಿದ್ದು\nಪಲ್ಲವಿ\nಹಾಡಿ ಪಾಡಿ ಮನವೇ\nಹಾಡಿ ಪಾಡಿ, ಎಲ್ಲರೇ\nಯೇಸು ಪಾಪಿಗಳನ್ನು\nಈಗ ಕ್ಷಮಿಸುವನು\n2. ಪಾಪ ಕಂಡು, ಅರಿಕೆ\nಮಾಡುವಂಥ ಪಾಪಿಗೆ\nಯೇಸುವನ್ನಂಬಿದರೆ\nಪರಿಹಾರವಾಗುತ್ತೆ.\n3. ಪಾಪಕ್ಕಾಗಿ ದುಚಖವೇ\nಸಾಲದು ಓ ಪಾಪಿಯೇ\nರಕ್ಷಕನ ಮೇಲೆಯೇ\nಇಡಬೇಕು ನಂಬಿಕೆ." },
  187: { title: "ಒಳ್ಳೇ ಸುದ್ದಿ ಕೇಳಿದೆ", lyrics: "1. ಒಳ್ಳೇ ಸುದ್ದಿ ಕೇಳಿದೆ\nರಕ್ಷಣೆ ಸಿದ್ಧಿಯೇ\nಸರ್ವತ್ರ ಈ ಸುದ್ಧಿಯೇ\nಹಬ್ಬುತ್ತೆ, ಹಬ್ಬುತ್ತೆ\nಜನರೆಲ್ಲಾ ಕೇಳಲಿ,\nಯೇಸುವನ್ನು ನಂಬಲಿ,\nಯೇಸುವಿನ ನಾಮಕ್ಕೆ\nಘನವು ಆಗಲಿ.\n2. ಎಲ್ಲಾ ದೇಶಗಳಿಗೂ\nಹೋಗಿರಿ, ಹೋಗಿರಿ\nಸರ್ವ ಪಾಪಿಗಳಿಗೂ\nಹೇಳಿರಿ, ಹೇಳಿರಿ,\nಯೇಸು ರಕ್ಷಿಸುವನು\nಪಾಪ ಕ್ಷಮಿಸುವನು\nಯೇಸುವಿನ ಅಪ್ಪಣೆ\nಬೇಗನೆ ಸಾರಿರಿ.\n3. ದಿವ್ಯ ಸಮಾಚಾರವ\nಹಾಡಿರಿ, ಪಾಡಿರಿ\nಯೇಸು ಪಾಪಿಗಳಿಗೆ\nಸತ್ತನು, ಎದ್ದನು,\nಜೀವಮಾನದಲ್ಲಿಯೂ\nಎಲ್ಲಾ ಸ್ಥಳದಲ್ಲಿಯೂ\nಸರ್ವ ಜನರಲ್ಲಿಯೂ\nಪ್ರೇಮದಿಂ ಹಾಡಿರಿ\n4. ಯಾರು ಪುನಃ ಬರ್ವರು ?\nಯೇಸುವೇ, ಯೇಸುವೇ,\nಯಾರು ಆತನ್ ನೋಡ್ವರು!\nಕ್ರೆಸ್ತರೇ, ಕೈಸ್ತರೇ,\nಅಂತರಿಕ್ಷದಲ್ಲಿಯೂ\nಕರ್ತನ್ ಜೊತೆಯಲ್ಲಿಯೂ\nಸದಾಕಾಲದಲ್ಲಿಯೂ\nಜಯವೇ! ಜಯವೇ" },
  188: { title: "ನಾನು ಪಾಪದಲ್ಲಿ ಹುಟ್ಟಿ", lyrics: "1. ನಾನು ಪಾಪದಲ್ಲಿ ಹುಟ್ಟಿ\nಕಡು ಪಾಪಿಯಾದೆನು,\nನಾನಾ ವಿಧವಾಗಿ ತಪ್ಪಿ\nಪಾಪದಲ್ಲಿ ಬಿದ್ಯೆನು\nಪಲ್ಲವಿ\nಯೇಸು ನನ್ನ ರಕ್ಷ್ಕ\nಯೇನು ನ್ನ ರಕ್ಷ\nಯೇನು ನ್ನ ರಕ್ಷ್\n2. ಪಾಪಿಯಾಗಿ ನೆಡೆಯಲು,\nಯೆಸು ನ್ನಕಡೆಗೂ\nಶನ್ನ ದಿವ್ಯ ಪ್ರೀಶಿಯನ್ನು\nಕೋರಿಸುತ್ತಾ ಬಂದನು\n3. ಸ್ವಲ್ನಿ ಕಾಲ ಹೋದ ಮೇಲೆ\nದೈವ ಸಮಾಚಾಸವು\nಬಿತ್ತು ನನ್ನ ಕಿವಿಯಲ್ಲೆ\nಯಸುವ ಸಂಸಿದೆನು\nವಿವಿಧ ಸಂಗೀತಗಳು\n4. ಯೇಸು ನನ್ನ ಆತ್ಮವನ್ನು\nಪ್ರೀತಿಸಿದ ನಾಥನೇ\nಪಾಪ ಪರಿಹಾರವನ್ನು\nಕೊಟ್ಟಿದ್ದಾನೆ ನನಗೆ\n5. ಹ್ಯಾಗೆ ಯೇಸುವನ ಮೇಲೆ\nನಾ ನಂಬಿಕೆ ಇಟ್ಟೆನೋ\nಹಾಗೆಯೇ ನೀ ಕೂಡ ನಂಬಿ\nಆತನ್ ಕಡೆ ಸೇರಿಕೋ." },
  189: { title: "ನಾನು ಮಾಡಿದಂಥ ಪಾಪವಲ್ಲ ಹ್ಯಾಗೆ", lyrics: "1. ನಾನು ಮಾಡಿದಂಥ ಪಾಪವಲ್ಲ ಹ್ಯಾಗೆ\nಹೋದೀತು?\nಪರಿಹಾರ ನನಗೆಲ್ಲಿ ಸಿಕ್ಕೀತು?\nನನ್ನ ಕರ್ತನಾದ ಯೇಸುಸ್ವಾಮಿ\nಪ್ರಾಣ ಕೊಟ್ಟನು\nನನ್ನಂಥ ದೊಡ್ಡ ಪಾಪಿ ರಕ್ಷಿಸು\nಪಲ್ಲವಿ\nದೊಡ್ಡ ಪಾಪಿಯಾದ ನನ್ನ\nರಕ್ಷಿಸ, ರಕ್ಷಿಸ\nದೊಡ್ಡ ಪಾಪಿಯಾದ ನನ್ನ\nರಕ್ಷಿಸ, ರಕ್ಷಿಸ\nಯೆಸು ಸ್ವಾಮಿ ಬಂದನು\nತನ್ನ ಪ್ರಾಣ ಕೊಟ್ಟನು.\nದೊಡ್ಡ ಪಾಪಿಯಾದ ನನ್ನ ರಕ್ಷಿಸ\n2. ಇಷ್ಟು ಉಪಕಾರ ಮಾಡಿದಂಥ\nಯೇಸು ಕರ್ತಗೆ\nನಾನು ಬದಲಾಗಿ ವನು ಕೊಟ್ಟೇಮ?\nನನ್ನ ಪೂರ್ಣ ಶಕ್ತಿಯನ್ನು ಆತನ್\nದಿವ್ಯ ಸೇವೆಗೆ\nಕೊಟ್ಟು ಪ್ರೇಮದಿಂದ ಸ್ತೋಚ್ರ\nಮಾಡ್ವೆನು\n3. ನಾವು ಒಳ್ಳೇ ದಾಸರೆಂದು ನಮ್ಮ\nಕರ್ತ ಹೇಳುವ\nನೀತಿ ರಸ್ತೆಯಲ್ಲಿ ನಾವು ಹೋದರೆ\nಆತ ಶೀಘ್ರ ಬರುತ್ತಾನೆ ಎಂದು\nಜ್ಲಪ್ತಿ ಮಾಡುವ ;\nಆಗ ನೀತಿಯ ಕಿರೀಟ ನಮ್ಮದೇ." },
  190: { title: "ಎಲ್ಲರು ಕೂಡಿ ಹಾಡುವಾ", lyrics: "1. ಎಲ್ಲರು ಕೂಡಿ ಹಾಡುವಾ\nದೇವರು ಪ್ರೀತಿಯೇ ;\nಭೂಪರಲೋಕವು ಸಹ\nಹಾಡಲಿ ಪ್ರೀತಿಯೇ,\nಪಾಪಾತ್ಮರೆಲ್ಲಾ ಒನ್ನಿರಿ,\nರಕ್ಷಕನನ್ನು ನಂಬಿರಿ,\nಸಂಭ್ರಮದಿಂದ ಹಾಡಿರಿ\nದೇವರು ಪ್ರೀತಿಯೇ\n2. ಓ ಸಾರಿರೆಲ್ಲಾ ಜನಕ್ಕೆ\nದೇವರು ಪ್ರೀತಿಯೇ\nನಮ್ಮಾತ್ಮ ರಕ್ಷಕಾತನೇ ;\nಪ್ರೀತಿಯೇ, ಪ್ರೀಶಿಯೇ,\nಕ್ರಿಸ್ತೇಸುವಿನ ರಕ್ತವು\nಸಮಸ್ತ ಪಾಪ ತೊಳಿದು,\nನಮ್ಮನ್ನು ಶುದ್ಧ ಮಾಡಿತು,\nದೇವರು ಪ್ರೀಶಿಯೇಲ\n3. ಎಷ್ಟೋ ಅನಂದವಾಯಿತು,\nದೇವರು ಪ್ರೀತಿಯೇ ;\nಯೆಹೋವ ನಮ್ಮ ಶಂದೆಯೇ,\nಪ್ರೀಶಿಯೇ ಪ್ರೀಶಿಯೇ\nಗುರಾಣಿ, ಸೂರ್ಯ, ಸಂಪತ್ತು,\nವಿವಿಧ ಸಂಗೀತಗಳು\nಆಶ್ರಯ, ಕೋಟೆ, ದುರ್ಗವು,\nಅನಂತ ಭಾಗ್ಯವಾತನು\nದೇವರು ಪ್ರೀತಿಯೇ." },
  191: { title: "ಒಂದು ಊರಿನಲ್ಲಿ", lyrics: "1. ಒಂದು ಊರಿನಲ್ಲಿ\nಒಂದು ಬೆಳಕು\nಅಂಧಕಾರದಲ್ಲಿ\nತೋರಲಾಯಿತು ;\nಬೇತ್ಲೆಹೇಮಿನಲ್ಲಿ\nನೀತಿ ಸೂರ್ಯನು,\nಪಾಪ ಕತ್ತಲಲ್ಲಿ\nಕಾಂತಿ ಕೊಟ್ಟನು –3\n2. ಈಗ ನರರಲ್ಲಿ\nದಿವ್ಯ ಕೃಪೆಯು\nಎಲ್ಲಾ ಭೂಮಿಯಲ್ಲಿ\nದೊಡ್ಡದಾಯಿತು\nಈಗ ಶುದ್ಧ ನೀತಿ ;\nಒಳ್ಳೇ ಸುಖವು.\nಸಕ್ಯವಾದ ಪ್ರೀತಿ\nನೆಲಿಗೊಂಡವು -3\n3. ಬೇತ್ಲೆಹೇಮಿನಲ್ಲಿ\nಯಸು ಸ್ವಾಮಿಯು\nನರ ರೂಪದಲ್ಲಿ\nಹುಟ್ಟಿದಾಗಲು,\nಜೀವದ ಪ್ರಕಾಶ\nಪ್ರಭೆ ಕೊಟ್ಟಿತು\nಮರಣದ ಪಾಶ\nಬಿಚ್ಚಿ ಹೋಯಿಶು -3" },
  192: { title: "ಮಂದೆ ಸೇರಿದ ತೊಂಬತ್ತೊಂಬತ್ತು", lyrics: "1. ಮಂದೆ ಸೇರಿದ ತೊಂಬತ್ತೊಂಬತ್ತು\nಹಟ್ಟಿಯೊಳಗಿದ್ದವು.\nಇನ್ನೊಂದು ಎಲ್ಲಿಯೋ ಹೋಯಿತು\nಆಶ್ರಯಕ್ಕೆ ದೂರವು;\nಆ ಕುರಿಯು ಪಟ್ಟ ವೇದನೆ\nಯಾರಿಂದ ಹೇಳಲಾಗುತ್ತೇ ?1॥\n2. ಒಳ್ಳೇ ಕುರುಬನೇ! ತೊಂಬತ್ತೊಂಬತ್ತು\nನಿಂಗೆ ಸಾಕು ಅಲ್ಲವೇ ?\nಇವೆಲ್ಲಾ ಸಾಲದು ಅಂದನು\nನನಗೊಂದು ತಪ್ಪಿದೆ;\nಮತ್ತೆಷ್ಟು ಪ್ರಯಾಸವಾದರೂ\nನಾನ್ ಹೋಗಿ ಹುಡುಕುವೆನು 11\n3. ಆದರೆ ಕುರುಬ ಪಟ್ಟ ಕಷ್ವು\nಎಷ್ಟಾಧಿಕವಾದದ್ದೋ,\nವಿಮೋಚಿಸಲ್ಪಟ್ಟ ಒಬ್ಬರೂ\nಹೇಳಲಾರರಲ್ಲವೋ ?\nಅಘೋರವಾದಂಥ ಸಂಕಟ\n4. ನೋಡು ರಕ್ತದ ಗುರುತು ತೋರುತ್ತೆ\nಅಲ್ಲಿ ಮಾರ್ಗದಲ್ಲಿಯೇ,\nಹೌದು. ಕಳೆದು ಹೋದ ಕುರಿಗೆ\nಚೆಲ್ಲಲ್ಪಟ್ಟ ರಕ್ತವೇ ;\nದೇಹಾತ್ಮಗಳಲ್ಲಿಯೂ ಮಹಾ\nಸಂತೋಷಪಟ್ಟ ಕುರುಬ\n5. ಕೇಳು ಬೆಟ್ಟಗಳಿಂದ ಶಬ್ಧವು\nಆಕಾಶಕ್ಕೆ ಏರುತ್ತೆ,\n“ಆನಂದಪಡಿ ಎಲ್ಲರೂ\nನನ್ನ ಕುರಿ ಸಿಕ್ಕಿದೆ\"\nಮೇಲಾದ ಲೋಕದೊಳ್ ಸಹ\nಉಂಟಾಗುತ್ತದೆ ಹರುಷ\nಎವಿಧ ಸಂಗೀತಗಳು" },
  193: { title: "ಅಧೈರ್ಯಸ್ಥನೇ!", lyrics: "1. ಅಧೈರ್ಯಸ್ಥನೇ!\nನೀ ದೃಢಪಡು :\nಸಮೀಪದಲ್ಲೇ\nನಿನ್ನಾಶ್ರಯವು ?\nನೀ ಪ್ರಾರ್ಥನೆ ಮಾಡಿ.\nವಿಶ್ವಾಸವಿಡು ;\nಉಂಟ್ಯೇಸುವಿನಲ್ಲಿ\nಸಂಪೂರ್ಣತೆಯು.\n2. ಎಲ್ಲೆಲ್ಲಿ ನೀನು\nಉಪದ್ರ ಕಂಡ್ಯಾ ?\nಕಾರ್ಗತ್ತಲೆಯು\nಉಂಟಾಗಿದೆಯಾ ?\nನೀ ನಂಬಿಕೊಂಡಿರು\nದಿವ್ಯಾಪ್ತನನ್ನು;\nಕೈಬಿಡ ನಿನ್ನನ್ನು\nನಿರಂತರವೂ.\n3. ಎನ್ ಕರ್ತನಿಗೆ\nಸಂಭವಿಸಿದ್ದು\nನಾ ನೋಡಿದರೆ\nಅದಾಶ್ಚರ್ಯವು ;\nಎನ್ನೊಡೆಯ ಹೀಗೆ\nಸಂತಾಪಿಸಲು\nನಾ ಪಡುವ ಶ್ರಮ\nತೃಣಷ್ಟಾದದ್ದು\n4. ಪ್ರಯೋಜನಕ್ಕೇ\nಈ ಸೈರಣೆಯು ;\nಮೇಲೌಷಧವೇ\nಈ ಶಿಕ್ಷೆಗಳು ;\nಅವಸ್ಥೆ ಪ್ರಯಾಸ\nತತ್ಕಾಲವಷ್ಟೇ,\nವಿಜಯವಾದಾಗ\nನಿಶ್ಯೋತ್ಸವವೇ" },
  194: { title: "ನೋಡು ಕ್ರಿಸ್ತ ಭಕ್ತಾ!", lyrics: "1. ನೋಡು ಕ್ರಿಸ್ತ ಭಕ್ತಾ!\nನಿನ್ನ ಸುತ್ತಲು\nಅಂಧಕಾರ ಸೈನ್ಯ\nವರ್ತಿಸಿರ್ಪುದು,\nಸೈನಿಕಾ! ಎದ್ದೇಳು\nಸುಖವೇತಕ್ಕೆ ?\nಜಯಪ್ರದಾಯುಧ\nದಿವ್ಯ ಶಿಲುದೆ.\n2. ಮನದಲ್ಲಿ ಭಕ್ತಾ!\nಹಗಲಿರುಳು\nಶೋಧಕನ ತಂತ್ರ\nಯತ್ನಿಸುವುದು ;\nಆದರೇನು ಭಯ\nಧೈರ್ಯವಾಗಿರು ;\nಪ್ರಾರ್ಥನೆಯ ಬಲ\nಜಯಿಸುವದು.\n3. “ಉಪವಾಸ ಜಪ,\nಎಲ್ಲಾ ವ್ಯರ್ಥವು\"\nಎಂಬ ವಂಚಕನ\nಮಾತುಂಟಾಗಲು,\nಹೇಳು ಧೈರ್ಯದಿಂದ\n“ನಿತ್ಯ ಪ್ರಾರ್ಥನೆ\nಶೀರುತ್ತದೆ ಯುದ್ಧ\nಶಾಂತಿ ಸಿಕ್ಕುತ್ತೆ\"\n4. ನಿನಗಾಗುವಂಥ\nಕಷ್ಟ ಯಾವತ್ತೂ\nನಾನೇ, ನಿನ್ನ ಕರ್ತ,\nಸಹಿಸಿರಲು\n“ಭಟಾ ! ಕುಂದದಿರು,\nಹಿಂಸೆಯಿಂದಲೇ\nವಿವಿಧ ಸಂಗೀತಗಳು\nಸುಖ ಪ್ರಾಪ್ತಿಯಪ್ಪು\nದೆನ್ನ ಹತ್ರವೇ" },
  195: { title: "ಮಾತಾಡುವುದುಂಟಲ್ಲವೇ", lyrics: "1. ಮಾತಾಡುವುದುಂಟಲ್ಲವೇ\nಸುಲೋಕದ ವಿಷಯವು ;\nನಾವಲ್ಲಿಗೆ ಸೇರಿದರೆ,\nಎಷ್ಟೋ ಭಾಗ್ಯ ಸಿಕ್ಕುವದು 11\n2. ಸಂಕೀರ್ಶಿಸುತ್ತೇವಲ್ಲವೇ\nಆ ಲೋಕದ ಸುಖವನ್ನು ;\nನಾವಲ್ಲಿಗೆ ಸೇರಿದರೆ,\nಎಷ್ಟೋ ಭಾಗ್ಯ ಸಿಕ್ಕುವದು 11\n3. ಮನೋಹರ ಯೋಚನೆಯೇ\nಆ ಲೋಕದ ಮಹಿಮೆಯು;\nನಾವಲ್ಲಿಗೆ ಸೇರಿದರೆ,\nಎಷ್ಟೋ ಭಾಗ್ಯ ಸಿಕ್ಕುವದು\n4. ಹೌದೆನ್ನನ್ನು ಸೇರಿಸಿಕೋ,\nಓ ಕರ್ತನೇ! ಸ್ವರ್ಗದೊಳು ;\nನಾನಲ್ಲಿಗೆ ಸೇರಿದರೆ," },
  196: { title: "ಎನ್ ಪ್ರಿಯನೇ! ವಿಶ್ರಾಂತಿಯಲ್ಲಿರು", lyrics: "1. ಎನ್ ಪ್ರಿಯನೇ! ವಿಶ್ರಾಂತಿಯಲ್ಲಿರು\nಕರ್ತನ ಸನ್ನಿಧಿಯಲ್ಲೇ ಇರು.\nಆತನ ಪ್ರೇಮವೆಷ್ಟೋ ವಿಶೇಷವು !\nನಿದ್ದೆ ಮಾಡು, ಮಾಡು.\n2. ಕೂಸಿನ ಶಾಂತ ನಿದ್ದೆಯಂತೆಯೇ\nನೀನೀಗ ಶಾಂತಿ ಹೊಂದು, ಪ್ರಿಯನೇ\nಇನ್ನೆಂದಿಗೂ ಅಲ್ಲಿಲ್ಲಾ ವೇದನೆ ;\nನಿದ್ದೆ ಮಾಡು, ಮಾಡು.\n3. ಈ ಲೋಕದಂಧಕಾರ ಮುಗಿದು\nಸಮಾಧಿ ಸೀಳಿ ಹೋಗ್ವ ಮಟ್ಟಿಗೂ\nರೂಪಾಂತ್ರನಾಗಿ ಏಳ್ವ ಮಟ್ಟಿಗೂ,\nನಿದ್ದೆ ಮಾಡು, ಮಾಡು.\n4. ಮೇಲ್ಲೋಕದಲ್ಲಿ ಕೂಡ್ವ ಮಟ್ಟಿಗೂ,\nಸುಸೇವೆ ಮಾಡ್ವವರ್ಗೆ ಕರ್ತನು\nನಿರ್ಲಯ ಮುಡಿ ಇಡ್ವ ಮಟ್ಟಿಗೂ,\nನಿದ್ದೆ ಮಾಡು, ಮಾಡು." },
  197: { title: "ಹಾ! ಭಾಗ್ಯವುಳ್ಳ ದಿನ", lyrics: "1. ಹಾ! ಭಾಗ್ಯವುಳ್ಳ ದಿನ\nವಿಶ್ರಾಂತಿ ಕಾಲವು ;\nಸಂಭ್ರಮ ಪಡತಕ್ಕ\nಗಂಭೀರ ವೇಳೆಯು ;\nಈ ದಿವ್ಯವಾದ ದಿನ\nಅಮೂಲ್ಯ ಸಂಪತ್ತು,\nನನ್ನಾತ್ಮಕ್ಕೆ ಸುರತ್ನ\nಸಂತೋಷವಾದದ್ದು\n2. ಈ ದಿನ ಯೇಸು ಕರ್ತ\nಸಮಾಧಿ ಬಿಟ್ಟನು ;\nಈ ದಿನ ಲೋಕೋದ್ಧಾರ\nಸಂಪೂರ್ಣವಾಯಿತು ;\nಈ ದಿನ ದೇವರಾತ್ಮ\nಸಮೀಪ ಬರುವ ;\nಈ ದಿನ ಸಮಾಧಾನ\nನಮ್ಮೊಳು ಕೊಡುವ\nವಿವಿಧ ಸಂಗೀತಗಳು\n3. ಈ ಹೊತ್ತು ಕ್ರೈಸ್ತ ಸಭೆ\nಎಲ್ಲೆಲ್ಲೂ ಕೂಡುತ್ತೆ ;\nಎಲ್ಲರಿಗೂ ಸುವಾರ್ತೆ\nಪ್ರಸಂಗವಾಗುತ್ತೆ ;\nಅಜ್ಞಾನ ಮನದಲ್ಲಿ\nಪ್ರಕಾಶ ಹುಟ್ಟುತೆ ;\nಸದ್ಭಕ್ತಿ ಜನರಲ್ಲಿ\nಆಸಕ್ತಿ ಹೆಚ್ಚುತ್ತೆ.\n4. ಈ ದಿನ ದೇವಧ್ಯಾನ\nಹೆಚ್ಚಾಗಿ ಮಾಡುವೆ!\nವಿಮೋಚನೆಯ ರಾಗ\nಇಂಪಾಗಿ ಹಾಡುವೆ ;\nಭೂಲೋಕದಲ್ಲಿ ಸಬ್ಬತ್\nಸಮಾಪ್ತವಾದರೂ\nಸುಲೋಕದಲ್ಲಿ ಸಬ್ಬತ್\nಎಂದೆಂದೂ ತೀರದು." },
  198: { title: "ಕರ್ತಾ ; ನೋಡು ; ಭೂಮಿಯಲ್ಲಿ", lyrics: "1. ಕರ್ತಾ ; ನೋಡು ; ಭೂಮಿಯಲ್ಲಿ\nಎಷ್ಟು ಅಂಧಕಾರವು!\nಲೋಕದ ಕಾರ್ಗತ್ತಲಲ್ಲಿ\nಬೆಳಕಾರಿ ಹೋಯಿತು !\nವ್ಯರ್ಥ ಬೊಂಬೆ ಪೂಜೆಯು\nಎಷ್ಟು ಪ್ರಬಲವಾಯಿತು\n2. ಎಂದು ಹೋದೀತಂದಕಾರ!\nಸೂರ್ಯನೆಂದು ಮೂಡ್ಯಾನು?\nಎಂದು ಶುಭ ಸಮಾಚಾರ\nಲೋಕ ತುಂಬಿಸುವುದು ?\nಈಗ ಜ್ಞಾನ ತೊರೆದು,\nಜನ ಮೂರ್ಖರಾದರು.\nವಿವಿಧ ಸಂಗೀತಗಳು\n3. ಏಳು, ಜಗತ್ತಿನ ಕರ್ತಾ !\nಏಳು, ಕೃಪೆಯರಸೇ!\nರಾತ್ರಿಯನ್ನು ಪರಿಹಾರ\nಮಾಡು, ನೀತಿ ಸೂರ್ಯನೇ!\nನಿನ್ನ ವಾಕ್ಯ ಬೇಗನೇ\nಜಯ ಹೊಂದೀಸೇಸುವೇ.\n4. ಕರ್ತಾ ಕೊಡು ಸಿದ್ಧಿಯನ್ನು\nನಿನ್ನ ಸೇವಕರಿಗೆ ;\nಕೊಡು ಒಳ್ಳೇ ಫಲವನ್ನು\nವಾಕ್ಯದ ಪ್ರಸಂಗಕ್ಕೆ ;\nಪೂರ್ಣ ಕಾಂತಿಯಿಂದಲು\nಭೂಮಿಯನ್ನು ತುಂಬಿಸು." },
  199: { title: "ತಂದೆ ಇದ್ದಾನೆ ರಮ್ಯ", lyrics: "1. ತಂದೆ ಇದ್ದಾನೆ ರಮ್ಯ\nಲೋಕದೊಳ್,\nತಂದೆ ಇದ್ದಾನೆ ರಮ್ಯ\nಲೋಕದೊಳ್,\nಬಾ ಅನ್ನುತ್ತಾನೆ ನನ್ನನ,\nನಾ ನೋಡಲಿಕ್ಕೆ ಹೋಗುವೆ.\nಹೋಗುವೆ, ಹೋಗುವೆ\nರಮ್ಯ ಲೋಕಕ್ಕೆ.\n2. ಯೇಸು ಇದ್ದಾನೆ ರಮ್ಯ\nಲೋಕದೊಳ್,\nಯೇಸು ಇದ್ದಾನೆ ರಮ್ಯ\nಲೋಕದೊಳ್,\nಬಾ ಅನ್ನುತ್ತಾನೆ ನನ್ನನ್ನೇ\nನಾ ನೋಡಲಿಕ್ಕೆ ಹೋಗುಮೆ.\n3. ಉಂಟು ಕಿರೀಟ ರಮ್ಯ\nಲೋಕದೊಳ್,\nಉಂಟು ಕಿರೀಟ ರಮ್ಯ\nಲೋಕದೊಳ್,\nಕೊಡುತ್ತೇನೆಂದ ಕರ್ತನೇ,\nತಕ್ಕೊಳ್ಳಲಿಕ್ಕೆ ಹೋಗುಮೆ.\n4. ಉಂಟು ಸುವಾಸ ರಮ್ಯ\nಲೋಕದೊಳ್,\nಉಂಟು ಸುವಾಸ ರಮ್ಯ\nಲೋಕದೊಳ್,\nವಿಮುಕ್ತ ಸಭೆ ಅಲ್ಲಿಯೇ\nಒಂದಾಗಿದ್ದಾರೆ ಅಲ್ಲವೇ.\nಹೋಗುವೆ, ಹೋಗುವೆ\nರಮ್ಯ ಲೋಕಕ್ಕೆ ;\nವಿಮೋಚಕನ ಪಾದಕ್ಕೆ\nನಾ ಬಿದ್ದು ಸ್ತೋತ್ರ ಮಾಡುವೆ." },
  200: { title: "ಸಹೋದರರೇ", lyrics: "1. ಸಹೋದರರೇ\nಎಚ್ಚೆತ್ತು ಬನ್ನಿ\nಕ್ರಿಸ್ೆಸುವಿಗೆ\nಸನ್ಮಾನ ತನ್ನಿ ;\nಈ ದಿವ್ಯ ಸುನಾಮ\nಸಮಸ್ತರಿಗೆ\nಅತ್ಯಾಸಕ್ತಿಯಿಂದ\nಸಾರಿ ಹೇಳಿರಿ.\n2. ಸಂದೇಹ ಏಕೆ ?\nಮಹೋನ್ನತನು\nಇದ್ದಾನಲ್ಲವೇ,\nಸಹಾಯಕನು\nಯೆಹೋವನ ರಾಜ್ಯ\nಮೇಲ್ಗೊಳ್ಳುವದು ;\nಭೂ ಪ್ರಜೆಗಳೆಲ್ಲಾ\nಕೊಂಡಾಡುವರು.\n3. ಸಿಂಹಾಸನದೊಳ್\nಕೂತಾತನಿಗೆ\nಆಕಾಶಗಳೊಳ್\nಸ್ತೋತ್ರಾಡುವರು ;\nಒಂದೇ ಮನಸ್ಸಾಗಿ\nಶ್ರೇಷ್ಟಾತ್ಮಗಳು\nಆರಾಧನೆ ಮಾಡಿ\nಸಂಕೀರ್ತಿಪರು." },
  201: { title: "ಓ ಬನ್ನಿರಿ, ಈಗ", lyrics: "1. ಓ ಬನ್ನಿರಿ, ಈಗ\nಆನಂದ ಪಡೋಣ ;\nಸುದರ್ಶನ ನೋಡಿ ಕೊಂಡಾಡುತ್ತಿರ್ರಿ ;\nಮೇಲ್ಲೋಕದ ಕರ್ತ\nಈ ಭೂಮಿಗೆ ಬಂದ,\nಆರಾಧಿಸ ಬನ್ನಿ\nಸಹೋದರರೇ !\n2. ಹೌದ್ದೇವಾಧಿ ದೇವ\nಭೂಲೋಕಕ್ಕೆ ಬಂದ ;\nಪ್ರಸನ್ನನು ಅದನು ನರರಿಗೆ\nಈ ಆಶ್ಚರ್ಯ ಕಂಡು ;\nಸನ್ಮಾನವ ತಂದು\nಆರಾಧಿಸ ಬ್ನಿ\nಸಹೋದರರೇ !\n3. ಓ ದೂತರ ಸೈನ್ಯ,\nನಮ್ಮೊಂದಿಗೆ ಕೂಡ\nಸುರಾಗವನ್ನೆ್ತಿ ಸಂಭ್ರಮಿಸಿರಿ ;\nವಿವಿಧ ಸಂಗೀತಗಳು\nಈ ರಕ್ಷಕನನ್ನು\nಈ ಭೂಪತಿಯನ್ನು\nಶ್ರೇಷ್ಟಾತ್ಮಗಳೇ!" },
  202: { title: "ಸಭೈಕ ಅಸ್ತಿವಾರ", lyrics: "1. ಸಭೈಕ ಅಸ್ತಿವಾರ\nಕ್ರಿಸ್ೇಸುವು ತಾನೇ\nಅದಾತನ ನಿರ್ಮಾಣ\nತನ್ನಾತ್ಮನಿಂದಲೇ ;\nಆ ಸಭೆ ಶುದ್ಧಮಾಡ\nತಾ ಶಾಪ ತಿಂದನು,\nತನ್ನವರನ್ನು ಕಾಯ\nಸ್ವರಕ್ತ ಕೊಟ್ಟನು.\n2. ಆ ಸಭೆ ಲೋಕದಲ್ಲಿ\nಚದರಿ ಇದ್ದರೂ\nಎಲ್ಲರೂ ಕ್ರಿಸ್ತನಲ್ಲಿ\nಭ್ರಾತೃಗಳಾದರು ;\nಒಂದೇ ವಿಶ್ವಾಸ ಉಂಟು\nಒಂದೇ ನಿರೀಕ್ಷೆಯು ;\nಒಂದಭಿಲಾಷೆ ಪಟ್ಟು\nಸಂಚರಿಸುವರು.\n3. ಈವಾಗ ಯುದ್ಧಕಾಲ,\nಮಹಾ ಹೋರಾಟವೇ,\nಆದಾಗ್ಯೂ ಸಮಾಧಾನ\nಕಡೇಲಿ ಆಗುತ್ತೆ :\nಮಹತ್ತಿನಲ್ಲಿ ಸೇರಿ\nಎಂದೆಂದೂ ಸಾಯರು\nಜೀವ ಕಿರೀಟ ಹೊಂದಿ\nವಿಶ್ರಮಿಸುವರು\nವಿವಿಧ ಸಂಗೀತಗಳು\n4. ತ್ರಯೈಕ ದೇವರಲ್ಲಿ\nಅನ್ಯೋನ್ಯರಾದರು\nಆನಂದ ಲೋಕದಲ್ಲಿ\nಸ್ವತಂತ್ರರೆಂದಿಗೂ ;\nಓ ಶ್ರೇಷ್ಟವಾದ ಜನ,\nಸುಭಾಗ್ಯವಂತರೇ,\nನಾವೆಲ್ಲಾ ನಿಮ್ಮ ಕೂಡ\nಪೋಪೆವು ಮೋಕ್ಷ" },
  203: { title: "ಜೀವ ವಾಕ್ಯದ ಗಾನವ", lyrics: "1. ಜೀವ ವಾಕ್ಯದ ಗಾನವ\nಇಂಪಾಗಿ ಹಾಡಿರಿ ;\nದೇವ ಪ್ರೀತಿಯ ವಿವರ\nವರ್ಣಿಸಿ ಹೇಳಿರಿ ;\nಶುಭ ವರ್ತಮಾನ,\nಆತ್ಮಕ್ಕೆ ಆಧಾರ!\nಆನಂದವೇ, ಆನಂದವೇ ;\nಸದ್ವೇದ ವಾಕ್ಕವು 18\n2. ದೇವ ವಾಕ್ಯವ ನಮಗೆ\nಕ್ರಿಸತ್ಯೆಸು ಕೊಟ್ಟನು ;\nಕೇಳಿ ವಾಕ್ಯವ ಪಾಪಿಯೇ\nವಿಧೇಯನಾಗಿರು ;\nಮೋಕ್ಷ ಲೋಕ ಮಾರ್ಗ,\nಉಚಿತಾರ್ಥ ದಾನ\nಆನಂದವೇ, ಆನಂದವೇ,\nಸದ್ವೇದ ವಾಕ್ಯವು ॥\n3. ಸಾರು ವಾಕ್ಯವ ಜನಕ್ಕೆ\nಆಸಕ್ತಿಯಿಂದಲೇ ;\nಸಾರು ಪಾಪದ ಮನ್ನಣೆ\nಪಾಪಿಗಳೆಲ್ಲರ್ಗೆ ;\nಶುದ್ಧಮಾಡಿ ಯೇಸು\nಕಾಯುತ್ತಿರ್ಪನೆಂದೂ ;\nಆನಂದವೇ, ಆನಂದವೇ,\nಸದ್ವೇದ ವಾಕ್ಯವು" },
  204: { title: "ಪಾಪಿಷ್ಟ ತಪ್ಪಿಸು", lyrics: "1. ಪಾಪಿಷ್ಟ ತಪ್ಪಿಸು\nಪ್ರಾಣ ಕಾಪಾಡು\nಮೋಸದ ಮಾರ್ಗದಿಂದಾಕರ್ಷಿಸು ;\nದುರ್ಗತಿ ಬಿಡಿಸಿ,\nಸದ್ಗತಿ ಕೊಡ,\nಯೇಸು ಇದ್ದಾನೆಂದು ಪ್ರಕಟಿಸು.\nಪಲ್ಲವಿ\nಪಾಪಿಷ್ಟ ತಪ್ಪಿಸು,\nಪ್ರಾಣ ಕಾಪಾಡು,\nದಯದ ಯೇಸುವು ರಕ್ಷಿಸುವ\n2. ಜೀವಾಂತ್ಯ ಸಂಕಟ\nನ್ಯಾಯವಿಚಾರ\nಬರುವದೆಂದು ನೀ ಎಚ್ಚರಿಸು ;\nದಿವ್ಯಾಂತಃ ಕರುಣೆ\nಕಾದಿರುತ್ತದೆ,\nಈ ಒಳ್ಳೇ ಸುದ್ದಿಯ ಸಾರುತ್ತಿರು.\n3. ದುಷ್ಟ ಸೈತಾನನು\nದುಮಾರ್ಗರನ್ನು\nವಂಚಿಸುತ್ತಾ ಇರುತ್ತಾನಲ್ಲವೇ ?\nಗಂಡಾಂತ್ರ ಕೋರಿಸಿ,\nಸುಬುದ್ಧಿ ಹೇಳಿ,\nಆಯಾಸಗೊಳ್ಳದೆ ಎಚ್ಚರಿಸು.\n4. ಪ್ರೀತಿಯ ಪ್ರೇರಣೆ,\nಜ್ಞಾನದ ಬೋಧೆ ;\nಮಾಡುತ್ತಾ ಇರು ಪಾಪಿಷ್ಠರಿಗೆ,\nಕಠಿಣವಾದರೂ\nನಂಬಿಕೆ ಉಂಟು,\nಕರ್ತನಿದ್ದಾನೆ ದಯಾಪರನೇ." },
  205: { title: "ಆತ್ಮ ನಿನ್ನ ಕರ್ತನು", lyrics: "1. ಆತ್ಮ ನಿನ್ನ ಕರ್ತನು\nಪ್ರಶ್ನೆ ಕೇಳ ಬಂದನು ;\nಯೇಸು ಮಾತನ್ನಾಡಲು,\nಕಿವಿಗೊಟ್ಟಾಲೋಚಿಸು.\n2. ಪಾಪಿಯೇ! ನಾ ನಿನ್ನನ್ನು\nಎಷ್ಟೋ ಸ್ನೇಹಿಸಿದೆನು ;\nಪ್ರೀತಿ ನಿನ್ನಲ್ಲಿಲ್ಲವೇ ?\nನಿನ್ನ ರಕ್ಷಕ ನಾನೇ.\n3. ಸೆರೆಯಲ್ಲಿದ್ದಾಗಲೂ\nನಿನ್ನ ಬಿಡಿಸಿದೆನು,\nರೋಗದೊಳ್ ಬಿದ್ದಿರಲು\nಬಂದು ಸ್ವಸ್ಥ ಕೊಟ್ಟೆನು.\n4. ಮಾರ್ಗ ಬಿಟ್ಟು ದೂರವೇ\nಅಲೆದಾಡುವಾಗಲೇ\nನಿನ್ನ ಹುಡುಕಿದೆನು\nಮಾರ್ಗದಲ್ಲಿ ತಂದೆನು.\nವಿವಿಧ ಸಂಗೀತಗಳು\n5. ನನ್ನ ದಿವ್ಯ ಪ್ರೀತಿಯು\nತಪ್ಪಿ ಹೋಗಲಾರದು\nಸಾಗ್ರ ಜಲದಂತೆಯೇ\nಮಿತಿಯಿಲ್ಲದ್ದಾಗಿದೆ." },
  206: { title: "ನೀ ಬೇಕು ಸರ್ವದಾ,", lyrics: "1. ನೀ ಬೇಕು ಸರ್ವದಾ,\nಉದ್ಧಾರಕ!\nಇನ್ಯಾರು ಕೊಡೋರು ಸುಶಾಂತಿಯ?\nಪಲ್ಲವಿ\nಓ ಯೇಸು, ನೀನಗತ್ಯ !\nಯೇಸು ನೀನಗತ್ಯ!\nಕೈಚಾಚಿ ನನಗೀಗ ಸಹಾಯ ತಾ!\n2. ನೀ ಬೇಕು ಸರ್ವದಾ!\nನೀನಿದ್ದರೆ !\nಗಂಡಾಂತ್ರದಲ್ಲಿಯೂ ಪಾರಾಗುವೆ.\n3. ನೀ ಬೇಕು ಸರ್ವದಾ!\nನನ್ನೊಂದಿಗೆ!\nನೀನಿಲ್ಲದಿದ್ದರೆ, ಸೋತ್ಹೋಗುವೆ.\n4. ನೀ ಬೇಕು ಸರ್ವದಾ!\nಸುನಾಥನೆ!\nನೀ ಹೇಳಿದಂತೆಯೇ, ನಾ ಮಾಡುಮೆ\n5. ನೀ ಬೇಕು ಸರ್ವದಾ!\nಪವಿತ್ರನೇ !\nಮಾಡೆನ್ನ ಹೃದವಂ ಪವಿತ್ರವೇ!\nವಿವಿಧ ಸಂಗೀತಗಳು" },
  207: { title: "ನಾನು ನಿನ್ನವ, ಪ್ರಿಯ ಕರ್ತನೆ;", lyrics: "1. ನಾನು ನಿನ್ನವ, ಪ್ರಿಯ ಕರ್ತನೆ;\nನಿನ್ನ ವಾಕ್ಯ ಕೇಳಿದೆ,\nಇನ್ನು ಕೇವಲ ನಿನ್ನನ್ಯೋನ್ಯಕ್ಕೆ\nಸೇರೋದನ್ನ ಕೋರಿಕೆ.\nಪಲ್ಲವಿ\nಎಳೆ ನನ್ನ ಎಳೆ, ಪ್ರಿಯ ಕರ್ತನೇ,\nನಿನ್ನ ಕ್ರೂಜೆ ಕಂಬಕ್ಕೆ !\nಎಳೆ ನನ್ನ ಎಳೆ, ಪ್ರಿಯ ಕರ್ತನೇ,\nನಿನ್ನ ತಿವಿದೆದೆಗೆ!\n2. ನಿನ್ನ ಸೇವೆಗೆ, ಪ್ರಿಯ ರಕ್ಷಕ\nನೀ ಪ್ರತಿಷ್ಯಿೆನ್ನು\nದಯಪಾಲಿಸು ದೃಢ ನಿಶ್ಚಯ!\nನಿನ್ನ ಚಿತ್ತ ನ್ನದು.\n3. ನಾನು ಒರಗಿ ನಿನ್ನ ಪಾದಕ್ಕೆ\nಸುಸಂವಾದ ಮಾಡುತ್ತ\nನಿನ್ನ ಸಂಗಡ ಇರ್ವಗಳಿಗೆ\nಎಂಥಾಮೂಲ್ಯ ಸಂತಸ!\n4. ತಳವಿಲ್ಲದ ಪ್ರೀತಿಸಾಗರ!\nಬುದ್ಧಯತೀತ ಹರ್ಷವೇ!\nನನಗಾಗಲು ನಿನ್ನ ದರ್ಶನ\nನಿತ್ಯಸ್ತೋತ್ರ ನಿನಗೆ!" },
  208: { title: "ಯೇಸು ಕ್ರಿಸ್ತನೇ,", lyrics: "1. ಯೇಸು ಕ್ರಿಸ್ತನೇ,\nಮೃತ್ಯುಂಜಯನೇ,\nನಮ್ಮ ಜೀವ ಜೀವವೇ!\nನಿನ್ನ ಶ್ರಮೆ ನನ ಕ್ಷಮೆ,\nಕಾಯಿ, ಕಾಯಿ ನಮ್ಮನ್ನು!\n2. ಕಳ್ಳನಂತೆಯೆ\nನಮ್ಮ ದಂಡನೆ\nಹೊಣೆಯಾಗಿ ತಾಳಿದೆ.\nನೀ ಪವಿತ್ರ ದಿವ್ಯ ಮಿತ್ರ,\nಕಾಯಿ, ಕಾಯಿ ನಮ್ಮನ್ನು!\n3. ದುಷ್ಟ ಹಾಸ್ಯವು.\nಮುಳ್ಳುಮಾಲೆಯು\nನಿನ್ನ ಘನವಾಯಿತು,\nನಮ್ಮ ನಿಂದೆ ನೀನು ತಿಂದೆ,\nಕಾಯಿ, ಕಾಯಿ, ನಮ್ಮನ್ನು!\n4. ಬಡ ಪಾಪಿಗೆ\nನಿನ್ನ ಕ್ರೂಜೆಯ\nಜೀವವೃಕ್ಷವಾಗಿದೆ,\nನಿನ್ನ ದುಚು ನಮ್ಮ ಸುಖ,\nಕಾಯಿ, ಕಾಯಿ, ನಮ್ಮನ್ನು!\n5. ದಿವ್ಯ ಪ್ರೀತಿಯೇ,\nದೇವಪುತ್ರನೇ,\nಕನ್ಯಾಸ್ತ್ರೀಯ ಮಗುವೇ !\nಜೀವದಲ್ಲು ಮೃತಿಯಲ್ಲು\nಕಾಯಿ, ಕಾಯಿ, ನಮ್ಮನ್ನು!" },
  209: { title: "ಈ ಹೊತ್ತಿನ ದಿನದೊಳ್", lyrics: "1. ಈ ಹೊತ್ತಿನ ದಿನದೊಳ್\nದೇವ ಶಬ್ದ ಕಿವಿಯೊಳ್\nಬೀಳುವಾಗ ಎಚ್ಚರ !\nತೆರೆ ನಿನ್ನ ಹೃದವ !\nಆತ ಕರ್ಯುತಾನಲ್ಲಾ;\nಆತನ್ಹತ್ರ ಓಡಿ ಬಾ!\n2. ನಾಳೆ ಹೃದಯ ಕಠಿಣ–\nವಾಗಿ ಹೋದೀತಕಟ!\nಸ್ಥಿರವಲ್ಲ ಜೀವವು,\nಕೃಪಾಕಾಲ ತೀರ್ವದು,\nನಾಳೆ ನ್ಯಾಯತೀರ್ಪಿನ\nಕಾಲ ಬಂತು ಹತ್ತಿರ.\nಇಂದು ಕೃಪಾಸಮಯ\nಇನ್ನು ಇರೊ ಕಾರಣ,\nನಿನ್ನ ಪ್ರಾಣ ರಕ್ಷೆಗೆ\nಓಡಿ ಹೋಗು ಬೇಗನೆ\nಇಂದು ಹೋಗು ಶರಣ!\nದೇವ ಶಬ್ದ ಕೇಳಿ ಬಾ!\n. ಕೆಸ್ತ್ಯೇಸು ನಿನ್ನ ನೀತಿಯೆ\nನನ್ನಲಂಕಾರ ವಸ್ತ್ರವೇ ;\nಜಗತ್ತು ಸುಟ್ಟು ಹೋದರೆ,\nಅದನ್ನು ಹೊದ್ದು ನಿಲ್ಲುವೆ.\nನಾ ಗೋರಿಯಿಂದ ಹೊರಟು\nಸ್ವಪಟ್ಗಕ್ಷೇರಿ ಹೋಗಲು,\nವಿವಿಧ ಸಂಗೀತಗಳು\nಕ್ರಿಸ್ಯೇಸು ನನಗಾಗಿಯು\nಸತ್ತೆದ್ದನೆಂದು ನಾಚೆನು.\n3. ಆ ದಿನದಲ್ಲಿ ನನಗೆ\nಯಾರೂ ವಿರೋಧ ನಿಲ್ಲರು;\nಕ್ರಿಸ್ೇಸು ರಕ್ತದಿಂದಲೇ\nದುಷ್ಕರ್ಮ, ಭಯ ಹೋದವು.\n4. ಸಜೀವವಿಲ್ಲದವರೇ,\nಈ ವಾಕ್ಯ ಕೇಳತಕ್ಕದ್ದು\n“ಕ್ಿಸತ್ೈಸು ರಕ್ತ ನೀತಿಯೇ\nನಮ್ಮಲಂಕಾರ ವಸ್ತ್ವು !\"" },
  210: { title: "ನಮ್ಮ ಆಯಸ್ಸು", lyrics: "1. ನಮ್ಮ ಆಯಸ್ಸು\nಬಹು ಸ್ವಲ್ಪವು ;\nಬೇಗ ಬಪ್ಪುದಂತ್ಕಶ್ವಾಸ ;\nಲೋಕ ಕೊಡುವೀ ವಿಲಾಸ\nಬಹುಕಾಲವು\nನಿಲ್ಲಲಾರದು.\n2. ವ್ಯರ್ಥ ಭ್ರಮೆಯು\nಇನ್ನು ಬೇಡವು,\nಚುರುಕಾದ ಬುದ್ಧಿಯನ್ನು\nಹೃದ್ವಿ ಶುದ್ಧಭಾವವನ್ನು\nಕೊಡು ನಮಗೆ\nಪ್ರಿಯ ಕರ್ತನೆ!\n3. ಇಂದು ನಮ್ಮದು\nನಾಳಿನಾಪತ್ತು\nಪೂರ್ಣ ಮರ್ಮವಿರಲಾಗಿ,\nನಿತ್ಯ ಆತ್ಮ ಸುಖಕ್ಕಾಗಿ\nನೋಡದವನೇ\nಮೂಢನಲ್ಲವೇ ?\n4. ನನ್ನ ಅತ್ಮಕ್ಕೆ\nಒಂದೇ ಯೋಚನೆ\nಈ ಪ್ರಪಂಚವೆಲ್ಲ ಲಯ;\nಏಕೆ ಗತಿ ನಿನ್ನ ದಯ\nದಯವೆನಗೆ\nಕೊಡು ಯೇಸುವೆ!" },
  211: { title: "ಯೆಹೋವ ಪ್ರಾಪ್ತಕಾಲದ", lyrics: "1. ಯೆಹೋವ ಪ್ರಾಪ್ತಕಾಲದ\nಸುಭದ್ರ ದುರ್ಗಸ್ಥಳ ;\nಶತ್ರುಗಳನ್ನು ಜೈಸುವ\nಶ್ರೇಷ್ಯಾಸ್ತ್ರ ನಿಜ ಬಲ!\nಹಳೇ ವೈರಿಯು\nಈಗ ಮುನಿದು,\nಮಹಾಶಕ್ತಿಯಿಂ,\nಕುಯುಕ್ತಿ ತಂತ್ರದಿಂ\nವಿರೋಧಿ ನಿಂತಿದ್ದಾನೆ.\n2. ನಮ್ಮಲ್ಲಿ ತ್ರಾಣವಿಲ್ಲವು,\nನಾಂ ಗೆಲ್ಲ ಶಕ್ತರಲ್ಲ;\nಯೆಹೋವನಾಯ್ದ ಶೂರನು\nವಿಜಯ ಕೊಡಬಲ್ಲ\nಆದಾರೆಂದರೆ,\nಯೇಸು ಕ್ರಿಸ್ತನೆ!\nಎಲ್ಲಾ ಸೃಷ್ಟಗು\nಕರ್ತಾಧಿಕರ್ತನು ;\nಮತ್ತೊಬ್ಬ ದೇವರಿಲ್ಲ!\n3. ಭೂ ದೆವ್ವ ತುಂಬಿದ್ದಾದರು\nನಮ್ಮನ್ನು ನುಂಗೋದಿಲ್ಲ\nಸ್ತೋತ್ರದ ಸಂಗೀತಗಳು\nವಿಜಯ ಗತಿ ನಮ್ಮದು !\nನಮ್ಮಲ್ಲಿ ಭಯವಿಲ್ಲ\nಈ ಪ್ರಾಪಂಚಕನು\nಸಿಟ್ಟಿಗೆದ್ದರು\nಹ್ಯಾಗೂ ನಿಲ್ಲನು.\n“ಅಂತ್ಯಾಜ್ಞೆಯಾಯಿತು!\"\nಈ ಒಂದೆ ಮಾತು ಸಾಕು.\n4. ಯಾವಾತ ಬಂದು ಕೇಳ್ವನು\nಪವಿತ್ರ ವಾಕ್ಯವನ್ನು ?\nದಿವ್ಯಾತ್ಮನಾಳುತ್ತಿರ್ವನು\nಸದ್ಧ್ಕ್ತ ಸಭೆಯನ್ನು\nಸತೀಸುತರೂ\nಹೊನ್ನೂ ಹೆಸರೂ\nಎಲ್ಲಾ ಹೋಗಲಿ\nನೀ ವೈರಿ, ಸೋಲುವಿ\nರಾಜ್ಯಾಧಿ ನಮ್ಮ ಪಾಲು !" },
  212: { title: "ಈ ಲೋಕದವರೆಲ್ಲರೂ", lyrics: "1. ಈ ಲೋಕದವರೆಲ್ಲರೂ\nಕರ್ತನಿಗೆಂದೂ, ಹಾಡಲಿ\nಸಂತೋಷದಿಂದ ಎಲ್ಲರೂ\nಆತನ ಸೇವೆ ಮಾಡಲಿ.\n2. ಆತನು ಸಾಕ್ಷಾತ್ ಪ್ರಭುವೇ ;\nನಮ್ಮನ್ನು ಸೃಷ್ಟಿಸಿದನು,\nನಮ್ಮೆಲ್ಲರ ಪೋಷಕನೇ ;\nಉದ್ಧರಿಸುವ ಕರ್ತನು.\n3. ಸ್ತೋತ್ರವ ತಂದು ಕೊಡಿರಿ,\nಸಂತೋಷದಿಂದ ಬನ್ನಿರಿ,\nಆ ಹೆಸರಿಗೆ ಪ್ರೇಮದಿ\nತಕ್ಕಂಥ ಮಾನ ಕೊಡಿರಿ.\n4. ಮಹೋಪಕಾರಿ ಆತನೇ\nನಮ್ಮೆಲ್ಲರಿಂದ ಸ್ತುತ್ಯನೇ :\nಆತನ ಮಾತು ನಿಲ್ಲುತ್ತೆ,\nಮಾನವ ಕೊಡಿರೆಲ್ಲರೇ !" },
  213: { title: "ವಿಮೋಚಕನ ಸ್ತೋತ್ರವ", lyrics: "1. ವಿಮೋಚಕನ ಸ್ತೋತ್ರವ\nಹಾಡಲಿ ಮನವೇ :\nಎನ್ನರಸನ ಕೃಪೆಯ\nಪ್ರಸಿದ್ಧ ಮಾಡುವೆ.\n2. ಎಲ್ಲೆಲ್ಲಿ ನಿನ್ನ ನಾಮವ\nಪ್ರಸಿದ್ಧ ಮಾಡಲು\nತಕ್ಕಂಥ ಭಾಷೆ ನನಗೂ\nಕೊಡೀಗ ಕರ್ತನೆ!\n3. ಯೇಸು, ನಿನ್ನಾಮವೆನ್ನಲ್ಲಿ\nಆನಂದವೀಯುತ್ತೆ,\nಆ ನಾಮ ದಿವ್ಯ ಔಷಧಿ\nಮುಲಾಮು ಹಾಕುತ್ತೆ.\n4. ಎನ್ ಪಾಪ ಸಾಲ ತೀರಿತು,\nನಿನ್ನನ್ನು ನಂಬುವೆ\nನಿನ್ ದಿವ್ಯವಾದ ರಕ್ತವು\nವಿಶುದ್ಧ ಮಾಡುತ್ತೆ.\nಸ್ತೋತ್ರದ ಸಂಗೀತಗಳು\n5. ಆತನ ಮಾತು ಕೇಳಿದೆ;\nಆತನ ಆತ್ಮನು\nಸುಜ್ಞಾನ ಕೊಟ್ಟು ನನ್ನಲ್ಲೇ\nಉಲ್ಲಾಸ ಮಾಡಿತು.\n6. ಓ ಕೇಳಿರೆಲ್ಲಾ ಜನರೇ,\nರಕ್ಷಣೆ ಈಗಲೇ\nನಿಮಗೆ ಸಿಕ್ಕಲಾಗುತ್ತೆ\nಯೇಸುವಿನಿಂದಲೇ !" },
  214: { title: "ಬಲಿಷ್ಟನಾದ ದೇವರ್ಗೆ", lyrics: "1. ಬಲಿಷ್ಟನಾದ ದೇವರ್ಗೆ\nಸ್ತೋತ್ರವ ಮಾಡುವಾ\nಸ್ವಶಬ್ದ ಮಾರ್ಗಗಳಲ್ಲೇ\nಸಂಪೂರ್ಣನಾತನು !\n2. ಜನರು ಪಾಪದಿಂದಲೇ\nಅಶುದ್ಧರಾದರೂ,\nಕರ್ತನು ಪ್ರೀತಿಯಿಂದಲೇ\nರಕ್ಷಣೆ ತಂದನು.\n3. ಆತನು ಪ್ರೀತಿಯಿಂದಲೇ\nಸಹಾಯ ಮಾಡಿದ\nದೇವಾತ್ಮ ಬಲದಿಂದಲೇ\nವೈರಿಯ ಜೈಸಿದ.\n4. ಆ ವೈರಿ ಸೋಲಿಸಲಿಕ್ಕೆ\nಸ್ವಪ್ರಾಣ ಕೊಟ್ಟನು,\nಆತನ ಕ್ರೂಜೆಯಲ್ಲಿಯೇ\nಉದ್ಧರಿಸಿದನು.\n5. ಪಾಪದ ಶಿಕ್ಷೆ ಆತನೇ\nಸಹಿಸಿಕೊಂಡನು.\nಕ್ರಿ್ತನ ರಕ್ಿದಿಂದಲೇ\nಏಿಜಯ ಸಿಕ್ಕಿತು!\nಆ ತೋಟದಲ್ಲಿ ಆತನು\nದುಬುವ ಪಟ್ಟನು\nಕ್ರೂಜೆಯ ಮೇಲೆ ಆತನು\nಎಂಗಾಗಿ ಸತ್ತನು.\n7. ಬಲಿಷ್ಟನಾದ ದೇವರ್ಗೆ\nಸ್ತೋತ್ರವ ಮಾಡುವಾ\nಆ ಶುದ್ಧ ಲೋಕದಲ್ಲಿಯೇ\nನಿರಂತ್ರ ಸ್ತುತಿಯೇ.\nಆತನ ಬಗ್ಗೆ ಸ್ತುತಿ ಹಾಡಿರಿ,\nಆತನು ಗುರಾಣಿ, ಮಹಾವೃದ್ಧನು\nಗೌರವುಳ್ಳ ಸ್ವಾಮಿ, ಸರ್ವಶಕ್ತನು.\n2. ಆತನ ಕೃಪೆ ಪ್ರಕಟಿಸಿರಿ\nಆತನ ಶಕ್ತಿ ಸಂಕೀರ್ತಿಸಿರಿ\nಆತನ ವಾಹನ ನೀಲಮೇಘವೇ,\nಆತನ ನಿವಾಸ ಪರಲೋಕವೇ.\n3. ಸರ್ವಶಕ್ತನೇ! ನಿನ್ನ ಬಲದಿ\nಈ ಭೂಲೋಕವ ಉಂಟು ಮಾಡಿದಿ\nಆ ಮೇಲೆ ಸಮುದ್ರ ಬಟ್ಟೆಯ ಹಾಗೆ\nಭೂಮಿಯ ಸುತ್ತಲು ನೀನು ಹಾಕಿದೆ.\nಸ್ತೋತ್ರದ ಸಂಗೀತಗಳು\n4. ನಿನ್ನ ಪಾಲನೆ ಅತಿ ಶ್ರೇಷ್ಯದ್ದು\nನಮ್ಮ ಸುತ್ತಲು ಕಾಣಿಸುವದು\nಬೆಟ್ಟಗಳ ಮೇಲೂ ಬಯಲಿನಲ್ಲೂ\nನಿನ್ನ ದಿವ್ಯ ಕೃಪೆ ತಪ್ಪಿಹೋಗದು.\n5. ಸದ್ಭಕ್ತರಿಗೆ ಆಶ್ರಯ ನೀನೇ\nನಮ್ಮ ನಂಬಿಕೆ ನಿನ್ನ ಮೇಲಿದೆ\nನಿನ್ನ ಕರುಣೆಯು ಎಷ್ಟೋ ಒಳ್ಳೇದು !\nನೀನು ನಮ್ಮ ಕರ್ತ, ಮಿತ್ರ, ದೇವರು." },
  215: { title: "ದೇವಾಧಿದೇವ", lyrics: "1. ದೇವಾಧಿದೇವ\nಪ್ರಚಾರ ಮಾಡು ;\nಆ ನಾಮಧೇಯ\nಅಲ್ಲಲ್ಲಿ ಸಾರು ;\nಆ ಸುನಾಮದಲ್ಲಿ\nವಿಜಯವಿದೆ ;\nಎಲ್ಲೆಲ್ಲೂ ಆತನು\nಸ್ತುತಿ ಪಾತ್ರನೇ.\n2. ಸುಸ್ವರ್ಗದಲ್ಲೂ\nಭೂಲೋಕದಲ್ಲೂ\nನಮ್ಮ ದೇವರು\nವಾಸಿಸುವನು\nಭಕ್ತರ ಸಮೂಹ\nಕೊಂಡಾಡುವರು ;\nನಿರಂತ್ರ ರಕ್ಷಣೆ\nಮಾಡುವವನು.\n3. ಆಪ್ತ ಸ್ನೇಹಿತ\nನಾಗಿರುವನು ;\nಎಲ್ಲಾ ಮಕ್ಕಳ\nಪ್ರೀತಿಸುವನು.\nಆತನು ರಕ್ಷಣೆ\nಸಮಸ್ತರಿಗೂ\nನಿತ್ಯಾನಂದದಿಂದ\nಕೊಡಬಲ್ಲನು.\n4. ಸಿಂಹಾಸನದೊಳ್\nಆಸೀನನಿಗೆ\nಸರ್ವ ಜನರೊಳ್\nಸ್ತೋತ್ರವಿರುತ್ತೆ ;\nಕ್ರಿಸತ ಯೇಸುವಿಗೆ\nಕೊಂಡಾಟವನ್ನು\nಎಲ್ಲರು ಸಲ್ಲಿಸಿ\nಅರ್ಪಿಸುವರು.\n5. ನಾವಾತನನ್ನ\nಕೊಂಡಾಡುವೆವು ;\nತಕ್ಕ ಸ್ಥಾನವ\nಕೊಡಾತನಿಗೂ ;\nಕ್ರಿಸ್ರೇಸುವಿನಲ್ಲಿ\nಪ್ರೀತಿ ಬಲವು\nಪರಿಪೂರ್ಣವಾಗಿ\nನೆಲೆಗೊಂಡವು." },
  216: { title: "ಮೇಲ್ಲೋಕ ರಾಜನೇ,", lyrics: "1. ಮೇಲ್ಲೋಕ ರಾಜನೇ,\nಅಬ್ರಾಮನಾಪ್ತನೇ,\nನಿರಂತ್ರ ಕಾಲದಾತನೇ\nಸ್ತೋತ್ರದ ಸಂಗೀತಗಳು\nವಾತ್ಸಲ್ಯನೇ 1\nಭೂಪರಲೋಕವು\nನಿನ್ ಮುಂದೆ ಬೀಳುತ್ತೆ\nನಾನು ಸಹ ಬೀಳುವೆನು,\nಯೆಹೋವನೇ !\n2. ಅಬ್ರಾಮನಾಪ್ತನೇ\nನಿನ್ನಾಜ್ಞೆಯಂತೆಯೇ\nನಾ ಪಾಪ ಮಾರ್ಗ ಬಿಡುವ;\nಓ ಪ್ರಭುವೇ!\nಎಲ್ಲವ ಬಿಡುವೆ\nದುರ್ಬುದ್ಧಿ ಎಲ್ಲವು :\nನಿನ್ನನ್ನು ಮಾತ್ರ ನಂಬುವೆ ;\nಯೆಹೋವನೇ !\n3. ನೀ ಆಜ್ಞೆಯಿಟ್ಟಿದೆ :\nಆ ಆಜ್ಞೆನಂಬುವೆ :\nಆ ಆಜ್ಞೆಯಂತೆ ಸ್ವರ್ಗಕ್ಕೆ\nಸೇರುವೆನು !\nನಿನ್ನ ಸಮ್ಮುಖವೇ\nಕಾಣಿಸುತ್ತಿರುತ್ತೆ\nನಾ ನಿನ್ನ ಸ್ತೋತ್ರ ಹಾಡುವೆ ;\nಯೆಹೋವನೇ !\n4. ತ್ರಯೈಕ ದೇವರೇ\nನೀ ಅತಿ ಶ್ರೇಷ್ಯನೇ\nನಿನ್ನನ್ನು ಸ್ವರ್ಗದಲ್ಲಿಯೇ\nಕೊಂಡಾಡುವ !\nನೀ ನಿತ್ಯನಾಗಿಯೇ\nಸ್ವರಾಜ್ಯ ಕಾಯುವಿ,\nಅಲ್ಲಿರುವವರೆಲ್ಲರೂ\nವಿಧೇಯರು!\nಆ ಲೋಕದವರು\nತ್ರಯೈಣ ನಿನ್ನನ್ನು\nಕೊಂಡಾಡಿ ಸ್ತೋತ್ರಿಸುವರು,\nನಿರಂತ್ರನೇ !\nನಿನ್ನೆಲ್ಲ ಭಕ್ತರು\nನಿರಂತ್ರ ಬಾಳ್ವರು\nಶಕ್ತಿ ಪ್ರಾಬಲ್ಯ ನಿನ್ನವೆ\nಯಹೋವನೇ !" },
  217: { title: "ಕರುಣೆಯ ಕರ್ತಗೆ", lyrics: "1. ಕರುಣೆಯ ಕರ್ತಗೆ\nಹಾಡಿರೆಲ್ಲಾ ಭಕ್ತರೇ,\nಪಲ್ಲವಿ\nಆತನ ಕರುಣೆಯು\nಎಂದೂ ತಪ್ಪಿ ಹೋಗದು.\n2. ಸರ್ವಶಕ್ತನಾಗಿಯೂ\nಜ್ಯೋತಿ ಕೊಡುವಾತನು.\n3. ಸರ್ವಜೀವರಾಶಿಗೆ\nಜೀವ ಕೊಡುವಾತನು.\n4. ತನ್ನ ಸ್ವಂತ ಜನರ\nಪಾಪದಿಂದ ಕಾಯುವ.\n5. ಕ್ರಿಸ್ತನಿಂದ ದೇವರು\nಎಂಗೆ ಕ್ಷಮೆ ಕೊಟ್ಟನು.\n6. ಮನೋ ಪೂರ್ತಿಯಿಂದಲೇ\nಹಾಡಿರೆಲ್ಲಾ ಭಕ್ತರೇ.\nಸ್ತೋತ್ರದ ಸಂಗೀತಗಳು" },
  218: { title: "ಸ್ವರ್ಗಲೋಕ ರಾಜನಿಗೆ", lyrics: "1. ಸ್ವರ್ಗಲೋಕ ರಾಜನಿಗೆ\nಸ್ತೋತ್ರವರ್ಪಿಸುತ್ತಿರು ;\nಆತನನ್ನು ನಿನ್ನ ಹಾಗೆ\nಯಾರೂ ಸ್ತೋತ್ರ ಮಾಡಾರು ?\nಸ್ತೋತ್ರ ಮಾಡು, ಸ್ತೋತ್ರ ಮಾಡು\nಸ್ವರ್ಗಲೋಕ ರಾಜಗೆ!\n2. ದಿವ್ಯ ಕೃಪೆಗಾಗಿ ಸ್ತೋತ್ರ\nಅರ್ಪಿಸು ಎನ್ನಾತ್ಮವೇ !\nಮುಂಚೆ ಇದ್ದ ಹಾಗೆ ಈಗ\nಆಶೀರ್ವಾದ ಸಿಕ್ಕುತ್ತೆ!\nಸ್ತೋತ್ರ ಮಾಡು, ಸ್ತೋತ್ರ ಮಾಡು\nಕೃಪೆಯುಳ್ಳ ರಾಜಗೆ !\n3. ತಂದೆಯಾಗಿ ನಮ್ಮನ್ನೆಲ್ಲಾ\nಕೃಪೆಯಿಂದ ಕಾಯ್ವನು\nತನ್ನ ಕೈಗಳಲ್ಲಿ ಆತ\nಎತ್ತಿ ಹೊರುವಾತನು.\nಸ್ತೋತ್ರ ಮಾಡು, ಸ್ತೋತ್ರ ಮಾಡು\nಕರುಣೆಯ ರಾಜಗೆ !\n4. ಪವಿತ್ರಾತ್ಮ ನೆರವಾಗು\nಕ್ರಿ್ತ ಐಕ್ಯದಲ್ಲಿಯೇ\nನಾನು ನೆಲೆಗೊಳ್ಳುವಂತೆ\nಬಲ ಕೊಡು ಈಗಲೇ,\nಸ್ತೋತ್ರ ಮಾಡು, ಸ್ತೋತ್ರ ಮಾಡು\nಸರ್ವಕೃಪೆ ರಾಜಗೆ !" },
  219: { title: "ಸ್ತೋತ್ರಿಸು, ಸ್ತೋತ್ರಿಸು,", lyrics: "1. ಸ್ತೋತ್ರಿಸು, ಸ್ತೋತ್ರಿಸು,\nಯೆಹೋವನನ್ನೇ !\nಯೆಹೋವನ ಕಾರ್ಯವ ಕೀರ್ತಿಸಿರಿ.\nಕ್ರಿಸ್ತ್ಯೇಸುವಿನ ಮಹಿಮೆ ದಯೆಗಳನ್ನೆ\nಸಕಲರಿಗೆ ಈಗ ಹೇಳುತ್ತಾ ಇರ್ರಿ.\nಪಲ್ಲವಿ\nದಿವ್ಯ ಪ್ರೀತಿ ನದಿಯಂತೆ ಹರಿಯುತ್ತದೆ ;\nದಿವ್ಯ ಕರುಣೆ ಶಾಶ್ವತವಾಗುತ್ತದೆ.\n2. ಸ್ತೋತ್ರಿಸು, ಸ್ತೋತ್ರಿಸು\nಕ್ರಿಸ್ತ ಯೇಸುವನ್ನೇ!\nಪಾಪಿಗಾಗಿ ಸತ್ತು ಎದ್ದು ಬಂದನು\nಸ್ವರಾಜ್ಯವನ್ನು ಸ್ಥಾಪಿಸುವದಕ್ಕೆ\nಈ ಲೋಕಕ್ಕೆ ಬೇಗನೇ ಬರುವನು.\n3. ಆತನು ಬಂದಾಗ ಭ್ರಮೆಯಾಗುವದು !\nರಾಜಾಧಿರಾಜನು ತಾನಾಳುವನು\nತನ್ ವೈರಿಯಣಗಿಸಿಕೊಳ್ಳುವನು\nಸದಾ ತನ್ನ ಜನರ ಕಾಪಾಡುವನು." },
  220: { title: "ದೇವಾ ನಿನ್ನ ನಾಮ ಕೊಂಡಾಡುವೆನು ;", lyrics: "1. ದೇವಾ ನಿನ್ನ ನಾಮ ಕೊಂಡಾಡುವೆನು ;\nನೀ ರಕ್ಷಣೆಯನ್ನು ಏರ್ಪಡಿಸಿದ್ದಿ\nನನ್ನ ಬದಲಾಗಿ ಕ್ರಿಸ್ತೇಸುವನ್ನು\nಶಿಕ್ಷಿಸಿ ಎನ್ನಾತ್ಮವ ರಕ್ಷಿಸಿದ್ದೀ.\nಸ್ತೋತ್ರದ ಸಂಗೀತಗಳು\nಪಲ್ಲವಿ\nಕರ್ತನೇ, ನಿನಗೆ\nಸ್ತೋತ್ರ ಸಲ್ಲಿಸುವೆ !\nಕರ್ತನೇ, ನಿನಗೆ\nಸರ್ವ ಕೊಂಡಾಟವೇ!\nನೀನೇ ಜನಗಳ ಸಂರಕ್ಷಣೆಗೆ\nಮಹತ್ವವ ನಡಿಸಿ ಬಂದಾತನೇ.\n2. ರಕ್ತ ಕ್ರಯದಿಂದ ನೀನೆಲ್ಲರಿಗೆ\nಸಂಪೂರ್ಣ ಸ್ವಾತಂತ್ರ್ಯವ ಪಾಲಿಸಿದ್ದೀ\nನಿನ್ನ ನಂಬಿಕೊಂಡ ಪಾಪಿಗಳಿಗೆ\nನೀ ಮನ್ನಿಸಿ ಬರುವ ದಯಾಪ್ರನೇ.\n3. ಸತ್ಯಾರ್ಥವ ತೋರಿ ಮಹತ್ವವನ್ನು\nಕ್ರಿಸ್ತೇಸುವಿನಲ್ಲಿಯೇ ತೋರಿಸಿದ್ದೀ ;\nನಿತ್ಯಾಶ್ರಯದಲ್ಲಿ ನಾನಿರುವೆನು\nಸದಾ ನಿನ್ನ ಹತ್ರ ನಾ ವಾಸಿಸುವೆ." },
  221: { title: "ಆ ಕ್ರೂಜೆ ಮೇಲೆ ಪ್ರಾಣವ", lyrics: "1. ಆ ಕ್ರೂಜೆ ಮೇಲೆ ಪ್ರಾಣವ\nಬಿಟ್ಟಂಥವ ಕೊಂಡಾಡುವೆ\nಆತನ ಹಾಸ್ಯ ಮಾಡದೆ\nಆತನ ಸ್ತೋತ್ರ ಹಾಡುವೆ.\n2. ಆ ಕ್ರೂಜೆ ಮೇಲೆ ಪ್ರೀತಿಯೇ\nನಮಗೆ ಕಂಡು ಬಂದಿತು ;\nನಮ್ ಪಾಪಕ್ಕಾಗಿ ಆತಗೆ\nಆ ಕ್ರೂಜೆ ಶಿಕ್ಷೆಯಾಯಿತು.\nಆ ಕ್ರೂಜೆಯಿಂದ ನಮಗೆ\nಎಂಥಾಶೀರ್ವಾದವಾಗುತ್ತೆ :\nಅಲ್ಲ್ಯೇಸುವೆ ಶಿಕ್ಷೆಯನ್ನು\nನಮಗಾಗಿ ತಾಳಿದನು.\nಯೇಸುವಿನಿಂದ ನಮಗೆ\nಆಧಾರವೆಷ್ಟು ಬಂದಿದೆ ;\nಸಮಾಧಿಯಲ್ಲಿ ಬೀಳಲು\nಆಧೈರ್ಯವೆಲ್ಲ ಹೋಯಿತು.\n5. ಆ ಲೋಕ ದೇವದೂತರು\nಆಶ್ಚರ್ಯ ಪಡುವವರು\nಆ ಸ್ವಾಮಿ ಪ್ರಾಣ ಕೊಟ್ಟದ್ದು\nಆಶ್ಚರ್ಯವುಂಟುಮಾಡಿತು.\n6. ಪಾಪಿಯ ಶಿಕ್ಷೆ ಯೇಸುವೇ\nತಾಳಿದ್ದಕ್ಕಾಗಿ ಆತಗೆ\nಅನಂತ ಸ್ತೋತ್ರ ಮಾಡುವೆ\nಸದಾ ಆ ಸ್ತೋತ್ರವಾಗುತ್ತೆ." },
  222: { title: "ಯೇಸುವನ್ನು ಸ್ತೋತ್ರಿಸಲೀಗಲೇ ಬಂದು", lyrics: "1. ಯೇಸುವನ್ನು ಸ್ತೋತ್ರಿಸಲೀಗಲೇ ಬಂದು\nಕಿಸ್ತ ಪ್ರೀತಿ ನೆನಪು ಮಾಡಿರಿ ;\nದೂತಗಣ ಆತನ ಸ್ತೋತ್ರದಲ್ಲಿರು\nಮಾನ ಕೀರ್ತಿ ಸಲ್ಲಿಸ ಬನ್ನಿರಿ.\nಕುರ್ಬನಂತೆ ಯೇಸು ತನ್ನವರನ್ನು\nನೋಡಿ ಮೇಯ್ಸಿ ಕಾಯುವನಲ್ಲವೇ ?\nಪ್ರೀತಿ ಪ್ರೇಮ ಎಲ್ಲರ ಮೇಲೆ ತಾನಿಟ್ಟು\nಕರ್ಯುತ್ತಾನೆ ಕರುಣೆಯಿಂದಲೇ.\nಸ್ತೋತ್ರದ ಸಂಗೀತಗಳು\n2. ಯೇಸುವನ್ನು ಸ್ತೋತ್ರಿಸಲೀಗಲೇ ಬಂದು\nಕ್ರಿಸ್ತ ಹತ್ರ ಹೋಗಲು ಬಂದಿರು ;\nನಮಗಾಗಿ ಶಿಲುಬೆ ಮರಣ ಪಟ್ಟು\nತಂದೇ ಹತ್ರ ನಮ್ಮನ್ನು ತಂದನು.\nಕ್ರೂರವಾದ ಮುಳ್ಳಿನ ಮುಡಿ ತೊಟ್ಟು\nಮೃದುಭಾವ ತೋರಿಸಿ ಸತ್ತನು ;\nಎಂಥಾ ಕರ್ತ ! ಆತನ ಸ್ತೋತ್ರಿಸ ಬಂದು\nಸದಾ ಬಾಳು ಅನ್ನುತ್ತಾ ಬಂದಿರು.\n3. ಯೇಸುವನ್ನು ಸ್ತೋತ್ರಿಸಲೀಗಲೇ ಬಂದು\nಕ್ರಿಸ್ತವಾಣಿ ಕೇಳುತ್ತಾ ಬಂದಿರು ;\nಆತ ಸರ್ವಲೋಕದ ರಾಜನಾಗಿದ್ದು\nಹರ್ಷದಿಂದ ಆಳಲು ಬರ್ವನು,\nಅಡ್ಡ ಬಿದ್ದು ಆತನಾಶ್ರಯದಲ್ಲಿ\nಸೇರಿರೀಗ ಬಾಳುವಿರೆಂದಿಗೂ ;\nಕಾಯುತ್ತಾನೆ ಆತನ ರಕ್ಷಣೆಯಲ್ಲಿ\nನಂಬಿ ಬನ್ನಿ ಆತನು ತಳ್ಳನು." },
  223: { title: "ಕ್ರಿಸ್ತೇಸು ಸರ್ವಲೋಕವ", lyrics: "1. ಕ್ರಿಸ್ತೇಸು ಸರ್ವಲೋಕವ\nಸ್ವರಾಜ್ಯವ ಮಾಡುವನು\nಪಶ್ಚಿಮದಿಂದ ಪೂರ್ವಕ್ಕೆ\nತಾನೊಬ್ಬನೇ ಆಳುವನು.\n2. ಆ ರಾಜ್ಯಕ್ಕಾಗಿ ಬಯಸುವೆ ;\nಆ ದಿವ್ಯ ರಾಜ ಸ್ತುತ್ಯನೇ ;\nಆತನ ನಾಮ ಮಧುರವೇ ?\nಅಮೂಲ್ಯ ರತ್ನದಂತಿದೆ.\n3. ಆತನ ಪ್ರೀತಿ ಕಾರ್ಯವು\nಅಲ್ಲಲ್ಲಿ ಕಾಣಬರುತ್ತೆ\nಸಕಲ ರಾಜ್ಯದಿಂದಲೂ\nಆತಗೆ ಸ್ತೋತ್ರ ಸಿಕ್ಕುತ್ತೆ.\n4. ಆತನಿದ್ದಲ್ಲಿ ಜಯವೇ ;\nಅಲ್ಲೆಲ್ಲರೂ ಸ್ವತಂತ್ರರೇ ;\nದೈವಾಶೀರ್ವಾದದಿಂದಲೂ\nಸಂತೋಷ ಪಡುವವರು.\n5. ಆ ರಾಜ್ಯ ತನ್ನ ರಾಜಗೆ\nತಕ್ಕ ಸನ್ಮಾನವ ಕೊಡಲಿ\nಈ ಲೋಕದವರೆಲ್ಲರೇ\nಆತಗೆ ಅಡ್ಡ ಬೀಳಲಿ." },
  224: { title: "ಪ್ರಾರ್ಥನೆಯ ಮಾಡಿರಿ", lyrics: "1. ಪ್ರಾರ್ಥನೆಯ ಮಾಡಿರಿ\nಎಂದು ಕರ್ತ ಹೇಳಿದ,\nಪ್ರೀತಿಯಿಂದಲೇ ಕೇಳಿ\nಉತ್ತರವ ಕೊಡುವ.\n2. ಯೇಸು ಮಹಾರಾಜನು ;\nಎಲ್ಲಾ ಕೊಡಬಲ್ಲನು\nದಿವ್ಯ ಬಲಕ್ಕಿಂತಲೂ\nಹೆಚ್ಚು ಯಾರು ಕೇಳರು.\n3. ಕರ್ತಾ ನಮ್ಮ ಮನಸ್ಸು\nತೊಳೆ ನೀನು ಈಗಲೂ\nನಿನ್ನ ರಕ್ತದಿಂದಲೇ\nಶುದ್ಧಮಾಡು ನಮ್ಮನ್ನೇ.\nಸ್ತೋತ್ರದ ಸಂಗೀತಗಳು\n4. ಯೇಸು ನೀನು ನಮಗೆ\nಶಾಂತಿ ಕೊಡು ಈಗಲೇ\nನೀನು ನಮ್ಮ ಕರ್ತನು\nನಡಿಸೀಗ ನಮ್ಮನ್ನು\n5. ಇಹಲೋಕ ನಮಗೆ\nಪರಸ್ಥಳವಾಗಿದೆ\nನಿನ್ನ ರಾಜ್ಯದಲ್ಲಿಯೇ\nನಮ್ಮ ವಾಸಸ್ಥಳವೇ !" },
  225: { title: "ಹಗಲು ರಾತ್ರಿಯಲ್ಲಿಯೂ", lyrics: "1. ಹಗಲು ರಾತ್ರಿಯಲ್ಲಿಯೂ\nನೋಡುವ ಕಣ್ಣಿದೆ\nಎಲ್ಲರ ಮಾತು ಕೇಳಲು\nಕಿವಿಯು ಇರುತ್ತೆ.\n2. ಎಲ್ಲರ ಬಲ ಮೀರುವ\nಶಕ್ತಿಯು ಇರುತ್ತೆ ;\nಮನುಜ ಪ್ರೀತಿ ಹೋದರೂ\nಸುಪ್ರೀತಿಯಿರುತ್ತೆ.\n3. ಆ ಕಣ್ಣು ಎಲ್ಲ ನೋಡುತ್ತೆ,\nಆ ಶಕ್ತಿಯು ತಾಳುತ್ತೆ\nಆ ಕಿವಿ ಎಲ್ಲಾ ಕೇಳುತ್ತೆ\nಆ ಪ್ರೀತಿ ತಾಳುತ್ತೆ.\n4. ಎಲ್ಲರು ಸೋತು ಹೋದರೆ\nದೇವರು ಸೋಲದೆ\nನಮ್ಮನ್ನು ಎಂದೂ ತಳ್ಳದೆ\nಸಹಾಯ ಕೊಡುವ.\n5. ಪ್ರಾರ್ಥನೆ ಕೇಳಿ ದೇವರು\nಸಪಾಯ ಕೊಡುವ\nಪ್ರಾರ್ಥನೆಯಿಂದ ಜಯವ\nನಾವೀಗ ಹೊಂದುವ.\nಸನ್ನಿಧಿಯಲ್ಲಿ ಬೀಳುವೆ\nಪ್ರಸನ್ನದಿಂ ಈ ಸ್ಥಳವ\nತುಂಬಿಸು ಈಗ ಸ್ವಾಮಿಯೇ.\n2. ನನ್ನನ್ನು ದೇವ ಕಡೆಗೆ\nನೀ ರಕ್ತ ಚೆಲ್ಲಿ ತಂದಿದ್ದೀ\nತಂದೆಯ ನಾಮ ಸ್ತುತಿಸ\nನನ್ನನ್ನು ಶುದ್ಧ ಮಾಡಿದ್ದೀ.\n3. ಮುಳ್ಮುಡಿ ಹೊತ್ತಾ ತಲೆಯ\nಗಾಯದ ಪಕ್ಕೆ ಕೈಗಳ\nನಾ ನೋಡಿ ನಿನ್ನ ಪ್ರೀತಿಸ\nಸಹಾಯ ಮಾಡು, ಓ ಕರ್ತ.\n4. ಲೋ ವೈರತ್ವ ಮರೆಯ\nಸ್ವರ್ಗದಾನಂದವ ಪಡೆಯ\nನಿನ್ ಹತ್ರವೇ ನಾ ಬಂದೆನು\nನನ್ನನ್ನು ಈಗ ಪಾಲಿಸು.\nಪ್ರಾರ್ಥನೆ" },
  226: { title: "ಕರ್ತಾ, ನಿನ್ ಜನರೆಲ್ಲರೂ", lyrics: "1. ಕರ್ತಾ, ನಿನ್ ಜನರೆಲ್ಲರೂ\nಕೂಡುವ ಸ್ಥಳದಲ್ಲಿ\nನೀನಿದ್ದಿಯೆಂದು ಬಲ್ಲರು ;\nಆ ಸ್ಥಳ ಶುದ್ಧ ಭೂಮಿಯು!\n2. ವಿಶೇಷವಾದ ಮನೆಯು\nಅವಶ್ಯವಿಲ್ಲವೆಂದಿಗೂ ;\nಜನರು ಕೂಡುವದಲ್ಲಿ\nನೀನವರೊಂದಿಗಿರುತ್ತೀ !\n3. ಈ ಸ್ಥಾನದಲ್ಲಿ ನಮ್ಮಲ್ಲಿ\nನೀನಿರುವವನಾಗಿಯೇ ;\nಕೂಡಿದ ನಿನ್ನ ಜನರ\nನೀ ಕಾಣಿಸು ಓ ಕರ್ತನೇ!\n4. ಪ್ರಾರ್ಥನಾ ಬಲದಿಂದಲೇ\nವ್ಯಸನವೆಲ್ಲಾ ಹೋಗುತ್ತೆ.\nಹತ್ತಿರ ಸ್ವರ್ಗವಿರುತ್ತೆ,\nಅಲ್ಲಿ ವಿಶ್ರಾಂತಿ ಸಿಕ್ಕುತ್ತೆ.\n5. ಕೆಲವರಾಗಿ ಕೂಡಿದ\nನಮ್ಮನ್ನು ಈಗ ಲಾಲಿಸು\nಉತ್ತರ ಪ್ರೀತಿಯಿಂದಲೇ\nನೀನೇ ಕೊಡೀಗ ನಮಗೆ." },
  227: { title: "ಯೇಸು ವಿನಂತಿ ಕೇಳುವ", lyrics: "1. ಯೇಸು ವಿನಂತಿ ಕೇಳುವ\nಸ್ಥಾನಕ್ಕೆ ಬರುವೆ\nಆತನ ಮುಂದೆ ಬೀಳುವೆ\nಸುರಕ್ಷಿಸುತಿರುವೆ.\n2. ಅಲ್ಲಿ ನಾ ಬರುವದಕ್ಕೆ\nನಿನ್ನಾಜ್ಞೆಯಾಗಿದೆ\nಎನ್ ಭಾರವನ್ನು ಅಲ್ಲಿಯೇ\nನಾ ಬಿಟ್ಟು ಬರುವೆ.\n3. ಪಾಪದ ಭಾರದಿಂದಲೇ\nನಾ ಕಷ್ಟಪಡುವೆ\nನೀ ಬಲ ಪಾಲಿಸಿದರೆ\nವಿಜಯ ಹೊಂದುವೆ.\n4. ನನ್ನಾತ್ಮ ವೈರಿ ಬಂದರೆ\nನಿನ್ ಹತ್ರ ಬರುವೆ\nನನ್ನನ್ನು ವೈರಿ ಮುಟ್ಟದೆ\nಓಡೋಡಿ ಹೋಗುತ್ತೆ.\n5. ನೀ ಪ್ರೀತಿಯಿಂದ ನನ್ನನ್ನು\nರಕ್ಷಿಸು, ಪ್ರಭುವೇ!\nನಿನ್ನಾಮವೆತ್ತಿ ನಿನ್ನನ್ನು\nಕೊಂಡಾಡುತ್ತಿರುವೆ.\nಪ್ರಾರ್ಥನೆ" },
  228: { title: "ಕ್ರಿಸ್ತನ ಪ್ರೀತಿಯೇ", lyrics: "1. ಕ್ರಿಸ್ತನ ಪ್ರೀತಿಯೇ\nಅನ್ಯೋನ್ಯ ನಮ್ಮಲ್ಲಿ\nಸ್ವರ್ಗದ ಐಕ್ಯದಂತೆಯೇ\nಉಂಟಾಗ ಮಾಡುತ್ತೆ.\n2. ತಂದೆಯ ಮುಂದೆಯೇ\nಪ್ರಾರ್ಥನೆಯಿಂದಲೇ\nನಿರೀಕ್ಷೆ ಶಾಂತಿ ಆಗುತ್ತೆ\nಸಂತೋಷವಾಗುತ್ತೆ.\n3. ಇತರ ಕಷ್ಟದೊಳ್\nಸಂತಾಪಿಸುವೆವು\nಅವರ ಕಷ್ಟ ಕಣ್ಣೀರೊಳ್\nಭಾಗಸ್ಥರಾಗ್ವೆವು.\n4. ಅಗಲಿಸುವಾಗ್ಗೆ\nಮನೆಗೆ ಹೋದರೂ\nತಂದೆಯ ಹತ್ರ ಇದ್ದೇವೆ;\nನಾವೆಂದೂ ಮರ್ಯೆವು.\n5. ಈ ದಿವ್ಯ ಸತ್ಯವೇ\nತಿಳಿದುಕೊಂಡೆವು\nಎನ್ ದಿವ್ಯ ತಂದೆ ಮನೆಗೆ\nನಿರೀಕ್ಷಿಸುವೆವು.\nಪ್ರಾರ್ಥನೆ\nದೇವರೀಗ ಆಶೀರ್ವಾದ\nಕೊಡಲಿಕ್ಕಿರುವನು,\nಪವಿತ್ರಾತ್ಮ ಬಲವಾಗಿ\nಕಾರ್ಯ ಮಾಡುವಾತನು.\nಪಲ್ಲವಿ\nಬರಲಿ! ದಿವ್ಯಾಶೀರ್ವಾದ\nಬಲವಾಗಿ ಬೀಳಿಸು ;\nನಾವು ಕಾಯುತ್ತಿರುವಾಗ\nನಮ್ಮನ್ನಲ್ಲಾ ಶುದ್ಧಿಸು.\n2. ದೇವರಿಲ್ಲಿ ಇರುತ್ತಾನೆ,\nಬಂದಿದ್ದೇವೀ ಸ್ಥಳಕ್ಕೆ\nಆತನೀಗ ಕೃಪೆಯಿಂದ\nಆಶೀರ್ವಾದ ಕೊಡುವ.\n3. ದೇವರಿಲ್ಲಿ ಇರುತ್ತಾನೆ,\nನಂಬಿರಿ ಈ ಮಾತನ್ನ\nದಿದ್ಯ ಪ್ರೀಿ ನಮ್ಮಲ್ಲಿಟ್ಟು\nತನ್ನ ಕಾರ್ಯ ಮಾಡುವ.\n4. ರಕ್ಷಕಾ ನಮ್ಮ ವಿನಂತಿ\nನೀನು ಈಗ ಲಾಲಿಸು\nನಿನ್ನ ದಿವ್ಯ ಪ್ರೀತಿಯಿಂದ\nಆಶೀರ್ವಾದ ಸುರಿಸು." },
  229: { title: "ಕಷ್ಟವು ಬರುವಾಗಲೇ,", lyrics: "1. ಕಷ್ಟವು ಬರುವಾಗಲೇ,\nನಷ್ಟವು ಬಂದ ಕಾಲವೇ,\nಕೃಹಾಸನದಲ್ಲಿ ನಾವು\nಸಹಾಯ ಹೊಂದ ಬಲ್ಲೆವು.\n2. ಅಲ್ಲಿ ಕ್ರಿಸತ್ಯೇಸು ನಮಗೆ\nಸಹಾಯಿಸುವನಲ್ಲವೇ ?\nಆತನ ರಕ್ತದಿಂದಲೇ\nಆ ಕೃಪೆ ಸ್ಥಳ ಸಿಕ್ಕುತ್ತೆ.\n3. ಆ ಸ್ಥಳದಲ್ಲಿ ಭಕ್ತರು\nದೂರಸ್ಥರಾಗಿದ್ದರೂ\nಅನ್ಯೋನ್ಯವಾಗಿರಲಿಕ್ಕೂ\nಆ ಸ್ಥಳಕ್ಕೇರ ಬರ್ವರು.\n4. ಅಲ್ಲಿ ನಮ್ಮಾತ್ಮ ಏರುವ\nಕಾಲವು ಬೇಗ ಹೋಗುತ್ತೆ\nದೇವರು ಹತ್ರ ಇರುವ\nಬಲವು ಅಲ್ಲಿ ಸಿಕ್ಕುತ್ತೆ.\nದೇವರ ಮತ್ತು ಕ್ರಿಸ್ತನ ಪ್ರೀತಿಯು" },
  230: { title: "ಹಾ! ಎಂಥಾ ಪ್ರೀತಿ! ಕ್ರಿಸ್ತನ ಪ್ರೀತಿಯೇ!", lyrics: "1. ಹಾ! ಎಂಥಾ ಪ್ರೀತಿ! ಕ್ರಿಸ್ತನ ಪ್ರೀತಿಯೇ!\nಮಿತಿಯಿಲ್ಲದ ಪ್ರೀತಿಯೇ!\nಅವಧಿಯಂತೆ ತೋರುತ್ತಲೆನಗೆ ;\nಆ ಪ್ರೀತಿ ನನ್ನ ಮೇಲಿದೆ,\nನನ್ನ ಸುತ್ತಲದು ಇದ್ದು\nಆವರಿಸುತ್ತಲಿರುತ್ತೆ ;\nನನ್ನನ್ನು ದೇವ ಮನೆಗೆಯೇ\nನಡಿಸಲಿದ್ದು ಇರುತ್ತೆ.\n2. ಆ ದಿವ್ಯ ಪ್ರೀತಿ! ಆಗಾಧ, ಪ್ರೀತಿಯು!\nಅಲ್ಲಲ್ಲಿ ಹರ್ಡಿಸ ತಕ್ಕದ್ದೇ ;\nಆತನ ಪ್ರೀತಿ ಮಿತಿಯಿಲ್ಲದ್ದು\nಮಾರ್ಪಾಟವಿಲ್ಲದ ಪ್ರೀತಿಯೇ ;\nತನ್ನವರನ್ನೆಲ್ಲಾ ಸ್ವರಕ್ತ ಕೊಟು\nತಾ ಕೊಂಡುಕೊಳ್ಳ ಸತ್ತಲ್ಲವೇ ?\nಅವರನ್ನಾತ ಕಾಯುವನೆಂದೂ\nವಿಜ್ಞಾಪನೆ ಆತ ಮಾಡ್ವನೇ.\n3. ಆ ದಿವ್ಯ ಪ್ರೀತಿ! ಆಗಾಧ ಪ್ರೀತಿಯೇ\nಅಮೂಲ್ಯ ಪ್ರೀತಿಯು ಆಗಿದೆ!\nದೇವರ ವರ ಆ ಪ್ರೀತಿಯಲ್ಲಿದೆ ;\nದಿವ್ಯಶಾಂತಿ ಕೊಡುತ್ತೆ,\nಕ್ರಿಸ್ತನ ಪ್ರೀತ, ಅಗಾಧ, ಪ್ರೀತಿ,\nಸ್ವರ್ಗವ ತಂದು ಪಾಲಿಸಿದ್ದೇ ;\nದೇವರ ಹತ್ರ ನನ್ನನ್ನು ತಂದು\nಸದಾ ಸಂತೋಷ ಕೊಡುತ್ತೆ." },
  231: { title: "ಕ್ರಿಸ್ತನ ಚರಿತ್ರೆ ಹೇಳು,", lyrics: "1. ಕ್ರಿಸ್ತನ ಚರಿತ್ರೆ ಹೇಳು,\nನನಗೆ ವಿವರಿಸು,\nಎಲ್ಲಾ ಚರಿತ್ರೆಗಳಲ್ಲಿ\nನನಗೆ ಇಂಪಾದದ್ವು\nಆತನ ಜನ್ಮದ ರಾತ್ರಿ\nದೂತರು ಇಳಿದರು,\nರಕ್ಷಕನು ಹುಟ್ಟಿದ್ದಾನೆ,\nಎಂದು ಹಾಡುತ್ತಿದ್ದರು.\n2. ಆತನು ನಾಲ್ವತ್ತು ದಿನ,\nಅಡವಿಯಲ್ಲಿ ಇದ್ದನು\nಶೋಧನೆ ಸೈರಿಸಿಕೊಂಡು,\nವಿಜಯ ಗಳಿಸಿದ,\nಆತನು ದೇವರ ಸೇವೆ,\nಯಾವಾಗಲೂ ಮಾಡಿದ,\nಆತನು ಬಡವನಾಗಿ\nಕಷ್ಟವನ್ನು ತಾಳಿದ.\n3. ಆತನ ಕ್ರೂಜೆಯ ಬಗ್ಗೆ\nನನಗೆ ವಿವರಿಸು,\nಆತನು ಸಮಾಧಿಯಿಂದ\nದೇವರ ಮತ್ತು ಕ್ರಿಸ್ತನ ಪ್ರೀತಿಯು\nಎದ್ದನೆಂದು ತಿಳಿಸು,\nಕ್ರಿಸ್ತನ ಚರಿತ್ರೆಯಲ್ಲಿ\nಪ್ರೀತಿಯ ನೋಡುವೆನು,\nನನಗಾಗಿ ಯೇಸು ಸತ್ತ,\nಎಂದು ನಾ ನಂಬುವೆನು." },
  232: { title: "ನನ್ನಂಥ ಮಗ ರಕ್ಷಿಸ", lyrics: "1. ನನ್ನಂಥ ಮಗ ರಕ್ಷಿಸ\nಕ್ರಿಸ್ತೇಸು ಪ್ರಾಣ ಕೊಡಲು\nಸುಂದರವಾದ ಲೋಕವ\nಬಿಡುವದು ಆಶ್ಚರ್ಯವು.\n2. ಆತನು ಹುಟ್ಟಿ ಬಂದನು ;\nಈ ಮಾತು ನಿಜವಾಗಿದೆ\nಆತನು ಕಷ್ಟದಿಂದಲೂ\nಪ್ರೀತಿಯ ಸೇವೆ ಮಾಡಿದ.\n3. ನನ್ನಂಥ ಮಗ ಆತನು\nತನ್ ಕಡೆ ಸೇರಿಸಲಿಕ್ಕೆ\nಅಮೂಲ್ಯ ಪ್ರೀತಿಯಿಟ್ಟನು\nಆಶ್ಚರ್ಯವೇ! ಆಶ್ಚರ್ಯವೇ !\n4. ನನ್ನನ್ನು ರಕ್ಷಿಸಲಿಕ್ಕೆ\nಕ್ರೂಜೆಯ ಸಾವಿನ ಬಗ್ಗೆ\nನಾ ಯೋಚಿಸಿರುವಾಗಲೇ\nಆಶ್ಚರ್ಯವಾಗಿ ಕಾಣುತ್ತೆ.\n5. ಆತನ ಮರಣವನ್ನು\nಕಣ್ಣಾರೆ ನೋಡುತ್ತಿದ್ದರೆ\nಆ ಪ್ರೀತಿಯ ಸಂಪೂರ್ಣತೆ\nನೋಡಲಿಕ್ಕು ಅಸಾಧ್ಯವು.\nದೇವರ ಮತ್ತು ಕ್ರಸತನ ಪ್ರೀತಿಯು\nಆತನ ಪ್ರೀತಿ ಎಷ್ಟಿದೆ!\nನನ್ನೇ ಸ್ನೇಹಿಸಿದನು ;\nನಾನಾತನನ್ನು ನಂಬುವೆ,\nಆತನ ಪ್ರೀತಿಸುವೆನು.\n7. ಓ, ಪ್ರಿಯ ಕರ್ತಾ, ನಿನ್ನನ್ನು\nನಾ ಪ್ರೀತಿ ಮಾಡಿ ಬರುವೆ ;\nನನ್ನನು ನಿನ್ನ ಕಡೆಗೂ\nನೀನೆಳೆ, ಯೇಸು ಸ್ವಾಮಿಯೇ !\nಯಜ್ಞ ಬಲಿಯಿಲ್ಲಾ\nಯಜ್ಞ, ಬೆಂಕಿ ಕುರಿ ಹೊಗೆ,\nಯಾವದೂ ಬೇಡವೇ ;\nಪಾಪದ ಶಿಕ್ಷೆ ಹೋಗಲಿಕ್ಕೆ\nಬೇರೆ ಮಾರ್ಗವಿದೆ, ಕ್ರಿಸ್ತನ ರಕ್ತವೇ.\n2. ಕ್ರಿಸ್ತನ ರಕ್ತವೇ!\nಆ ರಕ್ತದಿಂದಲೇ\nನಮ್ಮಾತ್ಮ ಶುದ್ಧವಾಯಿತು,\nವಿಜಯ ಸಿಕ್ಕುತ್ತೆ,\nನರಕ ಪಾಪ ಶಿಕ್ಷೆಯಿಂದಲೇ\nರಕ್ಷಣೆಯಾಯಿತು, ನಮಗೆ ಜಯವೇ.\n3. ಆ ಲೋಕದಿಂದಲೇ\nಇಳಿದ ಕೃಪೆಯು\nನಮ್ಮಪರಾಧ ಮುಚ್ಚಿದೆ\nಎಷ್ಟೋ ಆನಂದವು ;\nತೈಯೇಕ ಪ್ರೀತಿ ವ್ಯಕ್ತವಾಗಿದೆ ;\nಪಿತಪುತ್ರ ಆತ್ಮನಿಗೆ ಸುಸ್ತೋತ್ರವೇ.\n4. ನಿರೀಕ್ಷೆಯಾಗಿದೆ\nಸಂತೋಷದಿಂದಲೇ\nಭವಿಷ್ಯ ಕಾಲ ಕಾಯುವೆ\nಕ್ರಿಸ್ತಾಗಮನವ\nಭೂಯಾತ್ರೆ ನಷ್ಟವೆಲ್ಲಾ ತೀರುತ್ತೆ\nಆ ದಿನ ಬರಲಿ ! ಎಂಥಾ ನಿರೀಕ್ಷೆಯೇ." },
  234: { title: "ಪಾಪಿಯ ಮಿತ್ರನೇ!", lyrics: "1. ಪಾಪಿಯ ಮಿತ್ರನೇ!\nನಿನ್ನನ್ನು ನಂಬುವೆ!\nಕ್ರಿಸ್ತೇಸು ನಮ್ಮ ಆಶ್ರಯ\nನನ್ನನ್ನು ಬಿಡನು.\n2. ನಿನ್ನಾಮ ಕೇಳಲು\nಆತನು ಮೆಚ್ಚುವ ;\nನಿನ್ನಿಂದಲಾಶೀರ್ವಾದವ\nಕ್ರಿಸ್ತೇಸು ಕೊಡುವ.\n3. ನಿನ್ನೀತಿ ವಸ್ತ್ರವು\nಎನ್ ಪಾಪ ಮುಚ್ಚಿತು.\nನಿನ್ನಿಂದ ಪರಲೋಕವ\nನಾ ಸೇರುವವನು.\n4. ನನ್ನನ್ನು ರಕ್ಷಿಸ\nನೀ ಶಾಪ ತಿಂದಿದ್ದಿ\nಪಾಪದ ಶಿಕ್ಷೆಯಿಂದಲೂ\nಸ್ವಾತಂತ್ರ್ಯ ಕೊಟ್ಟದ್ದೀ.\n5. ಪಾಪಿಯ ಮಿತ್ರನೇ!\nನಿನ್ನ ಕೊಂಡಾಡುವೆ ;\nನನ್ನಂತೆ ಯಾರು ನಿನ್ನನ್ನು\nಸ್ತೋತ್ರಿಸುವವರೇ ?\n6. ನಿನ್ನಿಂದ ಸ್ವರ್ಗದೊಳ್\nನಿನ್ನೀತಿಯಲ್ಲಿಯೇ,\nನಾ ನಿಂತು ಹರ್ಷಿಸುವೆನು\nಸದಾ ಕೊಂಡಾಡುವೆ.\n7. ಅಲ್ಲಿ ನಾ ನಿನಗೆ\nಅಭ್ಯಂತ್ರವಿಲ್ಲದೆ\nಸಂಪೂರ್ಣವಾಗಿ ಸ್ತುತಿಸಿ\nನಾ ಪ್ರೀತಿ ಮಾಡುವೆ." },
  235: { title: "ನಮ್ಮನ್ನು ರಕ್ಷಿಸಲಿಕ್ಕೆ", lyrics: "1. ನಮ್ಮನ್ನು ರಕ್ಷಿಸಲಿಕ್ಕೆ\nಪಟ್ಲದ ಹೊರಗೂ\nಕ್ರಿಸ್ೈೇಸು ಕಸಲ್ವಾರಿಯಲ್ಲಿಯೇ\nಕ್ರೂಜಿಸಲ್ಪಟ್ಟನು.\nಆತನ ಬಾಧೆ ಎಷ್ಟೆಂದು\nಯಾರೂ ತಿಳಿಯರು ;\nಆದೆಲ್ಲಾ ನಮಗಾಗಿಯೇ\nಸಹಿಸಿಕೊಂಡನು.\n3. ಪಾಪದ ಪರಿಹಾರವು\nಉಂಟಾಗುವಂತೆಯೂ\nತಾ ಶಾಪಗ್ರಸ್ಥನಾದನು ;\nಗೋರಿಗೆ ಬಿದ್ದನು.\n4. ಇನ್ನಾರು ನಮಗೋಸ್ಕರ\nಸ್ವಪ್ರಾಣ ಕೊಟ್ಟರೂ\nಪಾಪದ ಶಿಕ್ಷೆಯೆಂದಿಗೂ\nಹೋಗದ ಹಾಗಿತ್ತು.\n5. ನಾವೆಷ್ಟು ಪ್ರೀತಿಸಿದರೂ,\nಆತನು ಯೋಗ್ಯನೇ,\nದೇವರ ಮತ್ತು ಕ್ರಿಸ್ತನ ಪ್ರೀತಿಯು\nನಾವೆಲ್ಲವನ್ನು ಕೊಟ್ಟರೂ\nಅದಿನ್ನು ಸಾಲದು." },
  236: { title: "ಮರಣ ಮುಟ್ಟದಂತೆಯೇ", lyrics: "1. ಮರಣ ಮುಟ್ಟದಂತೆಯೇ\nಐಗುಪ್ತದಲ್ಲಿಯೂ\nದೇವರು ರಕ್ತದಿಂದಲೇ\nಸಂರಕ್ಷಿಸಿದನು.\nಪಲ್ಲವಿ\nರಕ್ತವ ನೋಡುವಾಗಲೇ\nನಿನ್ನನ್ನು ಬಿಡುವೆ\nಎಂಬುವ ದಿವ್ಯ ಮಾತನ್ನೇ\nನಾ ನಂಬಿಕೊಳ್ಳುವೆ.\n2. ಪಾಪದ ಶಿಕ್ಷೆ ನಮಗೆ\nಉಂಟಾಗದಂತೆಯೂ\nಸ್ವರಕ್ತ ಚೆಲ್ಲಿ ಯೇಸುವೇ\nಸಂರಕ್ಷಿಸಿದನು.\n3. ಆ ದಿವ್ಯ ರಕ್ತದಿಂದಲೇ\nನೀತಿಯ ಕೋಪದಿ\nಅಮೂಲ್ಯವಾದ ರಕ್ಷಣೆ\nನಮಗೆ ಸಿಕ್ಕುತ್ತೆ.\n4. ನಮ್ಮೆಲ್ಲಾ ಶಾಪ ಯೇಸುವು\nಸಹಿಸಿ ಸತ್ತನು,\nನಾವೆಂದೂ ಕೊಡಲಾಗದ\nಆ ಋಣ ಕೊಟ್ಟನು.\n5. ದೇವರ ಮಾತಿನಂತೆಯೇ\nನಡೆಯುವವರು\nಆ ನ್ಯಾಯ ದಿನದಲ್ಲಿಯೇ\nಅಂಜಿಕೆ ಪಡರು.\nದೇವರ ಮತ್ತು ಕ್ರಿಸ್ತನ ಪ್ರೀತಿಯು" },
  237: { title: "ರಕ್ಷಕಾ! ಕ್ರೂಜೆಯಲ್ಲಿ", lyrics: "ರಕ್ಷಕಾ! ಕ್ರೂಜೆಯಲ್ಲಿ\nತೋರಿದ ಪ್ರೀತಿಯು\nಹೆಚ್ಚಾಗಿ ನನ್ನ ಲಕ್ಷ್ಯಕ್ಷೆ\nಬರುವಂತೆ ಮಾಡು.\nಪಲ್ಲವಿ\nಹೆಚ್ಚಾಗಿ ತಿಳುಕೊಳ್ಳ\nನೀ ಮಾಡು ಕರ್ತನೇ;\nಪಾಪದ ಶಿಕ್ಷೆ ತಪ್ಪಿತು\nಆ ಪ್ರೀತಿಯಿಂದಲೇ.\n2. ಆ ಕ್ರೂಜೆಯಲ್ಲಿ ಮೊಳೆ\nಹಿಡಿಯಲಾಗದು ;\nನನ್ನಲ್ಲಿಟ್ಟಂಥ ಪ್ರೀತಿಯೇ\nನಿನ್ನಲ್ಲಿ ಹಾಕಿತು.\nಆಶ್ಚರ್ಯಗಳಾಶ್ಚರ್ಯ\nಆ ರಕ್ತದಿಂದಲೇ\nಎನ್ ಪಾಪವೆಲ್ಲಾ ಮನ್ನಣೆ\nಸದಾ ಉಂಟಾಗುತ್ತೆ.\n4. ನಾ ನಿನ್ನ ಪ್ರೀತಿ ಮಾಡ\nನನ್ನನ್ನು ನಡಿಸು ;\nನಿನ್ನ ಮುಖಾಂತರವಾಗಿ\nವಿಜಯ ಸಿಕ್ಕಿತು!" },
  238: { title: "ಲೋಕದ ಮೇಲೆ ದೇವರು", lyrics: "1. ಲೋಕದ ಮೇಲೆ ದೇವರು\nಪ್ರೀತಿಯನ್ನಿಟ್ಟನು,\nಸ್ವಪುತ್ರನನ್ನು ಕೊಟ್ಟನು\nರಕ್ಷಿಸಲೆಮ್ಮನ್ನು\nಪಲ್ಲವಿ\nಎಂಥಾ ಶ್ರೇಷ್ಠ ಪ್ರೀತಿಯನ್ನೇ\nರಕ್ಷಿಸಲೆಮ್ಮನ್ನು\nಕ್ರಿಸ್ತೇಸು ಕಲ್ವಾರಿಯಲ್ಲಿಯೇ\nತೋರ್ಪಡಿಸಿದನು.\n2. ಸತ್ತೆದ್ದಾ ರಕ್ಷಕನನ್ನು\nಸ್ವೀಕರಿಸಿದೆವು ;\nಆ ರಕ್ತದಿಂದ ನಮಗೂ\nರಕ್ಷಣೆ ಸಿಕ್ಕಿತು.\n3. ಭೂಲೋಕದಲ್ಲಿ ಈಗಲೇ\nಆ ಜೀವ ಸಿಕ್ಕುತ್ತೆ\nಸ್ವರ್ಗದ ಲೋಕದಲ್ಲಿಯೂ\nಸಂಪೂರ್ಣವಾಗುತ್ತೆ.\n4. ಸೈತಾನನ ಉಪಾಯವ\nವಿಶ್ವಾಸದಿಂದಲೇ\nಕ್ರಿಸ್ತನ ಬಲದೊಡನೇ\nಸೋಲಿಸಿ ಬರುವೆ." },
  239: { title: "ಪಾಪಿಯು ತನ್ನ ಕಡೆಗೂ", lyrics: "1. ಪಾಪಿಯು ತನ್ನ ಕಡೆಗೂ\nಅನ್ಯೋನ್ಯವಾಗಲಿ\nಅಮಿತವಾದ ಪ್ರೀತಿಯ\nದೇವ ತೋರಿಸಿದ.\nಪಲ್ಲವಿ\nಮಕ್ಕಳೆಂಬ ಹೆಸರನ್ನು\nನಮಗೆ ಕೊಡುವದರಲ್ಲಿ\nತಂದೆಯು ಎಂಥಾ ಪ್ರೀತಿ\nನಮ್ಮ ಮೇಲೆ ಇಟ್ಟನು.\n2. ಕ್ರಿಸ್ತನ ರಕ್ತದಿಂದಲೇ\nದೇವರ ಹತ್ರವೇ\nಕೊಂಡಾಡಿ ಸೇರುತ್ತಿರುವೆ\nಸಂತೋಷದಿಂದಲೇ.\n3. ಆ ಲೋಕದಲ್ಲಿಯಿರ್ವದು\nಎಷ್ಟೋ ಸಂತೋಷವೇ\nಸ್ವಾಮಿಯ ರೂಪದಲ್ಲಿಯೂ\nಸದಾ ನಾನಿರುವೆ.\n4. ಅಂಥ ನಿರೀಕ್ಷೆಯವನು\nಎಂಥವನಾಗುವ ?\nತನ್ ನಡೆ ನುಡಿಯಿಂದಲೂ\nಚೆನ್ನಾಗಿ ಇರುವ." },
  240: { title: "ಎಚ್ಚರವಾಗೆನ್ನಾತ್ಮವೇ !", lyrics: "1. ಎಚ್ಚರವಾಗೆನ್ನಾತ್ಮವೇ !\nರಕ್ಷಕನನ್ನು ಸ್ತುತಿಸು,\nಆತನ ಕೃಪೆ ಎಷ್ಟಿದೆ,\nಎನ್ನಾತ್ಮ ತಿಳುಕೊಳ್ಳದು." },
  241: { title: "ಸ್ವಾಮಿ ಬರುವಾತನು !", lyrics: "1. ಸ್ವಾಮಿ ಬರುವಾತನು !\nಅತ್ಯಾಮೂಲ್ಯ ಮಾತಿದು\nನಂಬುವವರೆಲ್ಲರೂ\nಹರ್ಷಗೊಳ್ಳತಕ್ಕದ್ದು;\nಆತ ಬಂದು ನಮ್ಮನ್ನು\nಸ್ವರ್ಗಕ್ಕೇರಿಸುವನು.\n2. ನಮ್ಮ ಅತಿ ಪ್ರಿಯರು\nಸಾಯುತ್ತಿರುವಾಗಲೂ\nಕ್ರಿಸ್ತನ ಪುನರುತ್ಥಾನವೂ ಪುನರಾಗಮನವೂ\n2. ಪಾಪದ ದೆಸೆಯಿಂದಲೇ\nತಪ್ಪಿತಸ್ಥನಾದ ನನ್ನನ್ನು\nಕ್ರಿಸ್ತೇಸು ಕೃಪೆಯಿಂದಲೇ\nಕೈ ಹಾಕಿ ರಕ್ಷಿಸಿದನು.\n3. ವೈರಿಗಳೆನ್ನ ಸುತ್ತಲು\nನನ್ನನ್ನು ಕೆಡಿಸಲಿಕ್ಕೆ\nಬಂದಾಗ್ಯೂ ದೊಡ್ಡ ಕೃಪೆಯು\nನನ್ನನ್ನು ಭದ್ರ ಕಾಯುತ್ತೆ,\n4. ಮೋಡದ ಹಾಗೆ ಸಂಕಟ\nಆವರಿಸುತ್ತಾ ಬಂದರೂ,\nಕ್ರಿಸ್ತೇಸು ಕೃಪೆ ಮೂಲಕ\nಸಹಾಯ ಕೊಟ್ಟು ಬಂದನು.\n5. ಆಗಾಗ್ಯೆ ಪಾಪದಿಂದಲೇ\nನಾ ದಾರಿ ಬಿಟ್ಟು ಹೋದರೂ,\nಆತನ ಕೃಪೆ ನನ್ನನ್ನೇ\nಧಿಕ್ಕಾರ ಮಾಡಲಾರದು.\nಕ್ರಿಸ್ತನ ಪುನರುತ್ಥಾನವೂ ಪುನರಾಗಮನವೂ\nದುಖ ಪಡುವಾಗಲೂ\nನೆನಪು ಮಾಡುವೆವು.\nಸ್ವಾಮಿ ಬರುವಾತನು!\nತಾಳಿಕೊಳ್ಳುತ್ತಾ ಇರು!\n3. ಸುತ್ತಲಾಗಿ ಕತ್ತಲು\nತುಂಬಿಕೊಂಡು ಇದ್ದರೂ ;\nಲೋಕ ದ್ವೇಷಿಸಿದರೂ\nಎಷ್ಟು ಕಷ್ಟ ಬಂದರೂ\nಸ್ವಾಮಿ ಬರುವಾತನು!\nತಾಳಿಕೊಳ್ಳುತ್ತಾ ಇರು!\nಕ್ರಿಸತನ ಪುನರುತ್ಥಾನವೂ ಪುನರಾಗಮನವೂ\nರೊಟ್ಟಿ ತಿಂದು ಪಾತ್ರೆಯಂ\nಸ್ವಾಮಿಯ ಮರಣವಂ ಪಾನ ಮಾಡಿಕೊಳ್ಳುವೆ.\nಸ್ವಾಮಿ ಬರುವಾತನು! ಜ್ಞಪ್ತಿ ಮಾಡಿಕೊಳ್ಳುವೆ,\nನಾವಾರಾಧಿಸುವೆವು." },
  242: { title: "ನೋಡಿ ಭಕ್ತರೆಂಥ ನೋಟ!", lyrics: "1. ನೋಡಿ ಭಕ್ತರೆಂಥ ನೋಟ!\nದುಬರಿತ ಮನುಷ್ಯನು\nಯುದ್ಧದಲ್ಲಿ ವೀರನಾಗಿ\nಜಯಶಾಲಿಯಾದನು !\nಘನ ಮಾನ ಸ್ತುತಿ ಸ್ತೋತ್ರ\nಆತನ ಕಿರೀಟವು !\n2. ಸ್ವರ್ಗದಲ್ಲಿ ದೂತರೆಲ್ಲಾ\nಯೇಸುವ ಕೊಂಡಾಡ್ವರು!\nಸಿಂಹಾಸನರೂಢನಿಗೆ\nಜಯಗೀತೆ ಹಾಡ್ವರು !\nಘನ ಮಾನ ಸ್ತುತಿ ಸ್ತೋತ್ರ\nರಾಜಾಧಿ ರಾಜನಿಗೆ!\n3. ದುಷ್ಟ ಜನ ಮುಳ್ಳು ಮಾಲೆ\nಹಾಕಿ ಗೇಲಿಯಿಟ್ಟರು\nದೇವದೂತ ಭಕ್ತರೆಲ್ಲಾ\nಸ್ತೋತ್ರ ಮಾಡುವವರು\nಘನ ಮಾನ ಸ್ತುತಿ ಸ್ತೋತ್ರ\nಜಯಶಾಲಿ ಕರ್ತಗೆ!\n4. ಕೇಳಿರೆಲ್ಲ ಜಯಧ್ವನಿ\nಸ್ವರ್ಗವೆಲ್ಲಾ ತುಂಬುತ್ತೆ !\nಆತ್ಯುನ್ನತ ಸ್ಥಾನದಲ್ಲಿ\nಯೇಸು ಶೋಭಿಸುವನು!\nಘನ ಮಾನ ಸ್ತುತಿ ಸ್ತೋತ್ರ\nಕರ್ತನಾದ ರಾಜಗೆ!" },
  243: { title: "ಮುಳ್ಳಿನ ಮುಡಿ ಹೊಂದಿದ", lyrics: "1. ಮುಳ್ಳಿನ ಮುಡಿ ಹೊಂದಿದ\nಆ ತಲೆಗೀಗಲೇ\nಅಮೂಲ್ಯವಾದ ಚಿನ್ನದ\nಕಿರೀಟವಿರುತ್ತೆ.\n2. ಸ್ವರ್ಗದ ಮುಖ್ಯ ಸ್ಥಾನವೇ\nಆತಗೆ ಯೋಗ್ಯವು ;\nರಾಜಾಧಿರಾಜನಾತನೇ\nಸ್ತುತ್ಯನು ಎಲ್ಲಕ್ಕೂ.\n3. ಆ ಲೋಕದಲ್ಲಿ ಸರ್ವರೂ\nಆ ಲೋಕದವರೂ\nಆತನ ಪ್ರೀತಿ ತಿಳಿದು\nಭಯವ ಪಡರು.\n4. ಕ್ರಿಸ್ತನ ಶಿಲುಬೆಯಲ್ಲಿ\nನಂಬಿಕೆಯಿಟ್ಟರೆ\nಆತನ ರಕ್ತದಿಂದಲೇ\nವಿಮುಕ್ತಿ ಸಿಕ್ಕುತ್ತೆ.\n5. ಆತನ ಕ್ರೂಜೆ ನಿಮಿತ್ತ\nಬಾಧೆಯ ಪಟ್ಟರೆ\nಸ್ವರ್ಗದ ಲೋಕದಲ್ಲಿಯೂ\nಸಂಪಾದ್ಯವಾಗುತ್ತೆ.\n6. ಕ್ರೂರ ಸಾವು ಆತಗೆ\nಕ್ರೂರದ ಕಷ್ಟವೂ\nಅವುಗಳಿಂದ ನಮಗೆ\nಶಾಶ್ವತ ಭಾಗ್ಯವು." },
  244: { title: "ಯೇಸುವು ತಿರಿಗಿ ಬರುವನು", lyrics: "1. ಯೇಸುವು ತಿರಿಗಿ ಬರುವನು\nಸ್ವರಕ್ತದಿಂದಲೇ ಶುದ್ದಿಸಿದ\nಜನರಿಗಾಗಿಯೇ ಬರುವನು\nಈ ಸತ್ಯ ಸಾರಿರೀಗು\nಪಲ್ಲವಿ\nಯೇಸುವು ತಿರಿಗಿ ಬರುವನು,\nತಿರಿಗಿ ಬರುವನು ;\nಎಲ್ಲೆಲ್ಲೂ ಸಾರಿರೀ ಸುದ್ದಿಯನು\nತಿರಿಗಿ ಬರುವನು.\n2. ಆತನ ಧ್ವನಿಯ ಕೇಳುವರು ;\nಸತ್ತವರೆದ್ದು ಆಕಾಶದಲ್ಲೂ\nಆತನ ಸಂಗಡ ಕೂಡುವರು !\nತಿರಿಗಿ ಬರುವನು.\n3. ಯೇಸುವು ಬಂದು ಸುಶಾಂತಿಯನ್ನು\nಲೋಕಕ್ಕೆ ತಂದಿಟ್ಟು ಆಳುವನು\nಕಣ್ಣೀರು ಹೋಗಿಸಲಿರುವನು ;\nತಿರಿಗಿ ಬರುವನು.\n4. ನಿಜವೇ ಯೇಸುವು ಬರುವನು ;\nತಮ್ಮನ್ನು ಶುದ್ಧಿಸಿಕೊಂಡವರು\nಆತನ ಸಂಗಡ ಕೂಡುವರು ;\nತಿರಿಗಿ ಬರುವನು." },
  245: { title: "ಮುಂಜಾನೆಯಲ್ಲಿ ಕ್ರಿಸ್ತ ಬರುವನು", lyrics: "1. ಮುಂಜಾನೆಯಲ್ಲಿ ಕ್ರಿಸ್ತ ಬರುವನು\nತನ್ನ ಜನರ ಕರಕೊಳ್ಳಬೇಕೆಂದು\nಸ್ವಮಹಿಮೆಯಲ್ಲಿ ಆತನೇ ಬರುವನು\nಬೇಗನೆ ಬರುವನು\nಕ್ರಿಸ್ತನ ಪುನರುತ್ಥಾನವೂ ಪುನರಾಗಮನವೂ\nಪಲ್ಲವಿ\nಶ್ರೀ ಯೇಸು ಸ್ವಾಮಿ!\nಎಂದು ತಿರಿಗಿ ಬರುವಿ ?\nಬರುತ್ತಾನೆ ! ಹಲ್ಲೆಲೂಯ!\nಹಲ್ಲೆಲೂಯ ! ಆಮೆನ್\nಹಲ್ಲೆಲೂಯ ! ಆಮೆನ್\n2. ಮಧ್ಯಾಹ್ನದಲ್ಲೋ ಆತನು ಬರುವನ್ಸು\nಮಧ್ಯರಾತ್ರಿಯೋ ಆತ ಕಾಣಿಸುವನು!\nಸ್ವಜನಕ್ಕಾಗಿ ಆತ ಮಹಿಮೆಯಲ್ಸೂ\nಬೇಗನೇ ಬರುವನು.\n3. ಆ ಲೋಕದಲ್ಲಿ ಇರುವಾತ್ಮಗಳೆಲ್ಲಾ\nಸ್ವಾಮಿಯೊಂದಿಗೆ ಇಳಿದು ಬರುವರು\nಸ್ವಘನವನ್ನು ದರ್ಸಿಕೊಂಡಿರುವನು\nಬೇಗನೇ ಬರುವನು.\n4. ಸದಾನಂದವೇ, ಯೇಸುವೇ ಬರುವನು\nದುಖ, ರೋಗ, ಕಷ್ಟಗಳಿರುವದಿಲ್ಲ\nಈ ಘನದಲ್ಲಿ ಸೇರಿಕೊಂಡಿರುವೆನು ;\nಬೇಗನೆ ಬರುವನು!" },
  246: { title: "ಭೂಲೋಕದವರೀಗ", lyrics: "1. ಭೂಲೋಕದವರೀಗ\nಕ್ರಿಸ್ತನ ನಂಬರು\nಆತನ ಕೊಂಚ ಜನ\nಸ್ವೀಕರಿಸುವರು ;\nಇನ್ನಲ್ಪ ಕಾಲ ಹೋಗಿ\nಆತನು ಬರುವ\nರಾಜ್ಯಾಧಿಕಾರ ವಹಿಸಿ ಬರುವ.\nಸುವಾರ್ತೆಯ ಸೇವೆಗಾಗಿ\nಪಲ್ಲವಿ\nತಾ ರಾಜನಾಗಿ ಬರುವ\nಲೋಕಕ್ಕೆ ಬರುವ\nಪೂರ್ಣಾಧಿಕಾರದಲ್ಲೂ\nಮಹಿಮೆಯಲ್ಲಿಯೂ\nನಿಜವಾಗಿ ಬರುವನು\nಆಶ್ಚರ್ಯವಾಗುತೆ\nರಾಜನಾಗಿ ಲೋಕದಲ್ಲಿ ಬರುವ.\nಆಕಾಶ ನಿರ್ಮಲವಾಗಿ\nಶೋಭಾಯವಾಗುತ್ತೆ\nಆತನ ಭಕ್ತರೆಲ್ಲಾ\nಸಂತೋಷಿಸುವರು\nಕ್ರಿಸ್ತನು ಮೈಮೆಯಲ್ಲಿ\nಕಂಗೊಳಿಸುವನು ;\nರಾಜ್ಯಾಧಿಕಾರ ವಹಿಸಿ ಬರುವ.\nಸುವಾರ್ತೆಯ ಸೇವೆಗಾಗಿ" },
  247: { title: "ಸ್ವಾಮಿಯ ಬಟ್ಟೆ ಮುಟ್ಟಿದ ಸ್ತ್ರೀಯು", lyrics: "1. ಸ್ವಾಮಿಯ ಬಟ್ಟೆ ಮುಟ್ಟಿದ ಸ್ತ್ರೀಯು\nಮುಟ್ಟಿದ ಕೂಡಲೇ\nಬಂದು ನೂಕಿ ಜನಗಳಲ್ಲಿಯೂ\nನಂಬಿ ನಿಂತಿದ್ದಳು.\nಪಲ್ಲವಿ\nಆ ಬಟ್ಟೆಶೆರಗವನ್ನು\nಮುಟ್ಟಿದ ಕೂಡಲೇ,\nಸುಶಕ್ತಿ ಬಂದು ನಿನ್ನಲ್ಲಿ\nಗುಣವ ಮಾಡುತ್ತೆ !\n2. ಕ್ರಿಸತ್ರೈಸು ಬಂದು ನಿಂತಿದ್ದನೆಂದು\nತಿಳುಕೊಂಡಾಗಲೂ\nಆ ಕ್ಷಣ ನುಗ್ಗಿಸ್ವಾಮಿಯ ಮುಟ್ಟಿ\nಗುಣ ಹೊಂದಿದಳು.\n3. ನಮ್ಮುಂದೆ ಪೂರ್ಣಾನಂದ\nವಿಜಯವಾಗುತ್ತೆ\nನಮ್ಮ ಹಿಂದೆ ದುಖವೆಲ್ಲಾ\nಮರೆತು ಹೋಗುತ್ತೆ\nನಮ್ಮ ರಕ್ಷಕನಲ್ಲಿ\nಸಂತೋಷವಾಗುತ್ತೆ\nರಾಜ್ಯಾಧಿಕಾರ ವಹಿಸಿ ಬರುವ.\n4. ಆ ದಿನ ಬಯಸುತ್ತೇವೆ\nಬರಲಿ ಬೇಗನೆ ;\nಆ ದಿನಕ್ಕಾಗಿ ಸೇವೆ\nಮಾಡುತ್ತಾ ಬರುವೆ\nನಂಬೀಗ ಅವಿಶ್ವಾಸಿ\nಬೇಗನೆ ನಂಬಿರಿ\nರಾಜ್ಯಾಧಿಕಾರ ವಹಿಸಿ ಬರುವ.\n3. ಆತನು ಬಂದಾ ಹೆಂಗಸ ನೋಡಿ.\nಧೈರ್ಯವ ಕೊಟ್ಟನು.\nಆ ಮಾತು ಕೇಳಿದ ಕ್ಷಣವಾಗಿ\nಸಂತೋಷವಾಯಿತು." },
  248: { title: "ಯೇಸು ನಿನ್ನ ಹತ್ರ", lyrics: "1. ಯೇಸು ನಿನ್ನ ಹತ್ರ\nನಾನು ಬರುವೆ ;\nನಾನು ಕೆಟ್ಟು ಹೋಗಿ\nದೂರ ಹೋಗಿದ್ದೆ;\nಯಾರು ನಿನ್ನ ಹಾಗೆ\nರಕ್ಷಿಸುವರು ?\nಯಾರು ನಿನ್ನ ಹಾಗೆ\nಪ್ರಾಣ ಕೊಟ್ಟರು ?\nಪಲ್ಲವಿ\nಯೇಸು ನಿನ್ನ ಹತ್ರ\nನಾನು ಬರುವೆ ;\nನಾನು ಕೆಟ್ಟುಹೋಗಿ\nದೂರ ಹೋಗಿದ್ದೆ\n2. ಯೇಸು ನಿನ್ನ ಮಾತ್ರ\nನಾನು ನಂಬುವೆ ;\nನಿನ್ನ ನಡೆ ನುಡಿ\nಧ್ಯಾನ ಮಾಡುವೆ\nಬೇರೆ ಬೇರೆ ರೋಗ\nವಾಸಿ ಮಾಡಿದೀ.\nಯಾವ ಪಾಪಿಯನ್ನು\nತಳ್ಳದೆ ಇದ್ದೀ.\n3. ಯೇಸು ನಿನ್ನ ನಂಬ\nಯಾರೂ ಬಂದರೂ,\nನಿನ್ನ ಬಳಿಯಿಂದ\nತಳ್ಳಲ್ಪಡರು ;\nನಿನ್ನನೆಂದೂ ನಾನು\nನೋಡದಿದ್ದರೂ,\nನಿನ್ನನ್ನು ನಾ ನಂಬಿ\nಬರುವವನು.\n4. ಯೇಸು ನಾನು ಇಂದು\nಭಯವಿಲ್ಲದೆ\nನಿಜವಾಗಿ ನಂಬಿ\nಬರುತ್ತಿರುವೆ\nನಿಜಾಶ್ರಯವಾಗಿ\nನಿನ್ನ ರಕ್ತವೇ ;\nಅದನ್ನು ನಾ ನಂಬಿ\nಬರುತ್ತಿರುವೆ.\nಸುವಾರ್ತೆಯ ಸೇವೆಗಾಗಿ" },
  249: { title: "ಎಲ್ಲಾ ಪಾಪಿಗಳನ್ನು", lyrics: "1. ಎಲ್ಲಾ ಪಾಪಿಗಳನ್ನು\nಯೇಸು ರಕ್ಷಿಸುವನು;\nಯಾವ ದೋಷವಿದ್ದರೂ\nಆತ ಮನ್ನಿಸುವನು.\nಪಲ್ಲವಿ\nಹಾಡಿರೀಗ ಭಕ್ತರೇ!\nಯೇಸು ರಕ್ಷಿಸುವನು\nಹೇಳಿರೆಲ್ಲಾ ಜನಕ್ಕೆ\nಈ ಆಮಂತ್ರಣವನ್ನು\n2. ಬನ್ನಿರೆಲ್ಲಾ ಹತ್ರಕ್ಕ\nಮನೋತೃಪ್ತಿಯಾಗುತ್ತೆ\nಎಂಥಾ ಪಾಪಿಯಾದರೂ\nಯೇಸು ಸೇರಿಸುವನು.\n3. ನಂಬಿಕೊಂಡು ಬಂದೆನು,\nಪಾಪಹರಿಸಿದನು ;\nಪಾಪಿಗಾಗಿ ಸತ್ತನು ;\nಯೇಸು ಸೇರಿಸುವನು.\n4. ಎಂಥಾ ಕಡುಪಾಪಿಯೂ\nಆತ ನಂಬಿಕೊಂಡರೂ\nನಿತ್ಯಜೀವ ದಾನವ\nಕ್ರಿಸ್ತನಿಂದ ಹೊಂದುವ." },
  250: { title: "ಹಾ! ಎಂಥಾ ಸ್ವಾಮಿ!", lyrics: "1. ಹಾ! ಎಂಥಾ ಸ್ವಾಮಿ!\nಪ್ರೀತಿಯಿಂದಲೂ\nನನ್ನನ್ನು ರಕ್ಷಿಸಲು ಬಂದನು,\nಆತನ್ನನಂಬುವವರೆಲ್ಲರ್ಗೂ\nಶಾಶ್ವತ ಜೀವವು.\nಸುವಾರ್ತೆಯ ಸೇವೆಗಾಗಿ\nಪಲ್ಲವಿ\n‘ಸತ್ಯವೇ, ನಿಜವೇ,\" ಸ್ವಾಮಿ\nಅಂದನು\n“ಸತ್ಯವೇ, ನಿಜವೇ,\"\nತಪ್ಪಿ ಹೋಗದು\nನನ್ನನ್ನು ನಂಬುವವರೆಲ್ಲರ್ಗೂ\nಶಾಶ್ವತ ಜೀವವು.\n2. ಪಾಪದ ಋಣವನ್ನು ಆತನು\nಸ್ವಪ್ರಾಣ ಕೊಟ್ಟು ತೀರಿಸಿದನು,\nಆತನ್ನನಂಬುವವರೆಲ್ಲರ್ಗೂ\nಶಾಶ್ವತ ಜೀವವು.\nಅಯೋಗ್ಯನಾದ ನಾನು ಅಂಜೆನು ;\nನಂಬುವ ಪಾಪಿಯಾಗಿ ಬಂದರೂ,\nನಂಬಿಕೆಯಿಟ್ಟು ನನಗೀಗಲೂ\nಶಾಶ್ವತ ಜೀವವ !\nಒಡವನಾಗಿ ನಾನು ಬಂದರೂ,\nನನ್ನು ಆತನೆಂದೂ ತಳ್ಳನು\nಆತನ ಮಾತಿನಂತೆ ಕೊಡುವ\nಶಾಶ್ವತ ಜೀವವ!" },
  251: { title: "ಪಾಪದ ಭಾರ ಕ್ರಾಂತರೇ", lyrics: "1. ಪಾಪದ ಭಾರ ಕ್ರಾಂತರೇ\nಬನ್ನಿರಿ ಈಗಲೇ\nಕರ್ಶನ ಮಾತು ನಂಬಿರಿ\nಶಾಚಿಯ ಹೊಂದಿರಿ.\nಪಲ್ಲವಿ\nನಂಬಿರೀಗ, ನಂಬಿರೀಗ,\nನಂಬಿರೀಗಲೇ !\nಈಗ ಯೇಸು ನಿಮ್ಮನ್ನೆಲ್ಲ\nರಕ್ಷಿಸುವನು.\n2. ಆ ಪಾಪ ಭಾರ ಹರಿಸ\nಸ್ವರಕ್ತ ಚೆಲ್ಲಿದ\nಈ ತೀರ್ಥದಲ್ಲಿ ನಿಮ್ಮನ್ನೀಗ\nಶುದ್ಧ ಮಾಡುವ.\n3. ಯೇಸು ತಾನೇ ಸತ್ಯ ಮಾರ್ಗ\nಆಗಿದ್ದಾನಲ್ಲವೇ !\nಸಾವಕಾಶ ಮಾಡಬೇಡ\nನಂಬಿ ಈಗಲೇ !\n4. ಕ್ರಿಸ್ತೇಸುವಿನ ಜನರೊಳ್\nಸೇರಿರಿ ಈಗಲೇ\nಆ ಸತ್ಯ ಲೋಕ ಭಾಗ್ಯದೊಳ್\nಸ್ಥಳವ ಹೊಂದಿರಿ." },
  252: { title: "ನಮಗೀಗಲೇ ತೋರುವ", lyrics: "1. ನಮಗೀಗಲೇ ತೋರುವ\nರಕ್ತ ಬುಗ್ಗೆ ಕೊಂಡಾಡುವೆ ;\nಬುಗ್ಗೆ ತೋರಿಸಿದ್ಯೇಸುವ\nನಾನು ಸ್ತೋತ್ರಿಸುತ್ತಿರುವೆ ;\nನಾನು ದಾರಿ ಬಿಟ್ಟವನು.\nಎಷ್ಟೋ ದೂರ ಹೋಗಿದ್ದೆನು\nದಿವ್ಯವಾದೀ ಬುಗ್ಗೆಯಲ್ಲೆ\nನಾನು ಶುದ್ಧನಾಗಿರುವೆ.\nಪಲ್ಲವಿ\nಶುದ್ಧನಾಗುವೆ, ಶುದ್ಧನಾಗುವೆ,\nಯೇಸುವಿನ ರಕ್ತದಲ್ಲೇ\nನಾನೇ ಶುದ್ಧನಾಗಿರುವೆ.\n2. ಯೇಸು ನನ್ನ ರಕ್ಷಿಸಲು\nಶಿಲುಬೆಯಲ್ಲಿ ಸತ್ತನು ;\nನಿತ್ಯಜೀವವ ಕೊಡಲು\nಮುಳ್ಳು ಮುಡಿಯ ತೊಟ್ಟನು,\nದಿವ್ಯವಾದೀ ತೀರ್ಥದಲ್ಲೇ\nಸ್ನಾನ ಮಾಡಿ ಬರುವೆನು ;\nನಾನೀಗ ಹಿಮಕ್ಕಿಂತಲೂ\nನಿತ್ಯ ಶುದ್ಧನಾಗುವೆನು.\n3. ನನ್ನಲ್ಲಿದ್ದ ಪಾಪವನ್ನು\nನೀನು ಶಿಕ್ಷಿಸ ಬಂದರೆ,\nನಾನು ನಿತ್ಯ ನಾಶದೊಳು\nಸಿಕ್ಕಿ ಬಿದ್ದು ಹೋಗಿದ್ದೆನು\nನಾನು ಕ್ರಿಸ್ತ ಬುಗ್ಗೆಯಲ್ಲೇ\nಶುದ್ಧನಾಗಿ ಬಂದಿರುವೆ\nನಾನು ನಾಶನ ಪಡದೆ\nಸದಾ ಸ್ವರ್ಗದಲ್ಲಿರುವೆನು." },
  253: { title: "ಸ್ವರ್ಗದ ಲೋಕ ಬಿಟ್ಟು", lyrics: "1. ಸ್ವರ್ಗದ ಲೋಕ ಬಿಟ್ಟು\nಬಂದಿದ್ದ ಸ್ವಾಮಿಯ\nಸುಪ್ರೇಮವನ್ನು ಹೇಳು,\nಕೇಳ ಸಂತೋಷವು ;\nಅದನ್ನು ಶುದ್ಧವಾಗಿ\nತಿಳಿಸು ನನಗೆ\nಪಾಪದ ದಾರಿಯಲ್ಲಿ\nನಡೆದು ಬಂದಿದ್ದೆ\nಸುವಾರ್ತೆಯ ಸೇವೆಗಾಗಿ\nಪಲ್ಲವಿ\nಆದಿಯಲ್ಲಿದ್ದಾ ಪ್ರೀತಿ,\nದೇವರ ದಿವ್ಯ ಪ್ರೀತಿ,\nಕ್ರಿಸತಸುವಿನ ಪ್ರೀತಿ\nಮರೆಯದೆ ಹೇಳಿರಿ,\n2. ಕ್ರಿಸ್ತೇಸು ಪಾಪಿಗಾಗಿ\nಸ್ವಪ್ರಾಣ ಕೊಟ್ಟನು\nಎಂಬದು ಶುದ್ಧವಾಗಿ\nನನಗೆ ತಿಳಿಸು\nಅದನ್ನು ಮರ್ಯದಂತೆ\nಆಗಾಗ್ಗೆ ತಿಳಿಸು ;\nಅದನ್ನು ಮನದಲ್ಲೇ\nನಾನಿಟ್ಟುಕೊಳ್ಳುವೆ.\n3. ಅದನ್ನು ಮಿತ್ರನಾಗಿ\nಪಾಪಾತ್ಮಗಳಿಗೆ\nಸುಪ್ರೇಮದಿಂದ ಹೇಳಿ\nನೀ ಬಿಡಬೇಡವೇ.\nನನ್ನ್ನು ಕ್ರಿಸ್ತನಲ್ಲಿ\nಸೇರುವವರೆಗೂ\nಮೇಲಿಂದ ಮೇಲೆ ಹೇಳಿ\nನನ್ನ ಎಚ್ಚರಿಸು.\n4. ಲೋಕದ ನೋಟದಿಂದ\nನಾ ದಾರಿ ಬಿಟ್ಟರೂ,\nನೀ ಬಂದು ಪ್ರೀತಿಯಿಂದ\nನನ್ನ ಎಚ್ಚರಿಸು ;\nಈ ಲೋಕ ಬಿಡುವಾಗ\nಸ್ವರ್ಗೀಯ ಲೋಕಕ್ಕೆ\nನಾ ಸೇರಿ, ಸದಾಕಾಲ\nಅಲ್ಲಿ ವಾಸಿಸುವೆ.\nಸುವಾರ್ತೆಯ ಸೇವೆಗಾಗಿ" },
  254: { title: "ಎಲ್ಲೆಲ್ಲಿಯೂ ಪಾಪದ ಕಾವಳಿತ್ತು", lyrics: "ಎಲ್ಲೆಲ್ಲಿಯೂ ಪಾಪದ ಕಾವಳಿತ್ತು\nಕ್ಿಸತ್ರೆು ಸತ್ಯ ಜ್ಯೋತಿ;\nನಮ್ ಮನದೊಳ್ ಆತನು ಹೊಳೆದನು\nಕ್ಿಸ್ರೆು ್ಯ ಜ್ಯೋತಿ\nಪಲ್ಲವಿ\nಜ್ಯೋತಿಗೆ ಬನ್ನಿರನ್ನುತ್ತಾನೆ ;\nನಮ್ಮಲ್ಲಿ ಅದು ಹೊಳೆಯುತ್ತೆ ;\nಕುರುಡನಾಗಿ ಕಾಣುತ್ತೇನೆ !\nಕ್ಿ್ಯೆು ಸತ್ಯ ಜ್ಯೋತಿ.\n2. ವಿಶ್ವಾಸಿಗಳಿಗೆ ಕತ್ತಲೆ ಇಲ್ಲ\nಕ್ರಿಸತ್ರೈಸುವೇ ಸತ್ಯ ಜ್ಯೋತಿ ;\nಆ ಜನರಿಗೀಗ ಪ್ರಕಾಶವೆಲ್ಲಾ!\nಕ್ಿ್ೈಸುವೇ ಸತ್ಯ ಜ್ಯೋತಿ.\n3. ಪಾಪಗಳ ಮಾರ್ಗದ ಜನಗಳೇ\nಕ್ರಿಸತ್ರೈಸುವೇ ಸತ್ಯ ಜ್ಯೋತಿ ;\nನಂಬುವವರಿಗೆ ಗೊತ್ತಾಗುತ್ತೆ\nಕ್ರಿ್ರಸುವೇ ಸತ್ಯ ಜ್ಯೋತಿ.\n4. ಪರಲೋಕದಲ್ಲಿ ಸೂರ್ಯ ಬೇಡವು\nಕ್ಿ್ರಸುವೇ ಸತ್ಯ ಜ್ಯೋತಿ ;\nಆ ಲೋಕದ ಜ್ಯೋತಿಯು ರಕ್ಷಕನು\nಕ್ಿ್ಯೆಸು ಸತ್ಯ ಜ್ಯೋತಿ" },
  255: { title: "ಯೇಸು ನನ್ನಾತ್ಮಾಧಾರವೇ;", lyrics: "1. ಯೇಸು ನನ್ನಾತ್ಮಾಧಾರವೇ;\nನನ್ನನ್ನು ರಕ್ಷಿಸ\nತನ್ನನ್ನು ಕ್ರೂಜೆ ಸಾವಿಗೆ\nಒಪ್ಪಿಸಿಕೊಂಡನು.\nಪಲ್ಲವಿ\nಕ್ರೂಜೆಯ ಮರಣವನ್ನು\nನಾನೆಂದು ಮರ್ಯದಂತೆಯೂ\nಎಂದಿಗೂ ಕ್ರೂಜೆ ನೆನಪು\nಹುಟ್ಟಿಸೆನ್ನಲ್ಲಯ್ಯಾ !\n2. ನೀ ಶಾಪಗ್ರಸ್ತನಾಗಿಯೇ\nಪಾಪದ ಹೊರೆಯ\nಆ ಕ್ರೂರ ಶಿಲುಬೆಯಲ್ಲೇ\nಹೊತ್ತಿದ್ದಿ ಸ್ವಾಮಿಯೇ !\n3. ಆ ಸಾವಿನಿಂದ ನನಗೆ\nರಕ್ಷಣೆಯಾಯಿತು ;\nನಿನ್ನನ್ನು ಪ್ರೀತಿಯಿಂದಲೇ\nನಾ ಸೇವಿಸುವೆನು." },
  256: { title: "ಕ್ರಿಸ್ತನ ರಕ್ತ ತೀರ್ಥ ನಂಬಿಕೊಂಡಿರು ;", lyrics: "1. ಕ್ರಿಸ್ತನ ರಕ್ತ ತೀರ್ಥ ನಂಬಿಕೊಂಡಿರು ;\nಆತನೇ ಶುದ್ಧ ಮಾಡುವನು ;\nಆತ ಪಾಪ ಶಿಕ್ಷೆ ಬಿಡಿಸುವನು,\nಆತನೇ ಶುದ್ಧ ಮಾಡುವನು.\nಪಲ್ಲವಿ\nಬನ್ನಿರಿ – ಈಗಲೇ –\nಕ್ರಿ್ತನ ರಕ್ತದ ತೀರ್ಥಕ್ಕೆ!\nಪಾಪದಿಂದ ಬಂದ\nಕೊಳೆ ತೊಳಿಸಿ,\nಹಿಮಕ್ಕಿಂತ ಬೆಳ್ಳಗಾಗಿರ್ರಿ!\n2. ಆತನ ಜೊತೆಯಲ್ಲಿ ನಡೆಯುವಿಯೋ?\nಆತನೇ ಶುದ್ಧ ಮಾಡುವನು ;\nಪೂರ್ಣವಾಗಿ ಆತನನ್ನು ನಂಬಿಕೋ,\nಆತನೇ ಶುದ್ಧ ಮಾಡುವನು.\n3. ಯೇಸು ಬರುವಾಗ ಸಿದ್ಧವಾದಿಯೋ?\nಆತನೇ ಶುದ್ಧ ಮಾಡುವನು ;\nನಿನ್ನ ಆತ್ಮ ಶುದ್ಧವಾಗಿ ಇಟ್ಟುಕೋ.\nಆತನೇ ಶುದ್ಧ ಮಾಡುವನು.\n4. ಹೊಲಸಾದ ಪಾಪವನ್ನು ಬಿಡಿರಿ\nಆತನೇ ಶುದ್ಧಮಾಡುವನು\nದಿವ್ಯವಾದ ತೀರ್ಥವನ್ನು ನಂಬಿರಿ\nಆತನೇ ಶುದ್ಧ ಮಾಡುವನು." },
  257: { title: "ನಿನ್ನ ಪ್ರೀತಿಸುವ", lyrics: "1. ನಿನ್ನ ಪ್ರೀತಿಸುವ\nಒಬ್ಬನಿದ್ದಾನೆ\nನೀನು ಆತನನ್ನು\nತಳ್ಳಬೇಡವೇ!\nದುಖುದಿಂದ ಆತ\nನಿಲ್ಲುವಾಗಲೂ,\nಬೇಗ ಬಂದು ಆತನ\nನಂಬೀಗಲೂ.\nಪಲ್ಲವಿ\nನಿನ್ನ ಪ್ರೀತಿಸುವ\nಒಬ್ಬನಿದ್ದಾನೆ\nನೀನು ಆತನನ್ನು\nತಳ್ಳಬೇಡವೇ!\nಸುವಾರ್ತೆಯ ಸೇವೆಗಾಗಿ\n2. ಪ್ರೀತಿಯಿಂದ ನಿಂತು\nಕರೆಯುತ್ತಾನೆ.\nನಿನ್ನ ಪಾಪ ಹೆಚ್ಚು\nತೋರಿ ಬಂದರೆ\nಆತ ಕೃಪೆಯಿಂದ\nಮನ್ನಿಸುವನು ;\nನೀನು ಯಾಕೆ ತಾಮಸ\nಮಾಡಬೇಕು.\n3. ಯೇಸು ನಿನ್ನ ಹತ್ರ\nಕಾಯುವಾಗಲೂ,\nಪಶ್ವಾತ್ತಾಪದಿಂದ\nಎದ್ದು ಬಂದಿರು ;\nಆತ ಸದಾಕಾಲ\nರಕ್ಷಿಸುವನು\nಬೇಗ ಬಂದು ಆತನ\nನಂಬೀಗಲೂ." },
  258: { title: "ವಿಮೋಚನೆ! ಎಂಥಾ ಸುವಾರ್ತೆ", lyrics: "1. ವಿಮೋಚನೆ! ಎಂಥಾ ಸುವಾರ್ತೆ\nಯೆಹೋವ ನಂಗೆ ಕೊಟ್ಟನು\nಕ್ರಿಸ್ಯೇಸು ಪಾಪಿಯ ಋಣವ\nಸ್ವರಕ್ತದಿಂ ತೀರಿಸಿದ.\nಪಲ್ಲವಿ\nಈ ವಾಕ್ಯವ ನಂಬಲು ಬನ್ನಿ;\nಆ ವಾರ್ತೆಯು ಸತ್ಯಮಾತೇ !\nಆ ರಕ್ಷಕನ ಮೇಲೆ ನಂಬಿ\nವಿಮೋಚನೆ ಸಿಕ್ಕುತ್ತದೆ.\nಸುವಾರ್ತೆಯ ಸೇವೆಗಾಗಿ\nಮರಣಕ್ಕೆ ಬದಲು ಜೀವ\nಸುಪ್ರೇಮದಿಂ ಕೊಡುವನು\nವಿಶ್ವಾಸಿಯ ಮನವ ಈಗ\nಕ್ರಸತ್ರೈಸು ಶುದ್ಧಿಸುವನು.\nದುರಾಶೆಯ ತ್ಯಜಿಸಿಬಿಡು\nಆ ಕಾರ್ಯವ ಮಾಡಿಸಲು\nನಮಗೆ ಅಸಾಧ್ಯವಿದ್ದಾಗ್ಯೂ\nಕ್ರಿಸ್ರೈಸು ಕಾಯುವನು.\n4. ಓ ಬನ್ನಿರಿ ಕ್ರಿಸ್ತನ ಹತ್ರ,\nಈ ರಕ್ಷಣೆ ಹೊಂದೀಗಲೂ\nಆ ರಕ್ಷಕನು ಪ್ರೀತಿಯಿಂದ\nಸ್ವೀಕರಿಸಿಕೊಳ್ಳುವನು." },
  259: { title: "ನಾ ಧೈರ್ಯವಾಗಿ ಕರ್ತನ", lyrics: "1. ನಾ ಧೈರ್ಯವಾಗಿ ಕರ್ತನ\nಅರಿಕೆ ಮಾಡುವೆ ;\nಆತನ ವಾಕ್ಯ ತಳ್ಳದೆ\nಕಾಪಾಡಿಕೊಳ್ಳುವೆ\nಪಲ್ಲವಿ\nಶಿಲುಬೆಯಲ್ಲಿಯೇ ನಿತ್ಯಜೀವ ನೋಡಿದೆ\nನನ್ನ ಪಾಪ ಭಾರವು ಹೋಗಿದೆ\nನಂಬಿಕೊಂಡೆನು, ಶಾಂತಿ ಹೊಂದಿದೆ\nನಾನೇ ಧೈರ್ಯವಾಗಿ ಹೋಗುವೆ.\n2. ಯೇಸು, ನಿನ್ನಾಮ ಬಲ್ಲೆನು\nಸಂಪೂರ್ಣ ನಂಬುವೆ ;\nನನ್ನಾತ್ಮ ನೀನು ತಳ್ಳದೆ\nರಕ್ಷಿಸುತ್ತಿರುವಿ.\n3. ನಿನ್ ಮಾತು ವ್ಯರ್ಥವಾಗದೆ,\nಎಂದೆಂದು ತಾಳುತ್ತೆ\nನಿನ್ ಹತ್ರವಿಟ್ಟ ಆತ್ಮವ\nನೀ ಕಾಯುವಾತನೇ.\n4. ತಂದೆಯ ಮುಂದೆ ನನ್ನನ್ನು\nಜ್ಞಾಫಕ ಮಾಡುವಿ\nಭೂಲೋಕದಲ್ಲಿ ನಿನ್ನನ್ನು\nಅರಿಕೆ ಮಾಡುವೆ." },
  260: { title: "ಕ್ರಿಸ್ತ್ಯೇಸು ಪಾಪ ಮುರಿದ,", lyrics: "1. ಕ್ರಿಸ್ತ್ಯೇಸು ಪಾಪ ಮುರಿದ,\nದಿವ್ಯ ರಕ್ಷಕ ಯೇಸು!\nಸಾಲವನ್ನು ಹರಿಸಿದ,\nದಿವ್ಯ ರಕ್ಷಕ ಯೇಸು\nಪಲ್ಲವಿ\nದಿವ್ಯ ರಕ್ಷಕ ಯೇಸುವು\nನನ್ನ ರಕ್ಷಕ !\nದಿವ್ಯ ರಕ್ಷಕ ಯೇಸುವು\nನನ್ನ ಪ್ರಭು!\n2. ಸ್ವರಕ್ತ ಚೆಲ್ಲಿ ಹೋದನು,\nದಿವ್ಯ ರಕ್ಷಕ ಯೇಸು!\nನನ್ನನ್ನು ಶುದ್ಧಿಸಿದನು\nದಿವ್ಯ ರಕ್ಷಕ ಯೇಸು!\n3. ನಿತ್ಯವೂ ನಮ್ಮಲ್ಲಿರುವ\nದಿವ್ಯ ರಕ್ಷಕ ಯೇಸು!\nನಮ್ಮನ್ನು ಎಂದೂ ಕಾಯುವ\nದಿವ್ಯ ರಕ್ಷಕ ಯೇಸು!\n4. ದುರಾಶೆ ತೆಗೆಯುವನು,\nದಿವ್ಯ ರಕ್ಷಕ ಯೇಸು!\nವಿಜಯ ಪಾಲಿಸುವನು,\nದಿವ್ಯ ರಕ್ಷಕ ಯೇಸು!\n5. ನಾ ಪೂರ್ಣವಾಗಿ ನಂಬುವೆ\nದಿವ್ಯ ರಕ್ಷಕ ಯೇಸು!\nಈ ಲೋಕ ತಳ್ಳಿಬಿಡುವೆ\nದಿವ್ಯ ರಕ್ಷಕ ಯೇಸು!" },
  261: { title: "ಕ್ರಿಸ್ತನ ರಕ್ತವ", lyrics: "1. ಕ್ರಿಸ್ತನ ರಕ್ತವ\nನೋಡಿ ನಂಬುವೆನು ;\nಆ ಬಲಿ ದೇವ ಒಪ್ಪುವ ;\nನನಗೆ ಶಾಂತಿಯು.\n2. ಆ ಶಾಂತಿ ಹೋಗದೆ\nಸ್ಥಿರತ್ವದಲ್ಲಿದೇ ;\nದೇವರ ಮಾತು ಹೋಗದೆ\nಎಂದೆಂದೂ ತಾಳುತ್ತೆ.\n3. ಕಷ್ಟವು ಬಂದರೂ,\nಲೋಕವು ಹೋದರೂ,\nಆ ಶಾಂತಿಯೆಂದೂ ಹೋಗದು\nಕ್ಿ್ತ್ರೈಸು ಅಂದನು.\n4. ನನ್ ಪ್ರೀತಿ ಕಮ್ಮಿಯೂ;\nಆನಂದ ಹೋದರೂ,\nದೇವರ ಮಾತು ಎಂದಿಗೂ\nಬದಲು ಆಗದು.\n5. ನನ್ ಪ್ರೀತಿಯಲ್ಲಿಯೇ\nನಾನಾತುಕೊಳ್ಳೆನು ;\nಸುವಾರ್ತೆಯ ಸೇವೆಗಾಗಿ\nದೇವರ ಪ್ರೀತಿಯಲ್ಲಿಯೇ\nನಾನಾತುಕೊಂಡೆನು." },
  262: { title: "ಕೊಂಡಾಟವಾಗಲಿ!", lyrics: "1. ಕೊಂಡಾಟವಾಗಲಿ!\nಯೆಹೋವ ದೇವ ಸ್ತೋತ್ರ ಹೊಂದಲಿ\nಆತನು ತನ್ನ ಮಗ ಕೊಟ್ಟನು ;\nಕೊಂಡಾಟವಾಗಲಿ !\n2. ಇನ್ನೇನು ಕೊಡುವ ?\nಆತನು ಸ್ವೇಚ್ಛೆಯಿಂದ ನಮ್ಮಲ್ಲಿ\nಪ್ರೀತಿಯನ್ನಿಟ್ಟು ಕಾರ್ಯ ಮಾಡಿದ;\nಕೊಂಡಾಟವಾಗಲಿ !\n3. ದೇವರು ಸ್ವಪುತ್ರ\nಕ್ರೂಜೆಯ ಕ್ರೂರ ಸಾವಿಗಾದರೂ\nಒಪ್ಪಿಸಿ ನಮ್ಮ ರಕ್ಷಿಸಿದನು ;\nಕೊಂಡಾಟವಾಗಲಿ !\n4. ಈವಾಗ ಕ್ರಿಸ್ತನು\nದೇವರ ಮುಂದೆ ಬೇಡುವಾತನು ;\nಯಾರೀಗ ನಮ್ಮ ತಳ್ಳುವವರು ?\nಕೊಂಡಾಟವಾಗಲಿ !\n5. ತೀರ್ಮಾನ ಮಾಡಿತು!\nದೇವರ ಕಾರ್ಯವಾದ್ದರಿಂದಲೂ,\nನಾವೀಗ ಶುದ್ಧ ಜನರಾದೆವು !\nಕೊಂಡಾಟವಾಗಲಿ !\n6. ಜಯವು ನಮಗೆ ;\nದೇವರು ಯೇಸು ಕ್ರಿಸ್ತನಿಂದಲೇ\nಆ ಜಯ ಪಾಲಿಸಿರುವಾತನೇ ;\nಕೊಂಡಾಟವಾಗಲಿ !\nಕ್ರೈಸ್ತರ ನಡತೆಯೂ ಭದ್ರತೆಯೂ" },
  263: { title: "ಕ್ರಿ್ತ್ ಾಯ್ವನು", lyrics: "ಕ್ರಿ್ತ್ ಾಯ್ವನು\nನಾನು ಬಿದ್ದು ಹೋಗುವಾಗ\nನನ್ನ ಕಾಯ್ವನು!\nಪಲ್ಲವಿ\nನನ್ನ ಕಾಯ್ವನು ;\nನನ್ನ ಕಾಯ್ವನು ;\nನನ್ನ ಪ್ರೀತಿಸುವನು ;\nನನ್ನ ಕಾಯ್ವನು !\n2. ನಾನು ತಪ್ಪಿ ಹೋಗುವಾಗ,\nನನ್ನ ಕಾಯ್ವನು ;\nನನ್ನ ಪ್ರೀತಿ ತಣ್ಣಗಾಗ\nನನ್ನ ಕಾಯ್ವನು !\n3. ರಕ್ತದಿಂದ ಕೊಂಡ ಮೇಲೆ,\nನನ್ನ ಕಾಯ್ವನು ;\nಕ್ರಿ್ತ ರತ್ವಾಗಿದ್ದಾನೆ,\nನನ್ನ ಕಾಯ್ವನು !\n4. ನರಕದ ನಾಶದಿಂದ\nನನ್ನ ಕಾಯ್ವನು ;\nತನ್ನ ಪೂರ್ಣಶಕ್ತಿಯಿಂದ\nನನ್ನ ಕಾಯ್ವನು !" },
  264: { title: "ನಮ್ಮೊಡೆಯ ಬಂದು ಮಾರ್ಗವ ತೋರಿ", lyrics: "1. ನಮ್ಮೊಡೆಯ ಬಂದು ಮಾರ್ಗವ ತೋರಿ\nನನ್ನ ಹಿಂದೆ ಬಂದು ಹಿಂಬಾಲಿಸೆಂದ ;\nಈ ಬೆಟ್ಟವ ಹತ್ತಿ, ಆ ತಗ್ಗನ್ನು ತುಳಿ,\nಎನ್ ಮನೆಗೆ ಬನ್ನಿ ಅಂದು ಹೋದನು ;\nಆತ ನಮ್ಮನ್ನು ತನ್ನ ಧ್ವಜದ ಹತ್ರ\nಮಹಾ ಪ್ರೀತಿಯಿಂದ ಕರೆಯುತ್ತಾನೆ\nಆತನನ್ನು ಪ್ರೀತಿಸಿ ಆತನ ಸ್ಥಳ\nಎಂದೆಂದಿಗೂ ನಾ ಸೇರಿ ಅಲ್ಲಿ ಇರುವೆ.\n2. ನಮ್ಮೊಡೆಯ ಕರೆದ, ಮುಂದಾಗಿ ಹೋಗಿ,\nಆಟಂಕವ ತಳ್ಳಿ ಹಿಂಜರಿಯೆವು ;\nಪವಿತ್ರ ತನ್ನಾತ್ಮನ ಸಹಾಯ ನೀಡಿ,\nಆ ಸ್ಥಳಕ್ಕೆ ಆತ ಸೇರಿಸುವನು ;\nಕಷ್ಟ ಸಂದೇಹ ಮುಟ್ಟಿ ಬಂದಿದ್ದರೇನು,\nತಾಳ್ಮೆಯಿಂದ ನಾವು ಅಲ್ಲಿ ಸೇರುವ\nಹಿಂಸೆಗಳ ತಾಳಿ ಕಷ್ಟಗಳ ತೂರಿ,\nಕ್ರಿಸ್ರೈಸುವಿಂ ಪಟ್ಲಕ್ಕೆ ಬರುವವು.\n3. ನಮ್ಮೊಡೆಯ ಕರೆದ ಮುಂಜೆಯಲ್ಲೆದ್ದು\nಸಂತೋಷದಿಂ ಹೋಗಿ ಹಿಂಬಾಲಿಸಲು\nಈ ಲೋಕದ ಧ್ವನಿಯು ತ್ಯಜಿಸಿಬಿಟ್ಟು\nಎಷ್ಟಾಗಿಯೇ ಕೂಗಿದ್ದರೂ ಕೇಳೆವು ;\nಆತ ನಮ್ಮನ್ನು ತನ್ನ ಜನರನ್ನಾಗಿ\nತಾ ಕರೆದದ್ದರಿಂದ ಭಾಗ್ಯವಂತರು\nಆತನು ಮೃಷ್ಟಾನ್ನವ ಕೊಟ್ಟು ನಮ್ಮಲ್ಲಿ\nಸಂತೋಷವನ್ನಿಟ್ಟು ತರುವನು." },
  265: { title: "ಸರ್ವಶಕ್ತನಾದ ದೇವಾ,", lyrics: "1. ಸರ್ವಶಕ್ತನಾದ ದೇವಾ,\nಇಹದಲ್ಲಿ ಕಾಪಾಡು!\nನಾ ನಿರ್ಬಲ, ನೀನು ಶಕ್ತ ;\nಹಸ್ತ ನೀಡಿ, ನಡಿಸು ;\n2. ಆತ್ಮ ತೊಳೆಯುವ ಬುಗ್ಗೆ!\nನಿನ್ನ ಹತ್ರ ಬರುವೆ ;\nಇಷ್ಟತೀರ್ಥ ಭಕ್ತರಿಗೆ\nಸರ್ವ ತೃಪ್ತಿಯಾಗುತ್ತೆ ;\nಮಹಾ ಕರ್ತಾ ॥\n3. ಕಡೆ, ಸಾವು ಬರುವಾಗಳ\nಭಯದಿಂದ ತಪ್ಪಿಸು ;\nಸ್ವರ್ಗಲೋಕಕ್ಕೇರುವಾಗ\nಹರ್ಷದಿಂದ ಬರುವೆ,\nಸದಾಕಾಲ |॥" },
  266: { title: "ಯೇಸು ಜೊತೆಯಿರುವಾಗ", lyrics: "1. ಯೇಸು ಜೊತೆಯಿರುವಾಗ\nನಾನು ಭಯ ಪಡೆನು ;\nಆತ ಹತ್ರವಿರುವಾಗ\nಭಯವೇನೂ ಇಲ್ಲವು.\nಕ್ರೈಸ್ತರ ನಡತೆಯೂ ಭದ್ರತೆಯೂ\nಪಲ್ಲವಿ\nಯಾವ ಭಯವಿಲ್ಲದೆ,\nಅನುಸರಿಸಿರುವೆ,\nಎಲ್ಲಿಯೂ ನಾ ಹೋಗುತ್ತೇನೆ\nನಿನ್ನ ಜೊತೆಯಲ್ಲಿಯೇ,\n2. ಯೇಸು ಜೊತೆಯಿರುವಾಗ\nಧೈರ್ಯಗೆಟ್ಟು ಹೋಗದೆ,\nಸ್ಥಿರವಾಗಿ ನಿಲ್ಲುವಾಗ\nಭಕ್ತಿ ಬಲವಿರುತ್ತೆ.\n3. ಯೇಸು ಜೊತೆಯಿರುವಾಗ\nವೈರಿ ಕೇಡು ಮಾಡನು ;\nಲೋಕ ಕಷ್ಟ ಬರುವಾಗ\nಆತ್ಮ ನಷ್ಟವಾಗದು.\n4. ಯೇಸು ಜೊತೆಯಿರುವಾಗ\nದಾರಿ ತಪ್ಪಿ ಹೋಗೆನು ;\nಯೇಸು ಕೂಡ ಬರುವಾಗ\nದಾರಿ ತೋರಿಸುವನು." },
  267: { title: "ಪರಿಶುದ್ಧಾತ್ಮ ಕೊಡುವೆ", lyrics: "1. ಪರಿಶುದ್ಧಾತ್ಮ ಕೊಡುವೆ\nಅಂದನು ಸ್ವಾಮಿಯೇ\nಆ ಆತ್ಮನೀಗ ನಮಗೆ\nಬಂದಿರುವ\n2. ಪಾರಿವಾಳದ ಹಾಗೆಯೂ\nಆತ್ಮನು ಬಂದನು ;\nಸುಶಾಂತಿ ಪ್ರೀತಿಗಳನ್ನು\nಕೊಡುವನು.\nಕ್ೈಸ್ತರ ನಡತೆಯೂ ಭದ್ರತೆಯೂ\n3. ಬೆಂಕಿ ಗಾಳಿಗಳಂತೆಯೂ\nಫಕ್ಕನೆ ಬಂದನು;\nಪಾಪದ ಆರುಹವನ್ನು\nಹುಟ್ಟಿದ\n4. ಯಾರ್ಕಾರು ತಮ್ಮ ಜೀವದೊಳ್\nಸ್ಥಾನ ಕೊಡುತ್ತಾರೋ\nಆವರಿಗೆ ಸುಶಾಂತಿಯ\nಪಾಲಿಸುವ\n5. ಪಾಪದ ಮಾರ್ಗದಲ್ಲಿಯು\nಹೋಗಲು ಒಪ್ಪನು ;\nವಿಶುದ್ಧ ಯೋಚನೆಯನ್ನು\nಹುಟ್ಟಸುಮ\n6. ಸುಸೇವೆಯನ್ನು ಮಾಡಲು\nಬಲ ಕೊಡುವನು\nಎಲ್ಲಾ ಸುಪ್ರೇರಣೆಯನ್ನು\nಕೊಡುವನು.\n7. ದೇವರ ಆತ್ಮ ನಮಗೂ\nಸುಯೋಚನೆಯನ್ನು\nನಿತ್ಯವೂ ಕೊಟ್ಟು ನಮ್ಮನ್ನು\nಕಾಯುವನು." },
  268: { title: "ದೇವರ ಹತ್ರದಲ್ಲಿಯೂ", lyrics: "1. ದೇವರ ಹತ್ರದಲ್ಲಿಯೂ\nನಾ ಕೃಪೆಯಿಂದಲೂ\nನಿರ್ಭಯವಾಗಿ ನಿಲ್ಲುವೆ\nಅನ್ಯೋನ್ಯವಿರುತ್ತೆ.\n2. ದೇವರ ಮಾರ್ಗ ಬಿಟ್ಟೆನು,\nನಾ ದೂರ ಹೋದೆನು ;\nಆತನು ಕೃಪೆಯಿಂದಲೂ\nನನ್ ಹತ್ರ ಬಂದನು.\n3. ಕ್ರಿಸ್ತನ ರಕ್ತದಿಂದಲೇ\nದೇವರು ನಮ್ಮನ್ನು\nಸ್ವಪುತ್ರ ಕ್ರಿಸ್ತನಂತೆಯೇ\nಸೇರಿಸುವಾತನು.\n4. ದೇವ ಸ್ವಪುತ್ರನಂತೆಯೇ\nನನ್ನನ್ನು ನೋಡುವ,\nನಮ್ಮನ್ನು ಕ್ರಿಸ್ತನ ಹಾಗೆ\nಪ್ರೀತಿಸುತ್ತಿರುವ\n5. ನಾನೆಂಥಾ ಪ್ರೀತಿಯಲ್ಲಿಯೂ,\nನೆಲೆಗೊಂಡಿರಲು,\nನಾನೆಂದೂ ಭಯಪಡೆನು\nನಾನಂಜಿಕೊಳ್ಳೆನು." },
  269: { title: "ನನ್ನನ್ನು ಕರ್ತ ಪ್ರೀತಿಸುವನು ;", lyrics: "1. ನನ್ನನ್ನು ಕರ್ತ ಪ್ರೀತಿಸುವನು ;\nನನ್ನನ್ನು ಕರ್ತ ಪ್ರೀತಿಸುವನು ;\nನನ್ನಾತ್ಮ ರಕ್ಷಿಸಿದನು,\nಸುಗುಣ ಹುಟ್ಟಿಸಿದನು,\nನನ್ನನ್ನು ಕರ್ತ ಪ್ರೀತಿಸುವನು.\n2. ನನ್ನನ್ನು ಕರ್ತ ಶುದ್ಧಿಸುವನು ;\nನನ್ನನ್ನು ಕರ್ತ ಶುದ್ಧಿಸುವನು ;\nಒಳಗಿನ ಪಾಪದಿಂ\nಹೊರಗಿನ ಪಾಪದಿಂ\nನನ್ನನ್ನು ಕರ್ತ ಶುದ್ಧಿಸುವನು.\n3. ನನ್ನನ್ನು ಕರ್ತ ನಡಿಸುವನು ;\nನನ್ನನ್ನು ಕರ್ತ ನಡಿಸುವನು ;\nದುರ್ಗುಣ ಬಿಡುವದಕ್ಕೂ\nಸನ್ಮಾರ್ಗ ಸೇರುವದಕ್ಕೂ\nನನ್ನನ್ನು ಕರ್ತ ನಡಿಸುವನು.\n4. ಕರ್ತನು ಸ್ವರ್ಗಕ್ಕೇರಿಸುವನು ;\nಕರ್ತನು ಸ್ವರ್ಗಕ್ಕೇರಿಸುವನು ;\nನಿರೀಕ್ಷೆಯಲ್ಲಿ ಕಾಯುವೆ,\nಸುಸೇವೆಯಲ್ಲಿ ನಿಲ್ಲುವೆ\nಕರ್ತನು ಸ್ವರ್ಗಕ್ಕೇರಿಸುವನು." },
  270: { title: "ಪಾಪಿಯ ಮಿತ್ರನು ಯೇಸುಸ್ವಾಮಿ", lyrics: "1. ಪಾಪಿಯ ಮಿತ್ರನು ಯೇಸುಸ್ವಾಮಿ\nಇದ್ದಾನೆ! ಇದ್ದಾನೆ!\nಪಾಪದ ರೋಗದ ವೈದ್ಯನಾಗಿ\nಇದ್ದಾನೆ, ಇದ್ದಾನೆ!\nಪಲ್ಲವಿ\nಆತನಾತ್ಮದ ಕಷ್ಟ ನೋಡಿ\nವಾಸಿ ಮಾಡುವನಲ್ಲವೇ ?\nಆತನು ಸ್ವರ್ಗದ ವೈದ್ಯನಾಗಿ\nಇದ್ದಾನೆ, ಇದ್ದಾನೆ!\n2. ಪಾಪಿಯ ಮಿತ್ರನು ಶಕ್ತನಾಗಿ\nಇದ್ದಾನೆ!, ಇದ್ದಾನೆ!\nಯಾರನ್ನೂ ತಳ್ಳದವನಾಗಿ\nಇದ್ದಾನೆ, ಇದ್ದಾನೆ!\n3. ಹಗಲೂ ಇರುಳೂ ನಮ್ಮ ಹತ್ರ\nಇದ್ದಾನೆ, ಇದ್ದಾನೆ!\nಕ್ೈಸ್ತರ ನಡತೆಯೂ ಭದ್ರತೆಯೂ\nಆತನು ನಮ್ಮನ್ನು ಪ್ರೀತಿಸುತ್ತಾ\nಇದ್ದಾನೆ, ಇದ್ದಾನೆ!\n4. ಈ ಮಿತ್ರ ನಮ್ಮನ್ನು ಕರೆಯುತ್ತಾ\nಇದ್ದಾನೆ ಇದ್ದಾನೆ!\nಆತನು ನಮ್ಮನ್ನು ಬಿಡಲಾರ\nಸಾಗುತ್ತಾ, ಇದ್ದಾನೆ!\n5. ಆತನು ಪಾಪವ ಮನ್ನಿಸುತ್ತಾ\nಇದ್ದಾನೆ. ಇದ್ದಾನೆ!\nನಮ್ಮನ್ನು ನಾಶಕ್ಕೆ ಹಾಕಲಾರ\nಸಾಗುತ್ತಾ ಇದ್ದಾನೆ!" },
  271: { title: "ಯೇಸುವೇ! ನಾನು ನಿನ್ನನ್ನೇ", lyrics: "1. ಯೇಸುವೇ! ನಾನು ನಿನ್ನನ್ನೇ\nತಿಳಿಯಲಾಶೆ ಪಡುವೆ,\nನಿನ್ನ ಸಹಾಯವೆನಗೆ\nಸಿಕ್ಕುವದೆಂದು ನಂಬುವೆ.\nಪಲ್ಲವಿ\nಹೆಚ್ಚೆಚ್ಚಾಗಿ ಯೇಸು,\nಹೆಚ್ಚೆಚ್ಚಾಗಿ ಯೇಸು,\nರಕ್ಷಣೆ ಮಾಡ್ವ ಕೃಪೆಯೇ\nತಿಳಿಯಲಾಶೆ ಪಡುವೆ !\n2. ಯೇಸುವೆ! ನಿನ್ನ ಹತ್ರವು\nಕಲಿಯಲಿಕ್ಕೆ ಆಶೆಯು\nಇರುವದೆಂದು ನನಗೂ\nಆತ್ಮನ ಬಲ ಪಾಲಿಸು.\nದೇವರ ಐಕ್ಯದಲ್ಲಿ ಇರುವುದು\nದೇವರ ವಾಕ್ಯದಲ್ಲಿಯೇ\nನಿನ್ನನು ನೋಡುವಂತೆಯೇ\nತಿಳಿಯ ಮಾಡು ಕರ್ತನೇ,\nನನ್ನ್ನು ದೃಷ್ಟಿಸ್ಯೇಸುವೇ!\n4. ಯೇಸುವೇ! ನಿನ್ನ ಮಹಿಮೆ\nನೋಡುವ ದಿನ ಬರುತ್ತೆ ;\nಇಲ್ಲಿಯು ನಾನು ನಿನ್ನನ್ನೇ\nಪ್ರೀತಿಯ ಸೇವೆ ಮಾಡುವೆ." },
  272: { title: "ಯೇಸುವಿಂ ತಿಳುವಳಿಕೆ", lyrics: "1. ಯೇಸುವಿಂ ತಿಳುವಳಿಕೆ\nಹೆಚ್ಚಾಗಿ ಬೇಕು ನನಗೆ\nಆತನ ದಿವ್ಯ ಪೂರ್ಣತೆ\nಹಚ್ಚಾಗಿ ತೋರಿಸೆನಗೆ.\nಪಲ್ಲವಿ\nಯೇಸುವಿನ ಪ್ರೀತಿ\nಯೇಸುವಿನ ನೀತಿ\nಯೇಸುವಿಂ ತಿಳುವಳಿಕೆ\nಹೆಚ್ಚಾಗಿ ಬೇಕು ನನಗೆ\n2. ಯೇಸುವಿಂ ದಿವ್ಯ ಚಿತ್ತವ\nಹೆಚ್ಚಾಗಿ ಕಲಿಸೆನಗೆ\nಪವಿತ್ರ ಆತ್ಮ ಜ್ಞಾನವ\nಹೆಚ್ಚಾಗಿ ಕೊಡು ನನಗೆ\n3. ಆತನ ವಾಕ್ಯದಲ್ಲಿಯೂ\nಕ್ರಿ್ತನ ಐಕ್ಯದಲ್ಲಿಯೂ\nಆತನ ವಾಣಿ ಕೇಳಲು\nಹೆಚ್ಚಾಗಿ ಕಲಿಸೆನಗೂ.\n4. ಆತನ ದಿವ್ಯ ರಾಜ್ಯವ\nಹೆಚ್ಚಾಗಿ ಕಾಯುವಂತೆಯೂ\nಆತನ ಶ್ರೇಷ್ಠ ಪ್ರೀತಿಯ\nಹೆಚ್ಚಾಗಿ ತೋರಿಸೆನಗೂ." },
  273: { title: "ಯೇಸು ನೀನು ನನಗೆ", lyrics: "1. ಯೇಸು ನೀನು ನನಗೆ\nಆತ್ಮೀಯ ಆಶ್ರಯವು ;\nನೀನು ಕಾಯುವಾತನು !\nನನಗೆ ರಕ್ಷಕನು !\nಹಿಂಸೆ ಬರುವಾಗಲೂ,\nನಷ್ಟ ಕಾಲದಲ್ಲಿಯೂ\nನಿತ್ಯವು ನನ್ನೊಂದಿಗೂ\nನಿತ್ಯ ಕಾಯುವಾತನು !\n2. ಎಲ್ಲಿಯೂ ನಾ ಹೋಗೆನು ;\nನಿನಗಾಗಿ ಕಾಯುವೆ,\nನೀನೇ ನನ್ನಾಶ್ರಯವು,\nನಿನ್ನ ವಾಕ್ಯ ನಂಬುವೆ.\nನಿನ್ನ ಕಡೆಯಿಂದಲೇ\nಶಕ್ತಿ ಕೊಡು ನನಗೆ\nನಿನ್ ಸಹಾಯದಿಂದಲೇ\nಜಯ ಘೋಷವಾಗುತ್ತೆ.\n3. ನನ್ನ ದಿವ್ಯ ಆಪ್ತನೇ!\nನಿನ್ನ ಪ್ರೀತಿ ನನಗೆ\nಎಷ್ಟಾಶ್ಚರ್ಯವಾಗಿದೆ.\nಮನೋತೃಪ್ತಿ ಕೊಡುತ್ತೆ,\nನಾನಾ ಯೋಗ್ಯನಾದರೂ,\nನೀನೇ ಪ್ರೀತಿ ಮಾಡುತ್ತೀ\nನಾನಾ ಶುದ್ಧನಾಗಲು\nನೀನೇ ಶುದ್ಧ ಮಾಡುವಿ.\n4. ನನ್ನಲ್ಲಿದ್ದ ಪಾಪವೇ\nನಿನ್ನ ರಕ್ತದಿಂದಲೇ\nಹೋಯಿತೆಲ್ಲಾ ನನಗೆ\nಸಮಾಧಾನವಾಗಿದೆ.\nಸದಾ ನೀನೇ ನನ್ನನ್ನು\nಕಾಯುವಾತನಾಗಿದ್ದಿ\nಜೀವದಂತ್ಯ ಬಂದರೂ\nನನ್ನನ್ನು ಸೇರಿಸುವಿ." },
  274: { title: "ಯೇಸು ನಮ್ಮಾತ್ಮಾಧರಣೆ!", lyrics: "1. ಯೇಸು ನಮ್ಮಾತ್ಮಾಧರಣೆ!\nಜೀವದಾಧಾರ! ಜ್ಯೋತಿಯು !\nನೀ ಕೊಟ್ಟಾನಂದ ನಮಗೆ\nಲೋಕವು ಕೊಡಲಾರದು!\n2. ನಿನ್ ಸ್ಥಿರವಾದ ಸತ್ಯವು\nಮಾರ್ಪಾಟ ಎಂದು ಪಡೆದು\nನಿನ್ನನ್ನು ಬಯ್ಸುವವರು\nಸದಾ ಸಂತೋಷಿಸುವರು.\n3. ನೀ ಜೀವರೊಟ್ಟಿ ನಮಗೆ ;\nನಿನಿಂದ ತೃಪ್ತಿಯಾಗುತ್ತೆ ;\nಜೀವದ ಬುಗ್ಗೆ ನಮಗೆ\nದಾಹವು ಎಂದೂ ಬಾರದೇ.\n4. ಎಲ್ಲೆಲ್ಲಿ ನಾವು ಹೋದರೂ\nನಿನ್ನನ್ನು ಬಯಸುವೆವು\nನಿನ್ನನ್ನು ತಳ್ಳಿದವರು\nಸಫಲವಾಗಲಾರರು.\nದೇವರ ಐಕ್ಯದಲ್ಲಿ ಇರುವುದು\n5. ಕ್ರಿಸ್ತ್ಯಸುವು ನಮ್ಮೆಲ್ಲರ\nಯಾವಾಗಲೂ, ಕಾಯುವನು,\nಕಷ್ಟಗಳನ್ನುನೀಗಿಸ\nಸದಾ ನಮ್ಮನ್ನು ಕಾಯ್ವನು." },
  275: { title: "ಆ ಸತ್ಯಲೋಕ ರಾಜನೇ", lyrics: "1. ಆ ಸತ್ಯಲೋಕ ರಾಜನೇ\nಕುರುಬನಂತಿದ್ದಾನೆ ;\nನನ್ನಲ್ಲಿದ್ದ ಕೊರತೆಯ\nಕ್ರಿಸ್ತೇಸು ನೀಗಿಸುವ.\n2. ಕ್ರಿಸ್ತೇಸು ಜಲ ಹತ್ರವೇ\nನನ್ನನ್ನು ನಡಿಸುವ\nಅಮೂಲ್ಯ ಮೇವಿನಲ್ಲಿಯೇ\nನನ್ನನ್ನು ಇರಿಸುವ.\n3. ನಾನೆಷ್ಟು ತಪ್ಪಿಹೋದರೂ\nಕ್ರಿಸ್ತೇಸು ಬಿಡಲಾರ;\nನನ್ನನ್ನು ಶುದ್ಧ ಮಾಡಲು\nಆತನ ದಿವ್ಯ ಚಿತ್ತ.\n4. ಮರಣ ದಿನ ಬಂದರೂ,\nನಾ ಹೆದರುವದಿಲ್ಲ\nಆತನು ಹತ್ರದಲ್ಲಿಯೂ\nಬಲವ ನೀಡುವನು.\n5. ಕ್ರಿಸ್ತೇಸು ನನ್ನ ಮುಂದೆಯೇ\nಆಹಾರವಿಡುವನು\nನಾ ತೃಪ್ತಿಪಟ್ಟು ಕರ್ತಗೆ\nಸುಸ್ತೋತ್ರ ಮಾಡುವೆನು.\nದೇವರ ಐಕ್ಯದಲ್ಲಿ ಇರುವುದು\nಆತನ ಪ್ರೀತಿ ತಪ್ಪದೆ\nಎನ್ ಪ್ರೀತಿಯುಳ್ಳ ಕರ್ತಗೆ ನನ್ನನ್ನು ಕಾಯುತ್ತದೆ ;\nಸುಸೇವೆ ಸಲ್ಲಿಸುವೆ.\nಅಮೂಲ್ಯ ರತ್ನವೇ ;\nಅದೆಲ್ಲಾ ನಾಮಕ್ಕಿಂತಲೂ\nಇಂಪಾದ ಹೆಸರೇ.\n2. ಆ ನಾಮ ನಿನ್ನ ಪ್ರೀತಿಯ\nಪ್ರಕಟಿಸುತ್ತದೆ ;\nಇನ್ಯಾರೂ ಹಾಗೆ ನಮ್ಮನ್ನು\nಪ್ರೀತಿಸುವವರು ?\n3. ನಾವೆಂಥಾ ಕಷ್ಟದಲ್ಲಿಯೂ\nಬಿದ್ದಾಗ್ಯೂ ನಮಗೂ\nಸಹಾಯ ಕೊಟ್ಟು ನಮ್ಮನ್ನು\nತಪ್ಪಿಸುವಾತನು.\n4. ಅಧೈರ್ಯವೆಲ್ಲಾ ಆತನು\nಬಿಡಿಸಬಲ್ಲನು,\nದೇವರ ವಾಕ್ಯ ನಂಬಲು\nಸಹಾಯಿಸುವನು.\n5. ಯೇಸು ನಿನ್ನಾಮ ಹೇಳಲು\nಎಲ್ಲೆಲ್ಲಿ ಹಾಡುವೆ!\nಅದರ ಬೆಲೆ ಹೇಳಲು\nಅಸಾಧ್ಯವಾಗಿದೆ." },
  276: { title: "ಎನ್ ಕರ್ತ ನನ್ನ ಕುರುಬನು ;", lyrics: "1. ಎನ್ ಕರ್ತ ನನ್ನ ಕುರುಬನು ;\nಕೊರತೆ ಪಡೆನು ;\nಮೃಷ್ಪನ್ನ ಶಾಂತಿಗಳನ್ನು\nಯೇಸು ಕೊಡುವನು.\n2. ನನ್ನಾತ್ಮ ಬಲ ಕೊಡಲು\nಸುಕೃಪೆ ತೋರುವ ;\nನಾ ನೀತಿವಂತನಾಗಲು,\nನನ್ನನ್ನು ಕಾಯುವ.\n3. ಮರಣ ಬಂದರಲ್ಲಿಯೂ\nನಾನಂಜಿಕೊಳ್ಳೆನು ;\nನನ್ನೊಂದಿಗೆ ನನ್ ಕರ್ತನು\nಸಹಾಯಿಸುವನು.\n4. ವೈರಿಯ ಮುಂದೆ ಮೇವನ್ನು\nಪೂರೈಸಿಸುವನು\nನನ್ ತಲೆಗೆಣ್ಣೆ ಹಚ್ಚಲು\nಸಂತೈಸಿಸುವೆನು.\n5. ಈಗಿನ ಕಾಲದಲ್ಲಿಯೂ\nತಾ ಪ್ರೀತಿಸುವನು\nಆತನ ಮನೆಯಲ್ಲಿಯೂ\nಸಂತೃಪ್ತಿಸುವನು." },
  277: { title: "ಪಾಪದ ಮಾರ್ಗದಲ್ಲಿ", lyrics: "1. ಪಾಪದ ಮಾರ್ಗದಲ್ಲಿ\nನಾ ತಪ್ಪಿ ಹೋದೆನು ;\nಯೇಸುವು ನನ್ನ ನೋಡಿ\nನನ್ನೆತ್ತಿ ತಂದನು ;\nತಾ ತನ್ನ ಹಟ್ಟಿಯಲ್ಲಿಯೇ\nಸ್ಥಳವ ಕೊಟ್ಟ ನನಗೆ\nಪಲ್ಲವಿ\nಪ್ರೀತಿಯಿಂದ ಬಂದ\nರಕ್ತದಿಂದ ಕೊಂಡ\nಕೃಪೆಯಿಂದ ನನ್ನ ತಂದನು,\nಎಂಥ ಕೃಪೆ ಯೇಸು ಇಟ್ಟನು.\n2. ಆತನು ನೋಡಿದಾಗ\nನಾ ಸಾಯುತ್ತಿದ್ದೆನು.\nಕ್ರಿಸ್ತೇೆಸು ಬಂದು, ನಂಗೆ\nಧೈರ್ಯವ ಕೊಟ್ಟನು ;\nಇಂಪಾದ ಮಾತಿನಿಂದಲೂ\nನನಗೆ ಹರ್ಷ ಕೊಟ್ಟನು.\n3. ತನ್ನ ಕೈಗಳಲ್ಲಿದ್ದ\nಗಾಯದ ಗುರುತು,\nಸ್ವಪಾದಗಳ ಸಹ\nತೋರ್ಪಡಿಸಿದನು,\nನನ್ನನ್ನು ರಕ್ಷಿಸಲಿಕ್ಕೆ\nಕ್ರಿಸತೇಸು ಬಾಧೆ ಪಟ್ಟನು.\n4. ಆತನ ಹತ್ರವಿದ್ರೆ\nಸಂತೋಷವಿರುತ್ತೆ :\nಆತನ ಮುಖ ನೋಡಿ,\nಆನಂದವಾಗುತ್ತೆ,\nಆತನ ಸ್ತೋಕ್ರ ಮಾಡಲು\nಹಗಲು ರಾತ್ರಿ ಸಾಲದು.\n5. ಆತನು ಬರುವನು\nಎಷ್ಟೋ ಅನಂದವೇ!\nಆ ದಿನಕ್ಕಾಗಿ ನಾನು\nಕಾಯುತ್ತಿರುವೆನು,\nಅವಾಗ ತನ್ನ ಹಟ್ಟಿಗೆ\nನನ್ನನ್ನು ಸೇರಿಸುವನು.\nದೇವರ ಐಕ್ಯದಲ್ಲಿ ಇರುವುದು" },
  278: { title: "ಯೇಸು ನಿನ್ನ ಸತ್ಯನೋಡಿ,", lyrics: "1. ಯೇಸು ನಿನ್ನ ಸತ್ಯನೋಡಿ,\nಮನೋತೃಪ್ತಿ ಹೊಂದುವೆ ;\nನಿನ್ನ ಅತಿ ಶ್ರೇಷ್ಠ ಪ್ರೀತಿ\nತಿಳುಕೊಳ್ಳುವೆ ;\nನಿನ್ನ ಕನಿಕರ ನೋಡಿ\nನನಗೆ ಸಂತೋಷವೇ ;\nನೀನು ನನ್ನ ಆತ್ಮ ಮುಟ್ಟಿ\nಧೈರ್ಯ ಕೊಟ್ಟಿದ್ದೀ.\nಪಲ್ಲವಿ\nಯೇಸು ನಿನ್ನ ಸತ್ಯ ನೋಡಿ,\nಮನೋತೃಪ್ತಿ ಹೊಂದುವೆ\nನಿನ್ನ ಅತಿ ಶ್ರೇಷ್ಠ ಪ್ರೀತಿ\nತಿಳುಕೊಳ್ಳುವೆ.\n2. ಅವಧಿಯ ಉದ್ದಕ್ಕಿಂತ\nನಿನ್ನ ಪ್ರೀತಿ ಮೀರುತ್ತೆ.\nನಿನ್ನ ದೊಡ್ಡ ಉಪಕಾರ\nನನ್ನ ಮೇಲಿದೆ.\nಪ್ರಿಯನೇ! ನಿನ್ನಲ್ಲಿ ನಾನು\nತೃಪ್ತಿ ಹೊಂದುತ್ತಿರುವೆ,\nನಿನ್ನ ವಾಕ್ಯವು ನನ್ನಲ್ಲಿ\nಕಾರ್ಯ ಮಾಡುತ್ತೆ.\n3. ನಂಬಿಕೆಯ ಮಾರ್ಗದಿಂದ\nಮನಶ್ಶಾಂತಿಯಾಗಿದೆ.\nನಿನ್ನ ಶ್ರೇಷ್ಠ ಪ್ರೀತಿಯಿಂದ\nತೃಪ್ತಿಗೊಳ್ಳುವೆ\nನಿನ್ನ ಶಕ್ತಿ ಬಲ ನೀಡಿ\nಜಯ ಧ್ವನಿಗೈಯುತ್ತೆ ;\nನೀನು ನಿನ್ನ ಹಸ್ತ ನೀಡಿ\nನನ್ನ ನಡಿಸು.\n4. ನಾನು ನಿನಗಾಗಿ ಕಾದು, ಸೇವೆ ಮಾಡುತ್ತಿರುವೆ ;\nನನ್ನ ಮೇಲೆ ದೃಷ್ಟಿಯಿಟ್ಟು\nನೀನು ದೇವ ಪ್ರೀತಿಗಾಗಿ ಕೃಪೆ ಪಾಲಿಸ್ೈೆ\nಕಾರ್ಯ ಮಾಡುವಾತನೇ\nನನ್ನೆಂದಿಗೂ ಕಾಪಾಡಿ\nಬಲದಿಂದಲೇ." },
  279: { title: "ಇರುವಾಗಲು,", lyrics: "ಇರುವಾಗಲು,\nನೀನು ಭಯಪಟ್ಟು\nಓಡಬಾರದು;\nನನ್ನ ಮಾತನ್ನಂಬಿ\nಸ್ಥಿರವಾಗಿರು;\nನಿನ್ನ ಬಿಡಲಾರೆ,\nಬಿಡೆನು ಎಂದೆಂದಿಗೂ!\nಪಲ್ಲವಿ\n“ನಾ ಕೈ ಬಿಡೆನು,\nನಾ ಕೈ ಬಿಡೆನು!\"\nಆ ಮಾತು ಹೇಳಿದನಲ್ಲ\nತಾ ಹೇಳಿದನಲ್ಲವೇ ?\n2. ಸುತ್ತಲು ಹೂಗಳು\nಬಾಡಿ ಹೋದರೂ\nಮೇಲೆ ಸ್ವರ್ಗದೊಳು\nಬದಲಾಗದು !\nಅಲ್ಲಿಂದ್ಯೇಸು ಸ್ವಾಮಿ\nಬರುವಾತನು\nದೇವರ ಐಕ್ಯದಲ್ಲಿ ಇರುವುದು\nನನ್ನ ಬಿಡಲಾರ\nನನ್ನನ್ನು ಕೈ ಬಿಡನು!\n3. ಮುಂದೆ ಬಹು ಕಷ್ಟ\nಬರುತ್ತಿದ್ದರೂ,\nಭಯಪಡಲಾರೆ\nಸ್ವಾಮಿ ಇದ್ದಾನೆ!\nಬಲವಾಗಿ ನಿಂತು,\nಹರ್ಷಗೊಳ್ಳುವೆ ;\nಸ್ವಾಮಿ ಬಿಡಲಾರ\nಸ್ವಾಮಿ ನನ್ನ ಬಿಡನು!" },
  280: { title: "ದಿವ್ಯ ಸಮಾಧಾನ", lyrics: "1. ದಿವ್ಯ ಸಮಾಧಾನ\nನದಿಯಂತಿದೆ ;\nಇಷ್ಪ ತೀರ್ಥಪಾನ\nಭಕ್ತರಾತ್ಮಕ್ಕೆ;\nಎಲ್ಲಾ ಭಯವನ್ನು\nನೀಗಿಸುವದು.\nನವ ಧೈರ್ಯವನ್ನು\nಹುಟ್ಟಿಸುವದು,\nಪಲ್ಲವಿ\nದಿವ್ಯ ಕೃಪಾನಿಧಿ\nಸುಖ ಪೂರ್ತಿಯೇ\nಪರಮಾರ್ಥ ಸಿದ್ಧಿ\nಶಾಂತಿ ಮೂಲವೇ.\n2. ದೇವಾಶ್ರಯದಲ್ಲಿ\nಸೇರಿದವನು,\nಸುರಕ್ಷಿತನಾಗಿ\nನಿಲ್ಲುವವನು ;\nಘೋರ ಬಾಧೆ, ಚಿಂತೆ\nಯಾವ ವಿಪತ್ತೂ,\nಯೇಸು ಭಕ್ತರಿಗೆ\nಮುಟ್ಟಲಾರವು.\n3. ಸುಖ, ದುಱಖವೆಲ್ಲಾ\nಆತನಿಂದಲೇ ;\nಶಿಕ್ಷೆ ರಕ್ಷೆಗೆಲ್ಲಾ\nಮೂಲ ಪ್ರೀತಿಯೇ ;\nನಂಬು ಆತನನ್ನು\nಸತ್ಯಸಂಧನು ;\nನಿನ್ನ ಕಾರ್ಯವನ್ನು\nನಡಿಸುವನು." },
  281: { title: "ಯೆಹೋವ ನನ್ನ ಕುರುಬ,", lyrics: "1. ಯೆಹೋವ ನನ್ನ ಕುರುಬ,\nಕೊರತೆ ಪಡೆನು\nಉತೃಷ್ಟ ಮೇವ ಕೊಡುವ\nಸಂತೃಪ್ತಿಗೊಳ್ಳುವೆ." },
  282: { title: "ಯೇಸು ಆಶ್ಚರ್ಯ ರಾಜನೇ!", lyrics: "1. ಯೇಸು ಆಶ್ಚರ್ಯ ರಾಜನೇ!\nನೀ ರಣ ವೀರನು!\nನೀ ನಮ್ಮ ಕಾರ್ಯದಲ್ಲಿಯೇ,\nಸಹಾಯ ಕೊಟ್ಟಿದ್ದೀ.\n2. ನೀ ನಮ್ಮ ಮನದಲ್ಲಿಯೂ\nಸತ್ಯವನ್ನಿಟ್ಟರೆ.\nದೇವರಿಗೆ ಪ್ರತಿಷ್ಠೆ ಮಾಡಿಕೊಳ್ಳುವುದು\n2. ವಿಶ್ರಾಂತಿಯನ್ನು ಕೊಡುವ\nನನ್ನನ್ನು ಕಾಯುವ\nನೀತಿಯ ಮಾರ್ಗ ತೋರುವ,\nಕೇಡೆಲ್ಲಾ ನೀಗುವ.\n3. ಎನ್ ವೈರಿ ಎದುರಿನಲ್ಲೂ\nಮೇಜನ್ನು ಇಡುವ\nಮೃಷ್ಪಾನ್ನ ಹಾಕಿ, ನನಗೂ\nಬಾ ತಿನ್ನು ಅನ್ನುವ.\n4. ನಾ ಮೃತ್ಯು ತಗ್ಗಿನಲ್ಲಿಯೂ\nನಡೆಯ ಬಂದರೂ,\nನಾನೆಂದೂ ಅಂಜದಿರುವೆ,\nಕ್ರಿಸ್ತನ ಹತ್ರವು.\n5. ಎನ್ ಶಿರಸ್ಸಿನ ಮೇಲೆಯೂ\nಸುತೈಲ ಹಚ್ಚಿದೆ ;\nಎನ್ ಪಾತ್ರೆಯಲ್ಲಾನಂದವು\nಸಂಪೂರ್ಣವಿರುತ್ತೆ.\n6. ಯೆಹೋವನು ಸ್ವಸ್ಥಾನಕ್ಕೆ\nನನ್ನನ್ನು ಕರೆದ ;\nಎನ್ ಸೇರಿಸುವವರೆಗೆ\nಕೃಪೆಯ ತೋರುವ.\nದೇವರಿಗೆ ಪ್ರತಿಷ್ಠೆ ಮಾಡಿಕೊಳ್ಳುವುದು\nದುರ್ಗುಣವೆಲ್ಲಾ ಸೋಲುತ್ತೆ\nಶುದ್ಧತ್ವವಾಗುತ್ತೆ.\n3. ಯೇಸುವೇ, ನಿನ್ನ ಪ್ರೀತಿಯು\nಮಿತಿಗೆ ಮೀರಿದೆ ;\nನಮಗೆ ಎಷ್ಟಾಶ್ಚರ್ಯವು\nಎಷ್ಟೋ ಕೃತಜ್ಞತೆ!\n4. ನಿನ್ನಾಮವ ಕೊಂಡಾಡುವೆ,\nನಾ ಹಾಡುತ್ತಿರುವೆ!\nನಿನ್ನನ್ನು ಬಯಸಿರುವೆ\nನಾ ಸ್ತೋತ್ರ ಮಾಡುವೆ.\n5. ನಿನ್ನನ್ನು ಪ್ರೀತಿ ಮಾಡುವೆ,\nಸುಸೇವೆ ಮಾಡುವೆ!\nನಾ ನಿನ್ನ ಹಿಂದೆ ಬರುವೆ,\nನಿಶ್ಚಯ ಮಾಡಿದೆ.\n6. ಈ ದಿವ್ಯ ಪ್ರೀತಿ ನನ್ನಲ್ಲೇ\nನಿತ್ಯವೂ ಇರುತ್ತೆ,\nನನ್ನಲ್ಲಿ ಕಾರ್ಯ ಮಾಡುತ್ತೆ\nಕಡೆಯ ವರೆಗೆ." },
  283: { title: "ಶುದ್ಧತೆಯನ್ನು ಅಭ್ಯಾಸಿಸಿರು,", lyrics: "1. ಶುದ್ಧತೆಯನ್ನು ಅಭ್ಯಾಸಿಸಿರು,\nನೀ ಕರ್ತನ ಮಾತನ್ನು ಹಿಂಬಾಲಿಸು\nಶುದ್ಧರ ನಿವಾಸ ಕೋರುತ್ತಾ ಇರು,\nದೇವರ ಸಹಾಯ ನೀನೇ ಹುಡುಕು.\n2. ಶುದ್ಧತೆಯನ್ನು ಅಭ್ಯಾಸಿಸಿರು,\nಪ್ರಾರ್ಥನೆಯ ಮಾಡಲು ಕಲಿತಿರು !\nನೀ ಕರ್ತನ ಹತ್ರ ತಂಗುತ್ತಾ ಇರು\nನಿನ್ನಲ್ಲಿ ಸುಗುಣ ಕಂಡಿರುವದು.\n3. ಶುದ್ಧತೆಯನ್ನು ಅಭ್ಯಾಸಿಸಿರು,\nನಿನ್ನಿಷ್ಟದ ಹಾಗೆ ನೀ ಹೋಗದಿರು,\nಆ ಕಾಲ ಸಕಾಲ ಏನೂ ಬಂದರೂ,\nನೀ ಕರ್ತನ ಹತ್ರ ತಂಗುತ್ತಾ ಇರು.\n4. ಶುದ್ಧತೆಯನ್ನು ಅಭ್ಯಾಸಿಸಿರು,\nನೀನೇ ಮಿತಿಮೀರಿ ಮಾತಾಡದಿರು ;\nಶುದ್ಧಾತ್ಮನಿಂದ ನಡಿಸಲ್ಪಡು\nನಿನ್ ನಡತೆ ಕರ್ತ ಮೆಚ್ಚಿರುವನು.\nದೇವರಿಗೆ ಪ್ರತಿಷ್ಠೆ ಮಾಡಿಕೊಳ್ಳುವುದು" },
  284: { title: "ಸುಮಿತ್ರನು ದೊರೆತನು", lyrics: "1. ಸುಮಿತ್ರನು ದೊರೆತನು\nಪ್ರೀತಿಯ ಭಾವದಿಂದ ;\nಸುವಾಕ್ಯವ ಆಡುತ್ತಲು\nಕರುಣೆ ಮೇಲೆ ಇಟ್ಟ;\nಆತನ ಧ್ವನಿ ಕೇಳಲು,\nಸಮ್ಮತಿಯಿಂದ ಬಂದೆ ;\nಆತನ ದಾಸನಾದೆನು,\nಆತನ ಸೇವಿಸುವೆ.\n2. ನನಗಾಗಿ ಈ ಮಿತ್ರನು\nಕ್ರೂಜೆಯ ಮೇಲೆ ಸತ್ತ ;\nತಾ ನನಗಾಗಿ ಸಾಯಲು,\nಕರುಣೆಯಿಂದ ಬಂದ ;\nನಾನಾತವನಾಗುವೆ\nಆತನು ನನ್ನ ಕರ್ತ ;\nನನ್ನಲ್ಲಿರುವ ಸರ್ವವೇ,\nಕೊಡುವೆ ಪ್ರೀತಿಯಿಂದ.\n3. ಸುಶಕ್ತಿಯಿಂದೀ ಮಿತ್ರನು\nಎಲ್ಲವ ಮಾಡಬಲ್ಲ;\nನನ್ನನ್ನು ನಿತ್ಯ ಸ್ವರ್ಗಕ್ಕೂ\nಸೇರಿಸಬಲ್ಲನಾತ\nಆತನಿಗಾಗಿ ಕಾಯುವೆ,\nಹೋರಾಡಿ ಸೇವಿಸುವೆ\nಅನಂತ್ರ ನಾನೆಂದೆಂದಿಗು\nಆತನ ಜೊತೆ ಇರ್ವೆ.\n4. ಈ ಮಿತ್ರನು ಎಲ್ಲರಿಗೂ\nಬೇಕಾದ ದಿವ್ಯ ವೈದ್ಯ ;\nಆತನು ಬುದ್ಧಿ ಕೊಡ್ವನು,\nಆತನು ಕಾಯಬಲ್ಲ\nತನ್ನ ದಿವ್ಯ ಪ್ರೀತಿಗೆ\nತಪ್ಪಿಸುವವನ್ಯಾರು ?\nನಾನೆಲ್ಲಿಯೂ ಎಂದೆಂದಿಗೂ\nಸ್ತೋತ್ರವ ಮಾಡುವೆನು." },
  285: { title: "ನಾನೆಲ್ಲಿಯೂ ಹೋಗಿರುವಾಗ", lyrics: "1. ನಾನೆಲ್ಲಿಯೂ ಹೋಗಿರುವಾಗ\nಉದ್ದಾರಕನಿರುವನು;\nಸಮೀಪಸ್ಥನಾಗಿರುತ್ತಾನೆ;\nತಿಳಿಯಲೆಲ್ಲರಿಗೂ !\nಪಲ್ಲವಿ\nಎಲ್ಲರೂ ತಿಳಿಯಬೇಕು !\nಎಲ್ಲರೂ ತಿಳಿಯಬೇಕು!\nಉದ್ಧರಿಸುವಾತನಿದ್ದಾನೆ ;\nಎಲ್ಲರೂ ತಿಳಿಯಬೇಕು !\n2. ಆತನ ಸುಕರುಣೆ ಪ್ರೀತಿ\nಅತ್ಯಧಿಕವಾಗಿರುತ್ತೆ ;\nಎಲ್ಲರಲ್ಲಿ ಪ್ರಥಮನಾತ !\nತಿಳಿಯಲೆಲ್ಲರಿಗೂ !\n3. ಕಷ್ಟಗಳಾವರಿಸುವಾಗ,\nಸಹಾಯವ ಕೊಡುವನು ;\nನಾ ಕೊಂಡಾಡುತ್ತೇನಾತನನ್ನು\nತಿಳಿಯಲೆಲ್ಲರಿಗೂ !\nದೇವರಿಗೆ ಪ್ರತಿಷ್ಠೆ ಮಾಡಿಕೊಳ್ಳುವುದು\n4. ನಾನಾತನ ಪ್ರೀತಿಸುತ್ತೇನೆ,\nಸೇವಿಸುತ್ತಾ ಬರುವೆನು.\nನಿನ್ನುದ್ಧರಿಸಿ ಬರುತ್ತಾನೆ !\nತಿಳಿಯಲೆಲ್ಲರಿಗೂ !" },
  286: { title: "ನನ್ನನ್ನು ಯೇಸುವೇ,", lyrics: "1. ನನ್ನನ್ನು ಯೇಸುವೇ,\nಪ್ರೀತಿಸಿದ್ದೀ,\nಶಿಲುಬೆಯಲ್ಲಿಯೇ\nನೀ ಸತ್ತಿದ್ದಿ\nನಿನ್ ಮುಂದೆ ತರುವೆ\nಹೃದಯ ಕಾಣಿಕೆ ;\nನಾ ಪ್ರೀತಿಯಿಂದಲೇ\nಕೊಂಡಾಡುವೆ !\n2. ಯೇಸು, ನೀ ಸ್ವರ್ಗಕ್ಕೆ\nಏರಿ ಹೋದಿ,\nನಿನ್ನ ಸಮ್ಮುಖಕ್ಕೆ\nಬಂದಿರುವೆ ;\nಕ್ರೂಜೆಯ ತಾಳಲು,\nಪ್ರೀತಿಯಿಂದಿರಲು\nಸೇವೆಯ ಮಾಡಲು\nಸಹಾಯಿಸು !\n3. ನಾ ಸ್ಥಿರವಾಗಿಯೇ\nನಿಂತಿರಲು,\nನೀ ನನ್ನ ಆತ್ಮಕ್ಕೆ\nಬಲಕೊಡು,\nನಿತ್ಯ ಸುಸೇವೆಯ\nಪರೋಪಕಾರವ,\nನನ್ನಲ್ಲಿ ಕಾಣಿಸ\nನೀ ಮಾಡಯ್ಯಾ !\nದೇವರಿಗೆ ಪ್ರತಿಷ್ಠೆ ಮಾಡಿಕೊಳ್ಳುವುದು\n4. ನನ್ನಲ್ಲಿ ಸರ್ವವ\nನಾ ನಿನಗೆ\nಅರ್ಪಿಸಿ ನಿನ್ನನ್ನ\nಕೊಂಡಾಡುವೆ !\nನಿನ್ನು ನೋಡಲು\nಸಂತೋಷ ಪೂರ್ತಿಯು\nನನ್ನಲ್ಲಿ ಇರ್ವದು\nಎಂದೆಂದಿಗು." },
  287: { title: "ಕರ್ತಾ! ಮಾತಾಡು ನನಗೂ,", lyrics: "1. ಕರ್ತಾ! ಮಾತಾಡು ನನಗೂ,\nನೀ ಸುಮ್ಮನಿರಬಾರದೇ,\nನಿನ್ನಂತೆ ಮಾತನಾಡಲು\nಸಹಾಯ ಕೊಡು, ಕರ್ತನೇ !\n2. ಇತರ ಜನ ನಡಿಸ\nನನ್ನನ್ನು ನಡಿಸು, ಕರ್ತಾ\nಹಸಿದ ಆತ್ಮಗಳನ್ನು\nನೀ ಶೃಪ್ತಿ ಮಾಡೆನ್ನೊಡೆಯ!\n3. ಹಲವು ಜನಗಳನ್ನು\nಆದರಿಸುವ ಹಾಗೆಯೂ,\nನೀ ನನ್ನ ಬಲಪಡಿಸು,\nನನ್ನನ್ನು ಕಾಪಾಡುತ್ತಿರು !\n4. ಅಮೂಲ್ಯ ನಿನ್ನ ಮಾತನ್ನೇ\nನಾನಾಡಿ ಬರುವಂತೆಯೇ,\nನನ್ನನ್ನು ಕಲಿಸ್ಯೇಸುವೇ ;\nಸಹಾಯ ಕೊಡು ನನಗೆ.\n5. ಕಷ್ಟದ ಕಾಲದಲ್ಲಿಯೇ,\nಪ್ರೀತಿಯ ಮಾತನ್ನಾಡಲು,\nನಿನ್ನ ಸುಶಾಂತಿ ನನಗೆ\nನನ್ನೊಡೆಯಾ, ನೀ ಪಾಲಿಸು.\n6. ನನ್ನಲ್ಲಿ ಪೂರ್ಣ ಪ್ರೀತಿಯು\nತೋರಲಿಕ್ಕೆ ಕ್ರಿಸ್ನೇಸುವೆ\nನಿನ್ನಾತ್ಮನಿಂದ ನಡಿಸು,\nಕೆಲಸ ಮಾಡು ನನ್ನಲ್ಲೇ !\n7. ನನ್ನನ್ನು ಉಪಯೋಗಿಸು ;\nನಿನ್ನ ಸುಚಿತ್ತ ನನ್ನಲ್ಲೂ\nಸ್ವರ್ಗಕ್ಕೆ ಸೇರೋವರೆಗೂ\nನನ್ನೊಡೆಯಾ ನೀ ನಡಿಸು." },
  288: { title: "ಮಂಗಳ ಶ್ರೀ ರಾತ್ರಿಯಲಿ", lyrics: "1. ಮಂಗಳ ಶ್ರೀ ರಾತ್ರಿಯಲಿ\nಬೇತ್ಲೆಹೇಮ್ ಛತ್ರದಿ\nವರ ಕನ್ಯೇಲಿ ಜನಿಸಿದ\nದೇವಪುತ್ರನಂ ವಂದಿಸುವ\nವಂದನೆ ರಕ್ಷಕನೇ !\n2. ಮಂಗಳ ಶ್ರೀ ರಾತ್ರಿಯಲಿ\nದೂತರು ಹೊಲದಿ\nಹಿಂಡು ಕಾಯುವ ಕುರ್ಬರಿಗೆ\nತಂದ ವಾರ್ತೆಯು ಶ್ರೇಷ್ಠವದೆ\nಬಂದನು ರಕ್ಷಕನೇ!\n3. ಮಂಗಳ ಶ್ರೀ ರಾತ್ರಿಯಲಿ\nಜಾತನ ಮುಖದಿ\nಸುಪ್ರಸನ್ನತೆ ಶೋಭಿಸುತೆ\nನೀತಿ ಸದ್ಗತಿ ಭ್ರಷ್ಟರಿಗೆ\nಸ್ವಾಗತ ರಕ್ಷಕನೇ !\nಪಲ್ಲವಿ\nನನ್ನ ಯೇಸು ಶಕ್ತನು ॥\nಎಂದೂ ನಡೆಸುವನು ॥\nಆನಂದವೇ, ಕರ್ತ ನನ್ನ ದುರ್ಗವೇ ॥\nಅನುದಿನ, ಆತನೊಡಗೂಡಿ\nನಡೆಯುವ |॥\nಚರಣಗಳು" },
  289: { title: "ಅದ್ಭುತವು ಆತನ್ ಪ್ರೀತಿ ॥", lyrics: "1. ಅದ್ಭುತವು ಆತನ್ ಪ್ರೀತಿ ॥\nಎಂದಿಗೂ ತಳ್ಳದಂತಹ ರೀತಿ ॥\nಪಾಪಿಯಾದ ನನ್ನನ್ನಾತ ॥\nಇಂದೆನಗೆ ಯೇಸುವಲ್ಲೇ ॥\nನಿತ್ಯವಾದ ದೇವಶಾಂತಿಯು!\nಶುದ್ಧತೆ ಹೊಂದ ಬುಗ್ಗೆಯದು |॥\nಕರಿ್ತನ ಕ್ತವದು ॥\nಪಾಪಿಗೆ ದೇವರ ದಾನವಿದು!\nಎಂದೆಂದು ಉಚಿತವು ॥.. ...ನನ್ನ\nಕರೆದಿಹ ಪಾಪಿಯ ದೀನನಾಗಿ ॥\nಹೊಂದದೆ ಹೋದರೆ ರಕ್ಷಣೆಯ |॥\nಕೃಪೆಯ ಕಾಲದಿ\nನ್ಯಾಯತೀರ್ಪ ದಿನದಿ 11\n..ನ್ನ\nಮಕ್ಕಳ ಸಂಗೀತಗಳು" },
  290: { title: "ಎಲ್ಲವನ್ನು ದೇವರು", lyrics: "1. ಎಲ್ಲವನ್ನು ದೇವರು\nಉಂಟು ಮಾಡಿದನು,\nಇಹ ಪರಲೋಕವ\nಆತನು ಮಾಡಿದ.\n2. ಬೇರೆ ಬೇರೆ ಬಣ್ಣದ\nಹೂ ಹಕ್ಕಿಗಳನ್ನೂ\nಸೃಷ್ಠಿಕರ್ತ ದೇವರು\nಉಂಟು ಮಾಡಿದನು.\n3. ಆತನು ಬೆಟ್ಟಗಳ,\nನದಿಗಳ ಸಹಾ,\nಆಕಾಶವನ್ನು ಕೂಡ,\nಎಲ್ಲವ ಮಾಡಿದ.\n4. ಮಳೆಗಾಲ ಚಳಿಯೂ,\nಬೇಸಿಗೇ, ಸೂರ್ಯನ\nತೋಟಗಳ ಫಲವ\nಪಾಲಿಸಿದಾತನು.\n5. ಎಲ್ಲ ನೋಡುವ ಕಣ್ಣು\nಸ್ತೋತ್ರವ ಮಾಡಲು,\nಬಾಯಿ ನಮ್ಮಲ್ಲಿಟ್ಟು\nಕಾಪಾಡುವವನು." },
  291: { title: "ತಮ್ಮ ಮಕ್ಕಳನ್ನು", lyrics: "1. ತಮ್ಮ ಮಕ್ಕಳನ್ನು\nಕರೆದುಕೊಂಡು ತಂದು,\nಕ್ರಿಸತೇಸುವಿನ ಹತ್ತಿರ\nಜನ ಬಂದರು.\nಹೋಗಿರಿ-ಎಂದು ಶಿಷ್ಯರು\nತಿಳಿಸಲಾಗಿ,ಕ್ರಿಸ್ತನು\nಸಣ್ಣ ಮಕ್ಕಳು ಬರಲಿ - ಅಂದನು\nಕುರುಬನ ಹಾಗೆ,\nಆ ಚಿಕ್ಕ ಮಕ್ಕಳನ್ನು\nಕುರಿಮರಿಗಳಂತೆಯೇ\nನಾ ಸಾಕುವೆನು,\nನನ್ನನ್ನು ನಂಬುವವರನ್ನು\nಸ್ವರ್ಗಕ್ಕೆ ಸೇರಿಸುವೆನು\nಸಣ್ಣ ಮಕ್ಕಳು ಬರಲಿ – ಅಂದನು.\n3. ಆ ಮಕ್ಕಳು ಬರ\nಹೇಳಿದ ನಮ್ಮ ಕರ್ತ\nಎಂಥವನೆಂದು ನೋಡಿರಿ\nಪ್ರಿಯ ಮಕ್ಕಳೇ ;\nಅಲ್ಲಲ್ಲಿ ಎಷ್ಟು ಮಕ್ಕಳು\nಆತನ ಶಬ್ದ ಕೇಳರು ;\nಸಣ್ಣ ಮಕ್ಕಳು ಬರಲಿ – ಅಂದನು.\n4. ಅಲ್ಲಲ್ಲಿಯ ಜನ\nಸ್ವ ವಿಗ್ರಹಗಳನ್ನು\nಬಿಸಾಡಿ ದೇವರ ಕಡೆಗೆ\nಎಂದು ಬರ್ವರು ?\nಓ ದೇವಾ, ಎಲ್ಲಾ ಮಕ್ಕಳು\nನಿನ್ ಕಡೆ ಬರುವಂತೆಯೂ\nಅವರಲ್ಲಿ ಸತ್ಯವ ಹೇಳುತ್ತಿರು !\nಕಾಯುವವನು ;\nಹತ್ರದಲ್ಲಿದ್ದಾನೆ\nಭಯ ಯಾತಕ್ಕೂ ?\nಆತ ಮಾರ್ಗದಲ್ಲಿ\nಮಕ್ಕಳ ಸಂಗೀತಗಳು\nನಡಿಸುತ್ತಲು\nನಮ್ಮನ್ನು ಕಾಪಾಡಿ\nಬರುವಾತನು.\n2. ಯೇಸು ನಮ್ಮನ್ನೆಲ್ಲಾ\nಕಾಯುವಾಗಲು,\nನಮ್ಮಲ್ಲಿ ಮಾತಾಡಿ\nಬರುವಾತನು,\nಕೆಲ ಕಾಲದಲ್ಲಿ\nತಿದ್ದುವಾತನು\nಹಾಗೆ ಮಾಡುತ್ತಾನೆ\nನಮ್ಮ ಮೇಲಿಗೂ.\n3. ಯೇಸು ನಮಗಾಗಿ\nಪ್ರೀತಿಯಿಂದಲೂ\nತನ್ನ ರಕ್ತ ಚೆಲ್ಲಿ\nರಕ್ಷಿಸಿದನು.\nನಂಬುವವರಲ್ಲಿ\nಚಿನ್ಹೆಯಿಟ್ಟನು,\nಇದು ನನ್ನ ಸೊತ್ತು\nಹೇಳುವಾತನು.\n4. ಯೇಸು ಕುರುಬನು\nಕಾಯುವಾತನು\nಯಾವ ವೈರಿ ಬಂದು\nಕೇಡು ಮಾಡನು,\nಕಡೆಯಲ್ಲಿ ನಾವು\nಸಾಯುವವರು ;\nಆತನು ನಮ್ಮನ್ನು\nಸೇರಿಸುವನು." },
  293: { title: "ತನ್ನ ರಾಜ್ಯ ಸ್ಥಾಪಿಸಲು", lyrics: "1. ತನ್ನ ರಾಜ್ಯ ಸ್ಥಾಪಿಸಲು\nಯೇಸು ಬರುವಾಗ\nತನ್ನ ರತ್ನಗಳನ್ನೆಲ್ಲಾ\nಕೂಡಿಸುವನು.\nಪಲ್ಲವಿ\nಕ್ರಿಸ್ತ ಕಿರೀಟದಲ್ಲಿ\nತಾರೆಗಳ ಹಾಗೆ,\nಭಕ್ತರೆಂಬ ರತ್ನಗಳು\nಹೊಳೆಯುವರು.\n2. ಶುದ್ಧ ರತ್ನಗಳ ಹಾಗೆ\nಎಲ್ಲಾ ಭಕ್ತರನ್ನು\nತನ್ನ ನಿತ್ಯ ರಾಜ್ಯದಲ್ಲೇ\nಸೇರಿಸುವನು.\n3. ಕ್ರಿಸ್ತನನ್ನು ಪ್ರೀತಿಸುವ\nಚಿಕ್ಕ ಮಕ್ಕಳೆಲ್ಲಾ\nಯೇಸುವಿನ ರತ್ನಗಳು\nಆಗಿರುವರು." },
  294: { title: "ಪಾಪಕ್ಕೆ ಬಾಗಿಲ", lyrics: "1. ಪಾಪಕ್ಕೆ ಬಾಗಿಲ\nಮುಚ್ಚುವ ಪಟ್ಲಕ್ಕೆ,\nಅಶುದ್ಧ ಮಾಡ್ವ,\nಅಶುದ್ಧ ಮಾಡ್ವ,\nಯಾವದು ಸೇರದ್ದೇ!\n2. ರಕ್ಷಕ ಯೇಸುವೇ!\nನನ್ನನ್ನು ಶುದ್ಧಿಸು,\nನನ್ನನ್ನು ತೊಳೆ,\nವಿವಿಧವಾದ ಸಂಗೀತಗಳು\nನನ್ನನ್ನು ತೊಳೆ,\nನನ್ನನ್ನು ರಕ್ಷಿಸು.\n3. ಕರ್ತಾ ನಾನೀಗಲೂ\nನಿನ್ನನ್ನು ನಂಬುವೆ ;\nಬಲವ ಕೊಡು,\nಬಲವ ಕೊಡು,\nಪಾಪ ಬಿಡಲಿಕ್ಕೆ.\n4. ಆ ಶುದ್ಧ ಪಟ್ಣದೊಳ್\nನಾ ನಿನ್ನ ಮುಂದೆಯೇ\nನಿರ್ದೋೊಷತೆಯೊಳ್,\nನಿರ್ದೋಷತೆಯೊಳ್,\nನಿರಂತ್ರ ನಿಲ್ಲುವೆ !" },
  295: { title: "ಜ್ಯೋತಿ ಸ್ವರೂಪ ದೇವರೇ;", lyrics: "1. ಜ್ಯೋತಿ ಸ್ವರೂಪ ದೇವರೇ;\nನಿನ್ ಮುಂದೆ ನಿಲ್ಲಲು\nಯಾರಿಂದ ಸಾಧ್ಯವಾಗುತ್ತೆ ?\nಕಲ್ಮಷ ಪಾಪ ಯಾವದೂ\nಕಾಣಲು ಬಾರದು.\n2. ನಿನ್ ಸುತ್ತಲಾಗಿ ದೂತರು\nಆ ಜ್ಯೋತಿ ತಾಳ್ವರು;\nಅವರು ಪಾಪ ಮಾಡಲು\nಅಸಾಧ್ಯವೆಂದು ಅಲ್ಲಿಯು\nಎಂದೆಂದೂ ನಿಲ್ವರು.\n3. ಪಾಪಿಷ್ಠನಾದ ನನಗೂ\nಆ ಜ್ಯೋತಿ ಸಾಧ್ಯವೇ ?\nನಾ ಹ್ಯಾಗೆ ಅಲ್ಲಿ ನಿಲ್ವೆನು ?\nನನ್ನಾತ್ಮ ಹ್ಯಾಗೆ ತಾಳುತ್ತೆ\nಆ ಪ್ರಭೆಯಲ್ಲಿಯೇ ?\n4. ಕ್ರಿಸ್ರಸುವಿನ ಕೃಪೆಯೇ\nಮಾರ್ಗವ ಮಾಡಿತು ;\nಸ್ವರಕ್ತ ಚೆಲ್ಲಿ ನನಗೆ\nಶುದ್ಧತೆ ಪಾಲಿಸಿದನು\nಸಾಧ್ಯ ಮಾಡಿದನು.\n5. ದೇವರು ಪುತ್ರನಿಂದಲೇ\nಕರೆದ ನನ್ನನ್ನು ;\nಆತನ ಪ್ರೀತಿಯಿಂದಲೇ\nಜ್ಯೋತಿಸ್ವರೂಪಿ ಮುಂದೆಯೇ\nನಿರಂತ್ರ ನಿಲ್ಲುವೆ!" },
  296: { title: "ನಿನ್ ಹತ್ರ ಕರ್ತ, ಬರುವೆ,", lyrics: "1. ನಿನ್ ಹತ್ರ ಕರ್ತ, ಬರುವೆ,\nನೀ ನಮ್ಮ ಘನವೈದ್ಯನೇ\nಕಷ್ಟವು ಯಾವದಿದ್ದರೆ,\nನೀ ಗುಣಮಾಡುವಾತನೇ.\n2. ನಿನ್ನನ್ನು ಕಣ್ಣಿನಿಂದಲೂ\nನೋಡಲಿಕ್ಕಾಗದಿದ್ದರೂ,\nನೀ ನಿನ್ನ ಮಾತಿನಂತೆಯೂ\nಇರುವಿ ಎಂದು ಬಲ್ಲೆವು.\n3. ಓ ಕರ್ತನೇ! ನೀನೀಗಲೇ\nಸಹಾಯ ಮಾಡು ನಮಗೆ\nನಮ್ ಪ್ರೀತಿ ಕಮ್ಮಿಯಾಗಿದೆ ;\nಕೆಲವರಲ್ಲಿ ಇಲ್ಲವೆ !\n4. ಲೋಕವು ಮೋಸ ಮಾಡುತ್ತೆ\nಎಂಬದು ತಿಳುಕೊಂಡರೂ ;\nಅದನ್ನು ಬಿಡಲೊಲ್ಲದ\nಜನರ ಆಶೀರ್ವದಿಸು.\nವಿವಿಧವಾದ ಸಂಗೀತಗಳು\n5. ನಿನ್ ಸೇವೆ ಮಾಡುವವರು\nಸಂಪೂರ್ಣರಾರು ಹೇಳಲು\nಅಸಾಧ್ಯವಾಗದಿದ್ದರೂ,\nಅವರನ್ನಂಗೀಕರಿಸು !\n6. ಪ್ರೀತಿಯ ಭಾವದಿಂದಲೇ\nನೀನವತಾರ ತಾಳಿದ್ದೀ,\nಕರುಣೆ ತೋರಿಸಲಿಕ್ಕೆ\nನೀ ನಮಗಾಗಿ ಸತ್ತಿದ್ದಿ.\n7. ನೀನಾಗ ಮುಟ್ಟಿದ್ದಾಗಲೇ\nಗುಣವ ಮಾಡಿದಾತನೇ\nಈಗಲಾ ಬಲ ಹಾಗೆಯೇ,\nಗುಣವ ಮಾಡಲಾಗುತ್ತೇ." },
  297: { title: "ಹಗಲೀಗ ಹೋಗುತ್ತೇ", lyrics: "1. ಹಗಲೀಗ ಹೋಗುತ್ತೇ\nಕಾವಲೀಗ ಬಂದಿದೆ\nಸಂಜೆಯಲ್ಲಿ ಎಲ್ಲರೂ\nಸ್ತೋತ್ರ ಮಾಡತಕ್ಕದು\nಯೆಹೋವಗೆ.\nಪಲ್ಲವಿ\nಶುದ್ಧ ಶುದ್ಧ ಶುದ್ಧ\nಯೆಹೋವನೇ !\nಇಹ ಪರ ನಿನ್ನನ್ನು\nಸ್ತೋತ್ರಿಸುವರೆಲ್ಲರೂ\nಯೆಹೋವನೇ!\n2. ಜೀವವುಳ್ಳ ಕರ್ತನೇ\nಭಕ್ತರಾದ ನಮ್ಮನ್ನೇ\nಆಶೀರ್ವಾದದಿಂದಲೇ\nನಡಿಸೆಮ್ಮನೆಂದಿಗೂ\nನೀ ಕಾಪಾಡು.\n3. ಕಾವಳಿನ್ನು ಹೆಚ್ಚಲು\nಆಗುತ್ತಿರುವಾಗಲೂ\nನಿನಗೆ, ನಮ್ಮೊಡೆಯಾ,\nನಾವು ಪ್ರಾರ್ಥಿಸುವೆವು,\nಕರುಣಿಸು.\n4. ಲೋಕ ಕಷ್ಟವೆಲ್ಲವು\nಪರಿಹಾರವಾಗುತ್ತೆ!\nಆಗ ಸ್ತೋತ್ರ ನಿನಗೆ\nಸಲ್ಲಿಸುವರೆಲ್ಲರೇ,\nನಿರಂತ್ರವೇ !" },
  298: { title: "ನೀ ಕೊಟ್ಟ ದಿನ ತೀರಿ ಬಂತು,", lyrics: "1. ನೀ ಕೊಟ್ಟ ದಿನ ತೀರಿ ಬಂತು,\nಈಗಲು ರಾತ್ರಿಯಾಗಿದೆ ;\nಹೊತ್ತಾರೆಯಲ್ಲಿ ಸ್ತೋತ್ರ ಕೊಟ್ಟು\nನಾನೀಗ ಹಾಗೆ ಮಾಡುವೆ.\n2. ಈ ಲೋಕ ಸುತ್ತಿ ಬರುವಾಗ\nನಿನ್ ಸಭೆ ಕಾಯುತ್ತಿರುತ್ತೆ ;\nಪ್ರಾರ್ಥನೆಯಲ್ಲಿ ಇರುವಾಗ\nನಿನ್ ಕಾರ್ಯ ನಡೆಯುತ್ತದೆ.\n3. ಈ ದೇಶದಲ್ಲಿ ಕತ್ತಲಿದೆ\nಆ ದೇಶದಲ್ಲಿ ಬೆಳಕು,\nಅಲ್ಲ್ಲಿ ಕ್ನೈಸ್ತ ಸಭಿಕರು\nಕೊಂಡಾಟ ಸಲ್ಲಿಸುವರು.\n4. ಆ ದೇಶದಲ್ಲಿ ಸೂರ್ಯ ಮೂಡಿ\nಭಕ್ತರು ಸೇವಿಸುವರು\nಅಲ್ಲಲ್ಲಿ ಸ್ತೋತ್ರ ಕೊಡುತ್ತಾರೆ,\nಪ್ರಾರ್ಥನೆ ಮಾಡಲ್ಪಡುತ್ತೆ.\nವಿವಿಧವಾದ ಸಂಗೀತಗಳು\n5. ಈ ಲೋಕ ಕೆಡುತ್ತಿರುವಲ್ಲಿ;\nನಿನ್ ಲೋಕ ಶುದ್ಧವಾಗುತ್ತೆ ;\nಎಂದೆಂದಿಗೂ ನಿನ್ನಾಮ ಹಾಡಿ\nಕೊಂಡಾಟ ಮಾಡುತ್ತಿರುವೆ." },
  299: { title: "ಸಂಜೆಯಲ್ಲಿ ಸಹ ಬಿತ್ತುತ್ತಾ ಇರು!", lyrics: "ಸಂಜೆಯಲ್ಲಿ ಸಹ ಬಿತ್ತುತ್ತಾ ಇರು!\nಮುಂದೆ ಸುಗ್ಗಿಕಾಲ ಬರುತ್ತದೆ ಎಂದು\nಜ್ಞಪ್ತಿಮಾಡಿಕೊಂಡು ಕೆಲಸ ಮಾಡಿರು\nಪಲ್ಲವಿ\nಫಲ ಸಿಕ್ಕುತ್ತೆ ಫಲ ಸಿಕ್ಕುತ್ತೆ\nಪೂರ್ಣಾನಂದದಿಂದ\nಬಿತ್ತುತ್ತಾ ಇರು!\nಫಲ ಸಿಕ್ಕುತ್ತೆ, ಫಲ ಸಿಕ್ಕುತ್ತೆ\nಪೂರ್ಣಾನಂದದಿಂದ\nಬಿತ್ತುತ್ತಾ ಇರು!\n2. ಬಿಸಿಲಿರುವಲ್ಲಿ ನೆರಳಿರುವಲ್ಲಿ\nದೇವವಾಕ್ಯ ಸಾರು, ಹೇಳುತ್ತಾ ಇರು,\nಅಂತ್ಯಕಾಲದಲ್ಲಿ ಪೂರ್ಣಾನಂದದಲ್ಲಿ\nಫಲ ಸಿಕ್ವದೆಂದು ಜ್ಞಪ್ತಿಮಾಡಿರಿ." },
  300: { title: "ದುಷ್ಟೇರ್ಣೆಗೆಂದೂ ಕಿವಿಕೊಡದೆ", lyrics: "1. ದುಷ್ಟೇರ್ಣೆಗೆಂದೂ ಕಿವಿಕೊಡದೆ\nಯಾವಾಗಲೂ ಜಯ ಹೊಂದುತ್ತಾ ಇರು\nಹೋರಾಡಿ ದುರಾಶೆ ಸೋಲಿಸಲು\nಕರ್ತನ ಸಹಾಯ ಬೇಡಿಕೊಂಡಿರು.\nವಿವಿಧವಾದ ಸಂಗೀತಗಳು\nಪಲ್ಲವಿ\nಕರ್ತ ಬಲ ಸಹಾಯ\nಬೇಡಿಕೊಳ್ಳುತ್ತಾ ಇರು\nಆತ ನಿನ್ನನ್ನು ಕೇಳಿ\nಸಹಾಯಿಸುವ.\nದುಸ್ಸಂಗವ ಮತ್ತು ದುರ್ಭಾಷೆ ಬಿಡು\nದೇವರ ಸಹಾಯ ಬೇಡುತ್ತಾ ಇರು,\nಇತರರ ಲಾಭವುಂಟಾಗಲಿಕ್ಕೂ\nನೀ ಬದುಕಿ ಬಂದು ಕೈಹಾಕುತ್ತಿರು.\nಿಜಯವ ಹೊಂದಿ ಬಂದವರಿಗೂ\nಸುಜಯದ ಮಾಲೆ ಸಿಕ್ಕಿರುವದು\nಹೋರಾಡುತ್ತಾ ಕರ್ತ ವಾಕ್ಯವ ನಂಬು\nನಿನ್ನಲ್ಲಿ ವಿಜಯವುಂಟಾಗುವದು." },
  301: { title: "ಸುವಾರ್ತೆಯನ್ನು ಸಾರ", lyrics: "1. ಸುವಾರ್ತೆಯನ್ನು ಸಾರ\nಸಂತೋಷ ಪಡುವೆ,\nಕ್ರಸ್ರೇಸುವಿನ ವಾಕ್ಯ\nನಾ ಹೇಳುತ್ತಿರುವೆ,\nಆ ಶುಭವಾರ್ತೆ ಸತ್ಯ\nನಾ ತಿಳುಕೊಳ್ಳುವೆ\nಅದನ್ನು ಸಾರುವಾಗ\nಸಂತೋಷ ಪಡುವೆ.\nಪಲ್ಲವಿ\nಸುವಾರ್ತೆಯನ್ನು ಸಾರ\nಎಂದೆಂದಾನಂದಿಸುವೆ ;\nಕ್ಿಸ್ರೆಸುವಿನ ವಾಕ್ಯ\nನಾ ಹೇಳಲಿರುವೆ!\n2. ಆಶ್ಚರ್ಯವಾದ ವಾರ್ತೆ\nಯೋಚನೆ ಮೀರುತ್ತೆ ;\nಇನ್ಯಾವ ರೀತಿಯಲ್ಲಿ\nರಕ್ಷಣೆಯಾಗುತ್ತೆ ?\nಆ ವಾರ್ತೆಯು ನನ್ನಲ್ಲಿ\nಸುಕಾರ್ಯ ಮಾಡಿದೆ\nಎಲ್ಲೆಲ್ಲಿಯೂ ನಾ ಹೇಳಿ\nಅದನ್ನು ಸಾರುವೆ.\n3. ಸುವಾರ್ತೆ ಹೇಳುವಲ್ಲಿ\nಆನಂದವಿರುತ್ತೆ ;\nಕ್ರಿಸ್ಯೆಸುವಿನ ಪ್ರೀತಿ\nತೋರುತ್ತ ಬರುತ್ತೆ.\nಅದನ್ನು ಬಹುಜನ\nಎಂದಿಗೂ ಕೇಳರು !\nಆ ವಾರ್ತೆ ಅವರಿಗೆ\nನಾ ಸಾರುವವನು.\n4. ಭಕ್ತರು ಅರ್ಥಹೇಳ\nಸಂತೋಷಿಸುವರು ;\nಅದನ್ನು ಕೇಳುವಾಗ\nಸಂತೋಷಿಸುವರು,\nಸದಾ ಅದನ್ನು ಹಾಡಿ,\nಸಂಭ್ರಮದಿಂದಲೇ,\nದೇವರ ಹತ್ರ ಸೇರಿ\nನಾ ಹಾಡುತ್ತಿರುವೆ." },
  302: { title: "ಗೊಲ್ಗೊಥ ಗುಡ್ಡಕ್ಕೆ ನನ್ನನ್ನು ಒಯ್ಯು", lyrics: "1. ಗೊಲ್ಗೊಥ ಗುಡ್ಡಕ್ಕೆ ನನ್ನನ್ನು ಒಯ್ಯು\nಅಲ್ಲಿ ಯೇಸುಸ್ವಾಮಿ ನನಗಾಗಿ ಸತ್ತನು,\nಲೋಕದ ಪಾಪದ ಶಾಪವ ತಾಳಿ,\nಎಲ್ಲರಿಗಾಗಿ ತನ್ನ ಪ್ರಾಣ ಕೊಟ್ಟನು.\n2. ಗೊಲ್ಗೊಥ ಗುಡ್ಡಕ್ಷೆ ನನ್ನನ್ನು ಒಯ್ಯು.\nಅಲ್ಲಿ ಯೇಸುಸ್ವಾಮಿ ತನ್ನ ರಕ್ತ ಚೆಲ್ಲಿದ\nಆ ರಕ್ತದಿಂದಲೇ ನನ್ನನ್ನು ಕೊಂಡು,\nಅದರಿಂದಲೇ ನನ್ನನ್ನು ಶುದ್ಧ ಮಾಡಿದ.\n3. ಗೊಲ್ಗೊಥ ಗುಡ್ಡಕ್ಕೆ ನನ್ನನ್ನು ಒಯ್ಯು,\nಅಲ್ಲಿ ನಾನು ಯೇಸುವಿನ ಕ್ರೂಜೆ ನೋಡುವೆ\nಅಲ್ಲಿಯೇ ಇಂಪಾದ ಸೌಖ್ಯವ ಹೊಂದಿ\nಬೇರೊಂದು ಇಂಥ ಸ್ಥಾನ ನಾನು ಅರಿಯೆ.\n4. ಗೊಲ್ಗೊಥ ಗುಡ್ಡಕ್ಕೆ ನನ್ನನ್ನು ಒಯ್ಯು\nಶಿಲುಬೆಯ ಹತ್ರ ಸರ್ವಕಾಲ ಬಾಳುವೆ,\nಕರ್ತನ ದಿವ್ಯ ಕಟಾಕ್ಷವ ನೋಡಿ,\nಆತನನ್ನೇ ನಾನು ಪ್ರೀತಿ ಮಾಡುವೆ.\n5. ಗೊಲ್ಗೊಥ ಗುಡ್ಡಕ್ಕೆ ನನ್ನನ್ನು ಒಯ್ಯು,\nಅಲ್ಲಿ ನನ್ನ ಎಲ್ಲಾ ಆಶೆ ಬುಗ್ಗೆ ನೋಡುವೆ,\nಕರ್ತನ ಸಂಗಡ ಮೇಲ್ಲೋಕದಲ್ಲಿ\nಕ್ರೂಜೆಯ ಬಗ್ಗೆ ಸರ್ವಕಾಲ ಹಾಡುವೆ." },
  303: { title: "ದೂರ ದೇಶದಲ್ಲಿ ಕ್ರೂಜೆಯ", lyrics: "1. ದೂರ ದೇಶದಲ್ಲಿ ಕ್ರೂಜೆಯ\nಮೇಲೆಯೇ\nನಮ್ಮ ಶ್ರೇಷ್ಠ ಕರ್ತ ಸತ್ತನು.\nಪಾಪದಿಂ ತುಂಬಿದ\nಲೋಕಕ್ಕೋಸ್ಕರವೇ\nತನ್ನ ರಕ್ತವ ಚೆಲ್ಲಿದನು.\nವಿವಿಧವಾದ ಸಂಗೀತಗಳು\nಪಲ್ಲವಿ\nಯೇಸುವು ಬರುವ ವರೆಗೆ,\nನನ್ನ ಕ್ರೂಜೆಯ ಹೊರುವೆನು,\nಆಗ ಕ್ರೂಜೆಯ ಬದಲಾಗಿ\nನಾನು ಕಿರೀಟ ಹೊಂದುವೆನು\n2. ಲೋಕವು ಕ್ರೂಜೆಯ ತಿರಸ್ಕರಿಸುತ್ತೆ\nಆದಾಗ್ಯೂ ನನಗೆ ಚಂದದ್ದು\nದೇವರ ಕುರಿಯು ಮೆಲ್ಲೋಕವ ಬಿಟ್ಟು\nತಾನೇ ಕ್ರೂಜೆಯ ಏರಿದನು.\n3. ಕ್ರೂಜೆಯ ತಾಳಿದ ಯೇಸು ಕ್ರಿಸ್ತಗಾಗಿ\nಅಪಮಾನವ ತಾಳುವೆನು,\nಕಡೆಗೆ ಕರ್ತನ ಅಪ್ಪಣೆ ಕೈಕೊಂಡು\nನಾನು ಸ್ವರ್ಗಕ್ಕೆ ಸೇರುವೆನು." },
  304: { title: "ಪಲ್ಲವಿ", lyrics: "ಪಲ್ಲವಿ\nಕ್ರಿಸ್ಯೈಸು ದೇವರ ಪುತ್ರ,\nಕ್ರಿಸ್ರೈಸು ಮಾನವ ಪುತ್ರ\nಕ್ರೂಜೆಯ ಕಂಬದ ಮೇಲೆ,\nಸ್ವಪ್ರಾಣವ ಕೊಟ್ಟಿದ್ದಾನೆ.\nಚರಣಗಳು" },
  305: { title: "ಮೇಲಣ ಲೋಕವ ಬಿಟ್ಟು", lyrics: "1. ಮೇಲಣ ಲೋಕವ ಬಿಟ್ಟು\nಭೂಲೋಕಕ್ಕೆ ಬಂದನು\nಮನುಜ ರೂಪವ ಹೊಂದಿ,\nನಮ್ಮಂತೆಯೇ ಬಾಳಿದನು.\nವಿವಿಧವಾದ ಸಂಗೀತಗಳು\n2. ಪಾಪಿಷ್ಠರೇ ಆತನನ್ನು\nಹಿಡುಕೊಂಡು ಹೋದರು.\nಮರದ ಕಂಬದ ಮೇಲೆ,\nತೂಗಾಡಿಸಿ ಕೊಂದರು.\n3. ಸಾವಿನ ಶಕ್ತಿಯ ಮೇಲೆ,\nಜಯವ ಹೊಂದಿ ಬಂದನು.\nಸ್ವರ್ಗಕ್ಕೆ ಏರಿಸಲ್ಟ್ಟು\nಸಿಂಹಾಸನ ಹತ್ತಿದನು.\n4. ಈ ಹೊತ್ತು ಆತನ ಹತ್ರ,\nಓ ಪಾಪಿಗಳೇ ಬನ್ರಿ,\nನಿಮ್ಮೆಲ್ಲಾ ಪಾಪವ ಬಿಟ್ಟು\nಸಂರಕ್ಷಣೆಯ ಹೊಂದಿರಿ." },
  306: { title: "ಯೇಸು ಸ್ವಾಮಿ ತಾನೇ ಬೇಕು.", lyrics: "1. ಯೇಸು ಸ್ವಾಮಿ ತಾನೇ ಬೇಕು.\nಲೋಕಾನಂದ ಹೋಗುತ್ತೆ.\nಯೇಸುವಿನ ಶ್ರೇಷ್ಠ ಪ್ರೀತಿ,\nಸರ್ವಕಾಲ ತಾಳುತ್ತೆ.\nಪಲ್ಲವಿ\nಯೇಸುಸ್ವಾಮಿ ನನ್ನ ಮೇಲೆ,\nಎಷ್ಟೋ ಪ್ರೀತಿ ಇಟ್ಟನು,\nನನ್ನನ್ನೇ ರಕ್ಷಿಸಲಿಕ್ಕೆ\nತನ್ನ ಪ್ರಾಣ ಕೊಟ್ಟನು.\n2. ಯೇಸುಸ್ವಾಮಿ ತಾನೇ ಬೇಕು,\nಮನಶ್ಯಾಂತಿ ನೀಡುವ,\nನನ್ನ ಜೀವ ಮಾರ್ಗದಲ್ಲಿ,\nಸುಪ್ರಕಾಶ ಕೊಡುವ.\n3. ಯೇಸುಸ್ವಾಮಿ ತಾನೇ ಬೇಕು,\nಆತನೊಂದಿಗಿರುವೆ.\nದಿವ್ಯ ಸಮಾಧಾನ ಹೊಂದಿ,\nಕಷ್ಟದೊಳ್ ನಾ ಹಾಡುವೆ.\n4. ಯೇಸುಸ್ವಾಮಿ ನನಗಾಗಿ,\nಲೋಕದಲ್ಲಿ ಬಾಳಿದ,\nಪಾಪ ಭಾರ ಹೊತ್ತುಕೊಂಡು,\nಕ್ರೂಜೆಯನ್ನು ತಾಳಿದ.\n5. ಯೇಸುಸ್ವಾಮಿ ತಾನೇ ಬೇಕು,\nನೋಡದೆ ನಾ ನಂಬುವೆ,\nಕಡೆಯಲ್ಲಿ ಸ್ವರ್ಗದಲ್ಲಿ\nನಾ ಕಣ್ಣಾರೆ ಕಾಣುವೆ." },
  307: { title: "ಓ ಕ್ರಿಸ್ತ ಭಕ್ತರೇ", lyrics: "1. ಓ ಕ್ರಿಸ್ತ ಭಕ್ತರೇ\nಸಂತೋಷ, ಪಡುವಾ,\nಕ್ರಿ್ತಗೆ ಸ್ತೋತ್ರವು\nಪಲ್ಲವಿ\nಚೀಯೋನ್ ನಮ್ಮ ಸ್ಥಾನ,\nಸುಂದರ ಸುಂದರ ಚೀಯೋನ್\nದೇವರ ಸುಂದರ ಸ್ಥಾನ,\nಚೀಯೋನಿಗೆ ಹೋಗುವೆವು.\n2. ದೇವರ ಮಕ್ಕಳೇ,\nಈ ಗಾನ ಹಾಡಲಿ,\nಮತ್ತ್ಯಾರು ಹಾಡಲಾರರು ॥\n3. ದೇವರ ಮುಖವ,\nಅಲ್ಲಿ ನೋಡುವೆವು,\nಎಂದೆಂದಿಗೂ ಚೀಯೋನಿನೊಳ್ ॥\nಪಾಪವ ಮಾಡೆವು 1॥\n4. ಚೀಯೋನಿನಿಂದಲೇ,\nಸಹಾಯ ಬರುತ್ತೆ,\nಪ್ರವಾಸದಲ್ಲಿ ನಮಗೆ ॥\nಪ್ರಕಾಶ ಸಿಕ್ಕುತ್ತೆ ॥\n5. ಗೋಳಾಡ ಬಾರದು,\nಸಂತೋಷ ಪಡುವಾ,\nನಾವೆಲ್ಲಾ ಮುಂದೆ ಹೋಗುವಾ 1॥\nಸ್ತೋತ್ರವ ಹಾಡುವಾ 1॥" },
  308: { title: "ವಾತ್ಸಲ್ಯದಿಂದ ಕ್ರಿಸ್ತ್ಯೇಸುವು", lyrics: "1. ವಾತ್ಸಲ್ಯದಿಂದ ಕ್ರಿಸ್ತ್ಯೇಸುವು\nದಿನವೂ ನಿನ್ನನ್ನೂ ಕಾಯ್ವನು\nತಾಯಿ ಕೂಸ ಕಾಯುತ್ತಿರುವಂತೆಯೂ\nಯೇಸುವು ನಿನ್ನನ್ನೂ ಕಾಯ್ವನು\nದುಖದೊಳ್ ನಷ್ಟದೊಳ್\nಅಂಜಬೇಡ ಮಗುವೇ, ನಿನ್ನನ್ನೂ\nಕೈಬಿಡೆನು\nಎಂದು ನಮ್ಮ ಶ್ರೇಷ್ಠ ಕರ್ತನು\nದಿನವೂ ನಿನ್ನನ್ನೂ ಕಾಯ್ವನು.\n2. ವಾತ್ಸಲ್ಯದಿಂದ ಕ್ರಿಸ್ತೇಸುವು,\nದಿನವೂ ನಿನ್ನನ್ನೂ ಕಾಯ್ವನು\nತಾಯಿ ಕೂಸ ಕಾಯುತ್ತಿರುವಂತೆಯೂ\nವಿವಿಧವಾದ ಸಂಗೀತಗಳು\nಯೇಸುವು ನಿನ್ನನ್ನೂ ಕಾಯ್ವನು\nಧರಣಿ ಸೃಷ್ಟಿಸುವುದಕ್ಕಿಂತ ಮೊದಲು\nಕರ್ತನು ನಿನಗಾಗಿಯೂ ಚಿಂತಿಸಿದನ್ನು\nವಾತ್ಸಲ್ಯದಿಂದ ಕ್ರಿಸ್ತೇಸುವು\nದಿನವೂ ನಿನ್ನನ್ನೂ ಕಾಯ್ವನು." },
  309: { title: "ಓ ಕರ್ತಾ, ನಿನ್ನ ಪ್ರೀತಿ ನಮಗೆ", lyrics: "1. ಓ ಕರ್ತಾ, ನಿನ್ನ ಪ್ರೀತಿ ನಮಗೆ\nಸಂಬೋಧಿಸು,\nನಿನ್ನ ಕೈಕಾಲುಗಳ ನಮಗೆ\nತೋರ್ಪಡಿಸು,\nನಮ್ಮ ಹೃದಯದಿಂದಲೇ ನಾವು\nಆರಾಧನೆಯ ಸಲ್ಲಿಸುವೆವು.\n2. ನಿನ್ನ ಮರಣದಿಂದ ನಮಗೆ\nದೇವ ಪ್ರೀತಿ\nತೋರಿಸಿದಿ; ನಾವೀಗ ನಿನಗೆ\nಸ್ತೋತ್ರ ಸ್ತುತಿ\nಅರ್ಪಿಸುತ್ತೇವೆ, ಯೇಸು ಕರ್ತನೇ\nದೇವಪುತ್ರಾ, ನಮ್ಮ ಜೀವ ನೀನೇ.\n3. ನಿನ್ನ ದೇಹ ಆಹಾರ ನಮಗೆ\nಆಗಿರುತ್ತೆ,\nನಿನ್ನ ರಕ್ತವೇ ಪಾನ ನಮಗೆ\nಆಗಿರುತ್ತೆ,\nನಾವೆಂದೂ ನಿನ್ನ ಸಾವಿನಿಂದಲೇ\nಜೀವಿಸುತ್ತೇವೆ, ಯೇಸು ಕರ್ತನೇ\nವಿವಿಧವಾದ ಸಂಗೀತಗಳು\nಸಾರಲಿಕ್ಕೆ ಹೊರಡು\nಯೇಸು ಪಾಪಿಗಳಿಗಾಗಿ\nತನ್ನ ಪ್ರಾಣ ಕೊಟ್ಟನು.\nಪಲ್ಲವಿ\nಹೌದು ನಾನು ಹೋಗುತ್ತೇನೆ,\nಸುವಾರ್ತೆ ಸಾರಲಿಕ್ಕೆ ಹೋಗುತ್ತೇನೆ\nಹೌದು ನಾನು ಯೇಸುವಿನ\nಸುವಾರ್ತೆ ಸಾರುವೆ.\n2. ಪಾಪಿಗಳಿಗೆ ಸುವಾರ್ತೆ\nಸ್ಪಷ್ಟವಾಗಿ ತಿಳಿಸು\nಅವರ ದುಸ್ಥಿತಿಯನ್ನೇ\nಅವರಿಗೆ ತೋರಿಸು.\n3. ಸ್ವರ್ಗದ ಸುಖದ ಬಗ್ಗೆ\nಜನರಿಗೆ ತಿಳಿಸು\nಇದನ್ನೆಲ್ಲ ಕೊಡಲಿಕ್ಕೆ\nಯೇಸು ದುಖು ಪಟ್ಟನು.\n4. ಯೇಸು ತನ್ನ ಸಭೆಗಾಗಿ\nಸ್ಥಾನ ಸಿದ್ಧ ಮಾಡಲು\nಈಗ ಪರಲೋಕದಲ್ಲಿ\nಇದ್ದಾನೆಂದು ತಿಳಿಸು." },
  310: { title: "ಯೆಹೋವ ದೇವ ಭಯಭಕ್ತಿಯಿಂದ", lyrics: "1. ಯೆಹೋವ ದೇವ ಭಯಭಕ್ತಿಯಿಂದ\nನಿನ್ ಸೃಷ್ಟಿಯನ್ನು ನಾನು ನೋಡುವೆ ;\nಸ್ವಹಸ್ತದಿಂದ ನೀನು ಇದನ್ನೆಲ್ಲಾ\nತಯಾರಿಸಿದ್ದೀ ಎಂದು ನಂಬುವೆ.\nಪಲ್ಲವಿ\n2. ಅರಣ್ಯದಲ್ಲಿ ತಿರುಗಾಡುವಾಗ\nಇಂಪಾದ ಪಕ್ಷಿ ಸ್ವರ ಕೇಳುವೆ\nಪರ್ವತದಲ್ಲಿನ ಸೌಂದರ್ಯವನ್ನು\nಆನಂದದಿಂದ ನಾನು ನೋಡುವೆ.\n3. ಸ್ವಪುತ್ರನನ್ನು ದೇವರು ಎಂಗಾಗಿ\nಶಿಲುಬೆ ಸಾವಿಗೊಪ್ಪಿಸಿದನು\nಎನ್ ಪಾಪ ಭಾರ ಹೊತ್ತುಕೊಳ್ಳುವಂತೆ\nಸ್ವರಕ್ತ ಚೆಲ್ಲಿ ಯೇಸು ಸತ್ತನು.\n4. ಕ್ರಿಸ್ತ್ಯೇಸು ಮಹಿಮೆಯಿಂದ ಬರುವಾಗ\nತುತೂರಿ ಶಬ್ದ ನಾನು ಕೇಳುವೆ\nಸುಸ್ವರ್ಗಕ್ಕೆ ನನ್ನನ್ನು ಒಯ್ಯುವಾಗ\nಎಂದೆಂದೂ ನಾನು ಸ್ತೋತ್ರ ಮಾಡುವೆ." },
  311: { title: "ಯೇಸು ನನ್ನ ರಕ್ಷಕ", lyrics: "1. ಯೇಸು ನನ್ನ ರಕ್ಷಕ\nಪಾಪದಿಂದ ಬಿಡಿಸ\nತನ್ನ ಪ್ರಾಣ ಕೊಟ್ಟಿದ್ದ\nನನ್ನ ಪ್ರಭು!\n2. ಯೇಸು ನನ್ನ ಕುರುಬ\nನನ್ನನ್ನೆಂದೂ ಕಾಯುವ\nನನ್ನ ಮುನ್ನಡಿಸುವ\nನನ್ನ ಪ್ರಭು.\n3. ಯೇಸು ನನ್ನ ಅರಸ\nಆತ ಒಂದು ದಿವಸ\nಆಳಲಿಕ್ಕೆ ಬರುವ\nನನ್ನ ಪ್ರಭು.\n4. ಯೇಸು ನನ್ನ ಕರ್ತನು\nನನಗಾಗಿ ಸತ್ತನು\nನನ್ನ ಪ್ರೀತಿಸುವನು\nನನ್ನ ಪ್ರಭು." },
  312: { title: "ನಿತ್ಯ ಪ್ರೀತಿಯಿಂದಲೇ", lyrics: "1. ನಿತ್ಯ ಪ್ರೀತಿಯಿಂದಲೇ\nಪ್ರೀತಿಸಲ್ಪಟ್ಟಿರುವೆ\nಪವಿತ್ರಾತ್ಮನಿಂದಲೇ\nನಾನು ಕೃಪೆ ಹೊಂದಿದೆ\nಪರಿಪೂರ್ಣ ಶಾಂತಿಯೇ\nದಿವ್ಯವಾದನಂದವೇ\nಶಾಶ್ವತ ಪ್ರೀತಿಯಲ್ಲೇ\nನಾನು ಆತನವನೇ!\nದಿವ್ಯ ಪ್ರೀತಿಯಲ್ಲಿಯೇ\nಆತನು ನನ್ನಾತನೇ!\n2. ಈ ಭೂಲೋಕದಲ್ಲಿಯೇ\nಸುಸೌಂದರ್ಯ ನೋಡುವೆ\nಕ್ರಿಸ್ತಿನಿಂದ ನನಗೆ\nಹೊಸ ದೃಷ್ಟಿ ಸಿಕ್ಕುತ್ತೆ\nಹಕ್ಕಿ ಹೂಗಳಲ್ಲಿಯೂ\nದಿವ್ಯ ಪ್ರೀತಿ ಕಾಣುವೆ\nನನಗೀಗ ಗೊತ್ತುಂಟು\nನಾನು ಆತನವನೇ!\nಎಂಥ ಶ್ರೇಷ್ಠ ಸತ್ಯವು ;\nಆತನು ನನ್ನಾತನು!\nವಿವಿಧವಾದ ಸಂಗೀತಗಳು\n3. ಈಗ ಶಾಂತಿ ಸಿಕ್ಕಿತು!\nದೇವ ಹಸ್ತದಿಂದಲೇ\nಕಷ್ಟವೆಲ್ಲಾ ಹೋಯಿತು\nದೇವ ನನ್ನ ತಂದೆಯೇ\nಆತನು ನನ್ನಾಶ್ರಯ\nನನ್ನ ಆತ್ಮದಾಪ್ತನೇ\nಆತನಲ್ಲಿ ಇರುವೆ\nನಾನು ಆತನವನೇ\nನನಗೆ ಗೊತ್ತಾಗಿದೆ\nಆತನು ನನ್ನಾತನೇ!\n4. ಎಂದೆಂದು ನನ್ನಾತನೇ\nನನ್ನನ್ನು ಕೈಬಿಡನು\nಎಂಥಾ ಸಮಾಧಾನವೇ\nಕ್ರಿಸ್ತನಂದ ಸಿಕ್ಕಿತು!\nಭೂಲೋಕವು ಹೋದರೂ\nಸುಪ್ರಕಾಶ ಹೋದರೂ\nದೇವರಿರುವಾಗಲೇ\nನಾನು ಆತನವನೇ\nಸರ್ವಕಾಲ ಹಾಡುವೆ!\nಆತನು ನನ್ನಾತನೇ." },
  313: { title: "ವಿಶ್ವಾಸದ ರೆಕ್ಕೆಗಳೇ", lyrics: "1. ವಿಶ್ವಾಸದ ರೆಕ್ಕೆಗಳೇ\nನನಗೆ ಇದ್ದರೆ\nನಾ ಹಾರಿ, ಸ್ವರ್ಗದಲ್ಲಿಯೇ\nಭಕ್ತರ ನೋಡುವೆ.\n2. ಹಾ! ಒಮ್ಮೆ ಇಹದಲ್ಲಿಯೇ\nಸಂತಾಪ ಪಟ್ಟರು !\nಸ್ವಪಾಪದ ವಿರೋಧಿಯೇ\nಹೋರಾಡುತ್ತಿದ್ದರು.\nವಿವಿಧವಾದ ಸಂಗೀತಗಳು\n3. ವಿಜಯವು ಎಲ್ಲಿಂದಲೇ\nನಿಮಗೆ ಸಿಕ್ಕಿತು ?\nಈ ಪ್ರಶ್ನೆ ಕೇಳಿ, ನನಗೆ\nಈ ಉತ್ರ ಬಂತು.\n4. ಶ್ರೀ ದೇವ ಕುರಿಮರಿಯು\nಆ ಕ್ರೂಜೆ ಮೇಲೆಯೂ\nಸ್ವಪ್ರಾಣ ಕೊಟ್ಟು ನಮ್ಮನ್ನು\nಸಂರಕ್ಷಿಸಿದನು.\n5. ಕ್ರಿಸ್ತ್ರೇಸು ಹೋದ ಮಾರ್ಗದೊಳ್\nಹಿಂಬಾಲಿಸಿದ್ದೆವು.\nಈವಾಗ ಕ್ರಿಸ್ತ ಪಾದದೊಳ್\nವಿಶ್ರಾಂತಿ ಸಿಕ್ಕಿತು.\n6. ಸುಶ್ರೇಷ್ಠ ಯೇಸು ಕರ್ತನು\nಆ ಮಾರ್ಗವಾದನು,\nಅನೇಕ ದೇವ ಭಕ್ತರು\nಈ ಸಾಕ್ಷಿ ಕೊಟ್ಟರು." },
  314: { title: "ಓ ಕರ್ತಾ, ನಿನ್ನ ಪ್ರೀತಿ ಅಪಾರವಾದದ್ದು", lyrics: "1. ಓ ಕರ್ತಾ, ನಿನ್ನ ಪ್ರೀತಿ ಅಪಾರವಾದದ್ದು\nನಿನ್ನ ನೆನಪು ಮಾಡಿ\nನಾ ಹರ್ಷಿಸುವೆನು.\nಆದಾಗ್ಯೂ ನನ್ನ ಕರ್ತಾ,\nನನ್ನ ಮನದಲ್ಲೇ\nಮಗುವಿನ ನಿರ್ಬಲ\nನನಗೆ ಕಾಣುತ್ತೆ.\n2. ಆದಾಗ್ಯೂ ನಿನ್ನ ಪ್ರೀತಿ ವ್ಯತ್ಯಾಸವಾಗದು\nಪ್ರಕಾಶ ಮತ್ತು ಶಾಂತಿ\nನನಗೆ ಕೊಟ್ಟದ್ದು\nನಿನ್ನ ಸಾನಿಧ್ಯದಲ್ಲಿ\nಹೆಚ್ಚಾಗಿ ಇದ್ದರೆ\nನಾನೆನ್ನ ಜೀವದಲ್ಲಿ\nನಿನ್ನಾತ್ಮ ತೋರುವೆ.\n3. ಓ ಸೂರ್ಯನಂತೆ ನೀನು!\nಪ್ರೀತಿಸುವಾತನು !\nಮೋಡಗಳು ಬರಲು\nನಿನ್ನನ್ನು ನೋಡೆನು.\nಮೇಘವು ಹೋದ ಮೇಲೆ\nನಿನ್ನ ಪ್ರಕಾಶವೇ\nಅತಿ ಸೌಂದರ್ಯದಲ್ಲಿ\nನನಗೆ ಕಾಣುತ್ತೆ.\n4. ಓ ಕರ್ತಾ, ನನ್ನ ಆತ್ಮ\nಕಾಪಾಡುತ್ತಾ ಇರು!\nನಿನ್ನ ದಿವ್ಯ ಚಿತ್ತವ\nನನಗೆ ಬೋಧಿಸು!\nನಿನ್ನ ಕೃಪೆಯನ್ನೆಲ್ಲಾ\nನನಗೆ ತೋರಿಸು,\nನಿನ್ನಲ್ಲಿ ಯೇಸು ಕರ್ತ,\nನಿರೀಕ್ಷಿಸುವೆನು." },
  315: { title: "ಭೂಲೋಕದಲ್ಲಿ ದುಚ್ಥಿತಿಯ", lyrics: "1. ಭೂಲೋಕದಲ್ಲಿ ದುಚ್ಥಿತಿಯ\nನಾನೀಗ ನೋಡುವೆ\nಈ ಕೊರತೆಯ ಮೊರೆಯ\nನಾನೀಗ ಕೇಳುವೆ\nಶ್ರೀ ಯೇಸು, ನಿನ್ನ ಸಭೆಯ\nಈವಾಗ ಎಬ್ಬಿಸು!\nನಿನ್ನಾತ್ಮನಿಂದ ನಮ್ಮನ್ನು\nಸಂಜೀವ ಪಡಿಸು.\n2. ಅನೇಕರೂ ಅಜ್ಞಾನದಿಂ\nವಿಗ್ರಹ ಭಕ್ತರು!\nಅನೇಕರೂ ಅಜ್ಞಾನದಿಂ\nಸಂತೃಪ್ತಿ ಪಡರು!\nಶ್ರೀ ಯೇಸು ಕೃಪೆಯಿಂದಲೇ\nಈ ಕೊರತೆಯನ್ನು\nತಿಳಿದುಕೊಳ್ಳುವದಕ್ಕೆ\nನಿನ್ ಸಭೆ ನಡಿಸು.\n3. ಭೂಲೋಕದಲ್ಲಿ ಈಗಲೂ\nವಿಜ್ಞಾನ ಹೆಚ್ಚಿದೆ\nನಿನ್ ನಾಮ ಸರ್ವ ಲೋಕಕ್ಕೂ\nಸಾರಲ್ಪಡುತ್ತದೆ\nಶ್ರೀ ಯೇಸು, ನಿನ್ನ ವಾಕ್ಯವ\nಎಲ್ಲಾ ರೀತಿಯೊಳು\nನಾ ಧೈರ್ಯದಿಂದ ತಿಳಿಸ\nಸಹಾಯಿಸೆನಗೂ.\n4. ನಿನ್ ನ್ಯಾಯ ಕಾಲ ಘಂಟೆಯು\nನಾ ಕೇಳುತ್ತಿರುವೆ!\nನಿನ್ ಕ್ರೂರವಾದ ಕ್ರೂಜೆಯ\nಜ್ಞಾಪಕ ಮಾಡುವೆ!\nಶ್ರೀ ಯೇಸು, ವಾರ್ತಾ ಸಾರಲು\nನಿನ್ನ ಸಭೆಯನ್ನೂ\nಎಬ್ಬಿಸುತ್ತಿರುವಾಗಲೂ\nನನ್ನ್ನೂ ಎಬ್ಬಿಸು!" },
  316: { title: "ನನ್ನ ರಕ್ಷಕಾ! ಯೇಸು!", lyrics: "1. ನನ್ನ ರಕ್ಷಕಾ! ಯೇಸು!\nನಿನ ಶ್ರೇಷ್ಠ ಪ್ರೀತಿಯು!\nಇದರಲ್ಲಿ ಎಂದೆಂದೂ\nವಿವಿಧವಾದ ಸಂಗೀತಗಳು\nನಾ ಹರ್ಷಿಸುವೆನು\nಸ್ವರ್ಗದ ಮಾರ್ಗದಲ್ಲಿ\nನಾ ಹಾಡುವವನು\nಪಾಪಿಯಾದ ನನಗಾಗಿ\nಕ್ರಸ್ಯೆಸು ಸತ್ತನು\n2. ಗೊಲ್ಗಥ ಕ್ರೂಜೇ!\nಮುಳ್ಳಿನ ಕಿರೀಟ!\nಹಾ ಎಂಥಾ ಸಾವನ್ನೇ\nಕ್ರಿಸ್ಯೈಸು ಹೊಂದಿದ!\nಹಾ ಎಂಥಾ ದಿವ್ಯ ಪ್ರೀತಿ\nನಾನಲ್ಲಿ ಕಂಡೆನು\nಪಾಪಿಯಾದ ನನಗಾಗಿ\nಕ್ರಸ್ಯೆಸು ಸತ್ತನು.\n3. ಕ್ರಿಸ್ತ್ಯೇಸುವಿಗೆ ಸ್ತೋತ್ರ!\nಸುಯಜ್ಞಮಾಡಿದ\nನನ್ನ ಪಾಪದ ಶಿಕ್ಷೆ\nಕರ್ತನು ತಾಳಿದ,\nಕ್ರೂಜೆಯ ಮೇಲೆ ಯೇಸು\n“ತೀರಿತು” ಅಂದನು\nಪಾಪಿಯಾದ ನನಗಾಗಿ\nಕ್ರಿಸ್ೈನು ಸತ್ತನು.\n4. ಎಂದೂ ಸ್ವರ್ಗದಲ್ಲಿ\nನಾ ಕರ್ತನೊಂದಿಗೆ\nದೇವಭಕ್ತರ ಕೂಡ\nಸ್ತೋತ್ರವ ಮಾಡುವೆ,\nನಾ ಹಾಡುತ್ತಿರುವಲ್ಲಿ\nನನ್ನ ಗಾನವಿದು\nಪಾಪಿಯಾದ ನನಗಾಗಿ\nಕ್ಿಸ್ಯಸು ಸತ್ತನು.\nವಿವಿಧವಾದ ಸಂಗೀತಗಳು" },
  317: { title: "ಪಾಪಿಯನ್ನೆಂದಿಗೂ", lyrics: "ಪಾಪಿಯನ್ನೆಂದಿಗೂ\nಅವನ ಪಾಪದಿಂದಲೂ\nವಿಮುಕ್ತಿ ಮಾಡದು.\n2. ಓ ಯೇಸು ಕರ್ತನೇ!\nಸುಯಜ್ಞವೇ ನೀನೇ!\nನಂಗಾಗಿ ಕ್ರೂಜೆ ಮೇಲೆಯೇ\nಸ್ವರಕ್ತ ಚೆಲ್ಲಿದೆ.\n3. ವಿಶ್ವಾಸದಿಂದಲೇ\nನಿನ್ ತಲೇ ಮೇಲೆಯೇ\nಕೈಯಿಟ್ಟುಕೊಂಡು ನಿನಗೆ\nಅರಿಕೆ ಮಾಡುವೆ.\n4. ಕಲ್ವಾರಿ ಕ್ರೂಜೆಯೆ\nನೆನಪು ಮಾಡುವೆ\nಪಾಪದ ಭಾರ ಯೇಸುವೇ\nನೀನಲ್ಲಿ ತಾಳಿದೆ.\n5. ನಿನ್ನ ನಂಬಿ ನಾನೇ\nಸಂತೋಷಪಡುವೆ,\nದೇವರ ಕುರಿಮರಿಗೆ\nಸ್ತೋತ್ರವ ಹಾಡುವೆ." },
  318: { title: "ಕ್ರಿಸ್ತನ ಶಾಶ್ವತ ಪ್ರೀತಿಯೂ", lyrics: "1. ಕ್ರಿಸ್ತನ ಶಾಶ್ವತ ಪ್ರೀತಿಯೂ\nಆತನು ಚೆಲ್ಲಿದ ರಕ್ತವೂ\nಆತನ ರಕ್ಷಣಾ ಮಾರ್ಗವೂ\nಅವುಗಳ ಬಗ್ಗೆ ಹಾಡುವ.\nಪಲ್ಲವಿ\nಕಡೆಗೆ... ಸ್ವರ್ಗದೊಳ್\nನಾವೆಲ್ಲಾ ಕೂಡಿ ಬರುವೆವು\nಕ್ರಿ್ತಿಗೆ. ಎಂದಿಗೂ\nನಾವು ಸ್ತೋತ್ರವ ಹಾಡುವೆವು.\n2. ಕ್ರಿಸ್ತನು ತನ್ನ ರಕ್ತದಿಂದ\nಶುದ್ಧತಾ ಮಾರ್ಗವ ಮಾಡಿದ\nಆತನ ಮಹಾಯಜ್ಞದಿಂದ\nನಿತ್ಯಜೀವವು ಸಿಕ್ಕುತ್ತದೆ.\n3. ಕ್ರಿಸ್ತನ ಪ್ರೀತಿಯು ಈಗಲೇ\nನಮಗೆ ಆನಂದ ಕೊಡುತ್ತೆ\nಕ್ರಿಸ್ತನ ಕೂಡ ಸ್ವರ್ಗದಲ್ಲೇ\nಎಂಥ ಸಂತೋಷವಾಗುತ್ತದೆ." },
  319: { title: "ಮುಖಾ ಮುಖಿಯಾಗಿ ನಾನು", lyrics: "1. ಮುಖಾ ಮುಖಿಯಾಗಿ ನಾನು\nರಕ್ಷಕನ ನೋಡುವೆ,\nನನಗಾಗಿ ಸತ್ತ ಯೇಸು\nಹರ್ಷದಿಂದ ಕಾಣುವೆ.\nಪಲ್ಲವಿ\nಆಗ ಮುಖಾ ಮುಖಿಯಾಗಿ\nಯೇಸುವನ್ನೇ ನೋಡುವೆ,\nನನ್ನ ಗೌರವುಳ್ಳ ಸ್ವಾಮಿ,\nಕಡೆಯಲ್ಲಿ ಕಾಣುವೆ.\n2. ಈಗ ಯೇಸುವಿನ ಮುಖ,\nಮೊಬ್ಬಾಗಿ ನಾ ನೋಡುವೆ,\nಒಂದು ಧನ್ಯವಾದ ದಿನ\nಸ್ಪಷ್ಟವಾಗಿ ಕಾಣುವೆ.\n3. ಯೇಸುಸ್ವಾಮಿ ಎಲ್ಲಾ ಕಷ್ಟ\nಪೂರ್ಣವಾಗಿ ನೀಗುಮ,\nಡೊಂಕು ಮಾರ್ಗಗಳನ್ನೆಲ್ಲಾ\nನೆಟ್ಟಗಾಗಿ ಮಾಡುಮ\n4. ಮುಖಾ ಮುಖಿಯಾಗಿ ನೋಡಿ\nಎಂಥಾನಂದ ಹೊಂದುವೆ\nನನ್ನ ಪ್ರೀತಿಯುಳ್ಳ ಸ್ವಾಮಿ,\nಕರ್ತನಾದ ಯೇಸುವೆ." },
  320: { title: "ಕ್ರಿಸ್ತನ ಕ್ರೂಜೇ ಹತ್ರ", lyrics: "1. ಕ್ರಿಸ್ತನ ಕ್ರೂಜೇ ಹತ್ರ\nನಾ ನಿಂತುಕೊಳ್ಳುವೆ\nದಿಕ್ಕಿಲ್ಲದ ಪ್ರವಾಸಿಗೆ\nವಿಶ್ರಾಂತಿ ಸ್ಥಾನವೇ\nಅಡವಿಯಲ್ಲಿ ಮನೆಯೂ\nಮಾರ್ಗದೊಳ್ ಆಶ್ರಯ\nಕಡು ಬಿಸಿಲಿನಿಂದಲೂ\nಬೇಸರದಿಂದಲೂ.\n2. ಓ ಸುಂದರ ಆಶ್ರಯಾ!\nಓ ದಿವ್ಯ ಸ್ಥಾನವೇ!\nದೇವ ಪ್ರೀತಿ ನೀತಿಗಳ\nಬಿಟ್ಟೆಯ ಸ್ಥಾನವೇ!\nಯಾಕೋಬನ ಕನಸಿನೊಳ್\nನೋಡಿದ ಹಾಗೆಯೇ\nನನಗೆ ಕ್ರಿಸ್ತನ ಕ್ರೂಜೆ\nಸ್ವರ್ಗಕ್ಕೆ ಮಾರ್ಗವೇ.\nವಿವಿಧವಾದ ಸಂಗೀತಗಳು\n3. ಆ ಕ್ರೂಜೆ ಆಚೆ ಕಡೆ\nಹಾ ಎಂಥ ನೋಟವೇ!\nಪಾತಾಳದ ಕತ್ತಲೆಯ\nನಾನಲ್ಲಿ ನೋಡುವೆ !\nಆದಾಗ್ಯೂ ಕ್ರೂಜೆಯಲ್ಲಿಯೇ\nಆಶ್ರಯ ಸಿಕ್ಕಿತು\nಕ್ರೂಜಿಸಲ್ಪಟ್ಟ ಕರ್ತನಿಂ\nರಕ್ಷಣೆ ಆಯಿತು.\n4. ಆ ಯೇಸು ಕ್ರೂಜೆ ಮೇಲೆ\nಎಂಗಾಗಿ ಸ್ವಪ್ರಾಣ\nಕೊಟ್ಟ ಕಿಸ್ತನ ರೂಪವ\nಕಣ್ಣಾರೆ ಕಾಣುವೆ,\nನನ್ನ ಹೃದಯದಿಂದಲೇ\nಅರಿಕೆ ಮಾಡುವೆ\nಆತನ ಶ್ರೇಷ್ಠ ಪ್ರೀತಿಯೇ\nನನ್ನ ಅಯೋಗ್ಯತೆ.\n5. ಕ್ರೂಜಿಸಲ್ಪಟ್ಟ ಕ್ರಿಸ್ತಾ!\nನನ್ನಾಶ್ರಯ ನೀನು\nನಿನ್ನ ಕ್ರೂಜೆಯ ಮೂಲಕ\nಪಾಪಕ್ಕೆ ಸತ್ತೆನು\nಲೋಕದ ಸ್ತುತಿ ವ್ಯರ್ಥವೇ\nಚಿಂತೆಯು ಬೇಡವೇ\nನಿನ್ನ ಶಿಲುಬೆಯಲ್ಲಿಯೇ\nಹೆಚ್ಚಳ ಪಡುಮೆ\nವಿವಿಧವಾದ ಸಂಗೀತಗಳು" },
  321: { title: "ಕಿಸ್ತನ ಹಾಗೆ ಮತ್ತ್ಯಾರಿರ್ವರು ?", lyrics: "1. ಕಿಸ್ತನ ಹಾಗೆ ಮತ್ತ್ಯಾರಿರ್ವರು ?\nಯಾರಿಲ್ಲ ಯಾರಿಲ್ಲ\nಮತ್ತ್ಾರು ಸ್ವಸ್ಥತೆ ಕೊಡುವರು ?\nಯಾರಿಲ್ಲ ಯಾರಿಲ್ಲ\nಪಲ್ಲವಿ\nಕಷ್ಟ ್ಿದುಕೊಂಡ ಯೇಸು\nನಮ್ಮನ್ನೆಲ್ಲ ನಡಿಸುವವನು\nಆತನ ಹಾಗೆ ಮತ್ತಾರಿರ್ವರು ?\nಯಾರಿಲ್ಲ ಯಾರಿಲ್ಲ\n2. ಮತ್ತಾರು ಇಂತಹ ಶ್ರೇಷ್ಠ ಮಿತ್ರ ?\nಯಾರಿಲ್ಲ ಯಾರಿಲ್ಲ\nಆದಾಗ್ಯೂ ಇಂಥ ಸಾತ್ವಿಕ ಕರ್ತ\nಯಾರಿಲ್ಲ ಯಾರಿಲ್ಲ\n3. ಮತ್ತಯಾರು ಹಾಗೆ ರಕ್ಷಿಸುವರು ?\nಯಾರಿಲ್ಲ ಯಾರಿಲ್ಲ\nನಮ್ಮನ್ನು ಎಂದಿಗೂ ಕಾಯುವರು?\nಯಾರಿಲ್ಲ ಯಾರಿಲ್ಲ\n4. ಮತ್ತಾರು ಹಾಗೆ ಪ್ರೀತಿಸುವರು ?\nಯಾರಿಲ್ಲ ಯಾರಿಲ್ಲ\nಮತ್ತಾರು ಮೋಕ್ಷವ ಕೊಡುವರು ?\nಯಾರಿಲ್ಲ ಯಾರಿಲ್ಲ" },
  322: { title: "ಓ ಕರ್ತ ನನ್ನನ್ನು", lyrics: "1. ಓ ಕರ್ತ ನನ್ನನ್ನು\nಸಂಪೂರ್ಣ ಬಂಧಿಸು\nಖಡ್ಗವ ಬಿಡ ಪ್ರೇರಿಸು\nಉತ್ಸಾಹ ಪಡಿಸು\nಈ ಜೀವ ಕತ್ತಲೊಳ್\nಮುಳ್ಳುತ್ತಲಿದ್ದೇನೆ\nಕೈಚಾಚಿ ನನ್ನ ಅಪ್ಪಿಕೋ\nಚೈತನ್ಯ ಹೊಂದುಮೆ\n2. ಯೇಸೇ ಉದ್ಧಾರಕ\nನಾ ಬಡ ಪಾಪಿಯು\nಸಾಮರ್ಥ್ಯವೇನು ಇಲ್ಲದ\nಚಂಚಲ ಕ್ಸೆಸ್ತನು\nನಿಸ್ತುಲ್ಯ ಕ್ರಿಸ್ತನೇ\nನನ್ನನ್ನು ಜಯಿಸಿ\nಶರೀರ ಆತ್ಮ ಪ್ರಾಣವ\nಸ್ವಾಧೀನ ಮಾಡಿಕೊ.\n3. ನಾ ಬಲಹೀನನು\nಅಯೋಗ್ಯ ದಾಸನು\nಆರಂಭ ಪ್ರೀತಿ ಜಳವ\nಮತ್ತೊಮ್ಮೆ ಉರಿಸು\nಲೋಕವ ತ್ಯಜಿಸ\nನನ್ನಿಂದಲಾಗದು\nನಿನ್ನಾತ್ಮ ಶಕ್ತಿಯಿಂದಲೇ\nವಿಜಯ ಪಾಲಿಸು.\n4. ನನ್ನಿಚ್ಛೆ ಹೋಗಲಿ\nನಿನ್ ಚಿತ್ತ ಆಳಲಿ\nಪ್ರಪಂಚದ ವೈಯಾರವ\nನಾನೀಗ ಬಿಟ್ಟೆನು\nಗರ್ವಿಷ್ಯನಾಗದೆ\nಸರ್ವ ಪ್ರತಿಷ್ಠಿಸಿ\nನಿನ್ ತಿಎದೆದೆಗೊರಗಿ\nಉಜ್ಜೀವ ಹೊಂದಿದೆ." },
  323: { title: "ಯೇಸುವಿನ ಕುರಿಯು", lyrics: "1. ಯೇಸುವಿನ ಕುರಿಯು\nನಾನು ಚಿಂತೆಪಡೆನು,\nನಂಗೆ ನಿತ್ಯಕ್ಕೂ ಸಂತೋಷ\nಪ್ರೀತಿಯಿಂದ ಒಳ್ಳೇ ಪೋಷಣೆ\nಕೊಟ್ಟು ಕಾಯ್ವ ಯೇಸುವು\nನನ್ನ ನಾಮ ಬಲ್ಲನು.\n2. ಕೋಲು ಹಿಡಿದೆನ್ನನ್ನು\nಶಾಿಯಿಂದ ಕಾಯಲು\nಸುಖ ಕ್ಷೇಮದಲ್ಲಿದ್ದೇನೆ ;\nಒಳ್ಳೇ ಮೇವು ಮೆಲ್ಸುತ್ತೇನೆ ;\nದಾಹವಾಗ್ಗೆ ಕುರುಬ\nತೋರಿಸೋನು ಬುಗ್ಗೆಯ.\n3. ಸುಖಿಯಾದ ಕುರಿಗೆ\nಹೃತ್ಸಂತೋಷವಿರದೆ ?\nಈ ಸುಕಾಲದಂತ್ಯದಲ್ಲಿ\nಆತ ಸ್ವಂತ ಹೆಗಲಲ್ಲಿ\nಮನೆಗನ್ನನೊಯ್ಯಲು\nಸುಖಪೂರ್ತಿ ಅಹುದು." },
  324: { title: "ಯೇಸು ಪರಮ, ಕರ್ತ, ಪ್ರಿಯ ರಕ್ಷಕ,", lyrics: "1. ಯೇಸು ಪರಮ, ಕರ್ತ, ಪ್ರಿಯ ರಕ್ಷಕ,\nನಂಬಿದವನೆ ಭಕ್ತ ಭಾಗ್ಯ ಹೊಂದಿದ,\nನಿನ್ನ ಪ್ರೇಮದಲ್ಲಿ ಮುಣುಗಿ ನೋಡಲಿ ;\nಮೌನಗೊಳ್ಳುತಲಿ ಧನ್ಯನಾಗಲಿ.\nವಿವಿಧವಾದ ಸಂಗೀತಗಳು\nಪಲ್ಲವಿ\nಸ್ತೋತ್ರ, ಸ್ತೋತ್ರ, ಕರ್ತ, ಹಾಡುತಿರ್ನು\nನೀನು ಮಾತ್ರ ಯೋಗ್ಯ, ಸ್ತೋತ್ರ\nಹೊಂದಲ್ಲು\nಸ್ತೋತ್ರ, ಸ್ತೋತ್ರ ಕರ್ತ,\nಸ್ತುತಿಸುತಿರುವ್ನ\nನಾನು ನಿನ್ನ ಭಕ್ತ ; ಎಂಥ ಹರ್ಷವು!\n2. ಪಾಪ ಭಾರದಲ್ಲಿ ಹೃದಯ ಕುಗ್ಗಿಸಿ\nಶಾತಿ ಇಲ್ಲವಾಗಿ ಇದ್ದೆ ಭಯದಲಿ;\nಶಾಪ ನೀಗಿದಲ್ಲಿ ಕೋಪ ತಣಿಸಿದಿ ;\nಭೀತಿ ಈಗ ಎಲ್ಲಿ? ಧೈರ್ಯ ಪಡಿಸಿದಿ\n3. ನಿನ್ನ ಪಾದ ಸೇವೆ ನಿತ್ಯ ಮಾಡುವೆ;\nಬೇಡವೆನಗೆ ಬೇರೆ ; ತೃಪ್ತಿಯಾಗಿದೆ,\nಸ್ತೋತ್ರ ಯಜ್ಞತಂದು ಅರ್ಪಿಸಿರುವನು\nನಿನ್ನ ಘನವೇ ಒಂದು ಎನ್ನ ಗುರಿಯದು" },
  325: { title: "ನಿನ್ನ ಆಯುಸ್ವಲ್ಪವೇ ;", lyrics: "1. ನಿನ್ನ ಆಯುಸ್ವಲ್ಪವೇ ;\nಎಲೆಯು ಉದುರುವಂತೆಯೇ\nಸಿವುಡು ಕಟ್ಟುವಂತೆಯೇ ತೀರುತೆ,\nಮುಗಿವ ದಿನಗಳಿರುಹುದು,\nಮರಣ ಹಿಡಿದೆ ಹಿಡಿವುದು,\nನೀನು ಸಿದ್ಧನಾಗಿರು ಈಗಲೇ.\nಪಲ್ಲವಿ\nಈಗಲೇ, ಈಗಲೇ\nಯೇಸು ನಿನ್ನ ಕರೆವ ಸಮಯವೀಗಲೇ,\nಪಾಪದಲ್ಲೇ ಹೋದರೆ\nಕೃಪೆಯ ಬಾಗಿಲಡಚುತೆ ;\nಕೊನೆಗೆ ನಿನಗೆ ನರಕವೇ ನಾಶವೇ\nವಿವಿಧವಾದ ಸಂಗೀತಗಳು\n2. ಚೆಲುವ ಪುಷ್ಟ ಒಣಗುತೆ;\nಯೌವನದಂದ ಅಡಗುತೆ;\nನಿನಗೆ ಸಮಯ ಕೊಂಚವೇ ಇರುತ್ತದೆ\nಕರೆಯುತ್ತಾನೆ ದೇವರೇ ;\nಅಲೆಯ ಬೇಡ, ಪಾಪಿಯೇ ;\nದೈವಶಿಕ್ಷೆ ತಪ್ಪದೆ ಬರುತದೆ.\n3. ಸಮಯ ಹಾರಿ ಹೋಗುತೆ ;\nಮರಣ ತೀರ್ಪು ಬರುತದೆ ;\nಯೇಸು ಹಸ್ತಗಳಿಗೆ ಸೇರೀಗಲೇ.\nತಿಳಿದುಕೋ ವಿಶೇಷವೇ ;\nತ್ಯಜಿಸಿ ಬಿಡುವುದಾದರೆ\nನಿನ್ನ ಆತ್ಮ ಅಗ್ನಿಗೆ ನಿತ್ಯಕೆ.\n4. ಗಮನಿಸೀಗ, ಎಚ್ಚರ!\nನಂಬಿಕೊಳ್ಳು ಕ್ರಿಸ್ತನ ;\nಆಗ ಸ್ವರ್ಗದಲ್ಲಿಯ ಸಂತಸ\nಇರುಳಿನಿಂದ ಬೆಳಕಿಗೆ\nಸೆಳೆಯುವಾತ ಕ್ರಿಸ್ತನೇ,\nಬಳಿಗೆ ನೀನು, ಈಗಲೇ ಹೊರಟು ಬಾ.\nಕೊನೆಯ ಪಲ್ಲವಿ\nಹೊರಟು ಬಾ, ಹೂರಟು ಬಾ\nನಾಳೆ ಬೇಡ; ಇಂದೆ ನೀನು ಹೊರಟು ಬಾ ;\nಅಂತ್ಯಕಾಲ ಬರುವದು ;\nಮತ್ತು ಸಮಯ ದೊರಕದು ;\nನಿತ್ಯಗೋಳು ತೀರದು;\nಹೊರಟು ಬಾ." },
  326: { title: "ದಣಿದ ಭಕ್ತರಿಗೆ ಅಮೂಲ್ಯ", lyrics: "1. ದಣಿದ ಭಕ್ತರಿಗೆ ಅಮೂಲ್ಯ\nದೇವರ ವಾಗ್ದಾನವು\nಕೊಟ್ಟ ಲೋಕ ಯಾತ್ರೆಯಲ್ಲಿ:\n“ನಡಿಸುತ್ತೇನೆ ನಿನ್ನನ್ನು\"\nಪಲ್ಲವಿ\n“ನಡಿಸುತ್ತೇನೆ, ನಡಿಸುತ್ತೇನೆ\nನಡಿಸುತ್ತೇನೆ ಕಟಾಕ್ಷಿಸಿ’ ;\nಲೋಕದಿಂದ ದಿವಕೆ ಮಾರ್ಗ\n“ನಡಿಸುತ್ತೇನೆ ಕಟಾಕ್ಷಿಸಿ.”\n2. ಶೋಧನೇಲಿ ಸೋಲುವಲ್ಲಿ\nಮಿತ್ರರೆಲ್ಲ ತ್ಯಜಿಸಲು\nಮಾಡು ಈ ವಾಗ್ದಾನ ಜ್ಲಪ್ತಿ;\n“ನಡಿಸುತ್ತೇನೆ ನಿನ್ನ್ನು\"\n3. ನಿನ್ನ ಗೂಢ ಆಶೆ ನಷ್ಟ\nದಲಿ ಸಮಾಧಿಗಿಳಿಯಲು,\nಹಿಡುಕೊ ಈ ವಾಗ್ದಾನ ಭದ್ರ ;\n“ನಡಿಸುತ್ತೇನೆ ನಿನ್ನನ್ನು”\n4. ಜೀವಿತಕ್ಕೆ ಮೋಡ ಮುಚ್ಚಿ\nಮರಣ ವೇಳೆ ಬಂದರೂ\nನಂಬಿಗಸ್ತ, ಮಾತು ಕೊಟ್ಟ!\n“ನಡಿಸುತ್ತೇನೆ ನಿನ್ನನ್ನು’" },
  327: { title: "ಲೋಕದಿ ನೀನತಿ ಶ್ರೇಷ್ಠನು ;", lyrics: "1. ಲೋಕದಿ ನೀನತಿ ಶ್ರೇಷ್ಠನು ;\nನಿನ್ ಕನ್ಯೆಗೆಷ್ಟಮೂಲ್ಯನು ;\nಸಂಪೂರ್ಣ ನೀನೆ ಒಬ್ಬನು ;\nಅದ್ಭುತ ಶಿಲುಬೆ ಮನುಷ್ಯನು.\nಪಲ್ಲವಿ\nಆ ಶಿಲುಬೆ ಮನುಷ್ಯನು\nನಂಗಾಗಿ ಸತ್ತನು ;\nಎನ್ ಹೃದಯ ಗೆದ್ದನು ;\nಹಾ! ದಿವ್ಯ ಮನುಷ್ಯನು.\n2. ಪಾಪಿಗೆ ಜೀವವೂ ಶಾಂತಿಯೂ\nಪಾಪ ವಿಮುಕ್ತಿ ಕೊಟ್ಟನು ;\nಸ್ವರ್ತ ಚೆಲ್ಲಿ ಬಿಟ್ಟನು\nಕರುಣೆ ಶಿಲುಬೆ ಮನುಷ್ಯನು.\n3. ಸುವರಗಳನ್ನು ಇತ್ತನು\nಪರಮ ಪ್ರೀತಿ ಸುರಿದನು ;\nನಮ್ಮನ್ನು ಶುದ್ಧಿಗೈದನು ;\nದಯೆಯ ಶಿಲುಬೆ ಪುರುಷನು\n4. ನನಗೆ ನೀನಾದರಣೆಯು ;\nಕಾಣುವನೊಮ್ಮೆ ನಿನ್ನನ್ನು\nಅಲ್ಲಿಯೆ ಮಹಿಮೆ ಕೇಂದ್ರವು :\nಆಶ್ಚರ್ಯ ಶಿಲುಬೆ ವ್ಯಕ್ತಿಯು.\nವಿವಿಧವಾದ ಸಂಗೀತಗಳು" },
  328: { title: "ತನ್ ಪ್ರಿಯರನ್ನಾತನು ನಡಿಸೋನು", lyrics: "1. ತನ್ ಪ್ರಿಯರನ್ನಾತನು ನಡಿಸೋನು\nನಮ್ಮದ್ಭುತ ರಕ್ಷಕನು,\nಓ, ಎಲ್ಲಿಂಥ ಬೇರೊಬ್ಬ ಸ್ನೇಹಿತನು\nನೀ ಕಾರುಣ್ಯ ಸಾಗರನು.\nಪಲ್ಲವಿ\nಹಾ! ಅದ್ಭುತ ರಕ್ಷಕ!\nಹಾ! ಅದ್ಭುತ ರಕ್ಷಕ !\nಪ್ರೀತಿಯಿಂದೆಮ್ಮನು ಕಾಯ್ವನು\nಪ್ರಕಾಶವೆದುರು ಚೆಲ್ವನು\nಮಾನ ಪ್ರಭಾವ ನಿನ್\nಸ್ತೋತ್ರ ಮಾಡ್ವೆನು.\n2. ತನ್ ಪ್ರಿಯರನ್ನಾತನು ನಡಿಸೋನ್ು,\nನಾ ಮಾರ್ಗದಿ ದಣಿದಲ್ಲೂ\nಹಾ! ದಿವ್ಯಾಶೀರ್ವಾದವು ಸುರಿವದು\nಮುಂಜಾನೆಯ ಮಂಜಿನಂತೆ.\n3. ತನ್ ಪ್ರಿಯರನ್ನಾತನು ನಡಿಸೋನು\nಪ್ರಯಾಸ ಸಂಕಷ್ಟದಲ್ಲೂ\nತನ್ ಪ್ರೇಮದ ನೆರಳಲ್ಲಿರಿಸೋನು\nಅಲ್ಲೆಮಗೆ ವಿಶ್ರಾಂತಿಯು.\n4. ತನ್ ಪ್ರಿಯರನ್ನಾತನು ನಡಿಸೋನು\nಹಾ! ಪ್ರಯಾಣ ತೀರಿದಲ್ಲೂ\nಆ ಪಾದಕೆ ಬೀಳುವದಾನಂದವು\nಕೊಂಡಾಡುತ್ತ ಇರುವೆವು.\nವಿವಿಧವಾದ ಸಂಗೀತಗಳು" },
  329: { title: "ಸಂಪೂರ್ಣ ಸಮಾಧಾನವನ್ನು", lyrics: "1. ಸಂಪೂರ್ಣ ಸಮಾಧಾನವನ್ನು\nಕ್ಿಸ್ೈಸು ನಂಗೆ ಕೊಟ್ಟನು ;\nಆ ಉಗ್ರ ದೈವಕೋಪದಿಂದ\nನನ್ನನ್ನು ತಪ್ಪಿಸಿದನು.\nಪಲ್ಲವಿ\nಕ್ರಸತ್ರಸು ರ್ಿಸಿದನು,\nಪಾಪಾತ್ಮನಾದ ನನ್ನನ್ನು ;\nಎನ್ ಪಾಪವೆಲ್ಲ ನೀಗಿತು ;\nನಿನಗೆ ಸ್ತೋತ್ರ ಮಾಡ್ವೆನು.\n2. ಎಲ್ಲಿನ್ನು ನಂಗೆ ಸಮಾಧಾನ ?\nಈ ಲೋಕವೆಂದು ಕೊಡದು\nಹಿಂಸೆ ಇಕ್ಕಟ್ಟು ನಿಂದೆ ಕೂಡ\nಬಂದರೂ ಭಯಪಡೆನು.\n3. “ನನ್ನಲ್ಲಿರುವ ಶಾಂತಿಯನ್ನು\nನಿಮಗೆ ನಾನು ಕೊಡ್ವೆನು ;\nಲೋಕವು ಕೊಡೋ ರೀತಿಯಲ್ಸ\"\nಎಂದೇಳಿ ಧೈರ್ಯ ಕೊಟ್ಟನು.\n4. “ನನ್ನನ್ನು ನಂಬುವಾತನಿಗೆ\nಕೊಡುವೆ ನಿತ್ಯಜೀವವ\nಅವರು ನಾಶವಾಗೋದಿಲ್ಲ\"\nಹೀಗೆಂದು ಕೊಟ್ಟ ಧೈರ್ಯವ.\n5. ನಾನೀಗ ದೇವ ಮಗುವಾಗಿ\nಈ ಲೋಕದಲ್ಲಿ ಇರ್ವೆನು ;\nಕ್ರಿ್ತನ ಪ್ರತ್ಯಕ್ಷತೆಯಲ್ಲಿ\nಆತನ ಮುಖವ ನೋಡ್ವೆನು.\n6. ಅಲ್ಲೆಂದೂ ನಂಗೆ ಕಣ್ಣೀರಿಲ್ಲ;\nಲೋಕದ ಕಷ್ಟ ನೋಡೆನು,\nಕರ್ತನ ಮುಖವ ನೋಡುತ್ತಾ,\n“ಸ್ತೋತ್ರ” ! ಎಂತಂದು ಹಾಡ್ವೆನು.\n7. ಕ್ರಿಸ್ತನ ಹೆಜ್ಜೆ ಜಾಡಿನಲ್ಲಿ\nಮುಂದಕ್ಕೆ ಸಾಗುತಿರ್ವೆನು;\nಆತನನ್ನು ವಿಶ್ವಾಸದಿಂದ\nನಿರೀಕ್ಷಿಸುತ್ತಲಿರ್ವೆನು.\nಕೊನೆಯ ಪಲ್ಲವಿ\nಕ್ರಿಸ್ತೇಸು ಬೇಗ ಬರ್ವನು ;\nಸ್ವರ್ಗಕ್ಕೆನ್ನನ್ನು ಒಯ್ವನು ;\nಎಂಥ ಸೌಭಾಗ್ಯವಿರ್ವದು\nಸಂತೋಷವೆಂದೂ ತೀರದು." },
  330: { title: "ಕುರುಬನೊಂದು ಹಟ್ಟಿಯಲ್ಲಿ", lyrics: "1. ಕುರುಬನೊಂದು ಹಟ್ಟಿಯಲ್ಲಿ\nನೂರು ಕುರಿಗಳಿದ್ದವು ;\nಪ್ರೀತಿಯಿಂದ ಅವುಗಳನ್ನು\nಸಾಕಿ ಸಲಹುತ್ತಿದ್ದನು.\nಪಲ್ಲವಿ\nಕುರುಬ ನನ್ನ ಪ್ರಿಯ ಯೇಸು ;\nಕೊರತೆ ಎಂದೂ ಕಾಣೆನು ;\nಸ್ವರವ ಕೇಳಿ, ಹಿಂದೆ ಹೋಗಿ ;\nಒರತೆ ಕಂಡುಕೊಂಡೆನು.\n2. ಕಾಡಿನಲ್ಲಿ ಮೇಯಲೊಂದು\nಓಡಿ ತಪ್ಪಿ ಹೋಯಿತು ;\nಪಡುತ ಚಿಂತೆ ಕುರುಬನೊಡನೆ\nಹುಡುಕಲೆದ್ದು ಹೊರಟನು.\n3. ಎಷ್ಟು ತಗ್ಗು ದಿಣ್ಣೆ ಮುಳ್ಳು\nಕಷ್ಟಪಟ್ಟು ನೊಂದನು ;\nಸಿಕ್ಕಿತಾಗ ; ಹೆಗಲ ಮೇಲೆ\nಹಾಕಿ ಮನೆಗೆ ತಂದನು.\n4. “ಬನ್ನಿ ನನಗೆ ಹರ್ಷ ; ಕಳೆದು\nಹೋದ ಕುರಿಯು ಸಿಕ್ಕಿತು.”\nಇನ್ನಿತರರನಿಂತು ಕರೆದು.\nಎಲ್ಲ ಹರುಷಗೊಂಡರು.\n5. ಕುರುಬ ಯೇಸು ಪಾಪಿಗಳನ್ನು\nಹುಡುಕಲಿಕ್ಕೆ ಬಂದನು ;\nಕಂಡುಕೊಂಡ ಹಲವರನ್ನು\nನಂಬಿದವರೆ ಕುರಿಗಳು." },
  331: { title: "ಘನಮಾನ ಯೇಸುವಿಗೆ,", lyrics: "1. ಘನಮಾನ ಯೇಸುವಿಗೆ,\nಸ್ತುತಿ ನಮ್ಮ ಕರ್ತಗೆ,\nಪೂರ್ಣ ಮನದಿಂದ ಹಾಡ,\nಕೂಡಿ, ಬನ್ನಿ ಕ್ರೆಸ್ತರೇ,\nಪಲ್ಲವಿ\nಜಗದ್ರಕ್ಷಕನು ಈ ಹೊತ್ತು\nಕರೆಯುತ್ತಾನೆ ನಮ್ಮನ್ನು\nಶಿಶುಭಾವದಿಂದ ಬಂದು\nಆಶೀರ್ವಾದ ಹೊಂದಿರಿ.\n2. ಬಾಲ್ಯದಲ್ಲಿಯೇ ಸ್ಮರಿಸು\nನಿನ್ನ ಸೃಷ್ಟಿ ಕರ್ತನ\nಅತ್ಮದ ಉದ್ಧಾರಕ್ಕಾಗಿ\nನಂಬು ರಕ್ಷಾ ಕರ್ತನ.\nವಿವಿಧವಾದ ಸಂಗೀತಗಳು\n3. ಸ್ವಾಮಿ ಪ್ರೀತಿಗಂತ್ಯವಿಲ್ಲ.\nಯಾಕೆ ನಿಂಗೆ ಭಯವು ?\nತಾಯಿ ಪ್ರೀತಿಗಿಂತ ಮೂಲ್ಯ\nನಿನ್ನ ಪ್ರೀತಿ ಮಾಡ್ವನು.\n4. ತನ್ನ ಮಕ್ಕಳನ್ನು ಆತ,\nಎಂದು ಮರೆಯಲಾರನು.\nಭದ್ರವಾಗಿ ಕಾಯ್ವ ಭಾರ.\nನನ್ನ ಪ್ರಿಯ ಸ್ವಾಮಿದು." },
  332: { title: "ನಿಂಗಾಗಿ ಕೊಟ್ಟೆನು", lyrics: "1. ನಿಂಗಾಗಿ ಕೊಟ್ಟೆನು\nಎನ್ ಜೀವ ಮಗನೇ\nನಿನ್ ಪಾಪಕ್ಕಾಗಿಯೇ\nರಕ್ತವ ಸುರಿದೆ\nಎನ್ ಪ್ರಾಣವನ್ನೆ ಕೊಟ್ಟೆನು ;\nನೀನೇನು ಕೊಡುತ್ತೀ ?\n2. ನಿಂಗಾಗಿ ಬಿಟ್ಟೆನು\nಉನ್ನತ ಲೋಕವ\nನಿಂಗಾಗಿ ಬಂದೆನು\nಕನಿಷ್ಠ ಲೋಕಕ್ಕೆ\nನಾ ಸ್ವರ್ಗವನ್ನೇ ಬಿಟ್ಟೆನು ;\nನೀನೇನು ಬಿಡುತ್ತೀ ?\n3. ನಿಂಗಾಗಿ ಪಟ್ಟೆನು\nಆ ಘೋರ ತಾಪವ\nನಿಂಗಾಗಿ ಹೊಂದಿದೆ\nಅಪಾರ ಹಿಂಸೆಯ\nನಿಂಗಾಗಿ ಕಷ್ಟ ಪಟ್ಟೆನು ;\nನೀನೇನು ಪಡುತ್ತೀ ?\nವಿವಿಧವಾದ ಸಂಗೀತಗಳು\n4. ನಿಂಗಾಗಿ ತಂದೆನು\nರಕ್ಷಣಾ ಪಾತ್ರೆಯ\nನಿಂಗಾಗಿ ತಂದೆನು\nತಂದೆಯ ಕ್ಷಮೆಯ\nನಿಂಗಾಗಿ ಜೀವ ತಂದೆನು ;\nನೀನೇನು ತರುತ್ತೀ ?" },
  333: { title: "ನಿತ್ಯಜೀವ ಜೀವ ಕ್ರಿಸ್ತನಲ್ಲಿಯೇ", lyrics: "1. ನಿತ್ಯಜೀವ ಜೀವ ಕ್ರಿಸ್ತನಲ್ಲಿಯೇ\nನಂಬಿದಾಗ ಹೊಂದಿದೆ.\nದಿವ್ಯ ರಕ್ತ ಚೆಲ್ಲಿ ಕ್ರೂಜೆ ಮೇಲೆಯೇ\nನನ್ನ ಶಾಪ ತೀರಿದೆ.\nಅಪಾರವಾದ ಕೃಪೆಯ,\nನಾನು ಹಾಡಿ ಪಾಡುವೆ.\nನಿತ್ಯಜೀವ ಜೀವ ಕ್ರಿಸ್ತನಲ್ಲಿಯೇ\nನಂಬಿದಾಗ ಹೊಂದಿದೆ.\n2. ನಿತ್ಯಜೀವ ಜೀವ ಉಂಟು ನನಗೆ\nಕ್ರಸ್ಯೆಸುವಿನಲ್ಲಿಯೇ\nನಂಬು ಹೊಂದು ನೀನು, ತಡಮಾಡದೆ,\nನ್ಯಾಯತೀರ್ಪು, ತಪ್ಪುತೆ,\nಅಪಾರ ಈ ದೇವ ಕೃಪೆಯು\nಉಚಿತಾರ್ಥ ಸಿಕ್ಕಿದೆ\nನಿತ್ಯ ದೇವ ತಾನೆ ನಮ್ಮ ತಂದೆಯು\nಸ್ತುತಿ ಸ್ತೋತ್ರ ಆತಂಗೆ.\n3. ಅವಿಶ್ವಾಸ ಇನ್ನು ನಿಂಗೆ ಬೇಡವು\nಮೋಸ ಹೋಗುವಿ ನಿಶ್ಚಯ\nದೇವ ತಾನೆ ಗೈದ ದಿವ್ಯ ಕಾರ್ಯವು\nಸಿದ್ಧವಾಗಿದೆ ನಿಶ್ಚಯ.\nಓ ನಂಬು ಈ ದೊಡ್ಡ ರಕ್ಷಣೆ\nಇಂದೇ ಒಳ್ಳೇ ಸಮಯ.\nಪಾಪ ಶಾಪಕ್ಕೆಲ್ಲಾ ಅಂದೇ ನಾಶಣೆ\nಹೊಂದು ದೇವ ಆಶ್ರಯ.\n4. ಕ್ರೈಸ್ತ ಮಾರ್ಗ ಎಷ್ಟೋ ಬಿಕ್ಕಟ್ಟಾದರೂ\nಮುಂದೆ ಸಾಗುವ ಧೈರ್ಯದಿಂ\nಕ್ರಿಸ್ತನರ್ವ ಎಂಥಾ ಭಯವಿದ್ದರೂ\nಜೀವದಂತ್ಯಕ್ಕೂ ಸ್ಥೈರ್ಯದಿಂ.\nಕಿರೀಟ ಕೊಡ್ವನಲ್ಲಿಯೇ\nನಂಬಿಗಸ್ತ ಮಕ್ಕಳಿಗೆ\nಹಲ್ಲೆಲೂಯ ನನ್ನ ಯೇಸು ಕರ್ತಗೆ\nನಿತ್ಯ ಸ್ತೋತ್ರ ಹಾಡುವೆ." },
  334: { title: "ಕ್ರಿಸ್ತನಲ್ಲಿ ನ್ಯಾಯ ಪ್ರಮಾಣ", lyrics: "1. ಕ್ರಿಸ್ತನಲ್ಲಿ ನ್ಯಾಯ ಪ್ರಮಾಣ\nಅದಕ್ಕೆ ಬಂತು ಅವಸಾನ\nಯೇಸು ಬಂದಾಗ ವಿಶೇಷ ವಾರ್ತೆ\nಈ ಶುಭವಾರ್ತೆ ರಕ್ಷಣೆಯೇ.\nಪಲ್ಲವಿ\nಓ ಯೇಸು ನೀ ಮಾತ್ರ ಉದ್ದಾರಕ,\nನಿನ್ ಹೊರ್ತು ಬೇರೆ ಮಾರ್ಗವಿಲ್ಲ\nಕ್ರೂಜೆಯ ಮೇಲೆ, ನೀ ಬಲಿಯಾದಿ,\nಸ್ತೋತ್ರಕ್ಕೆ ನೀ ಯೋಗ್ಯ ಕ್ರಿಸ್ತ್ಯೇಸುವೆ.\n2. ಹೃದಯ ಶಾಂತಿ, ಕ್ರಿಸ್ತ್ಯೆಸು ಕೊಟ್ಟ\nನಂಬಿದೆ ನಾನು, ಕೃಪೆಯಿಂದ,\nಕ್ರಿಸ್ತನ ನೀತಿ, ನನ್ನಾತ್ಮ ಮುಟ್ಟ\nನಾ ದೇವ ಮಗು ಕ್ರಿಸ್ತನಿಂದ." },
  335: { title: "ಈ ಲೋಕ ಸಾಗ್ರದಲ್ಲಿಯೇ", lyrics: "1. ಈ ಲೋಕ ಸಾಗ್ರದಲ್ಲಿಯೇ\nಎನ್ ಪ್ರಿಯ ಕರ್ತನೇ\nಹೃದಯದ ಎನ್ ನಾವೆಯೇ\nನಿನ್ ರಕ್ತ ಲಂಗರೇ.\n2. ಸರ್ವಸ್ವ ನಿಂಗೆ ಇದ್ದರೂ\nಸಿಕ್ಕದಾ ತೃಪ್ತಿಯು\nಕ್ರಿ್ತನಲ್ಲಿ ನೀ ಇದ್ದರೆ\nಸಂತೃಪ್ತಿ ಇರ್ವದು.\n3. ಸಂಪತ್ತು ರೂಪ ಯೌವ್ವನ\nಅತ್ಯಲ್ಪ ಕಾಲಕ್ಕೆ\nಅಳಿಯದಂಥ ಭವನ\nನಿಂಗೀಯ್ವ ನಿತ್ಯಕ್ಕ\n4. ತಾಯ್ ತಂದೆ ಬಂಧು ಮಿತ್ರರು\nಕೈ ಬಿಟ್ಟು ಹೋದರೂ\nಎಂದೆಂದೂ ನಿನ್ನ ಬಿಡನು\nಸ್ವರ್ಗೀಯ ತಂದೆಯು." },
  336: { title: "ದೇವರಿಗೂ ನರರಿಗೂ", lyrics: "1. ದೇವರಿಗೂ ನರರಿಗೂ\nಏಕ ಮಧ್ಯವರ್ತಿಯು\nಭೂಮಿಯೊಳ್ ಪ್ರತ್ಯಕ್ಷನಾದ,\nಶಾಸ್ತ್ವ ಪೂರೈಸಿದ\nಪಲ್ಲವಿ\nಕೃಪೆಯಿಂದಲೇ ರಕ್ಷಣೆ\nನಂಬುವವರೆಲ್ಲ್ಗೆ\nಕ್ಿ್ತನಲ್ಲಿಯೇ ಈ ಮಾರ್ಗ\nಇದೇ ದೇವ ನಿರ್ಣಯ.\nವಿವಿಧವಾದ ಸಂಗೀತಗಳು\n2. ಪಾಪ ಭಾರದಿಂದ ನೊಂದು\nಯಾಕೆ ಚಿಂತೆ ನಿನಗೆ ?\nಆತ ದೀರ್ಘ ಶಾಂತನೆಂದೂ\nಕರೆಯುತ್ತಾನ ನಿನ್ನನ್ನೇ.\n3. ಆಕ್ಮ ಶಾಂತಿ ಸಮಾಧಾನ\nಸರ್ವ ಕ್ರಿಸ್ತನಲ್ಲಿಯೇ\nಉಚಿತಾರ್ಥ ದೇವದಾನ\nನಂಬಿ ಹೊಂದು ಈಗಲೇ." },
  337: { title: "ಶಾಸ್ತ್ರವ ಓದುತ್ತಿರು!", lyrics: "1. ಶಾಸ್ತ್ರವ ಓದುತ್ತಿರು!\nಈ ದಿವ್ಯ ಪುಸ್ತಕ\nಗಮನವಿಟ್ಟು ಓದು\nದೇವ ವಾಕ್ಯವ\nದೇವರು ಪ್ರೀತಿಯಿಂದ\nನಮಗೆ ನೀಡಿದ\nಪಾವನ ಗ್ರಂಥದಿಂದ\nಜ್ಞಾನ ಹೊಂದುವಾ.\n2. ದೇವರ ಚಿತ್ತವೇನು ?\nಎಂದು ಗ್ರಹಿಸಲು\nದೇವರ ವಾಕ್ಯವನ್ನು\nಓದುತ್ತಾ ಇರು !\nದೇವರ ವಾಕ್ಯ ಓದು\nಮುಂಜಾನೆಯಲ್ಲಿಯೂ\nಸಂಜೆ, ಮಧ್ಯಾಹ್ನದಲ್ಲೂ\nಧ್ಯಾನ ಮಾಡಿರು.\nವಿವಿಧವಾದ ಸಂಗೀತಗಳು\nದೇವ ಪ್ರಕಾಶದಲ್ಲೇ\nನಡೆದು ಹೋಗಲು\nಆತನ ವಾಕ್ಯವನ್ನೇ\nಓದುತ್ತಾ ಇರು\nಪಾಪವ ಜಯಿಸಲು\nದೇವರ ವಾಕ್ಯವ\nಹೃದಯದಲ್ಲಿ ಇಟ್ಟು\nಧ್ಯಾನ ಮಾಡುವಾ." },
  338: { title: "ನಿನ್ನಾಜ್ಞೆ ಅನುಸರಿಸಿ", lyrics: "1. ನಿನ್ನಾಜ್ಞೆ ಅನುಸರಿಸಿ\nಓ ಯೇಸು ಕರ್ತನೇ\nನಾ ನಮ್ರವುಳ್ಳ ಮನದಿ\nನಿನ್ನ ನನಸುವೆ.\n2. ನೀ ಕೊಟ್ಟ ನಿನ್ನ ದೇಹವು\nನನ್ನಾತ್ಮಾ ಹಾರವು\nನೀ ಸುರಿಸಿದ ರಕ್ತವು\nನನ್ನಾತ್ಮ ಪಾನವು.\n3. ಗೆತ್ಸೆಮನೆಯ ತೋಟದಿ\nನೀ ಪಟ್ಟ ಶ್ರಮವ\nಮರೆಯಲಾರದೆ ನಿನ್ನೀ\nದುಳು ನೆನಸುವಾ.\n4. ನಿನ್ನ ಶಿಲುಬೆ ಕಡೆಗೆ\nನಾ ದೃಷ್ಟಿ ಹಾಕುವೆ\nಯಜ್ಞದ ಕುರಿಯಾತನೇ,\nನಿನ್ನ ನೆನಸುವೆ.\n5. ನಿನ್ನ ಪ್ರೀತಿ ದುಚಖುಗಳ\nನೆನಪು ಮಾಡುವೆ\nಎನ್ ಜೀವಮಾನವೆಲ್ಲವು\nನಿನ್ನ ಸ್ಮರಿಸುವೆ.\n6. ಪುನಃ ನೀನು ಬರುವಿ!\nಆವಾಗ, ಕರ್ತನೇ,\nನಿನ್ನ ದಿವ್ಯ ಮಹಿಮದಿ\nನಿನ್ನನ್ನು ನೋಡುವೆ." },
  339: { title: "ಸ್ವರ್ಗಲೋಕದಿಂದ ಎಂದೂ", lyrics: "1. ಸ್ವರ್ಗಲೋಕದಿಂದ ಎಂದೂ\nಸುಪ್ರಕಾಶ ಕಾಣುತ್ತೆ\nಆದರೂ ಭೂಲೋಕಕ್ಕಿಂದೂ\nಕ್ಸೆಸ್ತೇ ದೀಪಗಳೇ.\nಪಲ್ಲವಿ\nಸುಪ್ರಕಾಶವ ಕೊಡೋಣ!\nಕ್ರಿಸತನ ಸುವಾರ್ತೆಯ\nಸಂದೇಶವ ತಿಳಿಸೋಣ,\nರಕ್ಷಣೆಯ ವಾಕ್ಯವ.\n2. ಪಾಪದ ಸಮುದ್ರದೊಳು\nಜನ ಮುಣುಗುವರು.\nಸುವಾರ್ತಾ ಕಿರಣಗಳು\nಅವರ ಮುಟ್ಟುವವು.\n3. ಪಾಪದ ಸಮುದ್ರದಿಂದ\nಜನಕ್ಕೆ ಅಪಾಯವು.\nಸುವಾರ್ತಾ ಪ್ರಕಾಶದಿಂದ\nಜನಕ್ಕೆ ಸಹಾಯವು." },
  340: { title: "ದೇವರಿಂದ ರಕ್ಷಣೆ", lyrics: "1. ದೇವರಿಂದ ರಕ್ಷಣೆ\nನಮಗೆ ಬರುತ್ತದೆ ;\nರಕ್ಷಣೆಯ ಮೂಲವು\nಜೀವವುಳ್ಳ ದೇವರು.\n2. ಕ್ರಿಸ್ತನಲ್ಲಿ ರಕ್ಷಣೆ\nನಮಗೆ ಸಿಕ್ಕುತ್ತದೆ ;\nಯೇಸು ಕ್ರಿಸ್ತನೊಬ್ಬನು\nರಕ್ಷಣೆಯ ಮಾರ್ಗವು.\n3. ಕೃಪೆಯಿಂದ ರಕ್ಷಣೆ\nನಮ್ಮ ಪಾಲು ಆಗುತ್ತೆ ;\nಸತ್ಕ್ರಿಯೆಗಳಿಂದಲೇ\nಹೊಂದಲು ಅಸಾಧ್ಯವೇ.\n4. ನಾವು ಕ್ರಿಸ್ತನಲ್ಲಿಯೇ\nನಂಬಿಕೊಳ್ಳುವಾಗಲೇ ;\nರಕ್ಷಣಾನುಭವವೇ\nನಮಗೆ ಆಗುತ್ತದೆ.\n5. ದಿವ್ಯವಾದ ರಕ್ಷಣೆ\nದೇವ ಕೃಪಾದಾನವೇ ;\nಈ ವಿಶೇಷ ದಾನಕ್ಕೆ\nಲಕ್ಷ್ಯಕೊಡಿರೆಲ್ಲರೇ.\n6. ನಿತ್ಯವಾದ ರಕ್ಷಣೆ\nಸರ್ವಕಾಲ ತಾಳುತ್ತೆ ;\nನಿತ್ಯಜೀವ ಎಂದಿಗೂ\nತಪ್ಪಿ ಹೋಗಲಾರದು.\n7. ರಕ್ಷಣೆಯ ಹೊಂದಿದ\nಯಾವನೊಬ್ಬ ಮಾನವ ;\nವಿವಿಧವಾದ ಸಂಗೀತಗಳು\nಒಳ್ಳೇ ಕಾರ್ಯಗಳಿಂದ\nದೇವರನ್ನು ಮೆಚ್ಚುವ.\n8. ವರ್ತಮಾನ, ಭವಿಷ್ಯ\nಭೂತ ಕಾಲದೊಳ್ ಸಹ ;\nದಿವ್ಯವಾದ ರಕ್ಷಣೆ\nಕಾರ್ಯ ಸಾಧಿಸುತ್ತದೆ.\n9. ರಕ್ಷಣೆಯ ಹೊಂದುವ\nಯೋಗ್ಯವಾದ ಸಮಯ ;\nನಾಳೆ ಅಲ್ಲ; ಈಗಲೇ\nಎಂದು ವೇದ ಹೇಳುತ್ತೆ.\n10. ರಕ್ಷಣೆಯ ಹೊಂದದ\nಮಾನವನ ಅಂತ್ಯದ\nಸ್ಥಿತಿ ಭಯಂಕರವೇ !\nಲಕ್ಷ್ಯ ಕೊಡಿರೀಗಲೇ !" },
  341: { title: "ಭೂತಕಾಲ", lyrics: "1. ಭೂತಕಾಲ" },
  342: { title: "ಕ್ರಿಸ್ತ್ಯೇಸು ನನ್ನ ರಕ್ಷಿಸಿದನು,", lyrics: "1. ಕ್ರಿಸ್ತ್ಯೇಸು ನನ್ನ ರಕ್ಷಿಸಿದನು,\nನನ್ನನ್ನು ರಕ್ಷಿಸಲು ಸತ್ತನು\nತನ್ನ ರಕ್ತದಿಂದಲೇ\nಪಾಪ ಶಿಕ್ಷೆಯಿಂದಲೇ\nಕ್ರಿಸ್ಯೇಸು ನನ್ನ ರಕ್ಷಿಸಿದನು.\n2. ಕ್ರಿಸ್ತ್ಯೇಸು ನನ್ನ ರಕ್ಷಿಸಿದನು\nನನ್ನನ್ನು ರಕ್ಷಿಸಲು ಸತ್ತನು\nತನ್ನ ಸಾವಿನಿಂದಲೇ\nಆತ್ಮ ರಕ್ಷಣೆಯನ್ನೇ\nನಂಗಾಗಿ ಯೇಸು ಸಾಧಿಸಿದನು\nವಿವಿಧವಾದ ಸಂಗೀತಗಳು\n3. ಕ್ರಿಸ್ತ್ರಸು ನನ್ನ ರಕ್ಷಿಸಿದನು,\nನನ್ನನ್ನು ರಕ್ಷಿಸಲು ಸತ್ತನು\nನಾನು ನಂಬಿದಾಗಲೇ\nನಾನು ನೀತಿವಂತನೇ\nಎಂಬ ನಿರ್ಣಯ ನನಗಾಗಿತ್ತು.\n2. ವರ್ತಮಾನ ಕಾಲ\n4. ಕ್ರಿಸ್ತ್ಯೈಸು ನನ್ನ ರಕ್ಷಿಸುತ್ತಾನೆ ;\nನನ್ನನ್ನು ರಕ್ಷಿಸುತ್ತಾ ಇದ್ದಾನೆ,\nನನ್ನನ್ನು ಜೀವದಿಂದಲೇ\nಪಾಪ ಶಕ್ತಿಯಿಂದಲೇ\nಕರಿಸ್ರೇಸು ನನ್ನ ರಕ್ಷಿಸುತ್ತಾನ.\n5. ಕ್ರಿಸ್ಯಸು ನನ್ನ ರಕ್ಷಿಸುತ್ತಾನೆ\nನನ್ನನ್ನು ರಕ್ಷಿಸಲು ಎದ್ದನು,\nಎದ್ದು ಬಂದ ಕರ್ತನು\nಪ್ರಾಣ ರಕ್ಷಣೆಯನ್ನು\nನನಗೆ ದಯಪಾಲಿಸುತ್ತಾನೆ.\n6. ಕ್ರಿಸ್ತ್ಯೇಸು ನನ್ನ ರಕ್ಷಿಸುತ್ತಾನೆ\nನನ್ನನ್ನು ರಕ್ಷಿಸುತ್ತಾ ಇದ್ದಾನೆ,\nನಾನು ನಂಬುವಾಗಲು\nಶುದ್ಧನಾಗಿ ಬಾಳಲು\nಕ್ರಿ್ರಸು ನನ್ನ ಸಾಗಿಸುತ್ತಾನೆ.\n3. ಭವಿಷ್ಯಕಾಲ\n7. ಕ್ರಿಸ್ತ್ಯೈಸು ನನ್ನ ರಕ್ಷಿಸುವನು,\nನನ್ನನ್ನು ರಕ್ಷಿಸಲು ಬರ್ವನು,\nತನ್ನ ಸಾಮರ್ಥ್ಯದಿಂದ\nಪಾಪ ಸಾನ್ನಿಧ್ಯದಿಂದ\nಕ್ರಿ್ತರಯಸು ನನ್ನ ರಕ್ಷಿಸುವನು.\n8. ಕ್ರಿಸ್ತ್ಯೇಸು ನನ್ನ ರಕ್ಷಿಸುವನು\nನನ್ನನ್ನು ರಕ್ಷಿಸಲು ಬರ್ವನು\nಮುಖಾ ಮುಖಿಯಾಗಿ ಆ\nದಿವ್ಯ ರೂಪ ನೋಡುವ\nನನಗೆ ದೇಹ ರಕ್ಷಣಾಗ್ವದು.\n9. ಕ್ರಿಸ್ತ್ಯೇಸು ನನ್ನ ರಕ್ಷಿಸುವನು,\nನನ್ನನ್ನು ರಕ್ಷಿಸಲು ಬರ್ವನು\nಯೇಸು ಮಹಿಮೆಯಿಂದಲೇ\nಪ್ರತ್ಯಕ್ಷನಾಗುವಾಗಲೇ\nನನ್ನನ್ನು ತನ್ನ ಹಾಗೆ ಮಾಡ್ವನು." },
  343: { title: "ಇದು ಸ್ಪಷ್ಟವಾದ ಮಾತು", lyrics: "1. ಇದು ಸ್ಪಷ್ಟವಾದ ಮಾತು\nನಾನು ಭ್ರಷ್ಟನಾದೆನು\nಬಹು ಕಷ್ಟದಲ್ಲಿ ಸಿಕ್ಕಿಕೊಂಡೆನು\nಸರ್ವೋತೃಷ್ಟ ಮಾರ್ಗ ಬಿಟ್ಟು\nನಾ ದುಷ್ಟನಾಗಿಯೇ\nಸ್ವಂತ ಇಷ್ಟದಂತೆ ಬಾಳುತ್ತಿದ್ದೆನು,\nಆಗ ಜೇಷ್ಠ ಪುತ್ರನಾದ\nನಮ್ಮ ಶ್ರೇಷ್ಠ ಗುರುವು\nತನ್ನ ಇಷ್ಟದಂತೆ ಪ್ರಾಣಕೊಟ್ಟನು\nನನ್ನ ಕಷ್ಟವೆಲ್ಲ ಬಿಡಿಸಿ ದುಷ್ಕರ್ಮ ತೆಗೆದು\nನೀನು ಶಿಷ್ಯನಾಗಿ ಬಾಳು ಅಂದನು.\n2. ನಾನು ಭಕ್ತಿಹೀನನಾಗಿ ಅಶಕ್ತನಾಗಿದ್ದೆ.\nದುಷ್ಟ ವ್ಯಕ್ತಿಯಾಗಿ ಬಾಳುತ್ತಿದ್ದೆನು\nಬಹು ಯುಕ್ತಿಯುಳ್ಳ ವೈರಿಗೆ\nಸಿಕಿಕೊಂಡೆನು.\nದೈವೋಕ್ತಿಯನ್ನು ನಿಂದಿಸಿದೆನು,\nಆಗ ಶಕ್ತಿಯುಳ್ಳ ಸ್ವಾಮಿ\nಸದ್ಯಕ್ಕಿ ಎಂಥಾದ್ದು\nಬಹು ವ್ಯಕ್ತವಾಗಿ ತೋರಿಸಿದನು\nತನ್ನ ರಕ್ತದಿಂದ ನನ್ನ ದುರ್ನೀತಿ ತೊಳೆದು\nನಿಜ ಮುಕ್ತಿಯಲ್ಲಿ ಸೇರಿಸಿದನು." },
  344: { title: "ಎನ್ನ ತಳ್ಳಬೇಡ ಕ್ರಿಸ್ತಾ!", lyrics: "1. ಎನ್ನ ತಳ್ಳಬೇಡ ಕ್ರಿಸ್ತಾ!\nಮೊರೆಯಾಲಿಸು ;\nಪರರನ್ನು ಕರೆದಾಗ\nಕರೆ ನನ್ನನ್ನೂ\nಪಲ್ಲವಿ\nಕರ್ತಾ! ಕರ್ತಾ!\nಮೊರೆಯಾಲಿಸು;\nಪರರನ್ನು ಕರೆದಾಗ\nಕರ ನನ್ನ್ನೂ\n2. ನಿನ್ನ ಕೃಪಾಸನವನ್ನು\nಸೇರಿ ಕ್ಲೇಶಕ್ಕೆ\nಒಳಗಾಗಿ ಅಡ್ಡಬಿದ್ದು\nಕೃಪೆ ಬೇಡುವೆ.\n3. ನಿನ್ನ ಪ್ರೀತಿಯೊಂದರಲ್ಲಿ\nಇಟ್ಟಿ ನಂಬಿಕೆ ;\nಕ್ಷೇಮ, ಸಮಾಧಾನ, ಶಾಂತಿ\nಕೊಡು ನನಗೆ\n4. ನನ್ನ ಸುಖಕ್ಕೆಲ್ಲಾ ಬುಗೆ\nಆಗಿದ್ದೀ ಕರ್ತಾ\nಇಹಪರದಲ್ಲಿ ನೀನೇ\nನನ್ನುದ್ಧಾರಕ.\nವಿವಿಧವಾದ ಸಂಗೀತಗಳು" },
  345: { title: "ಸ್ತೋತ್ರವನುತ್ತಮ ದೇವರಿ", lyrics: "1. ಸ್ತೋತ್ರವನುತ್ತಮ ದೇವರಿ\nಗರ್ಪಿಸ ಬನ್ನಿ ;\nಉನ್ನತದಲ್ಲಿ ಆ ಕರ್ತಗೆ\nಮಹಿಮೆ ಅನ್ನಿ;\nಹರುಷದಿ\nದೂತರ ಸಂಘದಲಿ\nಸ್ತೋತ್ರ ಸುಗಂಧವ ತನ್ನಿ\n2. ಭೂದಿವಲೋಕಗಳಾತನ\nಸ್ವಕೀಯ ರಾಜ್ಯ\nಭೂಪರ ಪಾಲನ ಸಂಗಡ\nಯಾವನು ವ್ಯಾಜ್ಯ ;\nಮಾಡುವನು ?\nಆತನ ಮಾತಿಗುಂಟು\nಮರ್ತ್ಯರ ಗೊಂದಲ ತ್ಯಾಜ್ಯ.\n3. ಕ್ರಯಕೆ ಕ್ರಿಸ್ತನು ಕೊಂಡ\nಜನಾಂಗವು ನಾವೇ\nಒಪ್ಪಲಿ ರಾಜನ ಚಿತ್ತಕೆ\nದಾಸರ ಸೇವೆ ;\nಒಡೆಯನು\nಪ್ರಸನ್ನನಾಗಲಿಂದು\nಸುಖದಿ ಜೀವಿಸುತ್ತೇವೆ." },
  346: { title: "ಶುಭವರ್ತಮಾನ ಸರ್ವರಿಗೆ", lyrics: "1. ಶುಭವರ್ತಮಾನ ಸರ್ವರಿಗೆ\nತಿಳಿಸುವದಕ್ಕೆ ನನಗೆ ಇದೆ ;\nಕ್ಿ್ತನಲ್ಲಿ ಶ್ರೇಷ್ಯ ಭಾಗ್ಯ ಸಿಕ್ಕಿದೆ.\nಜೀವ ವಾಕ್ಯದಿಂದಲೇ\nವಿವಿಧವಾದ ಸಂಗೀತಗಳು\nಪಲ್ಲವಿ\nಎಷ್ಟೋ ಆನಂದ!\nಆಹಾ! ಎಷ್ಟೋ ಆನಂದ!\nಲೋಕವೆಂದೂ ತೆಗೆಯದ ಆನಂದ!\nದೊಡ್ಡ ಸಮಾಧಾನ ನನಗಾಯಿತು,\nದೇವರಿಗೆ ಸ್ತೋತ್ರವು.\n2. ವಾಕ್ಯದಲ್ಲಿ ನಾನು ದೃಢ ನಂಬಿದೆ;\nನಂಬಿ ಪಾಪ ಪರಿಹಾರ ಹೊಂದಿದೆ ;\nನಿತ್ಯಜೀವ ನನಗೀಗ ಸಿಕ್ಕಿದೆ ;\nಇನ್ನು ಭಯವೇನಿದೆ ?\n3. ಶುಭವರ್ತಮಾನ ಸರ್ವರಿಗೆ\nತಿಳಿಸುವುದಕ್ಕೆ ನನಗೆ ಇದೆ ;\nಜಾತನಾದ ರಕ್ಷಕ ಕ್ರಿಸ್ತ ಯೇಸುವೆ,\nಸತ್ತ ನಮಗಾಗಿಯೇ.\n4. ಯೇಸು ಎದ್ದು ಬಂದು, ಜೀವ ತಂದನು ;\nನಂಬಿದವರಿಗೆ ಮುಕ್ತಿ ಕೊಟ್ಟನು ;\nಹೋಗಿ ಲೋಕಕ್ಕೆಲ್ಲಾ ಸಾರಿರೆಂದನು.\nನಂಬಿ, ಶುಭವಾರ್ತೆಯು." },
  347: { title: "ಓ ಎಂಥಾ ಅದ್ಬುತವಾದ ದಿನ", lyrics: "1. ಓ ಎಂಥಾ ಅದ್ಬುತವಾದ ದಿನ\nನಾನೆಂದಿಗೂ ಮರ್ಯೆನು\nಪಾಪಾಂಧಕಾರದೊಳ್ ಅಲೆದೆ ನಾ\nರಕ್ಷಕನ ಕಂಡೆನು\nಕೋಮಲ ಕರುಣೆಯುಳ್ಳ ಯೇಸು\nಎನ್ ಕೊರತೆ ನೀಗಿದ\nಕತ್ತಲೆ ಹೋಯಿತು ಜ್ಯೋತಿಯು\nಮೂಡಿತು\nನಾನೀಗ ಧನ್ಯನಾದೆ.\nಪಲ್ಲವಿ\nಸ್ವರ್ಗದಾನಂದ ಎನ್ನಾತ್ಮ ತುಂಬಿತು\nಶಿಲುಬೆನಾಥ ಎನ್ ಸ್ವಸ್ಥಗೈದನು\nಎನ್ ಪಾಪ ತೊಳೆದ\nಇರುಳ ದಿನಕ್ಕೆ ತಿರುವಿದ\nಸ್ವರ್ಗದಾನಂದ ಎನ್ನಾತ್ಮ ತುಂಬಿತು.\n2. ಆತ್ಮನ ನೂತನ ಜನ್ಮದಿಂದ\nದೇವಪುತ್ರನಾದೆನು\nನೀತಿನಿರ್ಣಯವ ಹೊಂದಿದೆನು\nಭಾಗ್ಯವಂತನಾದೆನು\nಪಾಪಾತ್ಮನಾಗಿ ನಾ ಬಂದಾಗಲೇ\nಆಶೀರ್ವಾದ ಸಿಕ್ಕಿತು\nಕೃಪೆಯ ಮೂಲವೇ - ರಕ್ಷಣೆ ಹೊಂದಿದೆ\nಸುನಾಮ ಕೊಂಡಾಡುವೆ.\n3. ಅನಂತ ನಿರೀಕ್ಷೆ ಎನಗಿದೆ\nಕಾಲವು ತೀರಲಾಗಿ\nಸ್ವರ್ಗದ ಭವ್ಯ ಬಿಡಾರದಲ್ಲಿ\nನಿತ್ಯವಾಗಿ ಇರುವೆ\nಶಿಲುಬೆ ನನಗೆ ಆಶ್ರಯವೇ\nನಂಬಿಕೆಗಾಧಾರವೇ\nನಿತ್ಯ ಐಶ್ವರ್ಯವ - ದಿವ್ಯಾಶೀರ್ವಾದವ\nಕರ್ತ ಈವನೆನಗೆ" },
  348: { title: "ಈ ವರೆಗೆಮ್ಮ ದೇವರು", lyrics: "1. ಈ ವರೆಗೆಮ್ಮ ದೇವರು\nಸಹಾಯ ಮಾಡಿದ್ದಾನೆ\nಈ ವರೆಗ್ಥಗಲಿರುಳು\nನಮ್ಮನ್ನು ಕಾಿದ್ದಾನೆ\nಈವರೆಗೆ ಯಾವಾಗಲೂ\nಸಂತೋಷ ದಯಪಾಲಿಸಿ,\nಉದ್ಧಾರ ಮಾಡಿದ್ದಾನೆ\n2. ಸಂಸ್ತುತಿ ನಿಂಗೆ, ಕರ್ತನೇ\nಸಂಕೀರ್ತಿ ನಮಸ್ಕಾರ\nನಿಶ್ಚಲ ಪ್ರೀತಿಯಿಂದಲೇ\nಸ್ವಪ್ರಜೆಯ ವಿಚಾರ\nನೀ ಗೈದದನ್ನು ನೆನಸಿ\nಕೊಂಡಾಡುತ್ತೇವೆ ಹರ್ಷದಿ\nನಿನ್ನಲ್ಲಾ ಉಪಕಾರ\n3. ಇನ್ನಾದರೂ ಸ್ವಜನಕೆ\nಆಶ್ರಯ ಸ್ಮಾನವಾಗು\nಸರ್ವವು ಪ್ರತಿಗಳಿಗೆ\nಸ್ವಃ ಸಮೀಪವಾಗು\nಕರಿ್ೈಸು ಶ್ರಮ ಮೂಲದಿಂ\nಸಮಸ್ತ ಕಷ್ಟದೊಳಗಿಂ\nನಮ್ಮನ್ನು ಪಾರುಮಾಡು." },
  349: { title: "ಓ ಬೆಳಕೇ ಕಾರುಣ್ಯ ನಿಧಿಯೇ", lyrics: "1. ಓ ಬೆಳಕೇ ಕಾರುಣ್ಯ ನಿಧಿಯೇ\nಮುನ್ನಡಿಸು\nಕತ್ತಲೆಯಾಯ್ತು ಮನೆ ದೂರವೇ\nವಿವಿಧವಾದ ಸಂಗೀತಗಳು\nಮುನ್ನಡಿಸು\nಮುಂದಡಿಯಿಡೆ ಬಲಹೀನನು\nಒಂದೊಂದು ಹೆಜ್ಜೆ ನಡಿಸನ್ನ್ನು\n2. ಹಿಂದೆಲ್ಲಾ ಸ್ವೇಚ್ಛೆಯಿಂದ ಸಾಗಿದ್ೆ\nಮುನ್ನಡಿಸು\nಎಂದು ನಿನ್ನನ್ನು ಬೇಡಲಿಲ್ಲವಯೈ\nಮುನ್ನಡಿಸು\nಹಿಂದೆ ನಾ ಸೊಕ್ಕಿನಿಂದ ನಡೆದೆ\nಅಂದಿನ ಎಲ್ಲಾ ಪಾಪ ಮನಿಸಕ್ಯೈ\n3. ಹಿಂದೆನ್ನ ಕಾಯ್ದ ನಿನ್ನ ಶಕ್ತಿಯೇ\nಕಾವಳದಿ\nಮುಂದೆನ್ನ ಕಾವುದೆಂದು ಗೊತ್ತಿದೆ\nಪ್ರವಾಸದಿ\nಉನ್ನತ ಸೇರಿ ಬೆಳಕಿನಲ್ಲೇ\nಚೆನ್ನಿಗರೊಂದಿಗಾನು ಬಾಳುವೆ.\nಪಲ್ಲವಿ\nಆರಾಧಿಸುವೆವು ಕರ್ತ ಯೇಸುವ\nಆತ್ಮ ಸತ್ಯದಿಂದ ಪ್ರಿಯ ಕ್ರಿಸ್ತನನ್\nಪರಮ ತಂದೆಯನ್ನೇ ಆರಾಧಿಸುವವು" },
  350: { title: "ಪಾಪಕ್ಷಮೆ ನೀಡಿದ ಆತ ನಮಗೆ", lyrics: "1. ಪಾಪಕ್ಷಮೆ ನೀಡಿದ ಆತ ನಮಗೆ\nಬಿಡಿಸಿದ ರಕ್ತದ ಕ್ರಯದಿಂದಲೇ ॥\nಜಯವೇ ಜಯವೇ ಸದಾ ಆತನಿಗೆ\n2. ಕಣ್ಣನ್ ದೃಷ್ಟಿ ತೆರೆದ ಯೇಸುವಿನಿಂದಾ\nಕಂಡು ಕೊಂಡೆವು ಆತ್ಮದ ಅಸ್ತಿವಾರವಃ\nವಿವಿಧವಾದ ಸಂಗೀತಗಳು\n3. ಸ್ವತಂತ್ರವ ಹೊಂದಲು ಬಾಧ್ಯರಾದೆವು\nಅಧಿಕಾರ ಹೊಂದಿದ ರಾಜ್ಯಕ್ಕಾಗಿಯೇ 11\n4. ಪ್ರಪಂಚವ ಜಯಿಸಲು ಶಕ್ತಿ ನೀಡಿದ\nಶಿಲುಬೆಯೊಳ್ ಮಾರ್ಗದೊಳ್ ನಡಿಸಿದನು !॥\nಲೋಕಾರಣ್ಯ ಯಾತ್ರೆಯೊಳ್\nನೀನೆ ಶಕ್ತ ನಾನಶಕ್ತ\nದಾಟಸೈ ಸ್ವಹಸ್ತದೊಳ್\nಜೀವದನ್ನ ತಿನ್ನಿಸೆನ್ನ\nಪೂರ್ಣ ತೃಪ್ತಿಗೊಳಿಸು.\n2. ಜೀವಜಲ ನಿಧಿಯಿಂದ\nನೀಗು ನನ್ನ ತೃಷೆಯ\nಅಗ್ನಿ ಮೇಘ ಸ್ತಂಭದಿಂದ\nತೋರು ನನ್ನ ಮಾರ್ಗವ\nನೀ ಸಮರ್ಥ ರಕ್ಷಕರ್ತ\nನೀನೇ ಡಾಲೂ ಖೇಡ್ಯವೂ.\n3. ಯೋರ್ದಾನ್ ತೀರದೊಳೆ ನನ್ನ\nಕೈಯೊಳೆತ್ತಿ ಸಲಹು\nರಕ್ಷೆಗೈದು ಪ್ರಾಣವನ್ನ\nಕಾನಾನ್ ದೇಶ ಸೇರಿಸು\nವಿನಗಲ್ಲಿ ನಿತ್ಯದಲ್ಲಿ\nಸ್ತೋತ್ರಗಾನ ಮಾಡ್ವೆನು." },
};
